_SMC_RECENCY_MIN = 30   # an FVG/OB alert counts as live analyst evidence for this long

def _recent_smc_signals(inst, within_min=_SMC_RECENCY_MIN):
    """Scan ALERT_HISTORY for recent Fair-Value-Gap / Order-Block alerts (pushed by
    pine/fvg_ob.pine) for `inst`, returned per-direction. DISPLAY-ONLY analyst
    evidence — never touches the gate, sizing, dedupe or the money path. Fail-open:
    any error (or no alerts) -> all False, so default behaviour is unchanged until
    those alerts actually flow."""
    out = {"fvg_long": False, "fvg_short": False, "ob_long": False, "ob_short": False}
    try:
        if not inst:
            return out
        cutoff = datetime.now(timezone.utc) - timedelta(minutes=within_min)
        for a in reversed(list(ALERT_HISTORY)):   # newest -> oldest
            t = a.get("alert_type") or ""
            if not (t.endswith("FVG") or t.endswith("OB")):
                continue
            try:
                if datetime.fromisoformat(a["timestamp"]) < cutoff:
                    continue   # outside the recency window — skip (deque cap keeps this cheap)
            except (KeyError, ValueError, TypeError):
                continue
            a_inst = a.get("instrument") or _instrument_from_text(t)
            if a_inst != inst:
                continue
            if   "BULLISH FVG" in t: out["fvg_long"]  = True
            elif "BEARISH FVG" in t: out["fvg_short"] = True
            elif "BULLISH OB"  in t: out["ob_long"]   = True
            elif "BEARISH OB"  in t: out["ob_short"]  = True
            if all(out.values()):
                break
        return out
    except Exception:
        return out


def compute_analyst_reasoning(result, strict, swing_ctx=None, market=None):
    """Professional-analyst reasoning over the assembled full_analysis `result`.
    Pure + fail-open (the caller also wraps it in try/except). Returns the block
    documented in _analyst_neutral_block with every key populated for real."""
    dirs = strict.get("directions") or {}
    cL   = (dirs.get("Long")  or {}).get("confluences") or {}
    cS   = (dirs.get("Short") or {}).get("confluences") or {}
    conflict = bool((dirs.get("Long") or {}).get("conflict")
                    or (dirs.get("Short") or {}).get("conflict"))

    price    = result.get("current_price")
    vwap     = result.get("vwap_value")
    sup      = result.get("nearest_supply")
    dem      = result.get("nearest_demand")
    vol      = result.get("volatility") or {}
    regime_raw = str(vol.get("regime") or "").upper()
    struct   = str(result.get("structure_label") or "")
    bias     = result.get("bias") or "Neutral"
    gate_v   = result.get("verdict")
    gate_dir = result.get("strict_direction")
    session  = result.get("session") or {}
    overext  = bool(result.get("overextended"))
    tp       = result.get("trade_plan") or {}
    # Smart-money evidence (FVG / Order Blocks) — DISPLAY-ONLY, read from recent
    # alerts. Empty until pine/fvg_ob.pine is deployed, so behaviour is unchanged.
    smc      = _recent_smc_signals(result.get("active_ticker") or result.get("instrument"))

    def _f(x):
        try:
            return f"{float(x):.2f}"
        except (TypeError, ValueError):
            return "—"

    def _near(a, b, pct=0.0015):
        try:
            return a is not None and b not in (None, 0) and abs(float(a) - float(b)) / abs(float(b)) <= pct
        except (TypeError, ValueError, ZeroDivisionError):
            return False

    # ── Evidence stacks (existing alerts read as EVIDENCE, scored per side) ───
    def _evidence(conf, side):
        long_ = (side == "Long")
        out = []
        if conf.get("choch"):
            out.append((("Bullish" if long_ else "Bearish") + " CHOCH (change of character)", _ANALYST_W["choch"]))
        if conf.get("bos"):
            out.append((("Bullish" if long_ else "Bearish") + " BOS (break of structure)", _ANALYST_W["bos"]))
        if conf.get("vwap"):
            out.append(("Price " + ("reclaimed/holding above VWAP" if long_ else "rejected/holding below VWAP"), _ANALYST_W["vwap"]))
        if conf.get("liquidity_sweep"):
            out.append((("Swept lows and reversed up" if long_ else "Swept highs and failed lower"), _ANALYST_W["sweep"]))
        if conf.get("cvd_confirmed"):
            out.append((("Positive delta / CVD" if long_ else "Negative delta / CVD"), _ANALYST_W["cvd"]))
        if conf.get("volume_confirmed"):
            out.append(("Volume confirmation (elevated RVOL)", _ANALYST_W["volume"]))
        if conf.get("zone_confirmed") or conf.get("zone_mitigated"):
            out.append((("Demand zone holding / reaction" if long_ else "Supply zone holding / reaction"), _ANALYST_W["zone"]))
        return out

    bull = _evidence(cL, "Long")
    bear = _evidence(cS, "Short")
    # FVG / Order-Block evidence (DISPLAY-ONLY, from _recent_smc_signals — NOT from
    # the gate's confluences, so the strict gate / goldens are untouched).
    if smc.get("fvg_long"): bull.append(("Bullish FVG (fair-value gap) to fill", _ANALYST_W["fvg"]))
    if smc.get("ob_long"):  bull.append(("Bullish order block reaction",         _ANALYST_W["ob"]))
    if smc.get("fvg_short"): bear.append(("Bearish FVG (fair-value gap) to fill", _ANALYST_W["fvg"]))
    if smc.get("ob_short"):  bear.append(("Bearish order block reaction",         _ANALYST_W["ob"]))
    bull_score = sum(w for _, w in bull)
    bear_score = sum(w for _, w in bear)

    # Directionless tailwind — preferred session window credited to the leading side.
    if session.get("preferred"):
        if bull_score > bear_score:
            bull.append(("Inside a preferred session window", _ANALYST_W["session"])); bull_score += _ANALYST_W["session"]
        elif bear_score > bull_score:
            bear.append(("Inside a preferred session window", _ANALYST_W["session"])); bear_score += _ANALYST_W["session"]

    # Higher-timeframe alignment (SWING HTF context, when present).
    htf_bias = "Neutral"
    if isinstance(swing_ctx, dict):
        if swing_ctx.get("aligned_long"):
            htf_bias = "Bullish"
            bull.append(("1H/4H higher-timeframe alignment", _ANALYST_W["htf"])); bull_score += _ANALYST_W["htf"]
        elif swing_ctx.get("aligned_short"):
            htf_bias = "Bearish"
            bear.append(("1H/4H higher-timeframe alignment", _ANALYST_W["htf"])); bear_score += _ANALYST_W["htf"]
    if htf_bias == "Neutral":
        htf_bias = bias if bias in ("Bullish", "Bearish") else "Neutral"

    stronger  = "Long" if bull_score > bear_score else ("Short" if bear_score > bull_score else "Neither")
    top       = max(bull_score, bear_score)
    margin    = abs(bull_score - bear_score)
    conf_side = cL if stronger == "Long" else (cS if stronger == "Short" else {})

    # ── Market context ───────────────────────────────────────────────────────
    def _regime():
        if conflict or stronger == "Neither":
            return "Ranging / choppy"
        sweep = cL.get("liquidity_sweep") or cS.get("liquidity_sweep")
        choch = cL.get("choch") or cS.get("choch")
        bos   = cL.get("bos") or cS.get("bos")
        volok = cL.get("volume_confirmed") or cS.get("volume_confirmed")
        if sweep and choch:
            return "Reverting (sweep + reversal)"
        if bos and volok:
            return "Breaking out"
        if bos or "bull" in struct.lower() or "bear" in struct.lower():
            return "Trending"
        return "Ranging"

    regime = _regime()

    loc_bits = []
    if _near(price, dem):
        loc_bits.append("at demand")
    if _near(price, sup):
        loc_bits.append("at supply")
    if _near(price, vwap, 0.001):
        loc_bits.append("at VWAP")
    if not loc_bits:
        loc_bits.append("in mid-range (no nearby zone/VWAP)")
    location = ", ".join(loc_bits)

    environment = "Choppy" if (conflict or regime.startswith("Ranging")
                               or regime_raw in ("HIGH_BLOCK", "HIGH_CAUTION")) else "Clean"

    # ── Risk & location check (for the leaning side) ─────────────────────────
    # Trade plans carry R:R as a DISPLAY string ("1:1", "1:4", "T1 .. / T2 ..");
    # the numeric value lives in rr_num. Prefer rr_num, fall back to parsing the
    # string (first "1:X" ratio, else the first number) so the risk check is real
    # (float("1:1") would otherwise raise -> phantom "no acceptable R:R").
    rr = tp.get("rr_num")
    if rr is None:
        _rr_disp = tp.get("rr")
        if isinstance(_rr_disp, str):
            _rm = (re.search(r"1\s*:\s*([0-9]+(?:\.[0-9]+)?)", _rr_disp)
                   or re.search(r"([0-9]+(?:\.[0-9]+)?)", _rr_disp))
            if _rm:
                rr = _rm.group(1)
    try:
        rr = float(rr) if rr is not None else None
    except (TypeError, ValueError):
        rr = None
    stop_logical    = bool(tp.get("stop_loss") is not None and tp.get("stop_valid", True))
    rr_acceptable   = bool(rr is not None and rr >= 1.0)
    target_room     = rr_acceptable
    chasing         = overext
    into_resistance = (stronger == "Long" and _near(price, sup, 0.0015)) \
                      or (stronger == "Short" and _near(price, dem, 0.0015))
    volatility_supports = (str(vol.get("status") or "ok").lower() == "ok"
                           and regime_raw not in ("HIGH_BLOCK",))

    risk = {"chasing": chasing, "stop_logical": stop_logical, "target_room": target_room,
            "rr_acceptable": rr_acceptable, "into_resistance": into_resistance,
            "volatility_supports": volatility_supports, "rr": rr}
    risk_ok = (not chasing and stop_logical and rr_acceptable
               and not into_resistance and volatility_supports)
    _risk_pass = (sum(1 for k in ("stop_logical", "target_room", "rr_acceptable",
                                  "volatility_supports") if risk[k])
                  + (0 if chasing else 1) + (0 if into_resistance else 1))
    risk["quality"] = "Good" if risk_ok else ("Fair" if _risk_pass >= 4 else "Poor")
    _rn = []
    if chasing:                 _rn.append("price overextended (chasing risk)")
    if into_resistance:         _rn.append("entering directly into the opposing zone")
    if not rr_acceptable:       _rn.append("no acceptable R:R yet")
    if not stop_logical:        _rn.append("no logical stop yet")
    if not volatility_supports: _rn.append("volatility not supportive")
    risk["summary"] = "; ".join(_rn) if _rn else "Entry location, stop, R:R and volatility all acceptable."

    # ── Missing high-value evidence on the leaning side (what to wait for) ────
    _checks = [("choch", "a CHOCH (change of character)"), ("bos", "a BOS (break of structure)"),
               ("vwap", "price to reclaim/hold the correct side of VWAP"),
               ("liquidity_sweep", "a liquidity sweep + reversal"),
               ("cvd_confirmed", "delta/CVD agreement"),
               ("volume_confirmed", "volume confirmation")]
    what_needs_next = []
    if stronger != "Neither":
        what_needs_next = [name for key, name in _checks if not conf_side.get(key)]
        if not risk_ok:
            if chasing:         what_needs_next.append("a pullback (price is extended)")
            if into_resistance: what_needs_next.append("room to the next opposing zone")
        # FVG / Order Block (display-only) — note when the leaning side has none yet.
        if stronger == "Long" and not (smc.get("fvg_long") or smc.get("ob_long")):
            what_needs_next.append("a bullish FVG or order block to form")
        elif stronger == "Short" and not (smc.get("fvg_short") or smc.get("ob_short")):
            what_needs_next.append("a bearish FVG or order block to form")

    # ── Verdict (independent of the gate — the analyst may WAIT even when alerts fire) ──
    if top < _ANALYST_NOTHING or stronger == "Neither":
        final = "NO TRADE"
    elif conflict or margin < _ANALYST_MIN_MARGIN:
        final = "WAIT"
    elif top >= _ANALYST_READY_EVIDENCE and risk_ok and (gate_dir in (stronger, None)):
        final = "READY LONG" if stronger == "Long" else "READY SHORT"
    else:
        final = "WAIT"

    gate_actionable = is_actionable(gate_v)
    agrees = (gate_actionable and final in ("READY LONG", "READY SHORT")
              and ((final.endswith("LONG") and gate_dir == "Long")
                   or (final.endswith("SHORT") and gate_dir == "Short")))
    veto_would_fire = bool(gate_actionable and not agrees)

    if stronger == "Neither":
        confidence = 0
    else:
        confidence = max(0, min(95, int(top * 0.7 + margin * 0.5)))
        if final.startswith("READY"):
            confidence = max(confidence, 70)
        elif final == "WAIT":
            confidence = min(confidence, 65)
        else:
            confidence = min(confidence, 40)

    bull_case = [lbl for lbl, _ in bull]
    bear_case = [lbl for lbl, _ in bear]

    # Best trade idea / forming setup (display-only; real plan if present, else preview).
    plan = tp if tp.get("trade_plan") else ((result.get("directions") or {}).get(stronger) or {}).get("potential_plan")
    if stronger == "Neither":
        best_idea = "No directional edge — stand aside."
    elif isinstance(plan, dict) and plan.get("entry_zone"):
        best_idea = (f"{stronger} from {plan.get('entry_zone')} — stop {_f(plan.get('stop_loss'))}, "
                     f"targets {_f(plan.get('target1'))}/{_f(plan.get('target2'))}"
                     + (f" (R:R {rr:.1f})" if rr is not None else ""))
    else:
        best_idea = f"{stronger} setup forming — no valid entry geometry yet."

    _inv_lvl = plan.get("stop_loss") if isinstance(plan, dict) else None
    if stronger == "Long":
        invalidation = f"A close back below {_f(_inv_lvl if _inv_lvl is not None else (dem if dem is not None else vwap))}."
    elif stronger == "Short":
        invalidation = f"A close back above {_f(_inv_lvl if _inv_lvl is not None else (sup if sup is not None else vwap))}."
    else:
        invalidation = "—"

    if stronger == "Neither":
        thesis = "Evidence is balanced or insufficient — no side has the stronger argument."
    else:
        thesis = (f"{stronger} has the stronger argument ({bull_score} vs {bear_score}). "
                  + ("Setup confirmed." if final.startswith("READY")
                     else "Not yet confirmed — waiting on the missing pieces."))
    market_story = (f"{htf_bias} higher-timeframe bias. Price is {location} in a "
                    f"{regime.lower()} ({environment.lower()}) environment. " + thesis)

    if final.startswith("READY"):
        why_not = ""
        reason_for_waiting = "Evidence aligned and risk acceptable — setup is actionable."
    elif final == "WAIT":
        if conflict:
            why_not = "Opposing structure on both sides — the tape is conflicted."
        elif margin < _ANALYST_MIN_MARGIN:
            why_not = "Bullish and bearish evidence are too close — no clear edge."
        elif not risk_ok:
            why_not = "A direction is leaning but the risk/location is not acceptable: " + risk["summary"]
        else:
            why_not = "A direction is leaning but key confirmation is still missing."
        reason_for_waiting = why_not
    else:
        why_not = "No setup — evidence is insufficient on both sides."
        reason_for_waiting = why_not

    watching = []
    if vwap is not None: watching.append(f"VWAP {_f(vwap)}")
    if dem is not None:  watching.append(f"Demand {_f(dem)}")
    if sup is not None:  watching.append(f"Supply {_f(sup)}")
    if smc.get("fvg_long") or smc.get("fvg_short"): watching.append("FVG active")
    if smc.get("ob_long")  or smc.get("ob_short"):  watching.append("Order block active")
    if what_needs_next:  watching.append("Trigger: " + what_needs_next[0])

    market_bias = (f"{htf_bias} HTF"
                   + (f" / {stronger} near-term" if stronger != "Neither" else " / no near-term edge"))

    location_quality = "—"
    if stronger != "Neither":
        if into_resistance:
            location_quality = "Poor — entering into the opposing zone"
        elif (stronger == "Long" and _near(price, dem)) or (stronger == "Short" and _near(price, sup)):
            location_quality = "Good — at the trade-side zone"
        elif _near(price, vwap, 0.001):
            location_quality = "Fair — at VWAP"
        else:
            location_quality = "Poor — mid-range, away from a zone"

    best_setup_forming = "None — flat" if stronger == "Neither" else f"{stronger}: {best_idea}"

    # ── Professional analyst upgrades (DISPLAY-ONLY): mode-correct VWAP extension
    #    (SCALP = 1m volatility ATR; SWING = HTF ATR from swing_ctx, else mark the
    #    extension unavailable), the Market-Phase classifier and the Analyst Outlook.
    #    All pure + fail-open; never feeds the gate / scoring / sizing / dedupe.
    _phase_atr = _analyst_phase_atr(TRADING_MODE, swing_ctx, vol)
    _vwap_ext_atr = None
    try:
        if _phase_atr and price is not None and vwap is not None:
            _vwap_ext_atr = abs(float(price) - float(vwap)) / _phase_atr
    except (TypeError, ValueError, ZeroDivisionError):
        _vwap_ext_atr = None
    _phase_block = _analyst_market_phase({
        "stronger": stronger, "conflict": conflict,
        "total": bull_score + bear_score, "top": top, "margin": margin,
        "conf_side": conf_side, "chasing": chasing, "into_resistance": into_resistance,
        "vwap_ext_atr": _vwap_ext_atr, "price": price, "vwap": vwap,
        "dem": dem, "sup": sup, "near": _near, "regime": regime,
        "vol_label": (vol.get("label") if isinstance(vol, dict) else None),
    })
    _outlook_block = _analyst_outlook({
        "stronger": stronger, "final": final, "conflict": conflict,
        "chasing": chasing, "into_resistance": into_resistance,
        "phase": _phase_block, "what_needs_next": what_needs_next,
        "price": price, "vwap": vwap, "dem": dem, "sup": sup,
        "sweep": bool(conf_side.get("liquidity_sweep")),
        "invalidation": invalidation, "fmt": _f,
    })

    return {
        "engine_enabled":         _analyst_engine_enabled(),
        "gate_enabled":           _analyst_gate_enabled(),
        "reviewed":               True,
        "market_bias":            market_bias,
        "thesis":                 thesis,
        "bull_case":              bull_case,
        "bear_case":              bear_case,
        "bull_score":             bull_score,
        "bear_score":             bear_score,
        "stronger_side":          stronger,
        "best_trade_idea":        best_idea,
        "invalidation":           invalidation,
        "why_not_trade":          why_not,
        "confidence":             confidence,
        "final_verdict":          final,
        "context":                {"htf_bias": htf_bias, "regime": regime,
                                   "location": location, "environment": environment},
        "risk":                   risk,
        "market_story":           market_story,
        "professionals_watching": watching,
        "fvg_active":             bool(smc.get("fvg_long") or smc.get("fvg_short")),
        "ob_active":              bool(smc.get("ob_long")  or smc.get("ob_short")),
        "best_setup_forming":     best_setup_forming,
        "location_quality":       location_quality,
        "risk_quality":           risk["quality"],
        "reason_for_waiting":     reason_for_waiting,
        "what_needs_next":        what_needs_next,
        "agrees_with_gate":       agrees,
        "veto_would_fire":        veto_would_fire,
        # DISPLAY-ONLY pro-analyst trade plan (probabilities / scenarios / R:R /
        # conclusion) derived purely from the locals computed above — never feeds
        # the gate, scoring, sizing, dedupe or execution (fail-open helper).
        "game_plan":              _analyst_game_plan({
            "mode": TRADING_MODE, "final": final, "stronger": stronger,
            "bull_score": bull_score, "bear_score": bear_score, "top": top, "margin": margin,
            "confidence": confidence, "regime": regime, "conflict": conflict,
            "risk": risk, "risk_ok": risk_ok, "rr": rr, "plan": plan,
            "price": price, "vwap": vwap, "dem": dem, "sup": sup,
            "reason_for_waiting": reason_for_waiting, "what_needs_next": what_needs_next,
            "fmt": _f,
        }),
        "market_phase":           _phase_block,
        "analyst_outlook":        _outlook_block,
        # Placeholder; full_analysis overwrites this (after entry_quality is computed)
        # with the real Entry-Quality-anchored forward projection.
        "entry_probability":      _analyst_entry_probability_neutral(),
        # Placeholder; full_analysis overwrites this with the SHARED memory review.
        "memory_review":          build_analyst_memory_review(None),
    }


# ── Professional Review (pre-READY "think like a pro" layer) ──────────────────
# A unified review brain that grades EVERY potential setup the way a professional
# discretionary trader would, BEFORE the bot commits to a READY. It runs two
# independently-selectable MODELS (selected per instrument so they run separately):
#   • SCALP — the operator's primary style: weights entry timing, VWAP location,
#     momentum and the personal prime-session window most heavily.
#   • SWING — 1-7 day holds: weights higher-timeframe alignment, target room and
#     risk geometry most heavily and is far more forgiving of exact minute timing /
#     VWAP extension.
# DISPLAY by default (_pro_review_engine_enabled). The money-path VETO
# (_pro_review_gate_enabled, default OFF) may ONLY demote an actionable gate verdict
# to WAIT — never promote. Attached at the full_analysis level (NOT inside
# evaluate_strict_setup / build_strict_trade_plan), so the strict-gate goldens stay
# byte-identical in every flag state. Fail-OPEN to a fully-populated neutral block.

PRO_REVIEW_MODELS = ("SCALP", "SWING")
PRO_NEAR_PCT = 0.005   # within this % of a favorable zone counts as "good location"

# Per-model scoring weights + thresholds. Entry Efficiency = timing + location +
# momentum + risk (each a fraction of its weight; the four weights sum to 100).
_PRO_REVIEW_CFG = {
    "SCALP": {
        "w":            {"timing": 30, "location": 25, "momentum": 25, "risk": 20},
        "vwap_ext_pct": 0.0035,   # > this distance from VWAP = over-extended / chasing
        "min_rr":       1.0,
        "min_room_r":   1.0,
        "use_htf":      False,
    },
    "SWING": {
        "w":            {"timing": 15, "location": 25, "momentum": 20, "risk": 40},
        "vwap_ext_pct": 0.012,    # swings tolerate far more VWAP extension
        "min_rr":       1.5,
        "min_room_r":   2.0,
        "use_htf":      True,
    },
}

# Per-instrument model selection ("run them separately"). In-memory + env-seedable;
# resets to the default on restart (intentional — like auto-trade arming, a restart
# is a clean, predictable state). Switched at runtime via /pro-review.
_PRO_REVIEW_DEFAULT_MODEL = os.environ.get("PRO_REVIEW_DEFAULT_MODEL", "SCALP").upper()
if _PRO_REVIEW_DEFAULT_MODEL not in PRO_REVIEW_MODELS:
    _PRO_REVIEW_DEFAULT_MODEL = "SCALP"
PRO_REVIEW_MODEL_BY_INST = {}
PRO_REVIEW_LOCK = threading.Lock()


def pro_review_model_for(inst):
    """Active review model (SCALP/SWING) for an instrument. Fail-safe default."""
    if not inst:
        return _PRO_REVIEW_DEFAULT_MODEL
    with PRO_REVIEW_LOCK:
        return PRO_REVIEW_MODEL_BY_INST.get(str(inst).upper(), _PRO_REVIEW_DEFAULT_MODEL)


def set_pro_review_model(inst, model):
    """Set the active review model for an instrument (runtime, in-memory)."""
    model = str(model).upper()
    if model not in PRO_REVIEW_MODELS or not inst:
        return False
    with PRO_REVIEW_LOCK:
        PRO_REVIEW_MODEL_BY_INST[str(inst).upper()] = model
    return True


def _pro_num(x):
    """Coerce a price-ish value (number / dict with price|level|value) to float."""
    try:
        if isinstance(x, dict):
            x = x.get("price") or x.get("level") or x.get("value")
        return float(x)
    except (TypeError, ValueError):
        return None


def _pro_review_model_stub(model, reason):
    """Fully-populated, inert per-model block (fail-open / closed / disabled)."""
    return {
        "model":                 model,
        "grade":                 "—",
        "entry_efficiency":      0,
        "timing_score":          0,
        "location_score":        0,
        "momentum_score":        0,
        "risk_score":            0,
        "market_type":           "—",
        "momentum_strength":     "—",
        "chase_risk":            "—",
        "trade_quality":         "—",
        "session_quality":       "—",
        "professional_decision": "—",
        "checklist": {
            "not_late":            False,
            "not_chasing":         False,
            "tp1_room":            False,
            "momentum_increasing": False,
            "volume_confirming":   False,
            "prime_session":       False,
            "pro_would_take":      False,
        },
        "hard_fails":      [],
        "why_not_trade":   reason,
        "veto_would_fire": False,
        "summary":         reason,
    }


def _pro_review_neutral_block(reason="Pro review unavailable.", inst=None):
    """Fully-populated, safe Pro-Review block (fail-open fallback + market-closed +
    disabled stub). EVERY key the /status serializer and dashboard read MUST exist
    here so the single-return-path / hard-indexed-consumer invariant holds in every
    branch. veto_would_fire stays False so a stub can NEVER demote a trade when the
    gate is on."""
    sel    = pro_review_model_for(inst)
    models = {m: _pro_review_model_stub(m, reason) for m in PRO_REVIEW_MODELS}
    return {
        "engine_enabled":   _pro_review_engine_enabled(),
        "gate_enabled":     _pro_review_gate_enabled(),
        "selected_model":   sel,
        "available_models": list(PRO_REVIEW_MODELS),
        "models":           models,
        "active":           models[sel],
    }


def _pro_grade_from_efficiency(eff):
    """Base letter grade from the 0-100 Entry Efficiency (before chase capping)."""
    if eff < 50:
        return "D"
    if eff >= 90:
        return "A+"
    if eff >= 80:
        return "A"
    if eff >= 65:
        return "B"
    return "C"


def _pro_eval_model(model, ctx):
    """Score ONE model from the shared, pre-extracted ctx. Pure + fail-open."""
    cfgm = _PRO_REVIEW_CFG.get(model, _PRO_REVIEW_CFG["SCALP"])
    w    = cfgm["w"]

    vdist_pct    = ctx["vdist_pct"]
    on_vwap_side = ctx["on_vwap_side"]
    near_zone    = ctx["near_zone"]
    room_r       = ctx["room_r"]
    rr_num       = ctx["rr_num"]
    stop_ok      = ctx["stop_ok"]
    struct_ok    = ctx["struct_ok"]
    sweep_recent = ctx["sweep_recent"]
    vol_conf     = ctx["vol_conf"]
    cvd_agree    = ctx["cvd_agree"]
    vol_label    = ctx["vol_label"]
    htf_agree    = ctx["htf_agree"]
    prime        = ctx["prime"]

    ext           = cfgm["vwap_ext_pct"]
    over_extended = (vdist_pct is not None and vdist_pct > ext)
    if vdist_pct is None:
        chase_risk = "Low"
    elif vdist_pct > ext:
        chase_risk = "High"
    elif vdist_pct > 0.6 * ext:
        chase_risk = "Medium"
    else:
        chase_risk = "Low"

    room_ok = (room_r is not None and room_r >= cfgm["min_room_r"])
    rr_ok   = (rr_num  is not None and rr_num  >= cfgm["min_rr"])

    # ── timing ──
    tf = 0.0
    if on_vwap_side:               tf += 0.40
    if not over_extended:          tf += 0.35
    if struct_ok or sweep_recent:  tf += 0.25
    timing = w["timing"] * tf

    # ── location ──
    lf = 0.0
    if near_zone:    lf += 0.50
    if room_ok:      lf += 0.30
    if on_vwap_side: lf += 0.20
    location = w["location"] * lf

    # ── momentum ──
    mf = 0.0
    if cfgm["use_htf"]:
        if vol_conf:  mf += 0.30
        if cvd_agree: mf += 0.30
        if htf_agree: mf += 0.40
    else:
        if vol_conf:  mf += 0.40
        if cvd_agree: mf += 0.35
        if vol_label in ("Normal", "Elevated"): mf += 0.25
    momentum = w["momentum"] * mf

    # ── risk ──
    rf = 0.0
    if rr_ok:    rf += 0.50
    if room_ok:  rf += 0.30
    if stop_ok:  rf += 0.20
    risk = w["risk"] * rf

    eff = int(round(min(100.0, timing + location + momentum + risk)))

    grade = _pro_grade_from_efficiency(eff)
    if over_extended or chase_risk == "High":
        grade = "D"
    elif chase_risk == "Medium" and grade in ("A+", "A", "B"):
        grade = "C"

    if   mf >= 0.80: momentum_strength = "Strong"
    elif mf >= 0.55: momentum_strength = "Building"
    elif mf >= 0.30: momentum_strength = "Fading"
    else:            momentum_strength = "Weak"

    if   eff >= 80: trade_quality = "Excellent"
    elif eff >= 65: trade_quality = "Good"
    elif eff >= 50: trade_quality = "Fair"
    else:           trade_quality = "Poor"

    tp1_room = room_ok or rr_ok
    checklist = {
        "not_late":            not over_extended,
        "not_chasing":         chase_risk != "High",
        "tp1_room":            bool(tp1_room),
        "momentum_increasing": bool(vol_conf or cvd_agree),
        "volume_confirming":   bool(vol_conf),
        "prime_session":       bool(prime),
        "pro_would_take":      False,
    }

    hard_fails = []
    if grade == "D":
        hard_fails.append("Setup grade D (extended / low quality)")
    if eff < 80:
        hard_fails.append("Entry efficiency %d below 80" % eff)
    if over_extended:
        hard_fails.append("Price over-extended from VWAP (chasing)")
    if not tp1_room:
        hard_fails.append("Insufficient room to first target")

    if hard_fails and (grade == "D" or eff < 60 or chase_risk == "High"):
        decision = "PASS"
    elif hard_fails:
        decision = "WAIT"
    else:
        decision = "TAKE"
    checklist["pro_would_take"] = (decision == "TAKE")

    why = "; ".join(hard_fails) if hard_fails else "Setup meets professional criteria."
    return {
        "model":                 model,
        "grade":                 grade,
        "entry_efficiency":      eff,
        "timing_score":          int(round(timing)),
        "location_score":        int(round(location)),
        "momentum_score":        int(round(momentum)),
        "risk_score":            int(round(risk)),
        "market_type":           ctx["market_type"],
        "momentum_strength":     momentum_strength,
        "chase_risk":            chase_risk,
        "trade_quality":         trade_quality,
        "session_quality":       "Prime" if prime else "Off-Prime",
        "professional_decision": decision,
        "checklist":             checklist,
        "hard_fails":            hard_fails,
        "why_not_trade":         why,
        "veto_would_fire":       decision != "TAKE",
        "summary":               "%s · %s · Eff %d · %s · %s" % (
            model, grade, eff, ctx["market_type"], decision),
    }


def _pro_market_type(result, vol_label):
    """Best-effort market-character label from structure + volatility + conflict."""
    sc = str(result.get("structure_class") or "").lower()
    if vol_label == "Extreme":
        return "Expansion Day"
    if any(k in sc for k in ("trend", "impuls")):
        return "Trend Day"
    if any(k in sc for k in ("range", "consolid", "balance")):
        return "Range Day"
    if any(k in sc for k in ("revers", "exhaust")):
        return "Reversal Day"
    try:
        cg = result.get("conflict_gap")
        if cg is not None and abs(float(cg)) < 10:
            return "Choppy Day"
    except (TypeError, ValueError):
        pass
    return "Range Day"


def compute_pro_review(result, strict, swing_ctx=None, market=None, inst=None):
    """Professional pre-READY review over the assembled full_analysis `result`.
    Pure + fail-open (the caller also wraps it in try/except). Computes BOTH models
    from one shared read of the evaluated setup; the active model is selected per
    instrument. Returns the block documented in _pro_review_neutral_block."""
    inst = (inst or result.get("active_ticker") or "")

    # Evaluated direction: the actionable side, else the strict direction, else the
    # dominant / stronger forming side (so a forming setup still gets graded).
    direction = ready_direction(result.get("verdict")) or result.get("strict_direction")
    if direction not in ("Long", "Short"):
        dd = result.get("dominant_direction")
        if dd in ("Long", "Short"):
            direction = dd
    if direction not in ("Long", "Short"):
        direction = "Long" if (result.get("long_score") or 0) >= (result.get("short_score") or 0) else "Short"
    long_ = (direction == "Long")

    price = _pro_num(result.get("current_price"))
    vwap  = _pro_num(result.get("vwap_value"))
    vdist_pct, on_vwap_side = None, False
    if price and vwap:
        try:
            vdist_pct    = abs(price - vwap) / price
            on_vwap_side = (price >= vwap) if long_ else (price <= vwap)
        except ZeroDivisionError:
            vdist_pct, on_vwap_side = None, False

    ref = _pro_num(result.get("nearest_demand") if long_ else result.get("nearest_supply"))
    near_zone = bool(price and ref and abs(price - ref) / price <= PRO_NEAR_PCT)

    tp = result.get("trade_plan") or {}
    rr_num = _pro_num(tp.get("rr"))
    if rr_num is None:
        rr_raw = tp.get("rr")
        if isinstance(rr_raw, str) and ":" in rr_raw:
            rr_num = _pro_num(rr_raw.split(":")[-1])
    room_r = rr_num   # room to first target approximated by the planned R:R
    stop_ok = bool(tp.get("stop_loss"))

    ad = result.get("alert_diagnostics") or {}
    comp_str = " ".join(str(c) for c in (ad.get("components") or [])).upper()
    struct_ok = (("BOS" in comp_str or "CHOCH" in comp_str or "STRUCTURE" in comp_str)
                 or result.get("strict_direction") == direction)
    sweep_recent = ("SWEEP" in comp_str)

    vol_conf = bool(result.get("volume_confirmed"))
    if not vol_conf:
        rv = _pro_num(result.get("rvol_value"))
        vol_conf = bool(rv is not None and rv >= 1.5)

    cvd_dir   = result.get("cvd_direction")
    cvd_agree = (cvd_dir == "Bullish" and long_) or (cvd_dir == "Bearish" and not long_)

    vol       = result.get("volatility")
    vol_label = vol.get("label") if isinstance(vol, dict) else None

    htf_bias = (swing_ctx or {}).get("htf_bias") or (swing_ctx or {}).get("bias")
    if not htf_bias:
        htf_bias = ((result.get("analyst") or {}).get("context") or {}).get("htf_bias")
    htf_bias = str(htf_bias or "").lower()
    htf_agree = ("bull" in htf_bias and long_) or ("bear" in htf_bias and not long_)

    prime = bool(get_prime_window_state(inst).get("prime"))

    ctx = {
        "direction": direction, "vdist_pct": vdist_pct, "on_vwap_side": on_vwap_side,
        "near_zone": near_zone, "room_r": room_r, "rr_num": rr_num, "stop_ok": stop_ok,
        "struct_ok": struct_ok, "sweep_recent": sweep_recent, "vol_conf": vol_conf,
        "cvd_agree": cvd_agree, "vol_label": vol_label, "htf_agree": htf_agree,
        "prime": prime, "market_type": _pro_market_type(result, vol_label),
    }

    models = {}
    for m in PRO_REVIEW_MODELS:
        try:
            models[m] = _pro_eval_model(m, ctx)
        except Exception as exc:   # per-model fail-open
            models[m] = _pro_review_model_stub(m, "model error (%s)" % exc)

    sel = pro_review_model_for(inst)
    if sel not in models:
        sel = _PRO_REVIEW_DEFAULT_MODEL
    return {
        "engine_enabled":   _pro_review_engine_enabled(),
        "gate_enabled":     _pro_review_gate_enabled(),
        "selected_model":   sel,
        "available_models": list(PRO_REVIEW_MODELS),
        "models":           models,
        "active":           models[sel],
    }


# ── Trade Debate Engine (Bull vs Bear vs Decision Judge) ──────────────────────
# A pre-READY internal debate computed from the FINAL assembled full_analysis
# result. Each analyst's CASE STRENGTH is DERIVED (never fabricated) from the
# already-computed per-direction Edge cards (result["directions"]): Bull = the Long
# case, Bear = the Short case. The Judge compares the two confidences and decides
# whether the edge is decisive enough — and aligned with the gate's chosen
# direction — to support the trade. DISPLAY-ONLY by default; the money-path veto is
# behind _trade_debate_gate_enabled() (default OFF) and can only DEMOTE to WAIT.
def _debate_side(block):
    """Build one analyst's case (Bull or Bear) from a per-direction Edge card.
    Pure + fail-open: a missing/empty card yields a zero-confidence, no-reason side
    (which can never win a debate)."""
    block   = block or {}
    eb      = block.get("edge_breakdown") or {}
    conf    = int(block.get("edge_score") or 0)
    grade   = block.get("edge_grade") or "—"
    reasons = [str(r) for r in (eb.get("reasons") or []) if r]
    # Strongest evidence = the highest-credited Edge component for this side.
    strongest, best_pts = "—", None
    for _item in (eb.get("score_breakdown") or []):
        _pts = _item.get("points") if isinstance(_item, dict) else None
        if isinstance(_pts, (int, float)) and _pts > 0 and (best_pts is None or _pts > best_pts):
            best_pts, strongest = _pts, (_item.get("label") or strongest)
    if strongest == "—" and reasons:
        strongest = reasons[0]
    risks = [str(x) for x in (eb.get("risks") or []) if x]
    return {
        "confidence":         conf,
        "grade":              grade,
        "reasons":            reasons,
        "strongest_evidence": strongest,
        "biggest_risk":       (risks[0] if risks else "None identified"),
    }


def _trade_debate_neutral_block(reason="Trade debate unavailable."):
    """Fully-populated, SAFE debate block (fail-open fallback + market-closed +
    disabled stub). EVERY key the /status serializer, dashboard and Discord card
    read MUST exist here so the single-return-path / hard-indexed-consumer invariant
    holds in every branch. veto_would_fire stays False so a stub can NEVER demote a
    trade when the gate is armed."""
    side = {"confidence": 0, "grade": "—", "reasons": [],
            "strongest_evidence": "—", "biggest_risk": "—"}
    return {
        "engine_enabled":  _trade_debate_engine_enabled(),
        "gate_enabled":    _trade_debate_gate_enabled(),
        "bull":            dict(side),
        "bear":            dict(side),
        "judge": {
            "winning_side":      "Balanced",
            "confidence_gap":    0,
            "edge_significant":  False,
            "too_balanced":      True,
            "final_verdict":     "WAIT",
            "reason_winner_won": reason,
            "reason_loser_lost": reason,
        },
        "veto_would_fire": False,
        "summary":         reason,
    }


def compute_trade_debate(result, strict=None):
    """Run the Bull/Bear/Judge debate over the assembled result. Pure + fail-open.

    Confidence = each side's per-direction Edge Score (case strength, already
    computed; the favored side mirrors the authoritative edge_score, the other is
    independently scored). Judge rules (spec): gap < TRADE_DEBATE_MIN_GAP -> too
    balanced -> WAIT; a decisive winner needs gap > TRADE_DEBATE_DECISIVE_GAP. The
    armed-gate veto (veto_would_fire) fires only when the gate verdict is ACTIONABLE
    and the debate is NOT a decisive winner ALIGNED with the trade's direction —
    i.e. balanced, weak (15-20 band), or pointing the other way. It can only DEMOTE."""
    dirs = result.get("directions") or {}
    bull = _debate_side(dirs.get("Long"))
    bear = _debate_side(dirs.get("Short"))
    bc, brc = bull["confidence"], bear["confidence"]
    gap = abs(bc - brc)
    if bc > brc:
        winning_side, win, lose = "Bull", bull, bear
    elif brc > bc:
        winning_side, win, lose = "Bear", bear, bull
    else:
        winning_side, win, lose = "Balanced", bull, bear

    too_balanced     = gap < TRADE_DEBATE_MIN_GAP
    edge_significant = gap > TRADE_DEBATE_DECISIVE_GAP
    decisive         = edge_significant and winning_side != "Balanced"

    verdict        = result.get("verdict") or ""
    actionable     = is_actionable(verdict)
    trade_dir      = ready_direction(verdict)   # "Long" / "Short" / None
    winner_aligned = bool(trade_dir and (
        (trade_dir == "Long"  and winning_side == "Bull") or
        (trade_dir == "Short" and winning_side == "Bear")))

    # Armed-gate veto: demote only an actionable verdict the debate does NOT
    # decisively + alignedly support (balanced, weak edge, or wrong direction).
    veto_would_fire = bool(actionable and not (decisive and winner_aligned))
    # TAKE ONLY when the gate verdict is actionable AND the debate is a decisive
    # winner ALIGNED with the trade direction. Every other case (non-actionable,
    # balanced, weak 15-20 edge, or a decisive winner pointing the OTHER way) reports
    # WAIT — the winning side / evidence is still shown, but the Judge never displays
    # a promotional TAKE on a setup it does not actually endorse. This keeps
    # final_verdict == "TAKE" equivalent to "actionable and not veto_would_fire".
    final_verdict   = "TAKE" if (actionable and decisive and winner_aligned) else "WAIT"

    if winning_side == "Balanced":
        reason_winner_won = ("Bull and Bear are evenly matched (%d vs %d) — no decisive edge."
                             % (bc, brc))
        reason_loser_lost = ("Neither side built a %d-point lead, so the tape is too "
                             "balanced to trade." % TRADE_DEBATE_MIN_GAP)
    else:
        loser_name = "Bear" if winning_side == "Bull" else "Bull"
        reason_winner_won = ("%s leads %d to %d (%d-pt edge). Strongest evidence: %s."
                             % (winning_side, win["confidence"], lose["confidence"], gap,
                                win["strongest_evidence"]))
        reason_loser_lost = ("%s trails at %d. Biggest risk: %s."
                             % (loser_name, lose["confidence"], lose["biggest_risk"]))

    if winning_side == "Balanced":
        summary = ("⚖️ Balanced debate — Bull %d vs Bear %d (gap %d < %d). Too balanced → WAIT."
                   % (bc, brc, gap, TRADE_DEBATE_MIN_GAP))
    else:
        _emoji = "🟢" if winning_side == "Bull" else "🔴"
        _opp   = "" if (winner_aligned or not actionable) else " but opposes the setup direction"
        summary = ("%s %s wins %d-%d (gap %d) → %s%s."
                   % (_emoji, winning_side, win["confidence"], lose["confidence"], gap,
                      final_verdict, _opp))

    return {
        "engine_enabled":  _trade_debate_engine_enabled(),
        "gate_enabled":    _trade_debate_gate_enabled(),
        "bull":            bull,
        "bear":            bear,
        "judge": {
            "winning_side":      winning_side,
            "confidence_gap":    gap,
            "edge_significant":  edge_significant,
            "too_balanced":      too_balanced,
            "final_verdict":     final_verdict,
            "reason_winner_won": reason_winner_won,
            "reason_loser_lost": reason_loser_lost,
        },
        "veto_would_fire": veto_would_fire,
        "summary":         summary,
    }


# ── Unified Analyst Report (DISPLAY-ONLY) ────────────────────────────────────
# ONE cohesive thesis that CONSUMES the already-assembled sub-engines on `result`
# (analyst / trade_debate / confidence_governor / trade_memory(_context) /
# volatility / strategy_engine / news_filter) — it NEVER recomputes them and has NO
# veto of its own. It answers, in one place: what's the trade, why it works, the
# evidence for / against, what would raise confidence, what invalidates it / when to
# bail early, and a 3-outcome probability estimate. Lives entirely on top of the
# assembled result (after the authoritative verdict) so the strict gate, every
# strategy/alert and all goldens are untouched. Pure builder + FAIL-OPEN.
def _analyst_report_enabled():
    """Unified Analyst Report DISPLAY layer — ON by default (fail-open). Env
    ANALYST_REPORT_ENABLED=0 hard-disables it as an emergency kill-switch. There is
    NO money-path veto for this layer (it only consumes other engines)."""
    return os.environ.get("ANALYST_REPORT_ENABLED", "1").strip().lower() not in ("0", "false", "no", "off")


def _ar_pct_split(cont, rng, rev):
    """Normalise three non-negative raw scores to integer percentages summing to 100
    (largest fractional parts absorb the rounding remainder). All-zero → near-even."""
    vals = [max(0.0, float(cont or 0)), max(0.0, float(rng or 0)), max(0.0, float(rev or 0))]
    s = sum(vals)
    if s <= 0:
        return [34, 33, 33]
    pct = [v / s * 100.0 for v in vals]
    floored = [int(p) for p in pct]
    rem = 100 - sum(floored)
    order = sorted(range(3), key=lambda i: pct[i] - floored[i], reverse=True)
    for i in range(max(0, rem)):
        floored[order[i % 3]] += 1
    return floored


def _analyst_report_neutral_block(reason="Analyst report unavailable."):
    """Neutral Unified Analyst Report (fail-open / market-closed / disabled). STABLE
    schema — every dashboard + Discord consumer reads exactly these keys."""
    return {
        "engine_enabled":            _analyst_report_enabled(),
        "reviewed":                  False,
        "headline":                  reason,
        "bias":                      "Neutral",
        "stance":                    "NO TRADE",
        "favored_direction":         None,
        "framed_on_position":        False,
        "why_it_works":              [],
        "evidence_for":              [],
        "evidence_against":          [],
        "what_increases_confidence": [],
        "early_exit_triggers":       [],
        "invalidation":              "—",
        "probability": {"continuation": None, "range": None, "reversal": None,
                        "favored_direction": None, "is_estimate": True, "basis": reason},
        "confidence": {"score": None, "threshold": None, "change": None,
                       "direction": "flat", "narrative": reason, "components": []},
        "summary":                   reason,
        "disclaimer":                _ANALYST_REPORT_DISCLAIMER,
        "reason":                    reason,
    }


def compute_analyst_report(result, position_dir=None, prev_conf=None):
    """Build the Unified Analyst Report from the assembled `result`. When
    `position_dir` ("Long"/"Short") is given a live position is held and the thesis
    is framed around THAT direction (continuation = the position keeps working);
    otherwise it frames around the current favored side. `prev_conf` (a stored prior
    confidence snapshot) drives the change narrative. Pure + FAIL-OPEN."""
    if not _analyst_report_enabled():
        return _analyst_report_neutral_block("Analyst report disabled.")
    if not result.get("market_open", False):
        return _analyst_report_neutral_block("Market closed — live analysis paused.")
    try:
        analyst  = result.get("analyst") or {}
        debate   = result.get("trade_debate") or {}
        governor = result.get("confidence_governor") or {}
        mem      = result.get("trade_memory") or {}
        mem_ctx  = result.get("trade_memory_context") or {}
        vol      = result.get("volatility") or {}
        se       = result.get("strategy_engine") or {}
        news     = result.get("news_filter") or {}
        dirs     = result.get("directions") or {}
        verdict  = result.get("verdict") or ""
        actionable = bool(is_actionable(verdict))

        # ── Direction the thesis is framed around ────────────────────────────
        pos_dir = position_dir if position_dir in ("Long", "Short") else None
        if pos_dir:
            fav = pos_dir
        elif actionable and ready_direction(verdict) in ("Long", "Short"):
            fav = ready_direction(verdict)
        elif analyst.get("stronger_side") in ("Long", "Short"):
            fav = analyst.get("stronger_side")
        else:
            le  = float((dirs.get("Long")  or {}).get("edge_score") or 0)
            se_ = float((dirs.get("Short") or {}).get("edge_score") or 0)
            fav = "Long" if le > se_ else "Short" if se_ > le else None
        opp = "Short" if fav == "Long" else "Long" if fav == "Short" else None
        fav_edge = float((dirs.get(fav) or {}).get("edge_score") or 0) if fav else 0.0
        opp_edge = float((dirs.get(opp) or {}).get("edge_score") or 0) if opp else 0.0

        # ── Stance / bias ────────────────────────────────────────────────────
        if pos_dir:
            stance = "MANAGING " + pos_dir.upper()
        elif actionable and fav:
            stance = "READY " + fav.upper()
        elif fav:
            stance = "WAIT"
        else:
            stance = "NO TRADE"
        bias = "Bullish" if fav == "Long" else "Bearish" if fav == "Short" else "Neutral"

        # ── Evidence for / against (framed around the favored side) ───────────
        bull_case = list(analyst.get("bull_case") or [])
        bear_case = list(analyst.get("bear_case") or [])
        if fav == "Short":
            evidence_for, evidence_against = bear_case[:], bull_case[:]
        else:
            evidence_for, evidence_against = bull_case[:], bear_case[:]
        # Historical lens as evidence.
        if mem.get("ready") and isinstance(mem.get("similar_win_rate"), (int, float)):
            wr = mem["similar_win_rate"] * 100
            n  = mem.get("similar_trades_found") or 0
            if mem["similar_win_rate"] >= 0.60:
                evidence_for.append("History favors it: %.0f%% weighted win across %d similar." % (wr, n))
            elif mem["similar_win_rate"] <= 0.40:
                evidence_against.append("History warns: similar setups won only %.0f%% (n=%d)." % (wr, n))
        # Volatility risk.
        vlabel = (vol.get("volatility_label") or "").strip().lower()
        if vlabel == "extreme":
            evidence_against.append("Volatility is extreme — wider stops and fakeouts more likely.")
        # Imminent high-impact news.
        nxt = news.get("next_event") if isinstance(news, dict) else None
        if news.get("within_window") and isinstance(nxt, dict):
            mu = nxt.get("minutes_until")
            evidence_against.append(
                "High-impact %s news (%s) in ~%s min — headline risk." % (
                    nxt.get("country") or "USD", nxt.get("title") or "event",
                    mu if mu is not None else "?"))
        # Debate disagreement.
        dj = debate.get("judge") or {}
        ws = dj.get("winning_side")
        if fav and ws in ("Bull", "Bear"):
            opp_side = (fav == "Long" and ws == "Bear") or (fav == "Short" and ws == "Bull")
            if opp_side and dj.get("confidence_gap"):
                evidence_against.append(
                    "Bull/Bear debate leans %s (gap %s) — momentum may be turning." % (
                        ws, dj.get("confidence_gap")))

        # ── What would raise confidence ──────────────────────────────────────
        what_next = list(analyst.get("what_needs_next") or [])
        score = governor.get("final_confidence_score")
        thr   = governor.get("threshold")
        if isinstance(score, (int, float)) and isinstance(thr, (int, float)) and score < thr and not actionable:
            what_next.append("Lift unified confidence to %d (now %d)." % (int(thr), int(round(score))))

        # ── Early-exit triggers (display-only management hints) ───────────────
        triggers = []
        vwap_v = result.get("vwap_value")
        if fav and isinstance(vwap_v, (int, float)):
            side = "below" if fav == "Long" else "above"
            triggers.append("Price closes %s VWAP (%.2f) against the %s." % (side, vwap_v, fav))
        if fav == "Long" and isinstance(result.get("nearest_supply"), (int, float)):
            triggers.append("Price reaches supply (%.2f) — scale out / tighten." % result["nearest_supply"])
        if fav == "Short" and isinstance(result.get("nearest_demand"), (int, float)):
            triggers.append("Price reaches demand (%.2f) — scale out / tighten." % result["nearest_demand"])
        if fav:
            triggers.append("A 5-minute CHOCH or BOS prints against the %s." % fav)
            cvd_s = (result.get("cvd_state") or "").strip().lower()
            adverse_cvd = "bearish" if fav == "Long" else "bullish"
            if cvd_s and cvd_s == adverse_cvd:
                triggers.append("CVD flips %s (order flow turning against the %s)." % (adverse_cvd, fav))
        if mem_ctx.get("ready"):
            mae = mem_ctx.get("weighted_avg_mae")
            hold = mem_ctx.get("weighted_avg_hold") or mem_ctx.get("weighted_avg_hold_min")
            if isinstance(mae, (int, float)) and mae:
                triggers.append("Drawdown beyond ~%.2fR (similar winners rarely gave back more)." % abs(mae))
            if isinstance(hold, (int, float)) and hold:
                triggers.append("No progress within ~%d min (similar winners resolved faster)." % int(hold))
        triggers = triggers[:6]

        # ── Invalidation ─────────────────────────────────────────────────────
        inval = analyst.get("invalidation") or "—"

        # ── 3-outcome probability (DERIVED HEURISTIC ESTIMATE) ───────────────
        reg = (se.get("market_regime") or "").strip().lower()
        cont_raw = fav_edge
        rev_raw  = opp_edge
        range_raw = max(0.0, 60.0 - abs(fav_edge - opp_edge)) * 0.8
        if "range" in reg or "chop" in reg:
            range_raw += 15.0
            cont_raw = max(0.0, cont_raw - 5.0)
        if "trend" in reg or "break" in reg or "drive" in reg:
            cont_raw += 10.0
        if vlabel == "extreme":
            rev_raw += 10.0
            range_raw += 5.0
        if dj.get("too_balanced"):
            range_raw += 10.0
        if result.get("overextended"):
            rev_raw += 10.0
        if fav and ws in ("Bull", "Bear") and (
                (fav == "Long" and ws == "Bear") or (fav == "Short" and ws == "Bull")):
            rev_raw += 8.0
        basis = "Live signal strength (favored vs opposing case, regime, volatility, debate)."
        wwr = mem_ctx.get("weighted_win_rate") if mem_ctx.get("ready") else None
        if isinstance(wwr, (int, float)):
            hist_cont  = wwr * 100.0
            hist_rev   = (1.0 - wwr) * 100.0 * 0.6
            hist_range = (1.0 - wwr) * 100.0 * 0.4
            wl, wh = 0.65, 0.35
            cont_raw  = wl * cont_raw  + wh * hist_cont
            rev_raw   = wl * rev_raw   + wh * hist_rev
            range_raw = wl * range_raw + wh * hist_range
            basis = ("Blend of live signal strength and historical outcomes "
                     "(%.0f%% weighted win across %d similar trades)." % (
                         wwr * 100, mem_ctx.get("matched") or 0))
        cont_p, range_p, rev_p = _ar_pct_split(cont_raw, range_raw, rev_raw)
        probability = {
            "continuation": cont_p, "range": range_p, "reversal": rev_p,
            "favored_direction": fav, "is_estimate": True, "basis": basis,
        }

        # ── Confidence + change narrative ────────────────────────────────────
        comps = governor.get("confidence_components") or []
        comp_scores = {c.get("name"): c.get("score") for c in comps if isinstance(c, dict)}
        change, cdir = None, "flat"
        if isinstance(score, (int, float)) and prev_conf and isinstance(prev_conf.get("score"), (int, float)):
            change = int(round(score - prev_conf["score"]))
            cdir = "up" if change >= ANALYST_REPORT_CONF_EPS else "down" if change <= -ANALYST_REPORT_CONF_EPS else "flat"
        thr_txt = ("%d" % int(thr)) if isinstance(thr, (int, float)) else "—"
        if not isinstance(score, (int, float)):
            narrative = "Confidence unavailable."
        elif change is None:
            narrative = "Confidence %d (READY threshold %s). First read this session." % (int(round(score)), thr_txt)
        elif cdir == "flat":
            narrative = "Confidence steady at %d (threshold %s)." % (int(round(score)), thr_txt)
        else:
            moved, best = None, 0
            prevc = (prev_conf or {}).get("components") or {}
            for name, sc in comp_scores.items():
                pv = prevc.get(name)
                if isinstance(sc, (int, float)) and isinstance(pv, (int, float)):
                    d = abs(sc - pv)
                    if d > best:
                        best, moved = d, name
            lens_lbl = {"current_setup": "current setup", "live_market": "live market",
                        "ai_reasoning": "AI reasoning", "historical": "historical"}
            why = (" — led by the %s lens" % lens_lbl.get(moved, moved)) if moved else ""
            verb = "rose" if cdir == "up" else "fell"
            narrative = "Confidence %s %d pt%s to %d (threshold %s)%s." % (
                verb, abs(change), "" if abs(change) == 1 else "s",
                int(round(score)), thr_txt, why)
        confidence = {
            "score": int(round(score)) if isinstance(score, (int, float)) else None,
            "threshold": int(thr) if isinstance(thr, (int, float)) else None,
            "change": change, "direction": cdir, "narrative": narrative,
            "components": comps,
        }

        # ── Headline / summary ───────────────────────────────────────────────
        thesis = analyst.get("market_story") or analyst.get("best_trade_idea") or ""
        if pos_dir:
            headline = ("Managing the open %s — %d%% continuation / %d%% range / %d%% reversal. %s" % (
                pos_dir, cont_p, range_p, rev_p, thesis)).strip()
        elif actionable and fav:
            headline = ("%s setup READY — %d%% continuation odds. %s" % (fav, cont_p, thesis)).strip()
        elif fav:
            headline = ("%s leaning but not confirmed. %s" % (
                fav, analyst.get("reason_for_waiting") or thesis)).strip()
        else:
            headline = thesis or "No directional edge — stand aside."

        return {
            "engine_enabled":            True,
            "reviewed":                  True,
            "headline":                  headline,
            "bias":                      bias,
            "stance":                    stance,
            "favored_direction":         fav,
            "framed_on_position":        bool(pos_dir),
            "why_it_works":              evidence_for[:4],
            "evidence_for":              evidence_for,
            "evidence_against":          evidence_against,
            "what_increases_confidence": what_next,
            "early_exit_triggers":       triggers,
            "invalidation":              inval,
            "probability":              probability,
            "confidence":               confidence,
            "summary":                   thesis or headline,
            "disclaimer":                _ANALYST_REPORT_DISCLAIMER,
            "reason":                    None,
        }
    except Exception as exc:
        return _analyst_report_neutral_block("Analyst report error (%s)." % exc)


def _analyst_report_prev(inst):
    """Copy of the stored prior confidence snapshot for `inst` (drives the change
    narrative), or None. Thread-safe."""
    if not inst:
        return None
    with ANALYST_REPORT_LOCK:
        snap = ANALYST_REPORT_PREV_CONF.get(inst)
        return dict(snap) if snap else None


def _analyst_report_update_prev(inst, report):
    """Re-baseline the stored confidence snapshot for `inst` ONLY on a meaningful move
    (|Δ| >= eps) or after the baseline TTL — so the high-frequency /status poll can't
    reset the delta to ~0 every few seconds. Display-only side effect."""
    if not inst or not isinstance(report, dict):
        return
    conf = report.get("confidence") or {}
    score = conf.get("score")
    if not isinstance(score, (int, float)):
        return
    comps = {c.get("name"): c.get("score")
             for c in (conf.get("components") or []) if isinstance(c, dict)}
    now = datetime.now(timezone.utc)
    with ANALYST_REPORT_LOCK:
        prev = ANALYST_REPORT_PREV_CONF.get(inst)
        rebaseline = True
        if prev and isinstance(prev.get("score"), (int, float)):
            moved = abs(score - prev["score"]) >= ANALYST_REPORT_CONF_EPS
            ts = prev.get("ts")
            aged = (not ts) or ((now - ts).total_seconds() >= ANALYST_REPORT_BASELINE_TTL)
            rebaseline = bool(moved or aged)
        if rebaseline:
            ANALYST_REPORT_PREV_CONF[inst] = {"score": score, "components": comps, "ts": now}


# ---------------------------------------------------------------------------
# Entry Quality Engine (LOCATION-aware) — DISPLAY by default; flag-gated veto.
# ---------------------------------------------------------------------------
# Separate from the strict gate (which decides IF a setup is valid). This layer
# answers WHETHER THIS IS A GOOD PLACE TO ENTER: distance to nearest resistance /
# support, % of the current impulse already completed, ATR extension from the mean
# (VWAP), pullback quality, momentum accel/decel, whether a liquidity sweep has
# completed, and three location traps (chasing a breakout, buying near a swing
# high, selling near a swing low). A technically-correct setup can still be
# rejected for poor LOCATION. Score 0-100 (>=90 Excellent / >=80 Good / >=70
# Acceptable / <70 Reject) — and a sub-70 reject only DEMOTES when the veto is
# armed AND confidence is NOT extremely high (Edge >= ENTRY_QUALITY_OVERRIDE_EDGE).
# Direction-aware; EVERY sub-score FAILS OPEN to a neutral fraction so missing
# alert data can never manufacture a false reject.
_EQ_NEUTRAL_FRAC = 0.70  # fail-open fraction when a sub-score's inputs are missing
# (key, label, weight) — weights sum to 100. LOCATION-only; orthogonal to Edge.
ENTRY_QUALITY_COMPONENTS = (
    ("room_to_resistance",  "Room to Resistance", 12),
    ("cushion_at_support",  "Cushion at Support", 12),
    ("impulse_completed",   "Impulse Completed",  12),
    ("atr_extension",       "ATR Extension",      12),
    ("pullback_quality",    "Pullback Quality",   12),
    ("momentum",            "Momentum",           10),
    ("sweep_complete",      "Liquidity Sweep",    10),
    ("not_chasing",         "Not Chasing",         8),
    ("not_near_swing_high", "Not At Swing High",   6),
    ("not_near_swing_low",  "Not At Swing Low",    6),
)


def _eq_grade(score):
    if score is None:
        return None
    if score >= 90:
        return "Excellent"
    if score >= 80:
        return "Good"
    if score >= ENTRY_QUALITY_MIN_SCORE:
        return "Acceptable"
    return "Poor"


def _eq_lin(x, lo, hi):
    """0..1 as x sweeps lo..hi (clamped). Returns None if x is None."""
    if x is None:
        return None
    if hi == lo:
        return 1.0
    return max(0.0, min(1.0, (x - lo) / (hi - lo)))


def _entry_quality_neutral_block(reason="Entry Quality engine disabled.", direction=None):
    """Inert Entry Quality block — veto_would_fire=False so it can NEVER demote.
    Used when the engine is disabled, the inputs are missing, the market is closed,
    or compute_entry_quality raised (fail-open)."""
    return {
        "engine_enabled":   _entry_quality_engine_enabled(),
        "gate_enabled":     _entry_quality_gate_enabled(),
        "available":        False,
        "direction":        direction,
        "score":            None,
        "grade":            None,
        "components":       [],
        "flags":            {},
        "reject":           False,
        "override_applied": False,
        "veto_would_fire":  False,
        "min_score":        ENTRY_QUALITY_MIN_SCORE,
        "override_edge":    ENTRY_QUALITY_OVERRIDE_EDGE,
        "edge_score":       None,
        "summary":          reason,
        "why_not_trade":    "",
        "strong_reject":    False,
        "strong_reject_score": ENTRY_QUALITY_STRONG_REJECT,
        "raw":              {},
        "improvements":     [],
        "improvement_plan": [],
        "projected_low":    None,
        "projected_high":   None,
        "better_entry_zone": None,
        "chasing_warning":  None,
        "entry_plan":       None,
        "verdict_label":    None,
        "verdict_tier":     None,
        "entry_planner":    None,
        "plain_english":    reason,
        "final_verdict":    None,
    }


def compute_entry_quality(result, strict=None, swing_ctx=None):
    """LOCATION-aware entry-quality score (0-100) computed from the FINAL assembled
    result. DISPLAY-ONLY here; the flag-gated veto is wired in full_analysis and can
    only DEMOTE. Direction = the gate's strict_direction (or its forming candidate).
    Every sub-score fails open to a neutral fraction, so missing data yields ~70
    (Acceptable), never a false reject."""
    direction = (result.get("strict_direction")
                 or result.get("gate_candidate")
                 or (strict.get("candidate") if isinstance(strict, dict) else None))
    price = result.get("current_price")
    if direction not in ("Long", "Short") or not price:
        return _entry_quality_neutral_block(
            "No directional candidate — entry location not evaluated.", direction=direction)
    is_long = (direction == "Long")

    vol = result.get("volatility") or {}
    atr = vol.get("atr_pts")
    unit = atr if (isinstance(atr, (int, float)) and atr > 0) else (price * 0.0015)

    # Mode-correct ATR for the EXTENSION metric ONLY (don't measure a session-VWAP
    # distance in 1-minute ATRs for SWING). SCALP: the 1-minute volatility ATR
    # (== unit, so SCALP scoring stays byte-identical). SWING: a higher-timeframe
    # ATR (1H → 4H → Daily) from swing_ctx, NEVER the 1-minute ATR. If no HTF ATR is
    # present in SWING we mark the extension UNAVAILABLE (ext_atr=None) and fail OPEN
    # to the neutral fraction — mixing in the 1m ATR is forbidden, since that is the
    # exact timeframe-mix that produced implausible "13 ATR" readings. The timeframe
    # label is surfaced raw on the dashboard so it can never be silently mixed.
    ext_atr, ext_tf = unit, "1m"
    if TRADING_MODE == "SWING":
        ext_atr, ext_tf = None, "HTF unavailable"
        if isinstance(swing_ctx, dict):
            for _ak, _alabel in (("atr_1h", "1H"), ("atr_4h", "4H"), ("atr_daily", "Daily")):
                _av = swing_ctx.get(_ak)
                if isinstance(_av, (int, float)) and _av > 0:
                    ext_atr, ext_tf = float(_av), _alabel
                    break

    resistance = result.get("nearest_supply")   # level ABOVE price
    support    = result.get("nearest_demand")   # level BELOW price
    vwap       = result.get("vwap_value")

    # Profit-direction ("target") and entry-side ("cushion") levels.
    target_level = resistance if is_long else support
    entry_level  = support    if is_long else resistance

    fracs, details = {}, {}

    # 1) Room to resistance/target — want room to run in the profit direction.
    if target_level and unit:
        room = (target_level - price) if is_long else (price - target_level)
        if room <= 0:
            fracs["room_to_resistance"] = 1.0   # broke past → open road (chasing scored below)
            details["room_to_resistance"] = "clear (price beyond level)"
        else:
            fracs["room_to_resistance"] = _eq_lin(room / unit, 0.3, 2.0)
            details["room_to_resistance"] = "%.2f ATR to target" % (room / unit)
    else:
        fracs["room_to_resistance"] = _EQ_NEUTRAL_FRAC
        details["room_to_resistance"] = "no level"

    # 2) Cushion at support — entering near the trade-side zone = tight risk.
    if entry_level and unit:
        dist = (price - entry_level) if is_long else (entry_level - price)
        if dist < 0:
            fracs["cushion_at_support"] = 0.20   # price beyond the zone (broken)
            details["cushion_at_support"] = "beyond zone"
        else:
            fracs["cushion_at_support"] = 1.0 - (_eq_lin(dist / unit, 0.2, 2.5) or 0.0)
            details["cushion_at_support"] = "%.2f ATR from zone" % (dist / unit)
    else:
        fracs["cushion_at_support"] = _EQ_NEUTRAL_FRAC
        details["cushion_at_support"] = "no zone"

    # 3) Impulse completed — early in the leg = good; late (>~80%) = poor.
    impulse_pct = None
    if entry_level and target_level and target_level != entry_level:
        span = (target_level - entry_level) if is_long else (entry_level - target_level)
        if span:
            prog = ((price - entry_level) / span) if is_long else ((entry_level - price) / span)
            prog = max(0.0, min(1.0, prog))
            impulse_pct = int(round(prog * 100))
            fracs["impulse_completed"] = 1.0 - (_eq_lin(prog, 0.45, 0.95) or 0.0)
            details["impulse_completed"] = "%d%% of leg done" % impulse_pct
        else:
            fracs["impulse_completed"] = _EQ_NEUTRAL_FRAC
            details["impulse_completed"] = "n/a"
    else:
        fracs["impulse_completed"] = _EQ_NEUTRAL_FRAC
        details["impulse_completed"] = "no leg"

    # 4) ATR extension from the mean (VWAP) — far beyond mean in trade dir = stretched.
    #    Uses the MODE-CORRECT ATR (ext_atr / ext_tf): SCALP 1m, SWING 1H/4H/Daily.
    ext = None
    ext_decision = "VWAP unavailable"
    if vwap and ext_atr:
        ext = ((price - vwap) if is_long else (vwap - price)) / ext_atr
        if ext <= 0:
            fracs["atr_extension"] = 1.0   # at/below the mean (for a long) = not extended
            details["atr_extension"] = "%.2f ATR from VWAP (%s)" % (ext, ext_tf)
            ext_decision = "At/below VWAP — not extended"
        else:
            # Graduated ATR-extension scoring (requirement #3): points decay in 1-ATR
            # bands instead of snapping straight to 0 once stretched. Max == the
            # component weight (12), so this stays a 0..1 fraction.
            if ext <= 1.0:
                _eq_ext_pts = 12
            elif ext <= 2.0:
                _eq_ext_pts = 10
            elif ext <= 3.0:
                _eq_ext_pts = 7
            elif ext <= 4.0:
                _eq_ext_pts = 4
            elif ext <= 5.0:
                _eq_ext_pts = 2
            else:
                _eq_ext_pts = 0
            fracs["atr_extension"] = _eq_ext_pts / 12.0
            details["atr_extension"] = "%.2f ATR beyond VWAP (%s)" % (ext, ext_tf)
            if ext <= 1.0:
                ext_decision = "Near VWAP — healthy"
            elif ext <= 2.0:
                ext_decision = "Stretched from VWAP"
            else:
                ext_decision = "Overextended — chasing risk"
    else:
        fracs["atr_extension"] = _EQ_NEUTRAL_FRAC
        if vwap and not ext_atr:
            # VWAP exists but no mode-correct ATR (SWING without HTF ATR): withhold the
            # extension rather than computing it from the wrong timeframe.
            details["atr_extension"] = "HTF ATR unavailable (%s)" % ext_tf
            ext_decision = "HTF ATR unavailable"
        else:
            details["atr_extension"] = "no VWAP"

    # 5) Pullback quality — entering on a controlled retrace (calmer side of VWAP,
    #    near the zone), not at full extension.
    if vwap and entry_level and unit:
        below_mean = (price <= vwap) if is_long else (price >= vwap)
        adist = abs(price - entry_level) / unit
        frac = (0.60 if below_mean else 0.25) + 0.40 * (1.0 - (_eq_lin(adist, 0.2, 2.0) or 0.0))
        fracs["pullback_quality"] = max(0.0, min(1.0, frac))
        details["pullback_quality"] = "retraced toward zone" if below_mean else "above mean"
    else:
        fracs["pullback_quality"] = _EQ_NEUTRAL_FRAC
        details["pullback_quality"] = "insufficient data"

    # 6) Momentum accel/decel — heuristic (alert-driven, limited OHLC): CVD direction
    #    alignment + RVOL + volume confirmation.
    cvd_dir = (result.get("cvd_direction") or "").lower()
    rvol = result.get("rvol_value")
    volume_confirmed = bool(result.get("volume_confirmed"))
    if cvd_dir in ("bullish", "bearish") or isinstance(rvol, (int, float)) or volume_confirmed:
        m = 0.5
        if cvd_dir == ("bullish" if is_long else "bearish"):
            m += 0.25
        elif cvd_dir == ("bearish" if is_long else "bullish"):
            m -= 0.25
        if isinstance(rvol, (int, float)) and rvol >= 1.3:
            m += 0.15
        if volume_confirmed:
            m += 0.10
        fracs["momentum"] = max(0.0, min(1.0, m))
        details["momentum"] = "CVD %s%s%s" % (
            cvd_dir or "?",
            (" · RVOL %.1f" % rvol) if isinstance(rvol, (int, float)) else "",
            " · vol✓" if volume_confirmed else "")
    else:
        fracs["momentum"] = _EQ_NEUTRAL_FRAC
        details["momentum"] = "no order-flow"

    # 7) Liquidity sweep complete — a swept stop run before entry is a PLUS.
    conf = result.get("confluences")
    sweep_present = None
    if isinstance(conf, dict):
        if "liquidity_sweep" in conf:
            sweep_present = bool(conf.get("liquidity_sweep"))
        else:
            for _sub in conf.values():
                if isinstance(_sub, dict) and _sub.get("liquidity_sweep"):
                    sweep_present = True
                    break
    if sweep_present is True:
        fracs["sweep_complete"] = 1.0
        details["sweep_complete"] = "sweep confirmed"
    elif sweep_present is False:
        fracs["sweep_complete"] = 0.55
        details["sweep_complete"] = "no sweep"
    else:
        fracs["sweep_complete"] = _EQ_NEUTRAL_FRAC
        details["sweep_complete"] = "unknown"

    # 8) Not chasing a breakout — price extended beyond the broken level / the mean.
    chasing = False
    if target_level and unit:
        room = (target_level - price) if is_long else (price - target_level)
        if room <= 0 and (abs(price - target_level) / unit) > 0.5:
            chasing = True
    if ext is not None and ext > 2.0:
        chasing = True
    fracs["not_chasing"] = 0.15 if chasing else 1.0
    details["not_chasing"] = "chasing" if chasing else "ok"

    # 9/10) Swing-high/low traps — buying near a swing high (long) or selling near a
    #       swing low (short). The opposite trap is N/A for the active direction (full
    #       marks). Uses swing_ctx extremes when present (SWING), else the nearest zone
    #       as a proxy (SCALP).
    near_high = near_low = False
    highs = (swing_ctx or {}).get("swing_highs") if isinstance(swing_ctx, dict) else None
    lows  = (swing_ctx or {}).get("swing_lows")  if isinstance(swing_ctx, dict) else None
    if is_long:
        ref_high = None
        if highs:
            above = [h for h in highs if h and h >= price]
            ref_high = min(above) if above else None
        if ref_high is None and resistance and resistance >= price:
            ref_high = resistance
        if ref_high and unit and 0 <= (ref_high - price) / unit < 0.4:
            near_high = True
        fracs["not_near_swing_high"] = 0.2 if near_high else 1.0
        fracs["not_near_swing_low"]  = 1.0   # N/A for a long
        details["not_near_swing_high"] = "at swing high" if near_high else "clear"
        details["not_near_swing_low"]  = "n/a (long)"
    else:
        ref_low = None
        if lows:
            below = [l for l in lows if l and l <= price]
            ref_low = max(below) if below else None
        if ref_low is None and support and support <= price:
            ref_low = support
        if ref_low and unit and 0 <= (price - ref_low) / unit < 0.4:
            near_low = True
        fracs["not_near_swing_low"]  = 0.2 if near_low else 1.0
        fracs["not_near_swing_high"] = 1.0   # N/A for a short
        details["not_near_swing_low"]  = "at swing low" if near_low else "clear"
        details["not_near_swing_high"] = "n/a (short)"

    # ── Assemble the 0-100 location score from the weighted sub-scores. ──
    components = []
    total = 0.0
    for key, label, weight in ENTRY_QUALITY_COMPONENTS:
        frac = fracs.get(key)
        if frac is None:
            frac = _EQ_NEUTRAL_FRAC
        pts = weight * frac
        total += pts
        components.append({
            "key": key, "label": label, "max": weight,
            "score": round(pts, 1), "detail": details.get(key, ""),
        })
    score = int(round(max(0.0, min(100.0, total))))
    score_uncapped = score

    # Good room-to-target must NEVER override a BAD location. When a HARD location
    # trap is present (chasing / overextended / impulse nearly done / sitting on a
    # swing extreme), the score can't sit in the Acceptable band on the strength of
    # room or cushion alone — cap it just below the Reject line. Cap DOWN only: it can
    # never raise a score, so it only makes the engine MORE conservative (safe for a
    # demote-only veto). SCALP common path is unaffected (traps already score < 70).
    hard_trap = bool(chasing
                     or (ext is not None and ext > 2.0)
                     or (impulse_pct is not None and impulse_pct >= 90)
                     or near_high or near_low)
    if hard_trap and score >= ENTRY_QUALITY_MIN_SCORE:
        score = ENTRY_QUALITY_MIN_SCORE - 1
    cap_release = max(0, score_uncapped - score)   # points the hard-trap cap removed
    grade = _eq_grade(score)

    edge_score = result.get("edge_score")
    reject = score < ENTRY_QUALITY_MIN_SCORE
    strong_reject = score < ENTRY_QUALITY_STRONG_REJECT
    override_applied = bool(reject and isinstance(edge_score, (int, float))
                           and edge_score >= ENTRY_QUALITY_OVERRIDE_EDGE)
    veto_would_fire = bool(reject and not override_applied)

    # Worst two LOCATION factors → the human "why not enter here" reason.
    worst = sorted(components, key=lambda c: (c["score"] - c["max"]))[:2]
    why = ""
    if reject:
        why = "Poor entry location — " + "; ".join(
            "%s (%s)" % (c["label"].lower(), c["detail"]) for c in worst if c["detail"])
        if override_applied:
            why += " — overridden (Edge %s ≥ %d)." % (edge_score, ENTRY_QUALITY_OVERRIDE_EDGE)

    flags = {
        "chasing_breakout": bool(chasing),
        "near_swing_high":  bool(near_high),
        "near_swing_low":   bool(near_low),
        "sweep_complete":   (bool(sweep_present) if sweep_present is not None else None),
        "overextended":     bool(ext is not None and ext > 2.0),
        "impulse_pct":      impulse_pct,
    }

    # ── What Improves This Trade (requirement #2) — per-condition point deltas + the
    #    score those fixes would project to. The "improvable" components are the
    #    location factors a pullback / fresh confirmation can fix (a deeper pullback
    #    simultaneously eases extension, tightens cushion AND opens room-to-target). A
    #    liquidity SWEEP can also be waited for, so it is improvable too.
    _improvable = ("impulse_completed", "atr_extension", "pullback_quality",
                   "cushion_at_support", "momentum", "room_to_resistance",
                   "sweep_complete", "not_chasing",
                   "not_near_swing_high" if is_long else "not_near_swing_low")
    _imp_labels = {
        "atr_extension":       "Price pulls back closer to VWAP",
        "pullback_quality":    "Controlled pullback into the zone",
        "cushion_at_support":  ("Fresh demand retest (tighter risk)" if is_long
                                else "Fresh supply retest (tighter risk)"),
        "impulse_completed":   "Enter earlier in the leg (wait for a 38–50% pullback)",
        "room_to_resistance":  "Deeper pullback opens room to target",
        "momentum":            ("CVD / order-flow confirms buyers" if is_long
                                else "CVD / order-flow confirms sellers"),
        "sweep_complete":      "Liquidity sweep occurs first",
        "not_chasing":         "Stop chasing — enter on the retrace",
        "not_near_swing_high": "Avoid entering at the swing high",
        "not_near_swing_low":  "Avoid entering at the swing low",
    }
    _eq_weight = {_k: _w for _k, _l, _w in ENTRY_QUALITY_COMPONENTS}
    improvements = []
    for _k in _improvable:
        _f = fracs.get(_k)
        if _f is None or _f >= 0.999:
            continue
        _pts = int(round(_eq_weight.get(_k, 0) * (1.0 - _f)))
        if _pts < 1:
            continue
        improvements.append({"text": _imp_labels.get(_k, _k), "points": _pts})
    improvements.sort(key=lambda it: -it["points"])
    # A HARD location trap caps the displayed score below the Reject line; fixing the
    # trap also releases that penalty, so surface it as its own delta — otherwise the
    # per-condition points wouldn't add up from the (capped) displayed score.
    if cap_release > 0:
        improvements.append({
            "text": "Reset to a fresh pullback / retest (clears the over-extension penalty)",
            "points": cap_release,
        })
    improvement_plan = [it["text"] for it in improvements]

    def _projected(target):
        tot = 0.0
        for _k, _l, _w in ENTRY_QUALITY_COMPONENTS:
            _f = fracs.get(_k)
            if _f is None:
                _f = _EQ_NEUTRAL_FRAC
            if _k in _improvable and _f < target:
                _f = target
            tot += _w * _f
        return int(round(max(0.0, min(100.0, tot))))

    projected_low  = max(score, _projected(0.80))
    projected_high = max(projected_low, _projected(1.0))

    # ── Better Entry Zone (requirement #1) — where a smarter entry sits: a VWAP
    #    pullback, the nearest demand/supply zone, the 50% impulse pullback, or a prior
    #    breakout/retest level. Only references on the PULLBACK side of price count
    #    (below for a long, above for a short). Shown only when the location is poor.
    better_entry_zone = None
    if reject and unit:
        _refs = []
        if isinstance(vwap, (int, float)) and ((vwap < price) if is_long else (vwap > price)):
            _refs.append((vwap, "near VWAP"))
        if entry_level and ((entry_level < price) if is_long else (entry_level > price)):
            _refs.append((entry_level, "demand zone" if is_long else "supply zone"))
            _refs.append(((price + entry_level) / 2.0, "50% impulse pullback"))
        if target_level:
            _broke = (target_level - price) if is_long else (price - target_level)
            if _broke <= 0 and ((target_level < price) if is_long else (target_level > price)):
                _refs.append((target_level, "prior breakout retest"))
        if _refs:
            _lv = [r[0] for r in _refs]
            _lo, _hi = min(_lv), max(_lv)
            if (_hi - _lo) < 1e-9:
                _lo, _hi = _lo - 0.15 * unit, _hi + 0.15 * unit      # single level → ±band
            elif (_hi - _lo) > 1.2 * unit:
                if is_long:
                    _lo = _hi - 1.2 * unit          # keep the shallower (nearer) side
                else:
                    _hi = _lo + 1.2 * unit
            better_entry_zone = {
                "low":     round(min(_lo, _hi), 2),
                "high":    round(max(_lo, _hi), 2),
                "reasons": [r[1] for r in _refs],
            }

    # ── Chasing Warning (requirement #4) — price > 3 ATR beyond VWAP (mode-correct). ─
    chasing_warning = None
    if ext is not None and ext > 3.0:
        chasing_warning = (
            "Price is %.1f ATR beyond VWAP (%s) — far from fair value. Do not enter unless "
            "there is a fresh pullback/retest or strong order-flow confirmation."
            % (ext, ext_tf))

    # ── Entry Plan (requirement #5) — the next actionable step instead of a bare WAIT. ─
    entry_plan = None
    if reject and better_entry_zone:
        _then = [
            ("Bullish" if is_long else "Bearish") + " rejection candle at the zone",
            ("Bullish" if is_long else "Bearish") + " CVD / order-flow confirmation",
        ]
        if entry_level:
            _stop = (("Stop below the demand zone (%.2f)" % entry_level) if is_long
                     else ("Stop above the supply zone (%.2f)" % entry_level))
        else:
            _stop = "Stop below the entry zone" if is_long else "Stop above the entry zone"
        if target_level and (((target_level - price) if is_long else (price - target_level)) > 0):
            _tgt = ("Target back toward %.2f (%s)"
                    % (target_level, "resistance" if is_long else "support"))
        else:
            _tgt = "Target the recent %s / next structure level" % ("high" if is_long else "low")
        entry_plan = {
            "wait_for":     ("Wait for a pullback into %.2f – %.2f"
                             % (better_entry_zone["low"], better_entry_zone["high"])),
            "then_require": _then,
            "stop":         _stop,
            "target":       _tgt,
        }

    raw = {
        "price":            round(price, 2) if isinstance(price, (int, float)) else None,
        "vwap":             round(vwap, 2) if isinstance(vwap, (int, float)) else None,
        "distance_from_vwap": (round(price - vwap, 2)
                               if (isinstance(price, (int, float)) and isinstance(vwap, (int, float)))
                               else None),
        "atr":              round(ext_atr, 4) if isinstance(ext_atr, (int, float)) else None,
        "atr_timeframe":    ext_tf,
        "atr_extension":    (round(abs(price - vwap) / ext_atr, 2) if (vwap and ext_atr) else None),
        "atr_extension_signed": (round(ext, 2) if ext is not None else None),
        "atr_extension_decision": ext_decision,
    }

    # Plain-English explanation: direction can be right while the LOCATION is wrong.
    if reject:
        _bits = []
        if impulse_pct is not None and impulse_pct >= 80:
            _bits.append("the impulse leg is nearly complete")
        if ext is not None and ext > 2.0:
            _bits.append("price is overextended from VWAP")
        elif ext is not None and ext > 1.0:
            _bits.append("price is stretched from VWAP")
        if chasing:
            _bits.append("the entry would be chasing the move")
        if near_high or near_low:
            _bits.append("price is sitting at a swing %s" % ("high" if is_long else "low"))
        _cause = (" " + "; ".join(_bits) + ".") if _bits else ""
        _lead = ("Bad entry location — do not chase." if strong_reject
                 else "The trade idea may be directionally correct, but the entry LOCATION is poor.")
        plain_english = _lead + _cause + " Wait for a pullback or fresh confirmation before entering."
        if override_applied:
            plain_english += (" (Edge %s ≥ %d overrides the location veto.)"
                              % (edge_score, ENTRY_QUALITY_OVERRIDE_EDGE))
    else:
        plain_english = ("Entry location is acceptable (%s) — direction and timing line up and no "
                         "major location traps are present." % (grade or "OK"))

    # ── Verdict label (requirement #6) — a STRONG Edge with a poor LOCATION is "WAIT
    #    FOR BETTER ENTRY", not "NO TRADE": Entry Quality is the execution filter, not
    #    the setup-quality gate. DISPLAY-ONLY (the flag-gated veto wiring is unchanged).
    _edge_strong = isinstance(edge_score, (int, float)) and edge_score >= 70
    if not reject:
        verdict_label, verdict_tier = "OK ENTRY", "ok"
    elif override_applied:
        verdict_label, verdict_tier = "ENTER · EDGE OVERRIDE", "caution"
    elif _edge_strong:
        verdict_label, verdict_tier = "WAIT FOR BETTER ENTRY", "better_entry"
    elif strong_reject:
        verdict_label, verdict_tier = "WAIT · BAD LOCATION", "bad"
    else:
        verdict_label, verdict_tier = "CAUTION · POOR LOCATION", "caution"

    # ── Entry Planner (DISPLAY-ONLY synthesis) ────────────────────────────────
    # Reframes the LOCATION score into an actionable entry PLAN rather than a bare
    # reject: the current problems, a best-entry zone (ideal / acceptable range /
    # aggressive / conservative), what to wait for, and the concrete triggers that
    # would lift Entry Quality into the Good band — with an estimated quality /
    # confidence and a grounded suggested entry / stop / target. PURELY ADDITIVE: it
    # only re-reads values already computed above; it never changes the score, the
    # veto, the verdict, or the money path. Every number is grounded — null (not a
    # fabricated value) whenever it cannot be derived.
    def _eq_px(v):
        return round(v, 2) if isinstance(v, (int, float)) else None

    # 1) CURRENT ENTRY — only EVIDENCE-BACKED problems. A sub-score that merely
    #    failed OPEN on missing data (the neutral 0.70 fallback) is UNKNOWN, not a
    #    problem, so those detail markers are excluded. Ranked by weighted points lost.
    _eq_missing_markers = ("no level", "no zone", "no leg", "n/a", "no vwap",
                           "htf atr unavailable", "insufficient data",
                           "no order-flow", "unknown")
    _eq_problem_label = {
        "room_to_resistance":  "Limited room to target",
        "cushion_at_support":  "Wide risk — far from the trade-side zone",
        "impulse_completed":   "Late in the move — impulse nearly done",
        "atr_extension":       "Overextended from VWAP",
        "pullback_quality":    "Weak pullback into the zone",
        "momentum":            "Order flow not confirming",
        "sweep_complete":      "No liquidity sweep yet",
        "not_chasing":         "Chasing the breakout",
        "not_near_swing_high": "Entering at the swing high",
        "not_near_swing_low":  "Entering at the swing low",
    }
    planner_problems = []
    for _c in components:
        _ck = _c.get("key")
        _cdet = _c.get("detail") or ""
        _lost = (_c.get("max") or 0) - (_c.get("score") or 0)
        if _lost < 3:
            continue
        if any(_m in _cdet.lower() for _m in _eq_missing_markers):
            continue
        _ptxt = _eq_problem_label.get(_ck, _c.get("label") or _ck)
        if _cdet and _ck in ("impulse_completed", "atr_extension",
                             "cushion_at_support", "room_to_resistance"):
            _ptxt = "%s (%s)" % (_ptxt, _cdet)
        planner_problems.append({"text": _ptxt, "lost": int(round(_lost))})
    planner_problems.sort(key=lambda it: -it["lost"])

    # 2) BEST ENTRY ZONE — pullback-side references → ideal / acceptable range /
    #    aggressive (shallowest, nearest current price) / conservative (deepest).
    planner_zone = {"ideal": None, "range_low": None, "range_high": None,
                    "aggressive": None, "conservative": None, "reasons": []}
    _pz_refs = []
    if isinstance(vwap, (int, float)) and ((vwap < price) if is_long else (vwap > price)):
        _pz_refs.append((float(vwap), "VWAP"))
    if entry_level and ((entry_level < price) if is_long else (entry_level > price)):
        _pz_refs.append((float(entry_level), "demand zone" if is_long else "supply zone"))
        _pz_refs.append(((price + float(entry_level)) / 2.0, "50% pullback"))
    if target_level:
        _pz_broke = (target_level - price) if is_long else (price - target_level)
        if _pz_broke <= 0 and ((target_level < price) if is_long else (target_level > price)):
            _pz_refs.append((float(target_level), "breakout retest"))
    if _pz_refs:
        _pz_vals = [r[0] for r in _pz_refs]
        _pz_lo, _pz_hi = min(_pz_vals), max(_pz_vals)
        if is_long:
            _pz_aggr, _pz_cons = _pz_hi, _pz_lo   # shallow pullback = nearer price
        else:
            _pz_aggr, _pz_cons = _pz_lo, _pz_hi
        _pz_ideal = next((rv for rv, rl in _pz_refs if rl == "VWAP"), None)
        if _pz_ideal is None:
            _pz_ideal = (_pz_lo + _pz_hi) / 2.0
        _pz_ideal = max(_pz_lo, min(_pz_hi, _pz_ideal))
        planner_zone = {
            "ideal":        _eq_px(_pz_ideal),
            "range_low":    _eq_px(_pz_lo),
            "range_high":   _eq_px(_pz_hi),
            "aggressive":   _eq_px(_pz_aggr),
            "conservative": _eq_px(_pz_cons),
            "reasons":      [r[1] for r in _pz_refs],
        }

    # 3) WHAT NEEDS TO HAPPEN — forward "wait for" conditions. The ABSENCE of a
    #    confirming factor is legitimate wait-advice (unlike a "problem"), so these
    #    may reference not-yet-confirmed factors.
    _wnh = []
    if ext is not None and ext > 1.0:
        _wnh.append("Wait for a pullback toward VWAP")
    elif (fracs.get("pullback_quality") or 1.0) < 0.7:
        _wnh.append("Wait for a controlled pullback into value")
    if (fracs.get("cushion_at_support") or 1.0) < 0.7:
        _wnh.append("Wait for a fresh %s retest" % ("demand" if is_long else "supply"))
    _wnh.append("Wait for a %s engulfing / rejection candle at the zone"
                % ("bullish" if is_long else "bearish"))
    if sweep_present is not True:
        _wnh.append("Wait for a liquidity sweep")
    if (fracs.get("momentum") or 1.0) < 0.8 or cvd_dir == ("bearish" if is_long else "bullish"):
        _wnh.append("Wait for %s delta / CVD confirmation" % ("bullish" if is_long else "bearish"))
    if not volume_confirmed and not (isinstance(rvol, (int, float)) and rvol >= 1.5):
        _wnh.append("Wait for volume expansion")
    if (impulse_pct is not None and impulse_pct >= 80) or near_high or near_low \
            or (fracs.get("pullback_quality") or 1.0) < 0.7:
        _wnh.append("Wait for a new %s (structure reclaim)"
                    % ("higher low" if is_long else "lower high"))
    _wnh_seen = set()
    what_needs_to_happen = []
    for _w in _wnh:
        if _w not in _wnh_seen:
            _wnh_seen.add(_w)
            what_needs_to_happen.append(_w)

    # 4) ENTRY TRIGGERS — concrete conditions that would lift Entry Quality into the
    #    Good band, plus a grounded suggested entry / stop / target.
    _trigs = []
    if planner_zone["range_low"] is not None and planner_zone["range_high"] is not None:
        if is_long:
            _pb_a = price - planner_zone["range_high"]
            _pb_b = price - planner_zone["range_low"]
        else:
            _pb_a = planner_zone["range_low"] - price
            _pb_b = planner_zone["range_high"] - price
        _pb_lo, _pb_hi = sorted((_pb_a, _pb_b))
        _pb_lo = max(0.0, _pb_lo)
        if _pb_hi > 0:
            if round(_pb_lo) <= 0:
                _trigs.append("Pull back up to %.0f points" % _pb_hi)
            else:
                _trigs.append("Pull back %.0f–%.0f points" % (_pb_lo, _pb_hi))
    if ext is not None and ext > 2.0:
        _trigs.append("Hold ATR extension under 2.0 ATR from VWAP")
    _trigs.append("New %s forms" % ("higher low" if is_long else "lower high"))
    if (ext is not None and ext > 1.0) or (fracs.get("pullback_quality") or 1.0) < 0.7:
        _trigs.append("%s reclaim VWAP" % ("Buyers" if is_long else "Sellers"))
    if (fracs.get("momentum") or 1.0) < 0.8 or cvd_dir == ("bearish" if is_long else "bullish"):
        _trigs.append("%s delta confirmation appears" % ("Bullish" if is_long else "Bearish"))
    if not volume_confirmed and not (isinstance(rvol, (int, float)) and rvol >= 1.5):
        _trigs.append("Volume expansion (RVOL ≥ 1.5)")
    if sweep_present is not True:
        _trigs.append("Liquidity sweep prints")
    _trig_seen = set()
    entry_trigger_conditions = []
    for _t in _trigs:
        if _t not in _trig_seen:
            _trig_seen.add(_t)
            entry_trigger_conditions.append(_t)

    # Estimated quality if the waitable conditions confirm (reuses the projection). Uses
    # the conservative 0.80-"Good band" projection, not the perfect-confirm ceiling, so
    # the estimate is realistic ("if these conditions are met to a Good standard") rather
    # than an optimistic 100.
    _est_quality = projected_low
    # Transparent confidence estimate — a documented BLEND of projected location and
    # the setup Edge, never a true probability (the basis is surfaced). EQ-only when
    # Edge is unavailable.
    if isinstance(edge_score, (int, float)):
        _est_conf = int(round(max(0.0, min(99.0, 0.45 * _est_quality + 0.55 * edge_score))))
        _conf_basis = ("0.45 × projected location (%d) + 0.55 × Edge (%d)"
                       % (_est_quality, int(round(edge_score))))
    else:
        _est_conf = _est_quality
        _conf_basis = "Projected location only (Edge unavailable)"

    # Grounded suggested entry / stop / target. risk_unit = the HTF ATR in SWING (when
    # available) else the base unit, so a SWING stop isn't sized off a 1-minute ATR.
    _risk_unit = ext_atr if (TRADING_MODE == "SWING" and ext_atr) else unit
    _risk_tf = ext_tf if (TRADING_MODE == "SWING" and ext_atr) else "1m"
    _sugg_entry = planner_zone["ideal"]
    _sugg_stop = _sugg_target = _risk_pts = None
    if _sugg_entry is not None and _risk_unit:
        # Anchor the stop one ATR beyond the DEEPEST pullback reference (range bottom for
        # a long, range top for a short) so it always sits past the zone being entered —
        # never off entry_level alone, which can be on the wrong side of the ideal entry
        # (e.g. a demand zone above a VWAP-anchored ideal) and yield negative risk.
        if is_long:
            _stop_anchor = min(_sugg_entry,
                               planner_zone["range_low"] if planner_zone["range_low"] is not None
                               else _sugg_entry)
            _sugg_stop = _eq_px(_stop_anchor - 1.0 * _risk_unit)
        else:
            _stop_anchor = max(_sugg_entry,
                               planner_zone["range_high"] if planner_zone["range_high"] is not None
                               else _sugg_entry)
            _sugg_stop = _eq_px(_stop_anchor + 1.0 * _risk_unit)
        if _sugg_stop is not None:
            _risk_pts = (_sugg_entry - _sugg_stop) if is_long else (_sugg_stop - _sugg_entry)
            if _risk_pts and _risk_pts > 0:
                # Use the structural target only when it yields a sensible 1–4R; an
                # overextended fixture can put resistance 20R away, which is not a
                # realistic single-trade target. Otherwise project a clean 2R.
                _struct_ok = False
                if target_level:
                    _tgt_r = (((target_level - _sugg_entry) if is_long
                               else (_sugg_entry - target_level)) / _risk_pts)
                    _struct_ok = 1.0 <= _tgt_r <= 4.0
                if _struct_ok:
                    _sugg_target = _eq_px(target_level)
                else:
                    _sugg_target = (_eq_px(_sugg_entry + 2.0 * _risk_pts) if is_long
                                    else _eq_px(_sugg_entry - 2.0 * _risk_pts))
            else:
                _sugg_stop = None
                _risk_pts = None

    entry_planner = {
        "available":     True,
        "direction":     direction,
        "current_entry": {
            "score":    score,
            "grade":    grade,
            "problems": planner_problems,
        },
        "best_entry_zone":      planner_zone,
        "what_needs_to_happen": what_needs_to_happen,
        "entry_triggers": {
            "conditions":           entry_trigger_conditions,
            "estimated_quality":    _est_quality,
            "estimated_confidence": _est_conf,
            "confidence_basis":     _conf_basis,
            "suggested_entry":      _sugg_entry,
            "suggested_stop":       _sugg_stop,
            "suggested_target":     _sugg_target,
            "risk_points":          (round(_risk_pts, 2) if isinstance(_risk_pts, (int, float)) else None),
            "risk_basis":           ("%s ATR" % _risk_tf),
            "status":               ("WAIT FOR THESE CONDITIONS" if reject else "ENTRY LOCATION OK"),
        },
    }

    return {
        "engine_enabled":   _entry_quality_engine_enabled(),
        "gate_enabled":     _entry_quality_gate_enabled(),
        "available":        True,
        "direction":        direction,
        "score":            score,
        "grade":            grade,
        "components":       components,
        "flags":            flags,
        "reject":           reject,
        "override_applied": override_applied,
        "veto_would_fire":  veto_would_fire,
        "min_score":        ENTRY_QUALITY_MIN_SCORE,
        "override_edge":    ENTRY_QUALITY_OVERRIDE_EDGE,
        "edge_score":       edge_score,
        "summary":          "Entry Quality %d/100 (%s) — %s" % (score, grade, direction),
        "why_not_trade":    why,
        "strong_reject":    strong_reject,
        "strong_reject_score": ENTRY_QUALITY_STRONG_REJECT,
        "raw":              raw,
        "improvements":     improvements,
        "improvement_plan": improvement_plan,
        "projected_low":    projected_low,
        "projected_high":   projected_high,
        "better_entry_zone": better_entry_zone,
        "chasing_warning":  chasing_warning,
        "entry_plan":       entry_plan,
        "verdict_label":    verdict_label,
        "verdict_tier":     verdict_tier,
        "entry_planner":    entry_planner,
        "plain_english":    plain_english,
        "final_verdict":    None,
    }


def _fast_entry_money_enabled():
    """The Fast Entry MONEY path is live only when its own flag is on AND the
    display layer is on AND we are SCALP AND the dual-TF engine is OFF (mutually
    exclusive so the two seconds engines can never double-fire)."""
    return bool(FAST_ENTRY_MONEY and FAST_ENTRY_TRIGGER
                and TRADING_MODE == "SCALP" and not DUAL_TF_ENGINE)


def _fast_entry_neutral(reason="Fast Entry Trigger disabled."):
    """Inert Fast Entry block — early_entry_allowed=False so it can NEVER promote.
    Used when the flag is off, the mode is wrong, the market is closed, or the
    aggregator raised (fail-open). STABLE schema — the dashboard panel + the money
    path read exactly these keys (the 9 user-facing fields + internal twins)."""
    return {
        "enabled":             FAST_ENTRY_TRIGGER,
        "money_enabled":       _fast_entry_money_enabled(),
        "available":           False,
        "fast_entry_trigger":  False,
        "seconds_bias":        None,
        "micro_sweep":         None,
        "micro_choch":         None,
        "delta_flip":          None,
        "micro_vwap_status":   None,
        "early_entry_allowed": False,
        "entry_confidence":    None,
        "fast_entry_reason":   reason,
        # Internal twins (NOT among the 9 fields) — the money path reads these.
        "direction":           None,
        "htf":                 None,
    }


def _fast_entry_record(normalized, inst, data):
    """Record a seconds micro-event into FAST_ENTRY_STATE_BY_TICKER (DISPLAY / STATE
    only). No-op unless FAST_ENTRY_TRIGGER + SCALP. FAIL-OPEN — never raises into the
    webhook path. Each event stores its direction (where directional) + ts so the
    aggregator can check freshness / co-occurrence. A FAST SECONDS BAR is
    directionless and additionally carries hi/lo/vwap reference levels."""
    if not (FAST_ENTRY_TRIGGER and TRADING_MODE == "SCALP") or not inst:
        return
    try:
        cat, direction, extra = None, None, {}
        if normalized in FAST_SWEEP_RECLAIM_LONG_TYPES:
            cat, direction = "sweep_reclaim", "Long"
        elif normalized in FAST_SWEEP_RECLAIM_SHORT_TYPES:
            cat, direction = "sweep_reclaim", "Short"
        elif normalized in FAST_DELTA_FLIP_BULL_TYPES:
            cat, direction = "delta_flip", "Long"
        elif normalized in FAST_DELTA_FLIP_BEAR_TYPES:
            cat, direction = "delta_flip", "Short"
        elif normalized in FAST_MICRO_VWAP_RECLAIM_TYPES:
            cat, direction = "micro_vwap", "Long"
        elif normalized in FAST_MICRO_VWAP_LOSS_TYPES:
            cat, direction = "micro_vwap", "Short"
        elif normalized in FAST_MICRO_CHOCH_LONG_TYPES:
            cat, direction = "micro_choch", "Long"
        elif normalized in FAST_MICRO_CHOCH_SHORT_TYPES:
            cat, direction = "micro_choch", "Short"
        elif normalized in FAST_SECONDS_BAR_TYPES:
            cat = "bar"
            for _src, _dst in (("high", "high"), ("hi", "high"), ("low", "low"),
                               ("lo", "low"), ("vwap", "vwap"), ("price", "price")):
                _v = data.get(_src)
                if _v is not None and _dst not in extra:
                    try:
                        extra[_dst] = float(_v)
                    except (ValueError, TypeError):
                        pass
        if cat is None:
            return
        rec = {"direction": direction, "ts": now_utc().isoformat()}
        rec.update(extra)
        with FAST_ENTRY_LOCK:
            FAST_ENTRY_STATE_BY_TICKER.setdefault(inst, {})[cat] = rec
        logger.info("Fast-entry micro-event: %s %s (dir=%s)", inst, cat, direction)
    except Exception as exc:
        logger.error("Fast-entry record error (non-fatal): %s", exc)


def _fast_entry_snapshot(inst):
    """Lazy-expired per-instrument micro-event snapshot for DISPLAY. Returns
    {category: rec(+age seconds)} for events still within FAST_ENTRY_TTL_SEC and
    drops the rest. Empty dict when the layer is off / no events."""
    if not (FAST_ENTRY_TRIGGER and inst):
        return {}
    out = {}
    now = now_utc()
    with FAST_ENTRY_LOCK:
        st = FAST_ENTRY_STATE_BY_TICKER.get(inst)
        if not st:
            return {}
        for cat in list(st.keys()):
            rec = st.get(cat) or {}
            try:
                age = (now - datetime.fromisoformat(rec.get("ts"))).total_seconds()
            except Exception:
                age = None
            if age is None or age > FAST_ENTRY_TTL_SEC:
                st.pop(cat, None)                       # lazy-expire
            else:
                out[cat] = dict(rec, age=age)
    return out


def _fast_entry_htf_gate(result, direction):
    """Decide whether the EXISTING higher-timeframe strict setup is already valid or
    NEARLY valid AND aligned with `direction`. Reads ONLY the already-computed strict
    output (directions[dir].gate_debug / edge_score, dominant_direction,
    strict_direction) — it NEVER recomputes or bypasses the gate. The fast layer may
    improve TIMING only when (htf_ready OR htf_nearly) AND aligned; it can NEVER
    manufacture a setup the gate did not already form."""
    out = {"aligned": False, "htf_ready": False, "htf_nearly": False,
           "structure_ok": False, "edge_score": None, "edge_gap": None,
           "dominant": None, "reason": ""}
    if direction not in ("Long", "Short"):
        out["reason"] = "no micro direction"
        return out
    blk = ((result.get("directions") or {}).get(direction)) or {}
    gd = blk.get("gate_debug") or {}
    dominant = result.get("dominant_direction") or result.get("strict_direction")
    out["dominant"] = dominant
    out["aligned"] = (dominant == direction)
    out["structure_ok"] = bool(gd.get("structure_confirmed"))
    edge = blk.get("edge_score")
    try:
        edge = int(edge) if edge is not None else None
    except (ValueError, TypeError):
        edge = None
    out["edge_score"] = edge
    thr = int(cfg("EDGE_READY_THRESHOLD"))
    if edge is not None:
        out["edge_gap"] = thr - edge
        if edge >= thr:
            out["htf_ready"] = True
        elif out["structure_ok"] and (thr - edge) <= FAST_ENTRY_HTF_EDGE_BAND:
            out["htf_nearly"] = True
    if not out["aligned"]:
        out["reason"] = "micro %s vs HTF %s — not aligned" % (direction, dominant or "none")
    elif out["htf_ready"]:
        out["reason"] = "HTF %s setup READY + aligned" % direction
    elif out["htf_nearly"]:
        out["reason"] = "HTF nearly valid (edge %s, %s below) + aligned" % (edge, out["edge_gap"])
    else:
        out["reason"] = "HTF not valid for %s" % direction
    return out


def _compute_fast_entry_trigger(result, inst):
    """DISPLAY-FIRST seconds-timing aggregator. Combines the fresh micro-event
    snapshot with the EXISTING HTF strict gate (via _fast_entry_htf_gate) to decide
    whether a fast EARLY entry is PERMITTED. It NEVER recomputes the gate and NEVER
    allows when the HTF setup is missing or misaligned. FAIL-OPEN: any error / off /
    closed returns the inert neutral block so the dashboard still renders and the
    money path stays dormant."""
    if not FAST_ENTRY_TRIGGER:
        return _fast_entry_neutral("Fast Entry Trigger disabled.")
    if TRADING_MODE != "SCALP":
        return _fast_entry_neutral("Fast Entry Trigger is SCALP-only.")
    if not result.get("market_open"):
        return _fast_entry_neutral("Market closed — fast entry paused.")
    try:
        snap = _fast_entry_snapshot(inst)

        # DISPLAY descriptors use the TTL-fresh snapshot (recent events).
        def _desc(cat):
            rec = snap.get(cat)
            if not rec:
                return None
            d = rec.get("direction")
            age = rec.get("age")
            age_s = (" %.0fs ago" % age) if isinstance(age, (int, float)) else ""
            return ("%s%s" % (d, age_s)) if d else ("seen%s" % age_s)
        micro_sweep = _desc("sweep_reclaim")
        micro_choch = _desc("micro_choch")
        delta_flip  = _desc("delta_flip")
        mv = snap.get("micro_vwap")
        micro_vwap_status = None
        if mv:
            micro_vwap_status = ("Reclaimed" if mv.get("direction") == "Long"
                                 else "Lost" if mv.get("direction") == "Short" else None)

        # DECISION uses only events tight within FAST_ENTRY_WINDOW_SEC (co-occurrence).
        def _fresh(cat):
            rec = snap.get(cat)
            if rec and isinstance(rec.get("age"), (int, float)) and rec["age"] <= FAST_ENTRY_WINDOW_SEC:
                return rec
            return None
        votes = [_fresh(c).get("direction") for c in
                 ("sweep_reclaim", "delta_flip", "micro_vwap", "micro_choch")
                 if _fresh(c) and _fresh(c).get("direction")]
        seconds_bias = None
        if votes:
            longs, shorts = votes.count("Long"), votes.count("Short")
            if longs and not shorts:
                seconds_bias = "Long"
            elif shorts and not longs:
                seconds_bias = "Short"
            # mixed → None (no clean micro bias)

        # Micro confirmation rule (mirrors the spec): a directional micro signal
        # needs a sweep+reclaim AND >=1 agreeing confirm (delta flip OR micro VWAP
        # reclaim/loss OR micro CHOCH) — all within the window, all same direction.
        sweep_ok, confirms = False, 0
        if seconds_bias:
            _sw = _fresh("sweep_reclaim")
            sweep_ok = bool(_sw and _sw.get("direction") == seconds_bias)
            for c in ("delta_flip", "micro_vwap", "micro_choch"):
                rec = _fresh(c)
                if rec and rec.get("direction") == seconds_bias:
                    confirms += 1
        micro_ready = bool(seconds_bias and sweep_ok and confirms >= 1)

        # HTF gate (existing strict output ONLY) for the micro direction.
        htf = _fast_entry_htf_gate(result, seconds_bias) if seconds_bias else None
        allowed = bool(micro_ready and htf and htf["aligned"]
                       and (htf["htf_ready"] or htf["htf_nearly"]))

        # Entry confidence (display 0-100): micro confirmations + HTF readiness.
        conf = None
        if seconds_bias:
            conf = 0
            if sweep_ok:
                conf += 30
            conf += min(confirms, 3) * 15
            if htf and htf["aligned"]:
                conf += 15
            if htf and htf["htf_ready"]:
                conf += 10
            conf = min(conf, 100)

        if not seconds_bias:
            reason = "No clean seconds bias (need agreeing micro events)."
        elif not sweep_ok:
            reason = "Awaiting micro sweep+reclaim (%s)." % seconds_bias
        elif confirms < 1:
            reason = "Sweep seen; awaiting delta/VWAP/CHOCH confirm (%s)." % seconds_bias
        elif not (htf and htf["aligned"]):
            reason = "Micro %s but HTF favors %s — stand aside." % (
                seconds_bias, (htf or {}).get("dominant") or "none")
        elif not (htf["htf_ready"] or htf["htf_nearly"]):
            reason = "Micro %s ready but HTF setup not valid — no early entry." % seconds_bias
        elif allowed:
            reason = "Fast %s entry: micro timing confirmed on a %s HTF setup." % (
                seconds_bias, "READY" if htf["htf_ready"] else "nearly-valid")
        else:
            reason = "Holding."

        return {
            "enabled":             True,
            "money_enabled":       _fast_entry_money_enabled(),
            "available":           True,
            "fast_entry_trigger":  micro_ready,
            "seconds_bias":        seconds_bias,
            "micro_sweep":         micro_sweep,
            "micro_choch":         micro_choch,
            "delta_flip":          delta_flip,
            "micro_vwap_status":   micro_vwap_status,
            "early_entry_allowed": allowed,
            "entry_confidence":    conf,
            "fast_entry_reason":   reason,
            "direction":           seconds_bias if allowed else None,
            "htf":                 htf,
        }
    except Exception as exc:
        logger.error("Fast-entry compute error (non-fatal): %s", exc)
        return _fast_entry_neutral("Fast entry unavailable (%s)." % exc)


def full_analysis(current_price_override=None, ticker_override=None, cooldown_active=False):
    # Which instrument this analysis is for: an explicit override (dashboard tab)
    # wins; otherwise fall back to the most-recently-alerted instrument.
    active_ticker = instrument_of(ticker_override) if ticker_override else _active_ticker()

    score_window = cfg("SCORE_WINDOW_MIN")
    if score_window:
        bullish, bearish, counts = score_alerts(alerts_in_window(score_window))
    else:
        bullish, bearish, counts = calculate_scores()
    bias, strength           = calculate_bias(bullish, bearish)
    confidence               = calculate_confidence(bullish, bearish)
    quality                  = calculate_trade_quality(bias, confidence, bullish, bearish)
    edge_score               = calculate_edge_score(bias, confidence, strength)

    with _timed("indicatorCalcMs"):
        last_price_by_type, all_supply, all_demand = get_price_context(active_ticker)
    current_price = current_price_override if current_price_override is not None else current_price_for(active_ticker)
    nearest_supply, nearest_demand = get_nearest_levels(current_price, all_supply, all_demand)

    structure_label, structure_detail = get_market_structure(current_price, last_price_by_type)
    risk_label, risk_detail, overextended = get_risk_zone(
        bias, current_price, nearest_supply, nearest_demand
    )

    recommendation, verdict, structure_class, reasoning_chain = decision_engine(
        structure_label, risk_label, overextended,
        bias, bullish, bearish, confidence
    )

    market_direction = get_market_direction(structure_label)
    trade_opportunity, opportunity_reason, entry_trigger, invalidation = get_trade_opportunity(
        market_direction, structure_label, risk_label,
        overextended, bullish, bearish, nearest_supply, nearest_demand, last_price_by_type
    )

    # ── Strict recommendation ruleset — AUTHORITATIVE verdict ────────────────
    # A trade is recommended ONLY when BOS + CHOCH + 5m confirmation candle + the
    # price-vs-VWAP filter all align on one side. Score 0-100 → Strong/Possible/WAIT.
    # active_ticker resolved at the top (honours the dashboard's instrument tab).
    with _timed("indicatorCalcMs"):
        vwap_value, vwap_status = get_vwap(active_ticker)
    with _timed("volatilityCalcMs"):
        volatility = get_volatility(active_ticker)
    # Preferred-session state (ET) computed ONCE here and threaded through the gate
    # AND stored on the result, so the +10 Session Bonus the gate credits and the
    # Session block on the card/status are derived from the same instant.
    session_state = get_session_state()
    # Market-session state (CME/COMEX hours, shared by MNQ & MGC). Computed once
    # here and applied as a single neutralising override right before `return`, so
    # all result keys still exist (single-return-path invariant) and the gate is
    # paused — not deleted — while the market is closed.
    market = market_session_status()
    with _timed("scoringMs"):
        strict = evaluate_strict_setup(
            current_price, active_ticker, vwap_value, vwap_status,
            nearest_supply, nearest_demand, bullish, bearish, confidence, ALERT_HISTORY,
            volatility=volatility, session=session_state, cooldown_active=cooldown_active,
        )
    strict_label     = strict["label"]
    strict_score     = strict["score"]
    strict_direction = strict["direction"]
    confluences      = strict["confluences"]
    strict_reason    = strict.get("reason", "")
    strict_missing   = strict.get("missing", [])

    # SWING higher-timeframe context — computed ONCE here (only under SWING + flag-on)
    # and REUSED by the plan builder (target geometry), the P4 entry veto, the
    # potential-plan preview, and the display attach below, so the gate and every
    # surface read the SAME context (no drift). None in SCALP / flag-off → the builder
    # falls through to its byte-identical 1:1 path and the veto block never runs.
    swing_ctx = None
    if _swing_htf_enabled(TRADING_MODE):
        try:
            swing_ctx = compute_swing_context(active_ticker, current_price)
        except Exception:
            swing_ctx = None

    if strict_label in ("Strong Trade", "Possible Trade") and strict_direction:
        trade_plan = build_strict_trade_plan(
            strict_direction, active_ticker, current_price, nearest_supply, nearest_demand,
            volatility=volatility, mode=TRADING_MODE, vwap=vwap_value, edge_score=edge_score,
            swing_context=swing_ctx,
        )
        if trade_plan["trade_plan"]:
            # EARLY READY (SCALP Edge 50-59) is actionable but half size / lower
            # conviction; a full READY is Edge >= the full-READY floor (60). Both still
            # require a valid trade plan (R:R + an anchor — a trade-side zone OR
            # VWAP), so an EARLY setup that can't form a real plan still falls
            # through to WAIT below.
            _early = strict.get("readiness") == "EARLY"
            if strict_direction == "Long":
                verdict = "LONG EARLY READY" if _early else "LONG READY"
            else:
                verdict = "SHORT EARLY READY" if _early else "SHORT READY"
        else:
            # Fixed targets can't meet the 1:2 R:R (or no zone/VWAP anchor) → no trade.
            verdict        = "WAIT"
            strict_label   = "WAIT"
            strict_reason  = trade_plan.get("reason", strict_reason)
    elif strict_label == "Setup Building" and strict.get("candidate"):
        # SETUP BUILDING (informational, NON-actionable). Like MARKET CLOSED, the
        # journaling label is forced to WAIT so the journal + live-card paths skip it;
        # the building state is surfaced via the verdict + diagnostics ONLY. NO trade
        # plan is built, so the broker path (is_actionable + top-level trade_plan)
        # can never light up for a building setup.
        verdict       = "SETUP BUILDING"
        strict_label  = "WAIT"
        trade_plan = {
            "trade_plan": False,
            "reason":     strict_reason or "Setup building — not yet READY.",
            "entry_zone": None, "stop_loss": None,
            "target1":    None, "target2":   None,
            "rr":         None, "direction": strict.get("candidate"),
            "instrument": active_ticker, "point_value": point_value_for(active_ticker),
        }
    else:
        verdict    = "WAIT"
        trade_plan = {
            "trade_plan": False,
            "reason":     strict_reason or "Strict conditions not met.",
            "entry_zone": None, "stop_loss": None,
            "target1":    None, "target2":   None,
            "rr":         None, "direction": strict_direction,
            "instrument": active_ticker, "point_value": point_value_for(active_ticker),
        }

    # ── SCALP dynamic-exit ENTRY VETOES (Phase S2, MONEY-PATH) ───────────────────
    # SCALP-only + master-flag-gated. Turns the S1 diagnostics into real entry
    # filters: an Edge-actionable setup (READY or EARLY) that fails setup-quality,
    # room-to-target, opposing-zone, chop, or loss-size becomes WAIT with a precise
    # reason and NO trade plan — so neither the live card nor the execution gateway
    # (which re-checks is_actionable from THIS verdict) can act on it. Computed once
    # from the REAL plan just built and reused for the display block below, so the
    # gate and the dashboard can never drift. FAIL-CLOSED: if the check can't run the
    # setup is vetoed. SWING / flag-off skip this entirely → byte-identical.
    scalp_quality_block = None
    if _scalp_dynamic_enabled() and is_actionable(verdict) and strict_direction:
        try:
            _sq = compute_scalp_quality(
                strict_direction, current_price, vwap_value, vwap_status,
                nearest_supply, nearest_demand, trade_plan, edge_score,
                instrument_of(active_ticker),
                (volatility or {}).get("atr_pts"),
            )
            _veto = _scalp_entry_veto_reasons(_sq)
        except Exception as exc:   # FAIL-CLOSED — a broken check must not let a trade through.
            _sq   = None
            _veto = [("unavailable", f"SCALP entry checks unavailable ({exc})")]
        if _veto:
            verdict       = "WAIT"
            strict_label  = "WAIT"
            strict_reason = "SCALP filter: " + "; ".join(m for _, m in _veto) + "."
            trade_plan = {
                "trade_plan": False,
                "reason":     strict_reason,
                "entry_zone": None, "stop_loss": None,
                "target1":    None, "target2":   None,
                "rr":         None, "direction": strict_direction,
                "instrument": active_ticker, "point_value": point_value_for(active_ticker),
            }
            if isinstance(_sq, dict):
                _sq["overall_pass"] = False
                # Reuse this block for display so the dashboard keeps the REJECTED
                # setup's geometry + failing checks (recomputing after the plan is
                # dropped below would read the nulled plan and lose them).
                scalp_quality_block = _sq

    # ── SWING entry MONEY-PATH vetoes (P4) ───────────────────────────────────────
    # SWING-only + master-flag-gated, mirroring the SCALP veto block above. An
    # Edge-/strict-actionable setup that fails higher-timeframe confirmation (1H+4H
    # bias agreement, a daily key level with a valid pullback, fresh HTF data) becomes
    # WAIT with a precise reason and NO trade plan — so neither the live card nor the
    # execution gateway (which re-checks is_actionable from THIS verdict) can act on
    # it. The ≥SWING_MIN_RR target + trade-side-zone requirements are already enforced
    # inside build_strict_trade_plan (a failure there drops the plan → WAIT BEFORE this
    # point, so is_actionable is already False); this block adds the HTF-confirmation
    # gate the builder does not check and re-validates the rest defensively.
    # FAIL-CLOSED: a broken check vetoes. SCALP / flag-off never enter (mutually
    # exclusive modes), so those paths stay byte-identical.
    if _swing_htf_enabled() and is_actionable(verdict) and strict_direction:
        try:
            _sv = _swing_entry_veto_reasons(swing_ctx, trade_plan, strict_direction)
        except Exception as exc:   # FAIL-CLOSED — a broken check must not let a trade through.
            _sv = [("unavailable", f"SWING entry checks unavailable ({exc})")]
        if _sv:
            verdict       = "WAIT"
            strict_label  = "WAIT"
            strict_reason = "SWING filter: " + "; ".join(m for _, m in _sv) + "."
            trade_plan = {
                "trade_plan": False,
                "reason":     strict_reason,
                "entry_zone": None, "stop_loss": None,
                "target1":    None, "target2":   None,
                "rr":         None, "direction": strict_direction,
                "instrument": active_ticker, "point_value": point_value_for(active_ticker),
            }

    # get_setup_stage retained for lifecycle display context in the embed.
    setup_stage, stage_next_step, stage_entry_rule, stage_invalidation, stage_direction = get_setup_stage(
        current_price, nearest_supply, nearest_demand, bullish, bearish, ALERT_HISTORY
    )

    # Align the displayed lifecycle stage with the authoritative strict verdict.
    if is_actionable(verdict):
        setup_stage      = "Trade Ready"
        stage_direction  = strict_direction
        if is_early_ready(verdict):
            stage_next_step  = strict_reason or (
                "Early setup — enter aggressive (reduced size) or wait for the "
                "confirmation candle.")
            stage_entry_rule = (
                f"Enter {strict_direction.lower()} early at reduced size, "
                "or wait for a confirmation candle.")
        else:
            stage_next_step  = strict_reason or "All strict conditions met — enter now."
            stage_entry_rule = f"Enter {strict_direction.lower()} per strict checklist."

    # ── Zone Broken: cancel setup, reduce confidence, mark structure invalidated ──
    # Scoped to the analyzed instrument: a broken MGC zone must not invalidate a
    # valid MNQ setup (and vice versa). Untagged (legacy) breaks apply globally.
    zone_broken_active = (
        ZONE_BROKEN_AT is not None
        and ZONE_BROKEN_AT.get("instrument") in (None, instrument_of(active_ticker))
    )
    # SWING hard-gates on zone (GATE_REQUIRE_ZONE True): a broken or consumed zone is
    # a full WAIT override. SCALP demotes zone to a confirmation, so a broken/consumed
    # zone only updates the zone STATE for display and NEVER overrides a
    # structure+VWAP+Edge READY. cfg() reads the active mode so SWING stays unchanged.
    zone_hard_gate = bool(cfg("GATE_REQUIRE_ZONE"))
    if zone_broken_active and zone_hard_gate:
        confidence         = max(0, confidence - 30)
        setup_stage        = "Watching"
        stage_direction    = None
        stage_next_step    = "Wait for structure to rebuild after zone break"
        stage_entry_rule   = "—"
        stage_invalidation = "Structure invalidated — zone broken"
        verdict            = "WAIT"
        strict_label       = "WAIT"
        strict_score       = 0
        strict_reason      = "Structure invalidated — zone broken."
        trade_plan         = {
            "trade_plan": False,
            "reason":     "Structure invalidated — zone broken.",
            "entry_zone": None, "stop_loss": None,
            "target1":    None, "target2": None,
            "rr":         None, "direction": None,
            "stop_valid": False,
            "stop_invalid_reason": "Structure invalidated — zone broken.",
        }

    # ── Zone Mitigated: a consumed zone blocks entries UNLESS the mitigation is
    # a confirmed bullish reaction (handled as a LONG via the strict gate). ──
    mitig_confirmed = bool(confluences.get("zone_mitigated"))
    _mit_inst = instrument_of(active_ticker)
    near_sup_mz, mz_sup_price = is_near_mitigated_zone(nearest_supply, _mit_inst)
    near_dem_mz, mz_dem_price = is_near_mitigated_zone(nearest_demand, _mit_inst)
    # Block only when THIS instrument's mitigation is active (flag not yet cleared
    # by a same-instrument structure reset, entries not yet TTL-expired) AND its
    # nearest zone actually sits on a mitigated price. State is instrument-scoped
    # so a mitigated MGC zone can neither WAIT-block nor arm an unrelated MNQ
    # alert (and vice-versa).
    zone_mitigated_near = (
        MITIGATED_FLAG_BY_TICKER.get(_mit_inst) and (near_sup_mz or near_dem_mz)
        and not zone_broken_active
        and not mitig_confirmed
    )
    _mit_records = MITIGATED_PRICES_BY_TICKER.get(_mit_inst)
    mitigated_zone_price = (
        mz_sup_price or mz_dem_price
        or (_mit_records[-1]["price"] if _mit_records else None)
    )
    if zone_mitigated_near and zone_hard_gate:
        # Full override — zone mitigation supersedes ALL scores, setups, and plans
        confidence         = max(0, confidence - 15)
        verdict            = "WAIT"
        recommendation     = "WAIT"
        trade_opportunity  = "None"
        opportunity_reason = "Zone already reacted and is no longer valid for entry."
        entry_trigger      = None
        invalidation       = None
        trade_plan         = {
            "trade_plan": False,
            "reason":     "Zone consumed — wait for fresh supply or demand zone.",
            "entry_zone": None, "stop_loss": None,
            "target1":    None, "target2": None,
            "rr":         None, "direction": None,
            "stop_valid": False,
            "stop_invalid_reason": "Zone consumed — wait for fresh supply or demand zone.",
        }
        setup_stage        = "Watching"
        stage_direction    = None
        stage_next_step    = "Zone consumed — wait for fresh supply or demand zone."
        stage_entry_rule   = "No entry from consumed zone."
        stage_invalidation = (
            f"Zone previously mitigated at {mitigated_zone_price:.1f} — invalid entry."
        )
        strict_label       = "WAIT"
        strict_reason      = "Zone consumed — wait for fresh supply or demand zone."

    why  = build_why(bias, confidence, bullish, bearish, counts,
                     verdict, overextended, risk_label)
    plan = build_trade_plan(bias, strength, bullish, bearish, counts)

    # Dashboard price readout (DISPLAY-ONLY; the gate above uses `current_price`).
    # An explicit price override is echoed as-is; otherwise show the fresh alert
    # price, falling back to the auto-fetched market price so the readout never
    # goes blank after a restart / quiet market.
    if current_price_override is not None:
        display_price, price_source = current_price, "alert"
    else:
        display_price, price_source = display_price_for(active_ticker)

    result = dict(
        bullish=bullish, bearish=bearish, counts=counts,
        bias=bias, strength=strength, confidence=confidence,
        quality=quality, edge_score=edge_score,
        recommendation=recommendation, verdict=verdict,
        reasoning_chain=reasoning_chain, why=why, plan=plan,
        setup_stage=setup_stage, stage_next_step=stage_next_step,
        stage_entry_rule=stage_entry_rule, stage_invalidation=stage_invalidation,
        stage_direction=stage_direction,
        market_direction=market_direction,
        trade_opportunity=trade_opportunity,
        opportunity_reason=opportunity_reason,
        entry_trigger=entry_trigger,
        invalidation=invalidation,
        trade_plan=trade_plan,
        current_price=current_price,
        display_price=display_price, price_source=price_source,
        last_price_by_type=last_price_by_type,
        nearest_supply=nearest_supply, nearest_demand=nearest_demand,
        structure_label=structure_label, structure_class=structure_class,
        structure_detail=structure_detail,
        risk_label=risk_label, risk_detail=risk_detail, overextended=overextended,
        zone_broken_active=zone_broken_active,
        zone_mitigated_near=zone_mitigated_near,
        mitigated_zone_price=mitigated_zone_price,
        strict_label=strict_label, strict_score=strict_score,
        strict_direction=strict_direction, strict_reason=strict_reason,
        strict_missing=strict_missing, confluences=confluences,
        vwap_value=vwap_value, vwap_status=vwap_status,
        volatility=volatility,
        active_ticker=active_ticker,
    )

    # Preferred-session state (Eastern Time) — drives the +10 Session Bonus in the
    # Edge Score and the Session block on /status, /why and the trade card. Reuses
    # the SAME instant threaded into the gate so the bonus stays consistent.
    result["session"] = session_state
    # Per-gate WAIT debug (which READY gate failed) — surfaced on /status + logs.
    result["gate_debug"] = strict.get("gate_debug")
    # Candidate direction the gate evaluated (Long/Short/None) — for /diagnostics.
    result["gate_candidate"] = strict.get("candidate")

    # ── Tiered alert level (SCALP early-warning ladder) — additive, DISPLAY-ONLY.
    #    Computed independently of the verdict; it NEVER alters verdict / score /
    #    direction / trade plan, so SWING decisions stay byte-for-byte identical.
    #      WATCH           = price is at a fresh trade-side zone (within WATCH_PCT)
    #      ARMED           = at the zone AND >= 1 real confirmation present
    #      WATCH FOR ENTRY = at the zone, confirmations satisfied AND Edge >= 50 but
    #                        the full READY gate has not passed yet — one decisive
    #                        trigger (BOS/CHOCH/rejection candle/VWAP) tips it READY
    #      READY           = the full READY gate passed (verdict LONG/SHORT READY)
    #      None            = no candidate side, zone consumed/broken, price away
    #    The trade-side zone is demand for Long / supply for Short. A consumed
    #    (mitigated-near) or broken zone yields None — we never WATCH a dead zone. ──
    alert_level = None
    _cand   = result.get("gate_candidate")
    _gd_lvl = result.get("gate_debug") or {}
    # Actionable verdicts (full READY *and* EARLY READY) own the signal — mark the
    # operational level READY so the tiered ladder defers (no redundant WATCH/ARMED).
    if is_actionable(result["verdict"]):
        alert_level = "READY"
    # SETUP BUILDING is informational (NON-actionable): surface its own operational
    # level so the dedicated dispatcher can post it, and the tiered WATCH/ARMED ladder
    # is bypassed (the building heads-up owns the level). Never an actionable signal.
    elif result["verdict"] == "SETUP BUILDING":
        alert_level = "SETUP BUILDING"
    # The "dead zone → never WATCH" rule is a ZONE HARD-GATE behaviour: it holds in
    # SWING (cfg on) but is bypassed in SCALP (zone demoted), so a consumed/broken
    # zone no longer mutes the tiered WATCH/ARMED teaser ladder. The ladder still
    # only fires near an existing zone (the inner proximity test below).
    elif (_cand in ("Long", "Short")
          and (not cfg("GATE_REQUIRE_ZONE")
               or (not zone_broken_active and not zone_mitigated_near))):
        _zone = nearest_demand if _cand == "Long" else nearest_supply
        if (_zone and current_price
                and abs(current_price - _zone) / _zone <= cfg("WATCH_PCT")):
            _confs = int(_gd_lvl.get("confirmations_passed") or 0)
            _need  = int(_gd_lvl.get("confirmations_needed") or 0)
            _edge  = int(_gd_lvl.get("edge_score") or 0)
            if _confs >= _need and _edge >= 50:
                alert_level = "WATCH FOR ENTRY"
            elif _confs >= 1:
                alert_level = "ARMED"
            else:
                alert_level = "WATCH"
    result["alert_level"] = alert_level

    # ── CVD / RVOL state (per-instrument; from the strict gate). Stamped onto the
    #    result BEFORE the Edge breakdown so compute_edge_breakdown reads the SAME
    #    rvol_adj the gate used (display == gate). cvd_* are display-only here; the
    #    +10 CVD-agreement bonus is already carried in the confluences. ──
    result["cvd_state"]     = strict.get("cvd_state")
    result["cvd_value"]     = strict.get("cvd_value")
    result["cvd_direction"] = strict.get("cvd_direction")
    result["rvol_value"]    = strict.get("rvol_value")
    result["rvol_adj"]      = strict.get("rvol_adj")
    # Volume confirmation (directionless) — stamped BEFORE the Edge breakdown so
    # compute_edge_breakdown reads the SAME volume_confirmed the gate scored.
    result["volume_confirmed"]    = strict.get("volume_confirmed")
    result["volume_data_present"] = strict.get("volume_data_present")
    result["volume_state"]        = strict.get("volume_state")

    # ── Unified Edge Score (single source of truth) ──────────────────────────
    # The transparent, confluence-based Edge Score replaces the legacy bias-derived
    # score on EVERY user-facing surface (status, why, alerts, journal, recaps,
    # dashboard, trade management). The legacy value is kept internal-only as a
    # last-resort ranking fallback for old/manual journal entries; never displayed.
    eb = _analysis_edge_breakdown(result)
    result["legacy_edge_score"] = edge_score
    result["edge_breakdown"]    = eb
    result["edge_score"]        = eb["score"]
    result["edge_grade"]        = eb["grade"]
    # ── Conviction tier (display-only, score-banded) — distinct from alert_level
    #    (operational dispatch state). HIGH CONVICTION >=70 / READY 50-69 / EARLY
    #    READY 35-49 / None. Names the STRENGTH of the Edge Score; never gates. ──
    result["conviction_tier"]   = _score_tier(result["edge_score"])

    # ── Gate diagnostics (additive, display-only) — surfaced on every alert,
    #    /status and the dashboard probability gauge. These are the SAME numbers
    #    the gate used to decide READY / WAIT / conflict (sourced from `strict`),
    #    plus the single volatility read, so the displayed values can never diverge
    #    from the decision. All keys ALWAYS set (single-return-path invariant). ──
    result["long_score"]            = strict.get("long_score")
    result["short_score"]           = strict.get("short_score")
    result["conflict_gap"]          = strict.get("conflict_gap")
    result["dominant_direction"]    = strict.get("dominant_direction")
    result["current_atr"]           = volatility.get("atr_pts")
    result["volatility_multiplier"] = volatility.get("ratio")
    result["ready_reason"]          = strict_reason
    result["rejected_reasons"]      = strict_missing
    # ── Alert diagnostics (additive, DISPLAY/observability ONLY) ─────────────
    # One transparent snapshot bundling the two per-direction scores, the unified
    # Edge Score, the conflict gap, the live ATR / volatility multiplier, plus the
    # human READY reason and the humanised rejected gate reasons. Attached to every
    # alert + /status + the dashboard diagnostics modules. NEVER feeds the trade
    # decision, so SWING is byte-for-byte unchanged. The market-closed override
    # below zeros it so a paused market can't present a stale "why".
    _diag_gd    = result.get("gate_debug") or {}
    _diag_long  = int(strict.get("long_score",  _diag_gd.get("long_score",  0)) or 0)
    _diag_short = int(strict.get("short_score", _diag_gd.get("short_score", 0)) or 0)
    _diag_gap   = int(strict.get("conflict_gap", _diag_gd.get("conflict_gap", 0)) or 0)
    if _diag_long > _diag_short:
        _diag_dom = "Long"
    elif _diag_short > _diag_long:
        _diag_dom = "Short"
    else:
        _diag_dom = "Neutral"
    _diag_ready = is_actionable(result["verdict"])
    # CVD agreement relative to the dominant side (display-only). "Confirmed" when
    # the delta agrees, "Conflicting" when it opposes, the raw bias when there is no
    # dominant side, and "Unknown" when CVD has not been reported for this instrument.
    _cvd_st = strict.get("cvd_state")
    _cvd_live = CVD_BY_TICKER.get(active_ticker) or {}
    if not _cvd_st:
        _cvd_agree = "Unknown"
    elif _diag_dom == "Neutral":
        _cvd_agree = "Bullish" if _cvd_st == "bullish" else "Bearish"
    elif (_diag_dom == "Long" and _cvd_st == "bullish") or (_diag_dom == "Short" and _cvd_st == "bearish"):
        _cvd_agree = "Confirmed"
    else:
        _cvd_agree = "Conflicting"
    # Per-setup score diagnostics (the authoritative breakdown for the favored side).
    _diag_eb       = result.get("edge_breakdown") or {}
    _diag_blockers = list(_diag_gd.get("failed_conditions") or [])
    # ── camelCase diagnostics (dashboard modules) — additive, observability-only ──
    _req_edge = int(cfg("EDGE_READY_THRESHOLD"))
    _strong   = cfg("EDGE_STRONG_THRESHOLD")
    _edge_now = int(result.get("edge_score") or 0)
    # readyStrength: only meaningful on an actionable verdict — "Strong" at/above the
    # strong threshold, else "Standard". None when not READY (incl. SETUP BUILDING/WAIT).
    if _diag_ready:
        _ready_strength = "Strong" if (_strong is not None and _edge_now >= int(_strong)) else "Standard"
    else:
        _ready_strength = None
    # vwapDistance: absolute points between price and the live VWAP (None-safe).
    try:
        _vwap_dist = (abs(float(current_price) - float(vwap_value))
                      if (current_price is not None and vwap_value is not None) else None)
    except (TypeError, ValueError):
        _vwap_dist = None
    if _vwap_dist is not None:
        _vwap_dist = round(_vwap_dist, 2)
    # zoneAge: best-effort minutes since the latest zone-FORMING alert for this
    # instrument (NEW/CONFIRMED demand/supply). None when none found or unparseable.
    _zone_age = None
    try:
        _inst_age = instrument_of(active_ticker)
        for _al in reversed(ALERT_HISTORY):
            _at = str(_al.get("alert_type") or "").upper()
            if "ZONE" not in _at or "BROKEN" in _at or "MITIGATED" in _at:
                continue
            _ai = _al.get("instrument") or instrument_of(_al.get("ticker") or "")
            if _inst_age and _ai and _ai != _inst_age:
                continue
            _zone_age = int((now_utc() - datetime.fromisoformat(_al["timestamp"])).total_seconds() // 60)
            break
    except Exception:
        _zone_age = None
    result["alert_diagnostics"] = {
        "long_score":            _diag_long,
        "short_score":           _diag_short,
        "edge_score":            int(result.get("edge_score") or 0),
        "conflict_gap":          _diag_gap,
        "dominant_direction":    _diag_dom,
        "current_atr":           (volatility or {}).get("atr_pts"),
        "volatility_multiplier": (volatility or {}).get("ratio"),
        "ready_reason":          (strict_reason if _diag_ready else ""),
        "rejected_reasons":      _humanize_gate_rejections(_diag_gd),
        "current_score":         int(result.get("edge_score") or 0),
        "required_score":        int(cfg("EDGE_READY_THRESHOLD")),
        # Per-setup Edge breakdown (display/observability): the credited components,
        # the confirmations that did NOT fire, the gates blocking READY, and the
        # honest raw-vs-clamped accounting.
        "score_breakdown":       _diag_eb.get("score_breakdown") or [],
        "components":            _diag_eb.get("components") or [],
        "failed_confirmations":  _diag_eb.get("failed_confirmations") or [],
        "ready_blockers":        _diag_blockers,
        "raw_score":             int(_diag_eb.get("raw_score") or 0),
        "max_score":             EDGE_SCORE_MAX,
        "cap_applied":           bool(_diag_eb.get("cap_applied")),
        # Volume confirmation (+15 component, fail-open READY gate) + location gate.
        "volume_state":          _diag_gd.get("volume_state"),
        "volume_confirmed":      bool(_diag_gd.get("volume_confirmed")),
        "volume_data_present":   bool(_diag_gd.get("volume_data_present")),
        "location_ok":           bool(_diag_gd.get("location_ok")),
        "near_vwap":             bool(_diag_gd.get("near_vwap")),
        # CVD hard-filter + RVOL soft-modifier diagnostics (display-only).
        # cvd_state is the COMMITTED direction (what the gate vetoes on); cvd_pending
        # + cvd_opposite_count expose the 2-candle flip confirmation in progress.
        "cvd_state":             _cvd_st,
        "cvd_pending":           _cvd_live.get("pending_dir"),
        "cvd_opposite_count":    int(_cvd_live.get("opposite_count") or 0),
        "cvd_value":             strict.get("cvd_value"),
        "cvd_direction":         strict.get("cvd_direction"),
        "cvd_agreement":         _cvd_agree,
        "rvol_value":            strict.get("rvol_value"),
        "rvol_adj":              int(strict.get("rvol_adj") or 0),
        # ── camelCase diagnostics consumed by the dashboard modules (additive,
        #    display-only). edgeScore/requiredEdgeScore/failedGates/scoreBreakdown
        #    mirror the snake_case fields above; zoneAge/zoneConsumed/vwapDistance/
        #    cvdState/readyStrength are new heads-up signals for the SCALP redesign. ──
        "edgeScore":             _edge_now,
        "requiredEdgeScore":     _req_edge,
        "failedGates":           _diag_blockers,
        "scoreBreakdown":        _diag_eb.get("score_breakdown") or [],
        "zoneAge":               _zone_age,
        "zoneConsumed":          bool(result.get("zone_mitigated_near")),
        "vwapDistance":          _vwap_dist,
        "cvdState":              _cvd_st,
        "readyStrength":         _ready_strength,
    }
    # Decision-support header (Quality/Probability/Risk/Reward/Window/Recommendation)
    # — all real-derived from the fields set above.
    result["decision_support"]      = _decision_support(result)

    # ── Per-direction Edge Scores (additive, display-only) ───────────────────
    # The dashboard Long/Short toggle shows the bull case AND the bear case. The
    # favored side REUSES the authoritative breakdown verbatim (guaranteed parity
    # with edge_score above); the other side is scored from its own confluences
    # with a WAIT state so it is never floored at 75. A conflict or a hard blocker
    # (zone broken / consumed) zeros both sides — neither is tradeable.
    dirs_raw = strict.get("directions") or {}
    auth_dir = (result.get("confluences") or {}).get("direction")
    # Zone is a hard blocker only in SWING (GATE_REQUIRE_ZONE). In SCALP a broken/
    # consumed zone is non-blocking, so it must not zero the direction cards either.
    blockers = bool(cfg("GATE_REQUIRE_ZONE")
                    and (result.get("zone_broken_active") or result.get("zone_mitigated_near")))
    out_dirs = {}
    for _d in ("Long", "Short"):
        block = dict(dirs_raw.get(_d) or {})
        if block.get("conflict"):
            block.update(
                ready=False, label="WAIT", score=0,
                edge_score=0, edge_grade=_grade_for_score(0),
                edge_breakdown={
                    "score": 0, "grade": _grade_for_score(0),
                    "score_breakdown": [],
                    "risk_adjustments": [{"label": "Conflicting structure — stand aside", "points": None}],
                    "reasons": [], "risks": ["Conflicting structure — stand aside"],
                },
            )
        elif _d == auth_dir:
            # Mirror the authoritative final decision so the favored side is identical.
            ready_dir = is_actionable(result["verdict"])
            block.update(
                ready=bool(ready_dir),
                label="READY" if ready_dir else "WAIT",
                score=0 if blockers else result["strict_score"],
                reason=result.get("strict_reason") or block.get("reason"),
                edge_score=result["edge_score"],
                edge_grade=result["edge_grade"],
                edge_breakdown=result["edge_breakdown"],
            )
        else:
            a_copy = dict(result)
            a_copy["confluences"]      = block.get("confluences") or {}
            a_copy["strict_direction"] = _d
            a_copy["strict_label"]     = "WAIT"
            a_copy["verdict"]          = "WAIT"
            # Read THIS side's own stamped soft modifiers (not the candidate's) so the
            # non-favored Edge Score keeps gate↔display parity for its own direction.
            a_copy["gate_debug"]       = block.get("gate_debug") or {}
            eb_d = _analysis_edge_breakdown(a_copy)
            block.update(edge_score=eb_d["score"], edge_grade=eb_d["grade"], edge_breakdown=eb_d)
            if blockers:
                block.update(ready=False, label="WAIT", score=0)

        # ── Potential trade plan (DISPLAY-ONLY; NEVER broker-eligible) ──────────
        # As soon as a structural setup is FORMING for this side, surface the
        # would-be entry / stop / targets / R:R so the user can pre-plan BEFORE a
        # full READY. The real-order path keys off the actionable verdict + the
        # top-level result["trade_plan"] only, so this nested per-direction preview
        # can never light up the Apply / Copy / Send broker actions. Suppressed on
        # conflict, a hard blocker (zone broken/consumed), a missing price, a closed
        # session, or before any structural alert exists — and kept as None in all
        # those cases for single-return-path reader parity.
        potential_plan = None
        _gd = block.get("gate_debug") or {}
        if (current_price is not None and market["open"]
                and not block.get("conflict") and not blockers
                and _gd.get("structure_confirmed")):
            _pp = build_strict_trade_plan(
                _d, active_ticker, current_price, nearest_supply, nearest_demand,
                volatility=volatility, mode=TRADING_MODE, vwap=vwap_value,
                swing_context=swing_ctx,
            )
            if _pp.get("trade_plan"):
                potential_plan = _pp
        block["potential_plan"] = potential_plan
        out_dirs[_d] = block
    result["directions"] = out_dirs

    # ── Multi-strategy engine (Phase 1 — DISPLAY-ONLY detection) ─────────────
    # Regime + session bias + scored strategies + best-fit selection. Does NOT
    # touch verdict / directions / trade_plan (those stay owned by the strict
    # gate). The market-closed override below replaces it with a paused snapshot.
    result["strategy_engine"] = compute_strategy_engine(
        active_ticker, current_price, vwap_value, vwap_status, volatility,
        result.get("edge_score"),
    )
    # ORB-only exception to the fixed-1:1 rule: a real, actionable Opening-Range-
    # Breakout setup retargets to 1:4 (rewrites the authoritative trade_plan in place;
    # all other strategies remain 1:1). Runs while the market is open; the closed
    # override below independently neutralizes the verdict so no closed-market send.
    _apply_orb_target_override(result)

    # ── Display-only feeds (READ-ONLY; never touch the gate / money path) ─────
    result["equity_curve_today"] = get_today_equity_curve(active_ticker)
    result["news_filter"]        = get_news_filter()

    # ── Market-session awareness (additive; single neutralising override) ────
    # MNQ/MGC share the CME/COMEX schedule. While the market is CLOSED there is no
    # live tape, so reporting WAIT (or counting "failed" evals) is misleading. We
    # always surface the closed state, the next open, and the last valid price/time;
    # and when closed we PAUSE the trade decision (no READY/ARMED, no edge/confirm/
    # session scoring presented as a live read). All keys still exist, so every
    # hard-indexed consumer is safe (single-return-path invariant).
    result["market_open"]   = market["open"]
    result["market_status"] = market["status"]
    result["next_open"]     = market["next_open_et"]
    result["next_open_utc"] = market["next_open"].isoformat() if market["next_open"] else None
    result["market_reason"] = market["reason"]
    _lv_price, _lv_ts, _lv_src = last_valid_data_for(active_ticker)
    result["last_valid_price"]  = _lv_price
    result["last_valid_time"]   = fmt_et(_lv_ts, "%b %-d, %-I:%M %p ET") if _lv_ts else None
    result["last_valid_source"] = _lv_src

    # ── Analyst Reasoning Engine (Context -> Thesis -> Evidence -> Risk ->
    #    Verdict). DISPLAY by default; the flag-gated, fail-CLOSED veto can ONLY
    #    demote an actionable gate verdict to WAIT (never promote). Computed from the
    #    FINAL assembled result so it reflects every override above. The market-closed
    #    override below replaces it with a paused stub (single-return-path parity). ──
    if market["open"]:
        if _analyst_engine_enabled():
            try:
                _analyst = compute_analyst_reasoning(result, strict, swing_ctx, market)
            except Exception as exc:   # FAIL-OPEN — a broken analyst must never crash analysis.
                _analyst = _analyst_neutral_block(f"Analyst engine unavailable ({exc}).")
        else:
            _analyst = _analyst_neutral_block("Analyst engine disabled.")
        # Fail-CLOSED veto: only when explicitly enabled AND the analyst disagrees
        # with an actionable gate verdict. It can ONLY demote to WAIT — never promote.
        if (_analyst_gate_enabled() and _analyst.get("veto_would_fire")
                and is_actionable(result["verdict"])):
            _veto_reason = ("Analyst veto: "
                            + (_analyst.get("why_not_trade")
                               or "analyst reasoning does not support the trade."))
            result["verdict"]       = "WAIT"
            result["strict_label"]  = "WAIT"
            result["strict_reason"] = _veto_reason
            result["trade_plan"]    = {
                "trade_plan": False, "reason": _veto_reason,
                "entry_zone": None, "stop_loss": None,
                "target1":    None, "target2":   None,
                "rr":         None, "direction": result.get("strict_direction"),
                "instrument": active_ticker, "point_value": point_value_for(active_ticker),
            }
            for _vd in ("Long", "Short"):
                _vblk = (result.get("directions") or {}).get(_vd)
                if _vblk:
                    _vblk.update(ready=False, label="WAIT")
            _ad = result.get("alert_diagnostics") or {}
            _ad["ready_reason"]     = ""
            _ad["rejected_reasons"] = list(_ad.get("rejected_reasons") or []) + ["Analyst veto"]
            result["alert_diagnostics"] = _ad
            # Decision-support was computed earlier from the pre-veto plan — recompute
            # it so every display surface agrees with the demoted WAIT verdict.
            result["decision_support"] = _decision_support(result)
            _analyst["final_verdict"] = "WAIT"
        result["analyst"] = _analyst
        # ── Professional Review (DISPLAY-ONLY here; the flag-gated veto is wired
        #    in just below, mirroring the analyst layer). Computed from the FINAL
        #    assembled result so it reflects every override above. ──────────────
        if _pro_review_engine_enabled():
            try:
                result["pro_review"] = compute_pro_review(
                    result, strict, swing_ctx, market, active_ticker)
            except Exception as exc:   # FAIL-OPEN — a broken review must never crash analysis.
                result["pro_review"] = _pro_review_neutral_block(
                    "Pro review unavailable (%s)." % exc, inst=active_ticker)
        else:
            result["pro_review"] = _pro_review_neutral_block(
                "Pro review disabled.", inst=active_ticker)
        # Fail-CLOSED veto (flag-gated, default OFF): only when explicitly enabled
        # AND the ACTIVE model would not take the trade (veto_would_fire) AND the
        # gate verdict is still actionable. It can ONLY demote to WAIT — never
        # promote. The neutral / disabled / market-closed stub sets
        # veto_would_fire=False so it can NEVER demote. Mirrors the analyst veto.
        _pr      = result.get("pro_review") or {}
        _pr_act  = _pr.get("active") or {}
        if (_pro_review_gate_enabled() and _pr_act.get("veto_would_fire")
                and is_actionable(result["verdict"])):
            _pr_reason = ("Pro Review veto: "
                          + (_pr_act.get("why_not_trade")
                             or "professional review does not support the trade."))
            result["verdict"]       = "WAIT"
            result["strict_label"]  = "WAIT"
            result["strict_reason"] = _pr_reason
            result["trade_plan"]    = {
                "trade_plan": False, "reason": _pr_reason,
                "entry_zone": None, "stop_loss": None,
                "target1":    None, "target2":   None,
                "rr":         None, "direction": result.get("strict_direction"),
                "instrument": active_ticker, "point_value": point_value_for(active_ticker),
            }
            for _vd in ("Long", "Short"):
                _vblk = (result.get("directions") or {}).get(_vd)
                if _vblk:
                    _vblk.update(ready=False, label="WAIT")
            _ad = result.get("alert_diagnostics") or {}
            _ad["ready_reason"]     = ""
            _ad["rejected_reasons"] = list(_ad.get("rejected_reasons") or []) + ["Pro Review veto"]
            result["alert_diagnostics"] = _ad
            # Decision-support was computed earlier from the pre-veto plan — recompute
            # it so every display surface agrees with the demoted WAIT verdict.
            result["decision_support"] = _decision_support(result)
        # ── Trade Debate Engine (Bull vs Bear vs Decision Judge). DISPLAY-ONLY
        #    here; the flag-gated veto is wired in just below, mirroring the pro
        #    review / analyst layers. Computed from the FINAL assembled result so it
        #    reflects every override above (Analyst -> Pro Review -> Debate). ──────
        if _trade_debate_engine_enabled():
            try:
                result["trade_debate"] = compute_trade_debate(result, strict)
            except Exception as exc:   # FAIL-OPEN — a broken debate must never crash analysis.
                result["trade_debate"] = _trade_debate_neutral_block(
                    "Trade debate unavailable (%s)." % exc)
        else:
            result["trade_debate"] = _trade_debate_neutral_block("Trade debate disabled.")
        # Fail-CLOSED veto (flag-gated, default OFF): only when explicitly enabled
        # AND the Judge would not decisively + alignedly support the trade
        # (veto_would_fire) AND the gate verdict is still actionable. It can ONLY
        # demote to WAIT — never promote. The neutral / disabled / market-closed stub
        # sets veto_would_fire=False so it can NEVER demote. Mirrors the pro-review veto.
        _td = result.get("trade_debate") or {}
        if (_trade_debate_gate_enabled() and _td.get("veto_would_fire")
                and is_actionable(result["verdict"])):
            _td_reason = ("Trade Debate veto: "
                          + (_td.get("summary")
                             or "the market is too balanced to trade."))
            result["verdict"]       = "WAIT"
            result["strict_label"]  = "WAIT"
            result["strict_reason"] = _td_reason
            result["trade_plan"]    = {
                "trade_plan": False, "reason": _td_reason,
                "entry_zone": None, "stop_loss": None,
                "target1":    None, "target2":   None,
                "rr":         None, "direction": result.get("strict_direction"),
                "instrument": active_ticker, "point_value": point_value_for(active_ticker),
            }
            for _vd in ("Long", "Short"):
                _vblk = (result.get("directions") or {}).get(_vd)
                if _vblk:
                    _vblk.update(ready=False, label="WAIT")
            _ad = result.get("alert_diagnostics") or {}
            _ad["ready_reason"]     = ""
            _ad["rejected_reasons"] = list(_ad.get("rejected_reasons") or []) + ["Trade Debate veto"]
            result["alert_diagnostics"] = _ad
            # Decision-support was computed earlier from the pre-veto plan — recompute
            # it so every display surface agrees with the demoted WAIT verdict.
            result["decision_support"] = _decision_support(result)
            result["trade_debate"]["judge"]["final_verdict"] = "WAIT"
        # ── Entry Quality Engine (LOCATION-aware): scores WHETHER this is a good
        #    PLACE to enter (distance to S/R, impulse % completed, ATR extension,
        #    pullback, momentum, sweep, chasing, swing-high/low). DISPLAY-ONLY here;
        #    computed on the FINAL assembled result so it reflects every override
        #    above. Mirrors the analyst / pro-review / debate layers. ──────────────
        if _entry_quality_engine_enabled():
            try:
                result["entry_quality"] = compute_entry_quality(result, strict, swing_ctx)
            except Exception as exc:   # FAIL-OPEN — a broken engine must never crash analysis.
                result["entry_quality"] = _entry_quality_neutral_block(
                    "Entry Quality unavailable (%s)." % exc)
        else:
            result["entry_quality"] = _entry_quality_neutral_block("Entry Quality engine disabled.")
        # Fail-CLOSED veto (flag-gated, default OFF): only when explicitly armed AND
        # the entry LOCATION is poor (veto_would_fire = score < threshold and NOT an
        # extremely-high-confidence override) AND the gate verdict is still
        # actionable. It can ONLY demote to WAIT — never promote. The neutral /
        # disabled / market-closed stub sets veto_would_fire=False so it can NEVER
        # demote. Mirrors the pro-review / trade-debate vetoes.
        _eq = result.get("entry_quality") or {}
        if (_entry_quality_gate_enabled() and _eq.get("veto_would_fire")
                and is_actionable(result["verdict"])):
            _eq_reason = ("Entry Quality veto: "
                          + (_eq.get("why_not_trade")
                             or ("entry location is poor (%s/100)." % _eq.get("score"))))
            result["verdict"]       = "WAIT"
            result["strict_label"]  = "WAIT"
            result["strict_reason"] = _eq_reason
            result["trade_plan"]    = {
                "trade_plan": False, "reason": _eq_reason,
                "entry_zone": None, "stop_loss": None,
                "target1":    None, "target2":   None,
                "rr":         None, "direction": result.get("strict_direction"),
                "instrument": active_ticker, "point_value": point_value_for(active_ticker),
            }
            for _vd in ("Long", "Short"):
                _vblk = (result.get("directions") or {}).get(_vd)
                if _vblk:
                    _vblk.update(ready=False, label="WAIT")
            _ad = result.get("alert_diagnostics") or {}
            _ad["ready_reason"]     = ""
            _ad["rejected_reasons"] = list(_ad.get("rejected_reasons") or []) + ["Entry Quality veto"]
            result["alert_diagnostics"] = _ad
            # Decision-support was computed earlier from the pre-veto plan — recompute
            # it so every display surface agrees with the demoted WAIT verdict.
            result["decision_support"] = _decision_support(result)
            result["entry_quality"]["final_verdict"] = "WAIT"

    # ── Learning Engine v2 (display-only): Confidence Governor + Trade Memory.
    # Computed on the ASSEMBLED result AFTER pro_review/trade_debate so grade /
    # entry-efficiency / strategy_engine are populated. Strictly FAIL-OPEN (neutral
    # block on any error) and mutate NOTHING — the flag-gated demotion is T004.
    # SHARED Trade Memory — computed ONCE here (after pro_review / trade_debate so the
    # grade is available) and fed to BOTH the governor and the memory panel AND the
    # analyst, so all three read IDENTICAL historical data (single source of truth).
    try:
        _memory_ctx = find_similar_trades(result, active_ticker)
    except Exception:
        _memory_ctx = _similar_neutral_block()
    result["trade_memory_context"] = _memory_ctx
    try:
        result["confidence_governor"] = compute_confidence_governor(
            result, active_ticker, memory_ctx=_memory_ctx)
    except Exception:
        result["confidence_governor"] = _governor_neutral_block(result)
    try:
        result["trade_memory"] = compute_trade_memory(
            result, active_ticker, memory_ctx=_memory_ctx)
    except Exception:
        result["trade_memory"] = _memory_neutral_block()
    # Analyst (AI Reasoning) consumes the SAME shared memory to answer the trader's
    # six historical questions. DISPLAY-ONLY — never touches the analyst veto above.
    try:
        if isinstance(result.get("analyst"), dict):
            result["analyst"]["memory_review"] = build_analyst_memory_review(_memory_ctx)
    except Exception:
        pass
    # Entry Probability is a FORWARD projection over the Entry Quality block, which is
    # computed AFTER the analyst (ordering), so it is attached post-hoc here — exactly
    # like the shared memory review above. DISPLAY-ONLY + fail-open; the guard means the
    # market-closed / no-analyst branches keep the neutral placeholder.
    try:
        if isinstance(result.get("analyst"), dict):
            result["analyst"]["entry_probability"] = _analyst_entry_probability(
                result.get("entry_quality"), result["analyst"], result, TRADING_MODE)
    except Exception:
        pass

    # ── Learning Engine demotion (flag-gated, default OFF — mirrors the analyst /
    #    pro-review / trade-debate vetoes). When ARMED, a Confidence-Governor final
    #    score below the READY threshold DEMOTES an actionable gate verdict to WAIT
    #    (it can NEVER promote / force a trade / change geometry). The neutral /
    #    fail-open / market-closed governor block sets veto_would_fire=False so it can
    #    NEVER demote when there is no history or the market is closed. Guarded by
    #    market["open"] so it never touches the closed-override verdict below. ──────
    _cg = result.get("confidence_governor") or {}
    if (market["open"] and _learning_gate_enabled() and _cg.get("veto_would_fire")
            and is_actionable(result["verdict"])):
        _lr_reason = ("Learning veto: final confidence %d below the %d READY "
                      "threshold (historical edge for this setup is weak)." % (
                          int(_cg.get("final_confidence_score") or 0),
                          int(_cg.get("threshold") or 0)))
        result["verdict"]       = "WAIT"
        result["strict_label"]  = "WAIT"
        result["strict_reason"] = _lr_reason
        result["trade_plan"]    = {
            "trade_plan": False, "reason": _lr_reason,
            "entry_zone": None, "stop_loss": None,
            "target1":    None, "target2":   None,
            "rr":         None, "direction": result.get("strict_direction"),
            "instrument": active_ticker, "point_value": point_value_for(active_ticker),
        }
        for _vd in ("Long", "Short"):
            _vblk = (result.get("directions") or {}).get(_vd)
            if _vblk:
                _vblk.update(ready=False, label="WAIT")
        _ad = result.get("alert_diagnostics") or {}
        _ad["ready_reason"]     = ""
        _ad["rejected_reasons"] = list(_ad.get("rejected_reasons") or []) + ["Learning veto"]
        result["alert_diagnostics"] = _ad
        # Decision-support was computed earlier from the pre-veto plan — recompute
        # it so every display surface agrees with the demoted WAIT verdict.
        result["decision_support"] = _decision_support(result)
        result["confidence_governor"]["demotion_reason"] = _lr_reason
        logger.info("LEARNING VETO fired for %s: final=%s thr=%s — verdict -> WAIT",
                    active_ticker, _cg.get("final_confidence_score"), _cg.get("threshold"))

    if not market["open"]:
        result["verdict"]         = "MARKET CLOSED"
        # strict_label is the JOURNALING label and must stay in
        # {Strong Trade, Possible Trade, WAIT}; the closed state is surfaced via
        # verdict + market_status + strict_reason instead (the dashboard badge reads
        # those, not strict_label), so closed evals never journal as a tradeable setup.
        result["strict_label"]    = "WAIT"
        result["strict_reason"]   = (
            "Market closed — live alerts paused"
            + (f". Next open: {market['next_open_et']}." if market["next_open_et"] else ".")
        )
        result["alert_level"]     = None
        result["conviction_tier"] = None
        result["edge_score"]      = 0
        result["edge_grade"]      = None
        # Neutralise the live diagnostics too — there is no live tape when closed,
        # so stale per-direction scores must not read as a tradeable signal.
        result["long_score"]         = None
        result["short_score"]        = None
        result["conflict_gap"]       = None
        result["dominant_direction"] = None
        result["ready_reason"]       = result["strict_reason"]
        result["rejected_reasons"]   = ["market_closed"]
        # Neutralise the CVD / RVOL / volume stamps too — there is no live tape closed.
        result["cvd_state"]          = None
        result["cvd_value"]          = None
        result["cvd_direction"]      = None
        result["rvol_value"]         = None
        result["rvol_adj"]           = 0
        result["volume_confirmed"]    = False
        result["volume_data_present"] = False
        result["volume_state"]        = None
        result["alert_diagnostics"] = {
            "long_score":            0,
            "short_score":           0,
            "edge_score":            0,
            "conflict_gap":          0,
            "dominant_direction":    "Neutral",
            "current_atr":           None,
            "volatility_multiplier": None,
            "ready_reason":          "",
            "rejected_reasons":      ["Market closed — live alerts paused"],
            "current_score":         0,
            "required_score":        int(cfg("EDGE_READY_THRESHOLD")),
            # Per-setup Edge breakdown — neutralised while the market is closed.
            "score_breakdown":       [],
            "components":            [],
            "failed_confirmations":  [],
            "ready_blockers":        ["market_closed"],
            "raw_score":             0,
            "max_score":             EDGE_SCORE_MAX,
            "cap_applied":           False,
            "volume_state":          None,
            "volume_confirmed":      False,
            "volume_data_present":   False,
            "location_ok":           False,
            "near_vwap":             False,
            "cvd_state":             None,
            "cvd_pending":           None,
            "cvd_opposite_count":    0,
            "cvd_value":             None,
            "cvd_direction":         None,
            "cvd_agreement":         "Unknown",
            "rvol_value":            None,
            "rvol_adj":              0,
            # camelCase diagnostics — neutralised while the market is closed.
            "edgeScore":             0,
            "requiredEdgeScore":     int(cfg("EDGE_READY_THRESHOLD")),
            "failedGates":           ["market_closed"],
            "scoreBreakdown":        [],
            "zoneAge":               None,
            "zoneConsumed":          False,
            "vwapDistance":          None,
            "cvdState":              None,
            "readyStrength":         None,
        }
        result["decision_support"]   = _decision_support(result)
        # Strategy engine paused while the market is closed (no live tape).
        result["strategy_engine"]    = _closed_strategy_engine()
        # Display-only feeds stay present for parity with the open path.
        result["equity_curve_today"] = get_today_equity_curve(active_ticker)
        result["news_filter"]        = get_news_filter()
        # Analyst Reasoning paused while the market is closed (no live tape) — a
        # fully-populated stub keeps the single-return-path / hard-index invariant.
        result["analyst"]            = _analyst_neutral_block(
            "Market closed — live alerts paused.", verdict="NO TRADE")
        result["pro_review"]         = _pro_review_neutral_block(
            "Market closed — live alerts paused.", inst=active_ticker)
        result["trade_debate"]       = _trade_debate_neutral_block(
            "Market closed — live alerts paused.")
        result["confidence_governor"] = _governor_neutral_block(
            result, reason="Market closed — live alerts paused.")
        result["trade_memory"]        = _memory_neutral_block(
            "Market closed — live alerts paused.")
        result["entry_quality"]       = _entry_quality_neutral_block(
            "Market closed — live alerts paused.")
        for _d in ("Long", "Short"):
            _blk = result["directions"].get(_d)
            if _blk:
                _blk.update(ready=False, label="WAIT")
    # ── SCALP dynamic-exit DIAGNOSTICS (Phase S1 = DISPLAY-ONLY) ──────────────
    # Computed from the FINAL post-override result so it reflects every WAIT/closed
    # override above. SCALP-only + flag-gated inside the helper (SWING / disabled →
    # an inert block, no behaviour change). Direction is the authoritative strict
    # direction (or the gate's candidate while forming); neutral while closed.
    _sq_dir = result.get("strict_direction")
    if not _sq_dir and result.get("market_open"):
        _sq_dir = strict.get("candidate")
    if not result.get("market_open"):
        _sq_dir = None
    if scalp_quality_block is not None and result.get("market_open"):
        # A SCALP entry veto fired above and dropped the trade plan; reuse the block
        # computed from the REAL (pre-veto) plan so the dashboard still shows the
        # rejected setup's geometry + failing checks.
        result["scalp_quality"] = scalp_quality_block
    else:
        result["scalp_quality"] = compute_scalp_quality(
            _sq_dir, result.get("current_price"), result.get("vwap_value"),
            result.get("vwap_status"), result.get("nearest_supply"),
            result.get("nearest_demand"), result.get("trade_plan"),
            result.get("edge_score"), instrument_of(active_ticker),
            (result.get("volatility") or {}).get("atr_pts"),
        )

    # Adaptive-learning: cache the freshest engine+indicator snapshot per instrument
    # so a setup that registers right after this can be tagged with its entry context.
    try:
        _update_learning_snapshot(result, ticker_override)
    except Exception:
        pass

    # ── SWING higher-timeframe context (P2 = DISPLAY-ONLY) ────────────────────
    # Attached only under SWING + flag (SCALP / flag-off → key absent, byte-identical
    # to today). REUSES the single `swing_ctx` computed once above so the gate (P4),
    # the plan target geometry, the preview, and this display surface all read the
    # SAME context (no drift, no redundant fetch). FAIL-OPEN for display: if the
    # one-time precompute raised (swing_ctx is None), fall back to a stable schema so
    # the dashboard still renders. Curated /status whitelisting + the dashboard
    # module land in P7.
    if _swing_htf_enabled():
        result["swing_context"] = swing_ctx if isinstance(swing_ctx, dict) else {
            "enabled": True, "complete": False, "stale": True, "error": "compute_failed"}

    # ── Unified Analyst Report (DISPLAY-ONLY) ────────────────────────────────
    # SINGLE computation point, AFTER every verdict override above (open, vetoed and
    # closed paths all land here) so it always reflects the final result — this also
    # preserves the single-return-path / hard-index invariant. It only CONSUMES the
    # already-assembled analyst / debate / governor / memory / volatility / news
    # blocks (never recomputes them) and has NO veto. Framed around the OPEN
    # position's direction when one is held, else the favored side. The tiny
    # prev-confidence store (per-instrument, re-baselined only on a real move) powers
    # the change narrative — a display-only side effect; goldens never call
    # full_analysis. FAIL-OPEN so a bug here can never break the gate's result.
    try:
        _ar_inst = instrument_of(active_ticker)
        _ar_pos  = active_trade_for(_ar_inst)
        _ar_dir  = _ar_pos.get("direction") if isinstance(_ar_pos, dict) else None
        result["analyst_report"] = compute_analyst_report(
            result, position_dir=_ar_dir, prev_conf=_analyst_report_prev(_ar_inst))
        _analyst_report_update_prev(_ar_inst, result["analyst_report"])
    except Exception as _ar_exc:
        result["analyst_report"] = _analyst_report_neutral_block(
            "Analyst report unavailable (%s)." % _ar_exc)

    # ── Fast Entry Trigger (seconds-timing) — DISPLAY-FIRST aggregator ────────
    # SINGLE computation point AFTER every verdict override above (open / vetoed /
    # closed paths all land here). CONSUMES ONLY the already-assembled strict output
    # (never recomputes the gate) plus the fresh micro-event snapshot, and returns
    # the inert neutral block while closed / off (so it never reads as tradeable).
    # FAIL-OPEN. The optional money path is wired separately in the single-threaded
    # webhook worker — this attach is display / state only.
    try:
        result["fast_entry"] = _compute_fast_entry_trigger(result, instrument_of(active_ticker))
    except Exception as _fe_exc:
        result["fast_entry"] = _fast_entry_neutral("Fast entry unavailable (%s)." % _fe_exc)
    return result


# ---------------------------------------------------------------------------
# Trade Management v12
# ---------------------------------------------------------------------------

def compute_pnl(trade, current_price):
    """Returns (dollar_pnl, points_pnl) for the active trade.

    Uses the trade instrument's OWN point value (MGC $10, MNQ $2, MES $5, MYM
    $0.50) so PnL is correct per asset. MGC is unchanged (its spec point value IS
    MGC_POINT_VALUE); MNQ/MES/MYM now book PnL at their real contract multiplier
    instead of gold's. Falls back to MGC_POINT_VALUE for an unknown symbol.
    DISPLAY / JOURNAL only — never feeds the gate, sizing, or the broker order.
    """
    direction = trade["direction"]
    entry     = trade["entry_price"]
    contracts = trade["contracts"]
    pts = (entry - current_price) if direction == "Short" else (current_price - entry)
    try:
        pv = point_value_for(trade.get("symbol") or trade.get("profile") or DEFAULT_INSTRUMENT)
    except Exception:
        pv = MGC_POINT_VALUE
    dollars = pts * pv * contracts
    return dollars, pts


def compute_distances(trade, current_price):
    """Returns (to_t1, to_t2, to_stop) as positive point distances remaining."""
    direction = trade["direction"]
    if direction == "Short":
        to_t1   = current_price - trade["target1"]
        to_t2   = current_price - trade["target2"]
        to_stop = trade["stop_loss"] - current_price
    else:
        to_t1   = trade["target1"] - current_price
        to_t2   = trade["target2"] - current_price
        to_stop = current_price - trade["stop_loss"]
    return to_t1, to_t2, to_stop


def check_trade_events(trade, current_price):
    """Returns list of new events: 'T1_HIT', 'T2_HIT', 'STOP_HIT'. Fires each once."""
    direction = trade["direction"]
    if direction == "Short":
        t1_hit   = current_price <= trade["target1"]
        t2_hit   = current_price <= trade["target2"]
        stop_hit = current_price >= trade["stop_loss"]
    else:
        t1_hit   = current_price >= trade["target1"]
        t2_hit   = current_price >= trade["target2"]
        stop_hit = current_price <= trade["stop_loss"]

    events = []
    if stop_hit:
        events.append("STOP_HIT")
    else:
        # At a fixed 1:1 R:R, target2 mirrors target1 (single exit). Only emit a
        # distinct T2 event when the plan carries a genuinely deeper second target,
        # so a 1:1 close books one WIN (T1) instead of double-firing T1 + T2.
        distinct_t2 = trade.get("target2") != trade.get("target1")
        if t2_hit and distinct_t2 and not trade.get("t2_hit"):
            events.append("T2_HIT")
        if t1_hit and not trade.get("t1_hit"):
            events.append("T1_HIT")
    return events


def send_trade_event_message(event_type, trade, current_price):
    """Send a standalone Discord plain-text alert for a trade event."""
    _url = _discord_url(trade.get("profile", ""))
    if not _url:
        return
    dollar_pnl, pts_pnl = compute_pnl(trade, current_price)
    pnl_str = f"+${dollar_pnl:,.0f}" if dollar_pnl >= 0 else f"-${abs(dollar_pnl):,.0f}"
    msgs = {
        "T1_HIT":   (f"✅ **T1 HIT — WIN**\n"
                     f"Trade Closed\n"
                     f"{pnl_str}"),
        "T2_HIT":   (f"🎯🎯 **T2 HIT**\n"
                     f"Trade Closed\n"
                     f"{pnl_str}"),
        "STOP_HIT": (f"❌ **STOP HIT**\n"
                     f"Trade Closed\n"
                     f"{pnl_str}"),
    }
    content = msgs.get(event_type, f"Trade event: {event_type}")
    try:
        requests.post(_url, json={"content": content}, timeout=5)
        logger.info("Trade event sent: %s", event_type)
    except requests.RequestException as exc:
        logger.error("Trade event Discord send failed: %s", exc)


def send_journal_discord_embed(entry):
    """Post a journal entry to the dedicated trading-journal Discord channel."""
    if not DISCORD_JOURNAL_WEBHOOK_URL:
        logger.warning("DISCORD_JOURNAL_WEBHOOK_URL not set — journal Discord post skipped")
        return
    # Muted: skip the Discord embed only. The journal RECORD is created separately
    # (create_journal_entry, post_discord=False), so the dashboard/DB keep it.
    if _alerts_muted(entry.get("symbol") or entry.get("instrument")):
        return

    embed = _build_trade_card_embed(entry, f"Journal Entry #{entry['id']}")

    try:
        resp = requests.post(
            DISCORD_JOURNAL_WEBHOOK_URL,
            json={"embeds": [embed]},
            timeout=10,
        )
        if resp.status_code not in (200, 204):
            logger.warning("Journal Discord post failed: %s %s", resp.status_code, resp.text[:200])
    except Exception as exc:
        logger.error("Journal Discord post error: %s", exc)


def _build_trade_card_embed(entry, footer_text):
    """Build the clean trade-card embed shared by the journal channel and the
    live alert channel. `entry` is the dict produced by _build_card_entry()."""
    direction_emoji = "📈" if entry["direction"] == "Long" else "📉"
    # Strength label is driven by the Edge Score (Possible 75-79 / Strong 80-84 / A+ >= 85),
    # falling back to the strict gate label for legacy entries without one.
    strength        = entry.get("trade_strength") or entry.get("strict_label", "Possible Trade")
    strength_disp   = _strength_display(strength)
    if strength == "A+ Setup":
        color = 0xFF4500
    elif strength == "Strong Trade":
        color = 0x2ECC71
    else:
        color = 0xF1C40F

    def _val(v):
        return str(v) if v not in (None, "") else "—"

    def _lvl(v):
        try:
            return f"{float(v):.2f}"
        except (TypeError, ValueError):
            return "—"

    def _typed(t, lvl):
        lvl_str = _lvl(lvl)
        if t and lvl_str != "—":
            return f"{t} @ {lvl_str}"
        return _val(t) if t else lvl_str

    score = entry.get("strict_score")
    conf_score = f"{score}/{EDGE_SCORE_MAX}" if score not in (None, "") else _val(entry.get("confidence"))
    why_text = entry.get("why_qualifies") or entry.get("why") or "—"
    if len(why_text) > 1000:
        why_text = why_text[:1000] + "…"

    notes_text = entry.get("setup_notes") or "—"
    if len(notes_text) > 1000:
        notes_text = notes_text[:1000] + "…"

    # Session focus + next-step lines for the card (Feature: Session Focus).
    if entry.get("session_preferred"):
        session_line = (f"✅ Preferred Trading Window: YES "
                        f"({entry.get('session_window', '—')})\n"
                        f"Session Bonus: +{entry.get('session_bonus', SESSION_BONUS_POINTS)}")
    else:
        session_line = "❌ Preferred Trading Window: NO\nSession Bonus: 0"
    next_step = entry.get("next_step") or entry.get("stage_next_step") or "—"

    vol      = entry.get("volatility") or {}
    vol_disp = vol.get("display") if vol.get("status") == "ok" else "—"

    # Display-only Edge Score / Grade / Reasons / Risk block replaces the free-text
    # AI Analysis field on READY cards; fall back to notes when no breakdown exists.
    eb = entry.get("edge_breakdown")
    if eb and (eb.get("reasons") or eb.get("risks") or eb.get("score")):
        analysis_field = _render_edge_block_field(eb)
    else:
        analysis_field = {"name": "🤖 AI Analysis", "value": notes_text, "inline": False}

    tier = entry.get("conviction_tier")
    tier_disp = f"  ·  Tier: **{tier}**" if tier else ""

    # ── Decision-support header (all real-derived; never fabricated) ──────────
    ds = entry.get("decision_support") or _decision_support(entry)
    ds_field = {
        "name": "🧭 Decision Support",
        "value": (
            f"⭐ **Quality:** {ds['quality']}\n"
            f"🎯 **Probability:** {ds['probability']}%\n"
            f"⚠️ **Risk:** {ds['risk']}\n"
            f"💰 **Reward:** {ds['reward']}\n"
            f"🪟 **Trade Window:** {ds['trade_window']}\n"
            f"✅ **Recommendation:** {ds['recommendation']}"
        ),
        "inline": False,
    }
    # ── Per-direction gate diagnostics (the SAME numbers that drove the gate) ──
    diag_field = {
        "name": "🔬 Diagnostics",
        "value": (
            f"Long {_val(entry.get('long_score'))} · Short {_val(entry.get('short_score'))} · "
            f"Gap {_val(entry.get('conflict_gap'))} · Dominant {_val(entry.get('dominant_direction'))}\n"
            f"Edge {_val(entry.get('edge_score'))} · ATR {_val(entry.get('current_atr'))} · "
            f"Vol× {_val(entry.get('volatility_multiplier'))}"
        ),
        "inline": False,
    }
    embed = {
        "author":      {"name": f"{BOT_NAME} · {strength_disp} Detected"},
        "title":       f"📓 {entry['symbol']} {direction_emoji} {entry['direction']}",
        "description": f"**{strength_disp}**  ·  Verdict: **{entry['verdict']}**{tier_disp}",
        "color":       color,
        "timestamp":   entry["datetime"],
        "fields": [
            ds_field,
            diag_field,
            {"name": "📊 Instrument",          "value": _val(entry.get("symbol")),    "inline": True},
            {"name": "🕐 Time",                "value": fmt_et(entry["datetime"], "%Y-%m-%d %H:%M:%S ET"), "inline": True},
            {"name": "🧭 Direction",           "value": f"{direction_emoji} {entry['direction']}", "inline": True},
            {"name": "🏗️ BOS Type",            "value": _typed(entry.get("bos_type"), entry.get("bos_level")), "inline": True},
            {"name": "🔀 CHOCH Type",          "value": _typed(entry.get("choch_type"), entry.get("choch_level")), "inline": True},
            {"name": "📐 Entry",               "value": _val(entry.get("entry_zone")), "inline": True},
            {"name": "🛑 Stop Loss",           "value": _val(entry.get("stop_loss")),  "inline": True},
            {"name": "🎯 Take Profit",         "value": _val(entry.get("target1")),    "inline": True},
            {"name": "📏 Risk Distance",       "value": (f"{entry.get('risk_points')} pts" if entry.get('risk_points') is not None else "—"), "inline": True},
            {"name": "💯 Confidence Score",    "value": conf_score,                   "inline": True},
            {"name": "📈 VWAP",                "value": _val(entry.get("vwap_position")), "inline": True},
            {"name": "🧱 Zone",                "value": _val(entry.get("supply_demand_zone")), "inline": True},
            {"name": "📉 Volatility",          "value": _val(vol_disp),              "inline": True},
            {"name": "🗓️ Session",            "value": session_line,                "inline": False},
            analysis_field,
            {"name": "📝 Setup Notes",         "value": notes_text,                  "inline": False},
            {"name": "💬 Why the Trade Qualifies", "value": why_text,                 "inline": False},
            {"name": "➡️ Next Step",           "value": next_step,                   "inline": False},
        ],
        "footer": {"text": footer_text},
    }

    # ── Additive: 📋 Trade Management block (Feature 1). Built defensively so a
    # missing plan simply omits the field and never breaks the existing card. ──
    try:
        mgmt_lines = []
        if entry.get("target3") not in (None, ""):
            mgmt_lines.append(f"🎯 TP3: {entry['target3']}")
        if entry.get("be_level") not in (None, ""):
            mgmt_lines.append(f"🟰 Move stop to BE: {entry['be_level']}")
        if entry.get("partial_level") not in (None, ""):
            mgmt_lines.append(f"💰 Partial: {entry['partial_level']}")
        if entry.get("runner_target") not in (None, ""):
            mgmt_lines.append(f"🏃 Runner: {entry['runner_target']}")
        rdc = entry.get("risk_dollars_per_contract")
        if rdc is not None:
            # Fixed 1:1 R:R → expected profit per contract == dollar risk per contract.
            mgmt_lines.append(f"⚖️ R:R 1:1 · Dollar Risk ${rdc}/ct · Expected Profit ${rdc}/ct")
        if entry.get("atr_pts") is not None:
            mgmt_lines.append(
                f"📏 ATR Stop: {entry.get('atr_pts')} pts × {entry.get('atr_multiplier')} "
                f"→ {entry.get('stop_distance_ticks')} ticks "
                f"(${entry.get('risk_dollars_per_contract')}/contract)")
        if entry.get("max_invalidation"):
            mgmt_lines.append(f"🚫 Invalidation: {entry['max_invalidation']}")
        if mgmt_lines:
            embed["fields"].append({"name": "📋 Trade Management",
                                    "value": "\n".join(mgmt_lines)[:1024],
                                    "inline": False})
    except Exception as exc:
        logger.error("Trade-management card block error: %s", exc)

    # ── Additive: 🎓 Professional Review field (display-only; pre-READY pro grade).
    # Mirrors the dashboard's ACTIVE model verdict on the live card. Built
    # defensively so a missing/neutral block simply omits the field. ──
    try:
        pr = entry.get("pro_review") or {}
        if pr.get("engine_enabled"):
            act = pr.get("active") or {}
            grade = act.get("grade")
            if grade and grade != "—":
                hard = act.get("hard_fails") or []
                pr_lines = [
                    f"🧠 Model: **{pr.get('selected_model', '—')}**  ·  "
                    f"Grade: **{grade}**  ·  Eff: **{act.get('entry_efficiency', '—')}/100**",
                    f"🌐 Market: {act.get('market_type', '—')}  ·  "
                    f"Chase Risk: {act.get('chase_risk', '—')}  ·  "
                    f"Decision: {act.get('professional_decision', '—')}",
                ]
                if hard:
                    pr_lines.append("⛔ Hard fails: " + "; ".join(str(h) for h in hard[:3]))
                gate_note = "VETO ARMED" if pr.get("gate_enabled") else "display-only"
                pr_lines.append(f"_Pro Review · {gate_note}_")
                embed["fields"].append({"name": "🎓 Professional Review",
                                        "value": "\n".join(pr_lines)[:1024],
                                        "inline": False})
    except Exception as exc:
        logger.error("Pro-review card block error: %s", exc)

    # ── Additive: 🧠 Trade Debate field (display-only; Bull vs Bear vs Judge).
    # Summarizes the pre-READY debate on the live card BEFORE issuing READY. Built
    # defensively so a missing / neutral / disabled block simply omits the field. ──
    try:
        td = entry.get("trade_debate") or {}
        if td.get("engine_enabled"):
            jd   = td.get("judge") or {}
            bull = td.get("bull") or {}
            bear = td.get("bear") or {}
            td_lines = [
                "🟢 Bull **%s** vs 🔴 Bear **%s**  ·  Winner: **%s** (gap %s)"
                % (bull.get("confidence", "—"), bear.get("confidence", "—"),
                   jd.get("winning_side", "—"), jd.get("confidence_gap", "—")),
                "⚖️ Judge: **%s**  ·  %s"
                % (jd.get("final_verdict", "—"), jd.get("reason_winner_won", "")),
            ]
            gate_note = "VETO ARMED" if td.get("gate_enabled") else "display-only"
            td_lines.append("_Trade Debate · %s_" % gate_note)
            embed["fields"].append({"name": "🧠 Trade Debate",
                                    "value": "\n".join(td_lines)[:1024],
                                    "inline": False})
    except Exception as exc:
        logger.error("Trade-debate card block error: %s", exc)

    # Attach the chart screenshot when a validated public URL is present.
    shot = entry.get("screenshot_url")
    if shot:
        embed["image"] = {"url": shot}

    return embed


def send_live_ready_card(entry, ticker="", notify=False):
    """Post the clean trade-card to the LIVE alert channel when a setup is READY.
    Routed per-instrument via _discord_url() (MNQ → MNQ channel, else default).

    notify=True prepends DISCORD_ALERT_MENTION (e.g. @everyone) so the message
    pings phones set to "Only @mentions". Used ONLY for the instant first post of
    a fresh setup; the 5-min re-post loop calls with notify=False so a standing
    READY setup buzzes the phone once, not every interval.

    Returns True iff the main live-card Discord POST was actually DISPATCHED (the
    URL is set AND the instrument is not muted), so callers count only a real alert
    (alert_sent_at / alerts_sent). When the instrument is muted the two Discord
    POSTs are skipped but every TRACKING side-effect still runs — throttle stamps,
    _register_managed_trade and the LAST_READY snapshot — so a muted instrument is
    evaluated and tracked exactly like an un-muted one, just silently."""
    url = _discord_url(ticker or entry.get("symbol", ""))
    if not url:
        logger.warning("DISCORD_WEBHOOK_URL not set — live ready card skipped")
        return False
    # Checked at SEND time (most up-to-date) — suppresses ONLY the two Discord
    # POSTs below, never the tracking that follows.
    muted = _alerts_muted(ticker or entry.get("symbol", ""))
    footer = f"Live Signal · {entry.get('symbol') or ticker or '—'}"
    # Record the send time per-instrument so the periodic loop throttles against it
    # (prevents an instant card and a periodic card landing seconds apart).
    LAST_LIVE_CARD_AT[instrument_of(ticker or entry.get("symbol", ""))] = datetime.now(timezone.utc)
    # Additive: record the READY send time per-instrument for the Diagnostics
    # readyAlertTime / waitedForCandleClose fields (display-only; never gates).
    LAST_READY_SENT_AT[instrument_of(ticker or entry.get("symbol", ""))] = datetime.now(timezone.utc)
    # Build + post inside the guard so a render failure (e.g. an unforeseen new
    # card field) can never raise into the caller — the alert path stays fail-open.
    embed = None
    dispatched = False
    if not muted:
        try:
            embed = _build_trade_card_embed(entry, footer)
            payload = {"embeds": [embed]}
            if notify and DISCORD_ALERT_MENTION:
                # The single phone-pinging message: prepend the mention and allow it
                # so a "Only @mentions" device buzzes exactly on a fresh READY setup.
                payload["content"] = DISCORD_ALERT_MENTION
                payload["allowed_mentions"] = {"parse": ["everyone", "users", "roles"]}
            resp = requests.post(url, json=payload, timeout=10)
            dispatched = True
            if resp.status_code not in (200, 204):
                logger.warning("Live ready card post failed: %s %s", resp.status_code, resp.text[:200])
        except Exception as exc:
            logger.error("Live ready card build/post error: %s", exc)
        # Optionally mirror 🔥 A+ setups to a dedicated channel (additive — the card
        # already posted to the normal channel above, so this never blocks/relocates
        # Possible/Strong/A+ alerts). Skipped entirely when no A+ channel is set.
        try:
            if (embed is not None and entry.get("trade_strength") == "A+ Setup"
                    and DISCORD_APLUS_WEBHOOK_URL and DISCORD_APLUS_WEBHOOK_URL != url):
                requests.post(DISCORD_APLUS_WEBHOOK_URL, json={"embeds": [embed]}, timeout=10)
        except Exception as exc:
            logger.error("A+ channel mirror error: %s", exc)
    else:
        logger.info("Live ready card suppressed (alerts muted): %s",
                    instrument_of(ticker or entry.get("symbol", "")))
    # ── Additive: register the setup with the trade-management watcher and store
    # the latest READY snapshot (for /why). Both fail-open so a hiccup here can
    # never block the alert that already posted above. These run REGARDLESS of mute
    # so a muted instrument stays fully tracked (no data gap). ──
    try:
        _register_managed_trade(entry, ticker)
    except Exception as exc:
        logger.error("Managed-trade register error: %s", exc)
    try:
        LAST_READY_BY_TICKER[instrument_of(ticker or entry.get("symbol", ""))] = entry
    except Exception as exc:
        logger.error("LAST_READY snapshot error: %s", exc)
    return dispatched


# ── Tiered WATCH/ARMED early alerts (SCALP) ───────────────────────────────────
# Per-instrument throttle state: the last tier level we dispatched/observed and
# when the last WATCH/ARMED post went out. A level fires once on TRANSITION (the
# level changed) and then at most once per WATCH_ARMED_COOLDOWN_SEC while it
# persists, so a standing WATCH/ARMED never spams on every webhook.
LAST_TIER_LEVEL = {}   # instrument -> last alert_level seen ("WATCH"/"ARMED"/"READY")
LAST_TIER_AT    = {}   # instrument -> datetime (UTC) of last WATCH/ARMED post attempt

# SETUP BUILDING throttle state (SCALP only): the informational "setup building"
# heads-up posts once when an instrument ENTERS the building band and then at most
# once per SETUP_BUILDING_COOLDOWN_SEC while it persists, so it never spams.
LAST_BUILDING_AT = {}  # instrument -> datetime (UTC) of last SETUP BUILDING post attempt

# ── EARLY pre-READY alert runtime state (additive, display-only) ──────────────
LAST_EARLY_ANCHOR  = {}  # (instrument, direction) -> structure-anchor ISO already EARLY-alerted (per-setup dedupe)
LAST_EARLY_AT      = {}  # (instrument, direction) -> datetime (UTC) of last EARLY post (cooldown guard)
EARLY_EVENT_TIMES  = {}  # instrument -> latest event/alert timestamps (ISO) for the Diagnostics page
LAST_READY_SENT_AT = {}  # instrument -> datetime (UTC) the READY card last fired (Diagnostics readyAlertTime)


def _tiered_alert_url(inst):
    """Resolve the Discord channel for WATCH/ARMED early alerts. DEFAULT routes to
    the journal channel so the main signal channel stays READY-only; switchable via
    TIERED_ALERT_CHANNEL = journal (default) | main | none (none disables posting).
    Falls back to the instrument's main channel if the journal URL is unset."""
    channel = os.environ.get("TIERED_ALERT_CHANNEL", "journal").strip().lower()
    if channel == "none":
        return None
    if channel == "main":
        return _discord_url(inst)
    return DISCORD_JOURNAL_WEBHOOK_URL or _discord_url(inst)


def _build_tiered_embed(a, inst, level):
    """Compact WATCH/ARMED early-alert embed. DISPLAY-ONLY — it announces that price
    has reached a fresh trade-side zone (WATCH) and is gathering confirmations
    (ARMED) BEFORE a full READY, so the strict trade card stays the single READY
    signal. Everything shown is read from the analysis `a` (never fabricated)."""
    cand   = a.get("gate_candidate") or "—"
    gd     = a.get("gate_debug") or {}
    price  = a.get("current_price")
    zone   = a.get("nearest_demand") if cand == "Long" else a.get("nearest_supply")
    confs  = int(gd.get("confirmations_passed") or 0)
    needed = int(gd.get("confirmations_needed") or 0)
    edge   = a.get("edge_score", 0)
    grade  = a.get("edge_grade", "")
    side_word = "demand" if cand == "Long" else "supply"
    title_emoji, color = {
        "WATCH":           ("👀 WATCH", 0xF1C40F),
        "ARMED":           ("🎯 ARMED", 0xE67E22),
        "WATCH FOR ENTRY": ("⚡ WATCH FOR ENTRY", 0x3498DB),
    }.get(level, ("👀 WATCH", 0xF1C40F))
    # What still blocks READY (the gate's own failed conditions), conflict aside.
    missing = [m for m in (a.get("strict_missing") or []) if m != "conflicting_structure"]
    fields = [
        {"name": "Setup",         "value": f"{cand} · at {side_word} zone", "inline": True},
        {"name": "Edge",          "value": f"{edge}/{EDGE_SCORE_MAX}{(' · ' + grade) if grade else ''}", "inline": True},
        {"name": "Confirmations", "value": f"{confs}/{needed}", "inline": True},
    ]
    if price is not None:
        fields.append({"name": "Price", "value": f"{price:,.2f}", "inline": True})
    if zone:
        fields.append({"name": f"{side_word.title()} zone", "value": f"{zone:,.2f}", "inline": True})
    if missing:
        fields.append({"name": "Still needs", "value": ", ".join(missing[:4]), "inline": False})
    # Per-direction gate diagnostics (real numbers; display-only) so the early
    # alert carries the same transparency as the READY card.
    _dv = lambda v: v if v not in (None, "") else "—"
    fields.append({
        "name": "Diagnostics",
        "value": (f"L {_dv(a.get('long_score'))} · S {_dv(a.get('short_score'))} · "
                  f"Gap {_dv(a.get('conflict_gap'))} · Edge {edge} · "
                  f"ATR {_dv(a.get('current_atr'))} · Vol× {_dv(a.get('volatility_multiplier'))}"),
        "inline": False,
    })
    tail = {
        "WATCH FOR ENTRY": "confirmations in — waiting on one decisive trigger (BOS/CHOCH/rejection candle/VWAP) to go READY.",
        "ARMED":           "gathering confirmations.",
    }.get(level, "watching for confirmation.")
    return {
        "title":       f"{title_emoji} · {inst}",
        "description": f"Price is at a fresh {side_word} zone — {tail}",
        "color":       color,
        "fields":      fields,
        "footer":      {"text": f"Early Signal · {inst}"},
        "timestamp":   datetime.now(timezone.utc).isoformat(),
    }


def _post_tiered_embed(url, embed, inst, level):
    """Slow-task worker body: POST a prebuilt WATCH/ARMED embed to Discord. Runs OFF
    the webhook worker (via _enqueue_slow) so a slow or timing-out Discord call can
    never delay the decision, the READY card, the journal enqueue, or the next
    webhook evaluation. Best-effort — logs and swallows any failure."""
    # Muted-instrument choke point (covers WATCH/ARMED + SETUP BUILDING enqueues).
    if _alerts_muted(inst):
        return
    try:
        resp = requests.post(url, json={"embeds": [embed]}, timeout=10)
        if resp.status_code not in (200, 204):
            logger.warning("Tiered %s alert post failed (%s): %s %s",
                           level, inst, resp.status_code, resp.text[:200])
    except Exception as exc:
        logger.error("Tiered %s alert post error (%s): %s", level, inst, exc)


def _maybe_send_tiered_alert(a, record):
    """Fire a WATCH/ARMED early alert (SCALP only, ENABLE_TIERED_ALERTS) for the
    analysis `a`. Throttled per instrument: a level posts on transition (changed
    from the last level) OR after WATCH_ARMED_COOLDOWN_SEC while it persists.
    READY is NOT posted here (the live card owns it) but is recorded so a later
    retreat to ARMED/WATCH counts as a fresh transition.

    The throttle state and embed are computed synchronously, but the Discord POST
    is OFFLOADED to the slow-task worker, so this never blocks the webhook worker.
    Returns True iff a WATCH/ARMED embed was enqueued for posting. Fail-open: never
    raises into the webhook tail."""
    if not cfg("ENABLE_TIERED_ALERTS"):
        return False
    level = a.get("alert_level")
    inst  = instrument_of(record.get("ticker") or record.get("instrument")
                          or a.get("active_ticker") or "")
    if not inst:
        return False
    # Muted: skip the tiered WATCH/ARMED early alert entirely — no enqueue and not
    # counted as sent (tiered_sent stays False). The instrument was still evaluated
    # above; only the Discord teaser is suppressed.
    if _alerts_muted(inst):
        return False

    # READY: record (so a later ARMED/WATCH is a transition) but let the live card post it.
    if level == "READY":
        LAST_TIER_LEVEL[inst] = "READY"
        return False
    # No tier: forget the standing level so the next early alert fires immediately.
    if level not in ("WATCH", "ARMED", "WATCH FOR ENTRY"):
        LAST_TIER_LEVEL.pop(inst, None)
        LAST_TIER_AT.pop(inst, None)
        return False

    now           = datetime.now(timezone.utc)
    last_at       = LAST_TIER_AT.get(inst)
    cooldown      = int(cfg("WATCH_ARMED_COOLDOWN_SEC"))
    is_transition = (level != LAST_TIER_LEVEL.get(inst))
    cooled_down   = (last_at is None or (now - last_at).total_seconds() >= cooldown)
    if not (is_transition or cooled_down):
        return False

    # Record the attempt up-front (level + time) so a transient post failure can't
    # turn into a per-webhook retry storm; the next attempt waits for the cooldown.
    LAST_TIER_LEVEL[inst] = level
    LAST_TIER_AT[inst]    = now
    url = _tiered_alert_url(inst)
    if not url:
        return False
    # Build the embed synchronously (fast, in-memory) but hand the Discord POST to
    # the slow-task worker so a slow/timing-out call can't block this worker.
    try:
        embed = _build_tiered_embed(a, inst, level)
    except Exception as exc:
        logger.error("Tiered alert build error (%s/%s): %s", inst, level, exc)
        return False
    _enqueue_slow(lambda u=url, e=embed, i=inst, lv=level: _post_tiered_embed(u, e, i, lv))
    return True


def _build_setup_building_embed(a, inst):
    """Compact informational SETUP BUILDING embed (SCALP only). NON-actionable — it
    announces that a valid fresh zone + confirming structure are present and the Edge
    is climbing toward the READY floor, BEFORE a tradeable setup exists. Everything
    shown is read from the analysis `a` (never fabricated); there is NO trade plan."""
    cand   = a.get("gate_candidate") or "—"
    gd     = a.get("gate_debug") or {}
    price  = a.get("current_price")
    zone   = a.get("nearest_demand") if cand == "Long" else a.get("nearest_supply")
    edge   = a.get("edge_score", 0)
    need   = int(gd.get("ready_threshold") or cfg("EDGE_READY_THRESHOLD") or 0)
    side_word = "demand" if cand == "Long" else "supply"
    missing = [m for m in (a.get("strict_missing") or []) if m != "conflicting_structure"]
    fields = [
        {"name": "Setup",     "value": f"{cand} · at {side_word} zone", "inline": True},
        {"name": "Edge",      "value": f"{edge}/{EDGE_SCORE_MAX} (need ≥ {need})", "inline": True},
    ]
    if price is not None:
        fields.append({"name": "Price", "value": f"{price:,.2f}", "inline": True})
    if zone:
        fields.append({"name": f"{side_word.title()} zone", "value": f"{zone:,.2f}", "inline": True})
    if missing:
        fields.append({"name": "Still needs", "value": ", ".join(missing[:4]), "inline": False})
    return {
        "title":       f"🏗️ SETUP BUILDING · {inst}",
        "description": (f"A {cand} setup is forming at a fresh {side_word} zone — Edge is "
                       f"climbing toward READY. Informational only — **not a trade yet.**"),
        "color":       0x95A5A6,
        "fields":      fields,
        "footer":      {"text": f"Setup Building · {inst} · non-actionable"},
        "timestamp":   datetime.now(timezone.utc).isoformat(),
    }


def _maybe_send_setup_building_alert(a, record):
    """Fire the informational SETUP BUILDING heads-up (SCALP only) for analysis `a`.
    Throttled per instrument: posts once when the instrument ENTERS the building band
    and then at most once per SETUP_BUILDING_INTERVAL while it persists; the standing
    state is cleared the moment the verdict leaves SETUP BUILDING, so the next build
    fires immediately.

    NON-actionable: this never builds a trade plan, never touches the verdict, the
    journal, or managed trades — purely a display heads-up. The Discord POST is
    OFFLOADED to the slow-task worker so it never blocks the webhook worker. Returns
    True iff an embed was enqueued. Fail-open: never raises into the webhook tail."""
    inst = instrument_of(record.get("ticker") or record.get("instrument")
                         or a.get("active_ticker") or "")
    if not inst:
        return False
    # Only the SCALP-only informational verdict fires here. Any other verdict clears
    # the standing throttle so a later build is treated as a fresh entry.
    if a.get("verdict") != "SETUP BUILDING":
        LAST_BUILDING_AT.pop(inst, None)
        return False
    now      = datetime.now(timezone.utc)
    last_at  = LAST_BUILDING_AT.get(inst)
    cooled   = (last_at is None or (now - last_at).total_seconds() >= SETUP_BUILDING_INTERVAL)
    if not cooled:
        return False
    # Record the attempt up-front so a transient post failure can't turn into a
    # per-webhook retry storm; the next attempt waits for the interval.
    LAST_BUILDING_AT[inst] = now
    url = _tiered_alert_url(inst)
    if not url:
        return False
    try:
        embed = _build_setup_building_embed(a, inst)
    except Exception as exc:
        logger.error("Setup-building alert build error (%s): %s", inst, exc)
        return False
    _enqueue_slow(lambda u=url, e=embed, i=inst: _post_tiered_embed(u, e, i, "SETUP BUILDING"))
    return True


# ── EARLY intrabar pre-READY alerts (additive, DISPLAY-ONLY) ──────────────────
def _early_latest_ts(alert_history, alert_type, inst, ticker_scoped, cutoff):
    """Most recent UTC timestamp of `alert_type` for `inst` at/after `cutoff`, using
    the SAME instrument-scoping as evaluate_strict_setup._latest_ts (un-prefixed
    CHOCH/BOS/HH.. are scoped by the instrument resolved at ingestion; sweep types
    embed the instrument in their name). None if absent. Read-only."""
    latest = None
    for a in alert_history:
        if a.get("alert_type") != alert_type:
            continue
        if not ticker_scoped:
            a_inst = (a.get("instrument")
                      or _instrument_from_text(a.get("ticker"))
                      or _instrument_from_text(a.get("alert_type")))
            if a_inst != inst:
                continue
        try:
            ts = datetime.fromisoformat(a["timestamp"])
        except (KeyError, ValueError):
            continue
        if ts < cutoff:
            continue
        if latest is None or ts > latest:
            latest = ts
    return latest


def _early_event_times(inst, alert_history):
    """Scan ALERT_HISTORY (within EARLY_WINDOW_MIN) for the EARLY building blocks of
    each direction: a liquidity sweep + a structure shift. 'displacement' maps to
    impulsive structure (BOS / HH-HL-LH-LL) and 'choch' to CHOCH; 'structure' is
    the latest of the two. event_start is the first of (sweep, structure). All
    times are server-ingestion timestamps (no bar time is in the payload). Pure /
    read-only — never feeds the gate."""
    cutoff = now_utc() - timedelta(minutes=EARLY_WINDOW_MIN)
    def lt(t, scoped=False):
        return _early_latest_ts(alert_history, t, inst, scoped, cutoff)
    def _max(*xs):
        xs = [x for x in xs if x]
        return max(xs) if xs else None
    def _min(*xs):
        xs = [x for x in xs if x]
        return min(xs) if xs else None
    bear_sweep   = lt(f"{inst} BEARISH SWEEP", True)
    choch_sup    = lt("CHOCH SUPPLY")
    short_disp   = _max(lt("BOS SUPPLY"), lt("LH"), lt("LL"))
    short_struct = _max(choch_sup, short_disp)
    bull_sweep   = lt(f"{inst} BULLISH SWEEP", True)
    choch_dem    = lt("CHOCH DEMAND")
    long_disp    = _max(lt("BOS DEMAND"), lt("HH"), lt("HL"))
    long_struct  = _max(choch_dem, long_disp)
    return {
        "Short": {"sweep": bear_sweep, "choch": choch_sup, "displacement": short_disp,
                  "structure": short_struct, "event_start": _min(bear_sweep, short_struct)},
        "Long":  {"sweep": bull_sweep, "choch": choch_dem, "displacement": long_disp,
                  "structure": long_struct, "event_start": _min(bull_sweep, long_struct)},
    }


def _early_alert_url(inst):
    """Resolve the Discord channel for EARLY alerts. EARLY_ALERT_CHANNEL =
    main (default, the live signal channel) | journal | none (disables)."""
    if EARLY_ALERT_CHANNEL == "none":
        return None
    if EARLY_ALERT_CHANNEL == "journal":
        return DISCORD_JOURNAL_WEBHOOK_URL or _discord_url(inst)
    return _discord_url(inst)


def _build_early_embed(a, inst, direction, t):
    """Compact ⚡ EARLY LONG/SHORT embed. DISPLAY-ONLY — announces an early,
    UNCONFIRMED entry (sweep + structure shift) that fired before the candle close,
    with the confirmed READY card still to follow. Everything is read from the
    analysis `a` / event times `t`, never fabricated."""
    price     = a.get("current_price")
    side_word = "supply" if direction == "Short" else "demand"
    zone      = a.get("nearest_supply") if direction == "Short" else a.get("nearest_demand")
    bias_word = "bearish" if direction == "Short" else "bullish"
    title, color = (("⚡ EARLY SHORT", 0xE74C3C) if direction == "Short"
                    else ("⚡ EARLY LONG", 0x2ECC71))
    def et(ts):
        return fmt_et(ts, "%H:%M:%S ET") if ts else "—"
    fields = [
        {"name": "Trigger", "value": f"Liquidity sweep + {bias_word} structure (CHOCH/displacement)", "inline": False},
    ]
    if price is not None:
        fields.append({"name": "Price", "value": f"{price:,.2f}", "inline": True})
    if zone:
        fields.append({"name": f"{side_word.title()} zone", "value": f"{zone:,.2f}", "inline": True})
    fields.append({"name": "Sweep",     "value": et(t.get("sweep")),     "inline": True})
    fields.append({"name": "Structure", "value": et(t.get("structure")), "inline": True})
    # Per-direction gate diagnostics (real numbers; display-only).
    _dv = lambda v: v if v not in (None, "") else "—"
    fields.append({
        "name": "Diagnostics",
        "value": (f"L {_dv(a.get('long_score'))} · S {_dv(a.get('short_score'))} · "
                  f"Gap {_dv(a.get('conflict_gap'))} · Edge {_dv(a.get('edge_score'))} · "
                  f"ATR {_dv(a.get('current_atr'))} · Vol× {_dv(a.get('volatility_multiplier'))}"),
        "inline": False,
    })
    return {
        "title":       f"{title} · {inst}",
        "description": "Early, *unconfirmed* entry — fired before the candle close. "
                       "The confirmed READY card follows if it holds.",
        "color":       color,
        "fields":      fields,
        "footer":      {"text": f"Early Signal · {inst} · not a confirmed READY"},
        "timestamp":   datetime.now(timezone.utc).isoformat(),
    }


def _post_early_embed(url, embed, inst, direction, ping):
    """Slow-task worker body: POST a prebuilt EARLY embed to Discord, OFF the
    webhook worker (via _enqueue_slow) so a slow/timing-out call can never delay the
    decision, the READY card, or the next webhook. Best-effort — swallows failures."""
    # Muted: suppress the EARLY teaser send (dedupe/diagnostics state already set
    # at enqueue time is preserved, so tracking is unaffected).
    if _alerts_muted(inst):
        return
    try:
        payload = {"embeds": [embed]}
        if ping and DISCORD_ALERT_MENTION:
            payload["content"] = DISCORD_ALERT_MENTION
            payload["allowed_mentions"] = {"parse": ["everyone", "users", "roles"]}
        resp = requests.post(url, json=payload, timeout=10)
        if resp.status_code not in (200, 204):
            logger.warning("EARLY %s alert post failed (%s): %s %s",
                           direction, inst, resp.status_code, resp.text[:200])
    except Exception as exc:
        logger.error("EARLY %s alert post error (%s): %s", direction, inst, exc)


def _store_early_times(inst, direction, times):
    """Persist the latest EARLY event timestamps (ISO) per instrument for the
    Diagnostics page. Preserves earlyAlertTime (set only when EARLY actually fires)."""
    if not inst:
        return
    slot = EARLY_EVENT_TIMES.setdefault(inst, {})
    if direction is None:
        slot["direction"]        = None
        slot["eventStartTime"]   = None
        slot["sweepTime"]        = None
        slot["chochTime"]        = None
        slot["displacementTime"] = None
        return
    t = times[direction]
    def iso(x):
        return x.isoformat() if x else None
    slot["direction"]        = direction
    slot["eventStartTime"]   = iso(t.get("event_start"))
    slot["sweepTime"]        = iso(t.get("sweep"))
    slot["chochTime"]        = iso(t.get("choch"))
    slot["displacementTime"] = iso(t.get("displacement"))


def _maybe_dispatch_early_alert(a, record):
    """Fire an ⚡ EARLY LONG/SHORT the instant a sweep + structure shift appear
    together, BEFORE the strict candle-close confirmation. PURELY ADDITIVE and
    fail-open: never touches evaluate_strict_setup, the READY verdict/score, SWING
    parity, the journal, or managed trades. Fires ONCE per active setup (per-
    direction dedupe that resets when the setup goes inactive). Skipped when the
    verdict is already READY (the confirmed card owns it), the zone is broken, or a
    trade is active. Returns True iff an EARLY embed was enqueued. Refreshes
    EARLY_EVENT_TIMES (for the Diagnostics page) on every call."""
    if not EARLY_ALERTS_ENABLED:
        return False
    if (a or {}).get("market_open") is False:
        return False   # market closed — EARLY heads-up is paused with the gate
    inst = instrument_of(record.get("ticker") or record.get("instrument")
                         or a.get("active_ticker") or "")
    if not inst:
        return False
    times = _early_event_times(inst, ALERT_HISTORY)
    active = [d for d in ("Short", "Long")
              if times[d]["sweep"] and times[d]["structure"]]
    chosen = active[0] if len(active) == 1 else None  # ambiguous (both) → stand aside
    _store_early_times(inst, chosen, times)
    if not active:
        # Setup fully inactive → reset per-setup dedupe so the next clean setup
        # re-fires, and clear the stale early-alert stamp for the Diagnostics row.
        LAST_EARLY_ANCHOR.pop((inst, "Short"), None)
        LAST_EARLY_ANCHOR.pop((inst, "Long"), None)
        EARLY_EVENT_TIMES.get(inst, {}).pop("earlyAlertTime", None)
        return False
    if chosen is None:
        # Ambiguous (both sides active) → stand aside, but PRESERVE the dedupe
        # anchors: a side that already EARLY-fired must not be re-armed and re-fire
        # when the ambiguity later resolves back to that same side in-window.
        return False
    key = (inst, chosen)
    # An actionable verdict (full READY *or* EARLY READY) already owns the signal —
    # never post the intrabar ⚡EARLY teaser at/after it; mark dedupe so a late EARLY
    # can't fire after the verdict card for this setup.
    if is_actionable(a.get("verdict")):
        LAST_EARLY_ANCHOR[key] = "ready"
        return False
    # Honour the same hard invalidations the gate uses (display-side only). The
    # broken-zone skip is a ZONE HARD-GATE behaviour: it holds in SWING (cfg on) and
    # is bypassed in SCALP (zone demoted), so a broken zone no longer mutes the EARLY
    # teaser. An active trade still suppresses the teaser in EVERY mode.
    if (cfg("GATE_REQUIRE_ZONE") and a.get("zone_broken_active")) or active_trade_for(inst):
        return False
    if LAST_EARLY_ANCHOR.get(key):     # already EARLY-alerted this active setup
        return False
    now = datetime.now(timezone.utc)
    last_at = LAST_EARLY_AT.get(key)
    if last_at and (now - last_at).total_seconds() < EARLY_ALERT_COOLDOWN_SEC:
        return False
    url = _early_alert_url(inst)
    if not url:
        return False
    # Build the embed BEFORE committing any dedupe / diagnostics state, so a build
    # failure can't leave the setup stuck-deduped or falsely stamp earlyAlertTime.
    try:
        embed = _build_early_embed(a, inst, chosen, times[chosen])
    except Exception as exc:
        logger.error("EARLY alert build error (%s/%s): %s", inst, chosen, exc)
        return False
    anchor = times[chosen]["structure"]
    LAST_EARLY_ANCHOR[key] = anchor.isoformat() if anchor else now.isoformat()
    LAST_EARLY_AT[key]     = now
    EARLY_EVENT_TIMES.setdefault(inst, {})["earlyAlertTime"] = now.isoformat()
    _enqueue_slow(lambda u=url, e=embed, i=inst, d=chosen, p=EARLY_ALERT_PING:
                  _post_early_embed(u, e, i, d, p))
    logger.info("EARLY %s alert enqueued (%s) — sweep+structure before confirmation", chosen, inst)
    return True


def _trade_ready_loop():
    """Every TRADE_READY_INTERVAL seconds, re-evaluate each instrument and re-post
    the clean trade-card to the live alert channel while a setup stays READY.

    This is the recurring "update every 5 min" companion to the instant alert
    fired from the webhook. It posts only on READY verdicts and stays silent
    while a trade is already active (lifecycle alerts cover that case).
    """
    try:
        now = datetime.now(timezone.utc)
        for inst in enabled_instruments():
            # Per-instrument isolation: an open position on ONE asset must not
            # silence READY reposts for the others (only this asset's own live
            # position suppresses its repost — lifecycle alerts cover that case).
            if active_trade_for(inst):
                continue
            # Throttle: skip if a card (instant or periodic) was sent for this
            # instrument within the last TRADE_READY_INTERVAL seconds.
            last = LAST_LIVE_CARD_AT.get(inst)
            if last and (now - last).total_seconds() < trade_ready_interval():
                continue
            try:
                a = full_analysis(ticker_override=inst)
            except Exception as exc:
                logger.error("trade-ready loop analysis error (%s): %s", inst, exc)
                continue
            # Re-check this instrument's slot just before sending (it may have
            # changed while full_analysis ran).
            if not active_trade_for(inst) and is_actionable(a.get("verdict")):
                entry = _build_card_entry(a, ticker=f"{inst}1!")
                send_live_ready_card(entry, inst)
    except Exception as exc:  # never let the loop die
        logger.warning("trade-ready loop error: %s", exc)
    finally:
        threading.Timer(trade_ready_interval(), _trade_ready_loop).start()


# ── Cross-market index alignment (DISPLAY + ALERTS only) ─────────────────────
# Reads each enabled equity-index micro's AUTHORITATIVE per-tab bias (the same
# calculate_bias() value the dashboard shows when you switch tabs) and reports
# whether Nasdaq/S&P/Dow agree on direction. This is a pure read layered on top of
# full_analysis — it NEVER feeds the gate / scoring / sizing / dedupe / broker path.
_INDEX_DISPLAY_NAMES = {"MNQ": "Nasdaq", "MES": "S&P 500", "MYM": "Dow"}


def compute_index_alignment():
    """Cross-market directional agreement across the enabled equity-index micros
    (MNQ/MES/MYM). Built from each instrument's authoritative bias
    (calculate_bias → "Bullish"/"Bearish"/"Choppy" via full_analysis). Returns a
    snapshot dict; DISPLAY + NOTIFY only — never read by any trade decision."""
    enabled = set(enabled_instruments())
    insts = [i for i in INDEX_ALIGNMENT_INSTRUMENTS if i in enabled]
    members = []
    for inst in insts:
        try:
            a = full_analysis(ticker_override=inst)
        except Exception as exc:
            logger.warning("index-alignment analysis error (%s): %s", inst, exc)
            continue
        bias = a.get("bias")
        direction = ("Long" if bias == "Bullish"
                     else "Short" if bias == "Bearish"
                     else None)
        members.append({
            "instrument": inst,
            "name":       _INDEX_DISPLAY_NAMES.get(inst, inst),
            "bias":       bias,            # Bullish / Bearish / Choppy
            "direction":  direction,       # Long / Short / None (Choppy)
            "edge_score": a.get("edge_score"),
            "edge_grade": a.get("edge_grade"),
            "verdict":    a.get("verdict"),
        })
    longs  = [m for m in members if m["direction"] == "Long"]
    shorts = [m for m in members if m["direction"] == "Short"]
    total  = len(members)
    state, direction, agree = "n/a", None, 0
    if total >= 2:
        if longs and not shorts and len(longs) == total:
            state, direction, agree = "Aligned", "Long", len(longs)
        elif shorts and not longs and len(shorts) == total:
            state, direction, agree = "Aligned", "Short", len(shorts)
        elif len(longs) >= 2 and len(longs) > len(shorts):
            state, direction, agree = "Leaning", "Long", len(longs)
        elif len(shorts) >= 2 and len(shorts) > len(longs):
            state, direction, agree = "Leaning", "Short", len(shorts)
        else:
            state, direction, agree = "Mixed", None, max(len(longs), len(shorts))
    return {
        "state":     state,        # Aligned / Leaning / Mixed / n/a
        "direction": direction,    # Long / Short / None
        "agree":     agree,        # indexes agreeing in the dominant direction
        "total":     total,        # indexes evaluated
        "members":   members,      # per-index detail (display)
        "ts":        datetime.now(timezone.utc).isoformat(),
    }


def _cross_market_snapshot():
    """Thread-safe shallow copy of the latest cross-market alignment snapshot for
    /status (DISPLAY-ONLY). Empty dict until the first loop pass populates it."""
    with CROSS_MARKET_LOCK:
        return dict(CROSS_MARKET_STATE)


def _maybe_send_cross_market_alert(snap):
    """Fire the dedicated MES/MYM cross-market confirmation Discord alert when the
    equity indexes are newly Aligned. Transition-deduped (direction change) and
    cooldown-throttled, mute-respecting, called ONLY when DISCORD_LIVE_ENABLED.
    DISPLAY/NOTIFY only — never affects whether a trade is taken. Runs on the single
    cross-market loop thread, so CROSS_MARKET_LAST_ALERT needs no extra lock."""
    if snap.get("state") != "Aligned":
        return
    direction = snap.get("direction")
    if direction not in ("Long", "Short"):
        return
    now = datetime.now(timezone.utc)
    with CROSS_MARKET_LOCK:
        last_dir = CROSS_MARKET_LAST_ALERT.get("direction")
        last_ts  = CROSS_MARKET_LAST_ALERT.get("ts")
    # Only fire when the aligned direction CHANGED, or after the cooldown elapsed
    # for the same direction (a long-running alignment re-pings at most once per
    # cooldown, never every loop tick).
    if (direction == last_dir and last_ts
            and (now - last_ts).total_seconds() < CROSS_MARKET_ALERT_COOLDOWN):
        return
    # Targets: the non-Nasdaq index micros (MNQ already has its own READY-card flow).
    # Respect per-instrument mute (fail-safe toward alerting) and only enabled ones.
    enabled = set(enabled_instruments())
    targets = [i for i in ("MES", "MYM") if i in enabled and not _alerts_muted(i)]
    if not targets:
        return
    # Group by resolved channel so MES+MYM sharing the main channel post ONE
    # combined message (no double-post); dedicated channels later each get their own.
    by_url = {}
    for inst in targets:
        url = _asset_discord_url(inst)
        if url:
            by_url.setdefault(url, []).append(inst)
    if not by_url:
        return
    arrow = "📈" if direction == "Long" else "📉"
    word  = "BULLISH" if direction == "Long" else "BEARISH"
    lines = []
    for m in (snap.get("members") or []):
        dot = ("🟢" if m.get("direction") == "Long"
               else "🔴" if m.get("direction") == "Short" else "⚪")
        es  = m.get("edge_score")
        es_txt = f" · Edge {es}" if isinstance(es, (int, float)) else ""
        lines.append(f"{dot} **{m.get('name') or m.get('instrument')}** {m.get('bias') or '—'}{es_txt}")
    detail = "\n".join(lines)
    sent_any = False
    for url, insts in by_url.items():
        names = " & ".join(insts)
        content = (
            f"{arrow} **Cross-Market Confirmation — {word}**\n"
            f"All {snap.get('total')} equity indexes agree on direction.\n"
            f"{detail}\n"
            f"_Context for {names}. Display/notify only — does not place or change any trade._"
        )
        try:
            resp = requests.post(url, json={"content": content}, timeout=5)
            # Only a real 2xx counts as sent; a non-2xx must NOT arm the cooldown,
            # so a failed post is retried on the next loop pass instead of being
            # silently suppressed for CROSS_MARKET_ALERT_COOLDOWN seconds.
            if getattr(resp, "status_code", 0) < 300:
                sent_any = True
            else:
                logger.warning("cross-market alert non-2xx (%s) — not arming cooldown",
                               getattr(resp, "status_code", "?"))
        except Exception as exc:
            logger.warning("cross-market alert post failed: %s", exc)
    if sent_any:
        with CROSS_MARKET_LOCK:
            CROSS_MARKET_LAST_ALERT["direction"] = direction
            CROSS_MARKET_LAST_ALERT["ts"] = now
        logger.info("Cross-market alert sent: %s (%d indexes aligned)",
                    direction, snap.get("agree"))


def _cross_market_loop():
    """Refresh the cross-market index-alignment snapshot (DISPLAY) and, on the LIVE
    instance only, fire the dedicated MES/MYM cross-confirmation alert when the
    equity indexes newly agree. Mirrors _trade_ready_loop: a self-rescheduling
    daemon Timer. Runs on dev + prod (the dashboard needs the snapshot); the Discord
    SEND is gated to DISCORD_LIVE_ENABLED so dev can't post to the shared live
    channel. NEVER touches the gate / money path."""
    try:
        snap = compute_index_alignment()
        with CROSS_MARKET_LOCK:
            CROSS_MARKET_STATE.clear()
            CROSS_MARKET_STATE.update(snap)
        if DISCORD_LIVE_ENABLED:
            _maybe_send_cross_market_alert(snap)
    except Exception as exc:  # never let the loop die
        logger.warning("cross-market loop error: %s", exc)
    finally:
        threading.Timer(CROSS_MARKET_INTERVAL, _cross_market_loop).start()


def _post_analyst_report_update(inst, trade, report):
    """Post ONE Unified Analyst Report thesis update for an OPEN position to the
    JOURNAL Discord channel. DISPLAY/NOTIFY ONLY — never places or changes a trade.
    Returns True only on a 2xx send (so the loop arms its throttle on success)."""
    if not DISCORD_JOURNAL_WEBHOOK_URL:
        return False
    rep  = report or {}
    prob = rep.get("probability") or {}
    conf = rep.get("confidence") or {}
    direction = (trade or {}).get("direction") or rep.get("favored_direction") or "—"
    emoji = "📈" if direction == "Long" else "📉" if direction == "Short" else "🧭"
    cont, rng, rev = prob.get("continuation"), prob.get("range"), prob.get("reversal")
    prob_txt = "Continuation %s%% · Range %s%% · Reversal %s%%" % (
        cont if cont is not None else "—", rng if rng is not None else "—",
        rev if rev is not None else "—")
    cscore, cthr = conf.get("score"), conf.get("threshold")
    conf_txt = "%s%s — %s" % (
        cscore if cscore is not None else "—",
        ("/%s" % cthr) if cthr is not None else "",
        conf.get("narrative") or "—")
    exits = rep.get("early_exit_triggers") or []
    exit_txt = "\n".join("• " + str(t) for t in exits[:5]) or "—"
    fields = [
        {"name": "Outcome probability (heuristic estimate)", "value": prob_txt[:1024], "inline": False},
        {"name": "Confidence",          "value": conf_txt[:1024], "inline": False},
        {"name": "Early-exit triggers",  "value": exit_txt[:1024], "inline": False},
        {"name": "Invalidation",         "value": str(rep.get("invalidation") or "—")[:1024], "inline": False},
    ]
    embed = {
        "title":       ("%s Position Thesis Update — %s %s" % (emoji, inst, direction))[:256],
        "description": str(rep.get("headline") or "Position update.")[:2048],
        "color":       0x5865F2,
        "fields":      fields,
        "footer":      {"text": "Display/notify only — does not place or change any trade. "
                                "Probabilities are a derived heuristic estimate."},
        "timestamp":   datetime.now(timezone.utc).isoformat(),
    }
    try:
        resp = requests.post(DISCORD_JOURNAL_WEBHOOK_URL, json={"embeds": [embed]}, timeout=10)
        if resp.status_code in (200, 204):
            logger.info("Analyst report update posted for %s", inst)
            return True
        logger.warning("Analyst report update non-2xx (%s) for %s", resp.status_code, inst)
        return False
    except Exception as exc:
        logger.warning("Analyst report update post failed (%s): %s", inst, exc)
        return False


def _analyst_report_loop():
    """Every ANALYST_REPORT_INTERVAL seconds, while a position is OPEN, post a fresh
    Unified Analyst Report thesis update for that instrument to the JOURNAL channel —
    the companion to _trade_ready_loop (which fires while FLAT). DISPLAY/NOTIFY only;
    never touches the gate / money path. Started on the LIVE instance only (boot),
    mute-aware, per-instrument throttled, self-rescheduling daemon Timer."""
    try:
        now = datetime.now(timezone.utc)
        for inst in enabled_instruments():
            if not active_trade_for(inst):
                continue
            last = ANALYST_REPORT_LAST_SENT.get(inst)
            if last and (now - last).total_seconds() < ANALYST_REPORT_INTERVAL:
                continue
            if _alerts_muted(inst):
                continue
            try:
                a = full_analysis(ticker_override=inst)
            except Exception as exc:
                logger.error("analyst-report loop analysis error (%s): %s", inst, exc)
                continue
            # No thesis updates while the market is closed (overnight holds).
            if not a.get("market_open"):
                continue
            # Re-check the slot just before sending (it may have closed while
            # full_analysis ran).
            pos = active_trade_for(inst)
            if not pos:
                continue
            rep = a.get("analyst_report")
            if not isinstance(rep, dict) or not rep.get("engine_enabled"):
                continue
            if _post_analyst_report_update(inst, pos, rep):
                ANALYST_REPORT_LAST_SENT[inst] = now
    except Exception as exc:  # never let the loop die
        logger.warning("analyst-report loop error: %s", exc)
    finally:
        threading.Timer(ANALYST_REPORT_INTERVAL, _analyst_report_loop).start()


def _update_journal_outcome(new_outcome, pnl_dollars=None, symbol=None):
    """Update the most recent journal entry that is still Pending or at T1.

    Matches the first entry whose outcome is 'Pending' or starts with 'T1 Hit'.
    When `symbol` (an instrument code) is given, only entries for THAT instrument
    are eligible — so closing one asset's position can't mark another asset's
    still-open journal entry (per-asset isolation). Posts a brief update line to
    the journal Discord channel. Returns the updated entry or None if nothing matched.
    """
    _want_inst = instrument_of(symbol) if symbol else None
    for entry in JOURNAL:
        o = entry.get("outcome", "")
        if _want_inst is not None and instrument_of(entry.get("symbol", "")) != _want_inst:
            continue
        if o == "Pending" or o.startswith("T1 Hit"):
            entry["outcome"] = new_outcome
            if pnl_dollars is not None:
                entry["pnl_dollars"] = round(pnl_dollars, 2)
            _persist_journal_entry(entry)  # fail-open: mirror the outcome update to Postgres
            logger.info("Journal #%d outcome → %s", entry["id"], new_outcome)
            # Post a short update line to the journal channel
            if DISCORD_JOURNAL_WEBHOOK_URL:
                _outcome_emoji = "✅" if "Win" in new_outcome else ("⚠️" if "T1" in new_outcome else "❌")
                content = (
                    f"{_outcome_emoji} **Journal #{entry['id']} updated**\n"
                    f"{entry.get('symbol','—')} {entry.get('direction','—')}  ·  "
                    f"Outcome: **{new_outcome}**"
                )
                try:
                    requests.post(
                        DISCORD_JOURNAL_WEBHOOK_URL,
                        json={"content": content},
                        timeout=5,
                    )
                except Exception:
                    pass
            # Performance analytics: fire once per entry on a terminal outcome
            # (Win / Loss / Breakeven). Intermediate states (Pending / T1 Hit)
            # do not trigger. Deduped via entry["analytics_posted"].
            state = _outcome_state(new_outcome, entry.get("pnl_dollars"))
            if state in ("win", "loss", "breakeven") and not entry.get("analytics_posted"):
                entry["analytics_posted"] = True
                post_performance_stats(
                    reason=f"After {entry.get('symbol','—')} "
                           f"{entry.get('direction','—')} closed: {new_outcome}"
                )
            return entry
    return None


# ───────────────────────────────────────────────────────────────────────────
# Trade-management watcher (Features 1-3, fully additive).
#
# When a setup goes READY and its clean card posts, the setup is registered as a
# *managed trade* keyed by (instrument, direction, entry-zone low, UTC date). A
# background pass — piggybacking the VWAP auto-fetch loop — pulls the latest
# 1-minute bar (high/low/close) from the same public feed and walks the trade
# to its first terminal level: TP1 reached = Win, stop breached = Loss (the stop
# is checked first so an ambiguous bar resolves against the trade). The terminal
# exit posts an outcome card and writes Result / R / MFE / MAE to the journal.
#
# This NEVER touches the manual ACTIVE_TRADE flow, the READY gate, throttling,
# or the existing cards. Every entry point is wrapped in try/except so a feed
# hiccup can never block an alert.
# ───────────────────────────────────────────────────────────────────────────

def _managed_trade_key(instrument, direction, entry_lo):
    """Dedup key — same setup on the same UTC day maps to one managed trade."""
    try:
        lo_key = round(float(entry_lo), 0)
    except (TypeError, ValueError):
        lo_key = 0.0
    return (instrument, direction, lo_key,
            datetime.now(timezone.utc).strftime("%Y-%m-%d"))


def _build_swing_thesis(entry, mp, swing_ctx):
    """Build the per-trade SWING thesis (DISPLAY / local-tracking ONLY — it never
    feeds the strict gate, sizing, dedupe, or the /traderspost money path).

    Sourced from the already-computed plan (mp) + the P4 swing_context so it can
    never drift from what the gate actually saw. Fail-open: returns a stable-schema
    dict even when swing_ctx is missing. Caller gates on _swing_htf_enabled().
    """
    ctx        = swing_ctx if isinstance(swing_ctx, dict) else {}
    direction  = entry.get("direction") or (mp or {}).get("direction") or "Long"
    instrument = entry.get("instrument") or "—"
    stop       = (mp or {}).get("stop")
    target     = (mp or {}).get("tp1")
    planned_rr = entry.get("rr_num")
    bias_1h    = ctx.get("bias_1h")
    bias_4h    = ctx.get("bias_4h")
    bias_daily = ctx.get("bias_daily")
    lvl        = ctx.get("daily_level_nearby") if isinstance(ctx.get("daily_level_nearby"), dict) else {}
    lvl_label  = lvl.get("label") if lvl else None
    review_min = int(cfg_for("SWING", "SWING_REVIEW_INTERVAL_MIN"))
    rr_str     = f"{planned_rr:.2f}" if isinstance(planned_rr, (int, float)) else "—"
    thesis_text = (
        f"{direction} {instrument} on HTF alignment "
        f"(1H {bias_1h or '—'} / 4H {bias_4h or '—'} / Daily {bias_daily or '—'}); "
        f"entry on pullback to {lvl_label or 'HTF structure'}, "
        f"target {target if target is not None else '—'}, "
        f"invalidation {stop if stop is not None else '—'}."
    )
    reason = (
        f"1H+4H bias aligned {str(direction).lower()}; daily level "
        f"{lvl_label or 'n/a'} respected; planned RR {rr_str}."
    )
    return {
        "original_thesis":      thesis_text,
        "status":               "VALID",
        "reason":               reason,
        "invalidation_level":   stop,
        "next_target":          target,
        "planned_rr":           planned_rr,
        "current_r":            0.0,
        "next_review_at":       (now_utc() + timedelta(minutes=review_min)).isoformat(),
        "last_review_decision": None,
        # HTF summary for the dashboard (display-only):
        "bias_1h":              bias_1h,
        "bias_4h":              bias_4h,
        "bias_daily":           bias_daily,
        "daily_level_nearby":   lvl_label,
        "created_at":           now_utc().isoformat(),
    }


def _find_open_swing_managed_trade(instrument, direction, entry_lo):
    """SWING (flag-on) cross-UTC-day dedup. _managed_trade_key embeds today's UTC
    date, so a SWING setup reposted on a LATER day would mint a new key and spawn a
    duplicate managed trade. Return an existing OPEN managed trade for the same
    instrument+direction whose entry sits within ~1 risk-unit, so a multi-day hold
    refreshes the SAME trade. Returns None when there is no close match (the caller
    then registers a fresh trade)."""
    try:
        target_lo = float(entry_lo)
    except (TypeError, ValueError):
        return None
    best, best_dist = None, None
    for mt in MANAGED_TRADES_BY_KEY.values():
        if mt.get("closed"):
            continue
        # Strictly SWING-local: never let a SWING repost reuse a non-SWING managed
        # trade if mode/flag state shifts within one process.
        if not mt.get("is_swing"):
            continue
        if mt.get("instrument") != instrument or mt.get("direction") != direction:
            continue
        me = mt.get("entry_lo")
        if me is None:
            continue
        try:
            dist = abs(float(me) - target_lo)
        except (TypeError, ValueError):
            continue
        if best is None or dist < best_dist:
            best, best_dist = mt, dist
    if best is None:
        return None
    tol = best.get("risk_points") or (abs(target_lo) * 0.01) or 1.0
    if best_dist is not None and best_dist > tol:
        return None
    return best


def _register_managed_trade(entry, ticker=""):
    """Register (or refresh) a READY setup with the trade-management watcher.

    Idempotent: a repost of the same setup refreshes the plan levels but keeps
    any events already sent and the running MFE/MAE. A closed trade is never
    re-opened by a later repost on the same key/day.
    """
    mp = entry.get("management_plan")
    if not mp:
        return None  # no numeric plan (e.g. legacy/no-plan entry) — nothing to track

    instrument = entry.get("instrument") or instrument_of(ticker or entry.get("symbol", ""))
    direction  = entry.get("direction") or mp.get("direction") or "Long"
    key = _managed_trade_key(instrument, direction, mp.get("entry_lo"))

    # SWING (flag-on): a multi-day hold reposted on a LATER UTC day would otherwise
    # mint a new date-stamped key and duplicate the trade — reuse the existing open
    # SWING managed trade instead so its thesis + progress carry forward.
    if _swing_htf_enabled() and key not in MANAGED_TRADES_BY_KEY:
        _open_swing = _find_open_swing_managed_trade(instrument, direction, mp.get("entry_lo"))
        if _open_swing is not None:
            key = _open_swing["key"]

    # Light housekeeping: drop closed trades from previous UTC days.
    today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    for k in [k for k, v in MANAGED_TRADES_BY_KEY.items()
              if v.get("closed") and k[3] != today]:
        MANAGED_TRADES_BY_KEY.pop(k, None)

    existing = MANAGED_TRADES_BY_KEY.get(key)
    if existing is not None:
        if not existing.get("closed"):
            # A SCALP-dynamic trade that has begun PROGRESSING (a partial booked or
            # the stop moved to BE) FREEZES its plan: refreshing levels/pcts/stop
            # mid-walk would clobber a moved stop or re-base already-booked partial R.
            # A trade that hasn't triggered anything refreshes its plan numbers as
            # before (legacy never sets these flags -> byte-identical full refresh).
            started = bool(existing.get("tp1_hit") or existing.get("be_moved"))
            if not started:
                # Refresh plan numbers, preserve progress (events/MFE/MAE/be_active).
                existing.update({k: mp.get(k) for k in
                                 ("entry", "entry_lo", "entry_hi", "stop", "tp1", "tp2",
                                  "tp3", "be_level", "partial", "runner", "risk_points",
                                  "point_value", "tp1_pct", "tp2_pct", "runner_pct")})
                existing["initial_stop"] = mp.get("stop")
        # SWING (flag-on): keep the persisted snapshot current after a same-setup
        # repost refresh (display / local-tracking only — no money-path effect).
        if _swing_htf_enabled() and existing.get("is_swing"):
            _persist_swing_thesis(existing)
        return existing

    mt = {
        "key": key, "instrument": instrument, "direction": direction,
        "symbol": entry.get("symbol") or instrument,
        "entry": mp.get("entry"), "entry_lo": mp.get("entry_lo"), "entry_hi": mp.get("entry_hi"),
        "stop": mp.get("stop"), "tp1": mp.get("tp1"), "tp2": mp.get("tp2"), "tp3": mp.get("tp3"),
        "be_level": mp.get("be_level"), "partial": mp.get("partial"), "runner": mp.get("runner"),
        "tp1_pct": mp.get("tp1_pct"), "tp2_pct": mp.get("tp2_pct"),
        "runner_pct": mp.get("runner_pct"),
        "risk_points": mp.get("risk_points"), "point_value": mp.get("point_value"),
        "registered_at": datetime.now(timezone.utc).isoformat(),
        # Epoch (secs) of entry. The same-bar fill guard in _watch_managed_trades
        # only evaluates this trade against bars that OPENED strictly after it, so a
        # trade can never be closed on a bar whose high/low predates the entry.
        "entry_epoch": datetime.now(timezone.utc).timestamp(),
        "events_sent": set(), "updates": [],
        "mfe": 0.0, "mae": 0.0, "be_active": False, "closed": False,
        # S4 dynamic-lifecycle state (SCALP local/paper; inert for SWING / legacy
        # single-TP / live-broker paths — exit_reason stays None there).
        "initial_stop": mp.get("stop"),
        "remaining_pct": 1.0, "realized_r": 0.0,
        "tp1_hit": False, "tp2_hit": False, "runner_hit": False,
        "be_moved": False, "exit_reason": None,
        "trade_strength": entry.get("trade_strength"),
        "edge_score": entry.get("edge_score"),
        "journal_id": entry.get("id"),
        # Adaptive-learning: freeze the entry-time engine/indicator context so the
        # trade can be tagged with its regime/strategy/session/indicators at close.
        "learning_ctx": _capture_learning_ctx(instrument),
    }
    # SWING (flag-on) only: attach the per-trade thesis (DISPLAY / local-tracking
    # only — never feeds the gate, sizing, dedupe, or the /traderspost money path)
    # and persist the trade so a multi-day hold survives a restart. SCALP / flag-off
    # add NOTHING here → the mt dict stays byte-identical.
    if _swing_htf_enabled():
        try:
            mt["is_swing"]     = True
            mt["thesis_key"]   = uuid.uuid4().hex
            mt["swing_thesis"] = _build_swing_thesis(entry, mp, entry.get("_swing_context"))
        except Exception as exc:
            logger.warning("SWING thesis build failed: %s", exc)
    MANAGED_TRADES_BY_KEY[key] = mt
    logger.info("Managed trade registered: %s %s entry≈%s", instrument, direction, mp.get("entry"))
    if _swing_htf_enabled() and mt.get("is_swing"):
        _persist_swing_thesis(mt)
    return mt


def _tag_dynamic_paper_managed_trade(inst, plan, setup_key):
    """Option C (S4): for a SCALP dynamic PAPER (simulated, non-live) AUTO entry,
    let the MANAGED_TRADES dynamic lifecycle be the SOLE tracker/authority for the
    journal / outcome / learning instead of creating a 1-slot ACTIVE_TRADE.

    Why: an ACTIVE_TRADE would be finalised by check_trade_events at a flat 1:1 the
    instant TP1 prints, racing — and overwriting — the managed trade's BLENDED-R
    close (a paper trade forced back to 1:1, the exact S4 bug). MANAGED_TRADES is
    1:N (it already supports stacked SCALP setups) whereas ACTIVE_TRADES is one slot
    per instrument, so making the managed trade authoritative also sidesteps the
    1:N "which managed close clears the single active slot" ambiguity.

    Matches the just-registered open managed trade for this setup (registered by
    send_live_ready_card BEFORE auto-exec on the SAME webhook) by instrument +
    direction + nearest entry within tolerance, and tags it with the auto-exec
    context so its close can re-arm / cooldown like the legacy ACTIVE_TRADE path.

    Returns True only when a matching open managed trade was tagged. False (no
    match) tells the caller to FALL BACK to legacy ACTIVE_TRADE tracking, so a
    missing managed trade can never leave the paper position untracked (fail-closed).
    """
    try:
        direction = plan.get("direction")
        entry = float(plan.get("entry"))
    except (TypeError, ValueError):
        return False
    if not direction:
        return False
    best, best_dist = None, None
    for mt in MANAGED_TRADES_BY_KEY.values():
        if mt.get("closed"):
            continue
        if mt.get("instrument") != inst or mt.get("direction") != direction:
            continue
        me = mt.get("entry")
        if me is None:
            continue
        try:
            dist = abs(float(me) - entry)
        except (TypeError, ValueError):
            continue
        if best is None or dist < best_dist:
            best, best_dist = mt, dist
    if best is None:
        return False
    # Guard against tagging a DIFFERENT (older, stacked) setup: the freshly
    # registered managed trade shares this plan's entry, so the match must be close.
    tol = best.get("risk_points") or (abs(entry) * 0.01)
    if best_dist is not None and best_dist > (tol or 0.0):
        return False
    best["auto_setup_key"]   = setup_key
    best["auto_exec_status"] = "simulated"
    best["auto_opened_at"]   = now_utc().isoformat()
    return True


def _fetch_latest_bar(instrument):
    """Return {'high','low','close'} of the most recent 1-minute bar, or None.

    Uses the same public feed as the VWAP fetch (MGC≈GC=F, MNQ≈NQ=F). Best-effort
    — any error returns None so the watcher simply skips this cycle.
    """
    symbol = VWAP_FEED_SYMBOL.get(instrument)
    if not symbol:
        return None
    quote, err = _fetch_intraday_quote(symbol)
    if err:
        _log_feed_status("Latest-bar fetch", instrument, err)
        return None
    _log_feed_status("Latest-bar fetch", instrument, None)
    highs, lows, closes = quote["high"], quote["low"], quote["close"]
    stamps = quote.get("_timestamps") or []
    for i in range(len(closes) - 1, -1, -1):
        if highs[i] is not None and lows[i] is not None and closes[i] is not None:
            start = None
            try:
                if i < len(stamps) and stamps[i] is not None:
                    start = int(stamps[i])
            except (TypeError, ValueError):
                start = None
            return {"high": float(highs[i]), "low": float(lows[i]),
                    "close": float(closes[i]), "start": start}
    return None


def _watch_managed_trades():
    """Evaluate every open managed trade against the latest bar (one fetch per
    instrument per cycle). Called from _managed_watch_loop on its own fast timer
    (MANAGED_WATCH_INTERVAL)."""
    active = [mt for mt in MANAGED_TRADES_BY_KEY.values() if not mt.get("closed")]
    if not active:
        return
    bars = {}
    for inst in {mt["instrument"] for mt in active}:
        bars[inst] = _fetch_latest_bar(inst)
    for mt in active:
        bar = bars.get(mt["instrument"])
        if not bar:
            continue
        # ── Same-bar / pre-entry fill guard ────────────────────────────────────
        # Never resolve a trade against a bar that OPENED at or before its entry:
        # that bar's high/low can include price action from BEFORE the trade was
        # entered, which would close it instantly (~0s hold) at the EXACT stop or
        # target — a look-ahead artifact, not a real fill. Only evaluate bars that
        # began strictly AFTER entry. FAIL-OPEN: if the bar has no open time or the
        # trade no entry epoch, fall back to the prior (unguarded) behavior.
        _bar_start   = bar.get("start")
        _entry_epoch = mt.get("entry_epoch")
        if (_bar_start is not None and _entry_epoch is not None
                and _bar_start <= _entry_epoch):
            continue
        try:
            _evaluate_managed_trade_levels(mt, bar)
        except Exception as exc:
            logger.error("Managed-trade eval error (%s): %s", mt.get("key"), exc)


def _scalp_dynamic_lifecycle_enabled(mt):
    """True only when the SCALP dynamic multi-leg exit lifecycle should drive THIS
    managed trade LOCALLY (journal / alerts / dashboard). ALL three gates fail-closed:

      1) SCALP + master flag on (_scalp_dynamic_enabled, keyed on TRADING_MODE) so
         SWING / flag-off walks the byte-identical legacy single-TP path below.
      2) execution NOT live. A real broker (traderspost / pickmytrade) sends ONE TP
         = intent.target1 and flattens the WHOLE position there; a local multi-leg /
         runner walk would book partial + runner R the broker never held (desync). In
         live modes we collapse to the legacy broker-owned single exit.
      3) the trade actually carries the staged dynamic geometry (tp1/tp2 + a usable
         entry/stop/risk basis).
    """
    try:
        if not _scalp_dynamic_enabled():
            return False
        if execution_is_live(resolve_execution_mode()):
            return False
        if not mt:
            return False
        if mt.get("entry") is None or mt.get("tp1") is None or mt.get("tp2") is None:
            return False
        if mt.get("stop") is None or not mt.get("risk_points"):
            return False
        return True
    except Exception:
        return False


def _dynamic_leg_r(price, entry, risk, is_long):
    """Signed R of an exit at `price` vs `entry` on the ORIGINAL risk basis, so a
    BE-moved stop books ~0R rather than a re-based number."""
    if price is None or entry is None or not risk:
        return 0.0
    pts = (price - entry) if is_long else (entry - price)
    return pts / risk


def _maybe_move_be_to_entry(mt, bar):
    """Delayed break-even (req 4): after TP1, move the stop to entry only when the
    configured condition holds (favorable close OR price reached 1R). Idempotent;
    mirrors the move onto the ACTIVE_TRADES tracker best-effort. Caller is already
    gated to the SCALP dynamic lifecycle, so cfg() resolves SCALP knobs."""
    if mt.get("be_moved"):
        return
    if cfg("SCALP_BE_AFTER_TP1_ONLY") and not mt.get("tp1_hit"):
        return
    entry = mt.get("entry")
    if entry is None:
        return
    is_long = mt["direction"] == "Long"
    if cfg("SCALP_BE_REQUIRE_FAVOR_CLOSE_OR_1R"):
        close = bar.get("close")
        tp1   = mt.get("tp1")
        favor_close = close is not None and ((close > entry) if is_long else (close < entry))
        reached_1r  = tp1 is not None and ((bar["high"] >= tp1) if is_long else (bar["low"] <= tp1))
        if not (favor_close or reached_1r):
            return
    mt["stop"]      = entry
    mt["be_moved"]  = True
    mt["be_active"] = True
    _send_management_update(mt, "Stop \u2192 break-even",
                            f"Stop moved to entry ({entry}) after TP1.")
    # Best-effort mirror onto the broker/dashboard tracker so manual views agree.
    try:
        _at = active_trade_for(mt.get("instrument"))
        if (_at and _at.get("status") != "closed"
                and _at.get("direction") == mt.get("direction")):
            _at["stop_loss"] = entry
    except Exception:
        pass


def _finalize_dynamic_close(mt, exit_price, exit_reason):
    """Close a SCALP-dynamic managed trade on its BLENDED realized R. Outcome is
    derived from realized_r (Win>0 / Loss<0 / Breakeven==0) so a TP1-then-BE-stop
    books the partial profit rather than a flat loss."""
    realized = mt.get("realized_r") or 0.0
    if realized > 1e-9:
        outcome = "Win"
    elif realized < -1e-9:
        outcome = "Loss"
    else:
        outcome = "Breakeven"
    reason_label = {
        "stop":           "stop hit",
        "breakeven_stop": "break-even stop",
        "tp1":            "TP1",
        "tp2":            "TP2",
        "runner":         "runner",
    }.get(exit_reason, exit_reason or "closed")
    mt["exit_reason"] = exit_reason
    _close_managed_trade(mt, outcome, f"{outcome} ({reason_label})", exit_price)


def _evaluate_dynamic_managed_levels(mt, bar):
    """SCALP dynamic multi-leg exit walk for ONE OHLC bar (local/paper only; caller
    has already gated on _scalp_dynamic_lifecycle_enabled).

    Conservative ordering, stop FIRST: the (possibly BE-moved) stop is tested before
    any favorable level so an ambiguous bar resolves against the trade. With the stop
    ruled out for this bar, favorable legs are walked in ascending order
    TP1 -> [delayed BE] -> TP2 -> runner; a single large bar may fill several. Each
    leg books leg_pct * leg_R into realized_r exactly once, decrements remaining_pct,
    and the final leg (runner, or TP2 when no runner) closes the trade."""
    high, low = bar["high"], bar["low"]
    entry   = mt.get("entry")
    risk    = mt.get("risk_points") or 0.0
    is_long = mt["direction"] == "Long"

    # ── 1) Stop first (BE-aware). Books the remaining position at the stop's R. ──
    stop = mt.get("stop")
    if stop is not None:
        breached = (low <= stop) if is_long else (high >= stop)
        if breached:
            leg_r = _dynamic_leg_r(stop, entry, risk, is_long)
            mt["realized_r"]    = round((mt.get("realized_r") or 0.0)
                                        + (mt.get("remaining_pct") or 0.0) * leg_r, 4)
            mt["remaining_pct"] = 0.0
            reason = "breakeven_stop" if (mt.get("be_moved") and abs(leg_r) < 1e-9) else "stop"
            _finalize_dynamic_close(mt, stop, reason)
            return

    # ── 2) TP1 partial + delayed break-even ──
    if not mt.get("tp1_hit"):
        tp1 = mt.get("tp1")
        if tp1 is not None and ((high >= tp1) if is_long else (low <= tp1)):
            mt["tp1_hit"] = True
            pct   = mt.get("tp1_pct") or 0.0
            leg_r = _dynamic_leg_r(tp1, entry, risk, is_long)
            mt["realized_r"]    = round((mt.get("realized_r") or 0.0) + pct * leg_r, 4)
            mt["remaining_pct"] = round(max(0.0, (mt.get("remaining_pct") or 0.0) - pct), 4)
            _send_management_update(mt, "TP1 hit",
                                    f"Booked {round(pct * 100)}% at {tp1} (+{leg_r:.2f}R).")
            _maybe_move_be_to_entry(mt, bar)

    # ── 3) TP2 ──
    if mt.get("tp1_hit") and not mt.get("tp2_hit"):
        tp2 = mt.get("tp2")
        if tp2 is not None and ((high >= tp2) if is_long else (low <= tp2)):
            mt["tp2_hit"] = True
            has_runner = mt.get("runner") is not None and (mt.get("runner_pct") or 0.0) > 0.0
            pct   = (mt.get("tp2_pct") or 0.0) if has_runner else (mt.get("remaining_pct") or 0.0)
            leg_r = _dynamic_leg_r(tp2, entry, risk, is_long)
            mt["realized_r"]    = round((mt.get("realized_r") or 0.0) + pct * leg_r, 4)
            mt["remaining_pct"] = round(max(0.0, (mt.get("remaining_pct") or 0.0) - pct), 4)
            _send_management_update(mt, "TP2 hit",
                                    f"Booked {round(pct * 100)}% at {tp2} (+{leg_r:.2f}R).")
            if not has_runner or (mt.get("remaining_pct") or 0.0) <= 1e-9:
                _finalize_dynamic_close(mt, tp2, "tp2")
                return

    # ── 4) Runner ──
    if mt.get("tp2_hit") and not mt.get("runner_hit") and mt.get("runner") is not None:
        runner = mt.get("runner")
        if (high >= runner) if is_long else (low <= runner):
            mt["runner_hit"] = True
            pct   = mt.get("remaining_pct") or 0.0
            leg_r = _dynamic_leg_r(runner, entry, risk, is_long)
            mt["realized_r"]    = round((mt.get("realized_r") or 0.0) + pct * leg_r, 4)
            mt["remaining_pct"] = 0.0
            _send_management_update(mt, "Runner hit",
                                    f"Booked final {round(pct * 100)}% at {runner} (+{leg_r:.2f}R).")
            _finalize_dynamic_close(mt, runner, "runner")
            return


def _swing_lifecycle_enabled(mt):
    """True only when the SWING 15-min review lifecycle should drive THIS managed
    trade. Gated on the per-trade is_swing stamp (set ONLY on flag-on SWING
    registration) AND the SWING master flag, so SCALP / legacy / flag-off trades fall
    through to the byte-identical SCALP-dynamic + legacy paths below. Fail-closed."""
    try:
        return bool(mt) and bool(mt.get("is_swing")) and _swing_htf_enabled()
    except Exception:
        return False


def _swing_current_r(mt, price):
    """Signed R of `price` vs entry on the ORIGINAL risk basis (display + review
    thresholds). 0.0 when entry / risk / price is unavailable."""
    entry = mt.get("entry")
    risk  = mt.get("risk_points") or 0.0
    if entry is None or price is None or not risk:
        return 0.0
    pts = (price - entry) if mt.get("direction") == "Long" else (entry - price)
    try:
        return round(pts / risk, 2)
    except Exception:
        return 0.0


def _swing_review_due(thesis):
    """True when the SWING review window (SWING_REVIEW_INTERVAL_MIN) has elapsed. A
    missing / unparseable next_review_at reads as due (the apply step reschedules)."""
    nxt = (thesis or {}).get("next_review_at")
    if not nxt:
        return True
    try:
        due = datetime.fromisoformat(nxt)
        if due.tzinfo is None:
            due = due.replace(tzinfo=timezone.utc)
        return now_utc() >= due
    except Exception:
        return True


def _schedule_next_swing_review(thesis):
    """Advance next_review_at one SWING_REVIEW_INTERVAL_MIN window into the future."""
    if not isinstance(thesis, dict):
        return
    try:
        mins = int(cfg_for("SWING", "SWING_REVIEW_INTERVAL_MIN"))
    except Exception:
        mins = 15
    thesis["next_review_at"] = (now_utc() + timedelta(minutes=mins)).isoformat()


def _derive_swing_review_decision(mt, bar, ctx):
    """Decide HOLD / REDUCE / MOVE_STOP / EXIT for a DUE SWING review from the thesis
    + the live HTF context. FAIL-OPEN: missing / incomplete / stale HTF defaults HOLD
    so a feed hiccup can never force a spurious discretionary exit (the hard terminal
    stop is honored separately on every bar)."""
    is_long = mt.get("direction") == "Long"
    cur_r   = _swing_current_r(mt, bar.get("close"))

    if not isinstance(ctx, dict) or not ctx.get("complete") or ctx.get("stale"):
        return "HOLD"

    aligned_long  = bool(ctx.get("aligned_long"))
    aligned_short = bool(ctx.get("aligned_short"))

    # EXIT: 1H+4H bias has FULLY flipped against the position -> thesis invalidated.
    if (is_long and aligned_short) or ((not is_long) and aligned_long):
        return "EXIT"

    # REDUCE (once, in non-loss): trade-side 1H/4H alignment no longer intact, or the
    # Daily bias opposes -> weakening but not a full flip.
    trade_side_intact = aligned_long if is_long else aligned_short
    daily_opposes     = ctx.get("bias_daily") == ("bear" if is_long else "bull")
    if (not trade_side_intact or daily_opposes) and cur_r >= 0 and not mt.get("swing_reduced"):
        return "REDUCE"

    # MOVE STOP (once): >=1R in profit with the stop still beyond entry -> trail to BE.
    entry = mt.get("entry")
    stop  = mt.get("stop")
    stop_beyond_entry = (stop is not None and entry is not None
                         and ((stop < entry) if is_long else (stop > entry)))
    if cur_r >= 1.0 and stop_beyond_entry and not mt.get("swing_stop_moved"):
        return "MOVE_STOP"

    return "HOLD"


def _apply_swing_review_decision(mt, decision, bar, ctx):
    """Apply a SWING review decision. Always refreshes the thesis (status / reason /
    current_r / last_review_decision / HTF summary) + reschedules + persists. LOCAL
    state mutations that change the money outcome (stop move, early EXIT close) apply
    ONLY when execution is NOT live -- a live broker holds a single bracket, so those
    decisions are Discord/dashboard ADVISORY there (never book exposure the broker did
    not take, mirroring the SCALP dynamic gate). FAIL-OPEN."""
    thesis = mt.get("swing_thesis")
    if not isinstance(thesis, dict):
        return
    close   = bar.get("close")
    is_long = mt.get("direction") == "Long"
    cur_r   = _swing_current_r(mt, close)
    try:
        live = execution_is_live(resolve_execution_mode())
    except Exception:
        live = False

    # Refresh the live HTF summary on the thesis (display-only).
    if isinstance(ctx, dict):
        thesis["bias_1h"]    = ctx.get("bias_1h")
        thesis["bias_4h"]    = ctx.get("bias_4h")
        thesis["bias_daily"] = ctx.get("bias_daily")
        _lvl = ctx.get("daily_level_nearby") if isinstance(ctx.get("daily_level_nearby"), dict) else None
        if _lvl:
            thesis["daily_level_nearby"] = _lvl.get("label")
    thesis["current_r"]            = cur_r
    thesis["last_review_decision"] = decision

    if decision == "EXIT":
        thesis["status"] = "INVALID"
        thesis["reason"] = "1H+4H HTF bias flipped against the position; thesis invalidated."
        if not live:
            outcome = "Win" if cur_r > 0 else ("Loss" if cur_r < 0 else "Breakeven")
            _send_management_update(
                mt, "SWING review \u2192 EXIT",
                f"Thesis invalidated (HTF bias flipped). Exiting at {close} ({cur_r:+.2f}R).")
            # _close_managed_trade re-persists the (now closed) thesis (P5 close path).
            _close_managed_trade(mt, outcome, f"SWING thesis exit ({cur_r:+.2f}R)", close)
            return
        if not mt.get("swing_exit_advised"):
            mt["swing_exit_advised"] = True
            _send_management_update(
                mt, "SWING review \u2192 EXIT (advisory)",
                f"Thesis invalidated (HTF bias flipped). Broker bracket still live \u2014 "
                f"consider a manual exit ({cur_r:+.2f}R).")
    elif decision == "REDUCE":
        thesis["status"] = "WEAKENING"
        thesis["reason"] = "HTF alignment weakening (not a full flip); reduce risk."
        mt["swing_reduced"] = True
        _send_management_update(
            mt, "SWING review \u2192 REDUCE",
            f"HTF alignment weakening \u2014 consider trimming / reducing risk ({cur_r:+.2f}R).")
    elif decision == "MOVE_STOP":
        entry = mt.get("entry")
        mt["swing_stop_moved"] = True
        thesis["status"] = "VALID"
        if (not live) and entry is not None:
            mt["stop"] = entry
            thesis["invalidation_level"] = entry
            _send_management_update(
                mt, "SWING review \u2192 MOVE STOP",
                f"In +{cur_r:.2f}R \u2014 stop moved to break-even ({entry}).")
        else:
            _send_management_update(
                mt, "SWING review \u2192 MOVE STOP (advisory)",
                f"In +{cur_r:.2f}R \u2014 move stop to break-even ({entry}).")
    else:  # HOLD (silent -- no Discord, just refresh the thesis + reschedule)
        thesis["status"] = "VALID"
        thesis["reason"] = "HTF thesis intact; holding."

    _schedule_next_swing_review(thesis)
    try:
        _persist_swing_thesis(mt)
    except Exception as exc:
        logger.warning("SWING review persist error: %s", exc)


def _evaluate_swing_managed_levels(mt, bar):
    """SWING (flag-on) managed-trade walk for ONE bar. Caller has gated on
    _swing_lifecycle_enabled. Every bar honors the terminal stop FIRST (hard
    invalidation; an ambiguous bar resolves against the trade) then banks the single
    broker TP target immediately (a hit profit target is not an adverse-candle
    discretionary exit, and local state must mirror the one broker TP). The
    discretionary HOLD/REDUCE/MOVE-STOP/EXIT thesis review fires at most once per
    SWING_REVIEW_INTERVAL_MIN window. MFE/MAE already updated by the caller."""
    high, low = bar.get("high"), bar.get("low")
    close     = bar.get("close")
    is_long   = mt.get("direction") == "Long"

    # 1) Terminal stop (hard invalidation; honored every bar).
    stop = mt.get("stop")
    if stop is not None and high is not None and low is not None:
        if (low <= stop) if is_long else (high >= stop):
            _close_managed_trade(mt, "Loss", "Loss (stop hit)", stop)
            return

    # 2) Broker TP target (banked immediately to mirror the single broker TP).
    tp1 = mt.get("tp1")
    if tp1 is not None and high is not None and low is not None:
        if (high >= tp1) if is_long else (low <= tp1):
            _close_managed_trade(mt, "Win", "Win (target hit)", tp1)
            return

    # 3) 15-min discretionary thesis review (cadence-gated; fail-open).
    thesis = mt.get("swing_thesis")
    if not isinstance(thesis, dict) or not _swing_review_due(thesis):
        return
    try:
        ctx = compute_swing_context(mt.get("instrument"), close)
    except Exception as exc:
        logger.warning("SWING review HTF read failed (%s): %s", mt.get("key"), exc)
        ctx = None
    decision = _derive_swing_review_decision(mt, bar, ctx)
    _apply_swing_review_decision(mt, decision, bar, ctx)


def _evaluate_managed_trade_levels(mt, bar):
    """Walk one managed trade through its plan using a single OHLC bar.

    Win/loss definition: a WIN is booked the moment TP1 is reached; a LOSS the
    moment the stop is breached. The stop is checked *before* TP1 so an ambiguous
    bar (whose range spans both levels) resolves conservatively against the trade.
    """
    if mt.get("closed"):
        return
    high, low = bar["high"], bar["low"]
    entry   = mt.get("entry")
    is_long = mt["direction"] == "Long"

    # ── Running MFE / MAE (price points, never negative) ──
    if entry is not None:
        if is_long:
            fav, adv = high - entry, entry - low
        else:
            fav, adv = entry - low, high - entry
        mt["mfe"] = round(max(mt["mfe"], fav, 0.0), 4)
        mt["mae"] = round(max(mt["mae"], adv, 0.0), 4)

    # ── SWING (flag-on) 15-min thesis review lifecycle: terminal stop + the single
    # broker TP banked every bar; discretionary HOLD/REDUCE/MOVE-STOP/EXIT only at the
    # 15-min review. Gated on is_swing (set ONLY on flag-on SWING registration) so
    # SCALP / legacy / flag-off fall through to the byte-identical SCALP-dynamic +
    # legacy paths below. ──
    if _swing_lifecycle_enabled(mt):
        _evaluate_swing_managed_levels(mt, bar)
        return

    # ── SCALP dynamic multi-leg exit lifecycle (req 3/4): partial scale at TP1/TP2/
    # runner + delayed break-even. Gated to SCALP + master flag + local/paper exec +
    # a trade carrying dynamic geometry; SWING / flag-off / live-broker fall through
    # to the byte-identical legacy stop-first / TP1=Win path below. ──
    if _scalp_dynamic_lifecycle_enabled(mt):
        _evaluate_dynamic_managed_levels(mt, bar)
        return

    # ── 1) Terminal stop (checked first; an ambiguous bar resolves against the trade) ──
    stop = mt.get("stop")
    if stop is not None:
        stop_breached = (low <= stop) if is_long else (high >= stop)
        if stop_breached:
            _close_managed_trade(mt, "Loss", "Loss (stop hit)", stop)
            return

    # ── 2) Win: TP1 reached closes the trade as a Win ──
    tp1 = mt.get("tp1")
    if tp1 is not None:
        tp1_reached = (high >= tp1) if is_long else (low <= tp1)
        if tp1_reached:
            _close_managed_trade(mt, "Win", "Win (TP1 hit)", tp1)
            return


def _close_managed_trade(mt, outcome, result_label, exit_price):
    """Finalise a managed trade: compute R / MFE / MAE / PnL, post the outcome
    card, and write the result back to the linked journal entry."""
    if mt.get("closed"):
        return
    mt["closed"]       = True
    mt["outcome"]      = outcome
    mt["result_label"] = result_label
    mt["exit_price"]   = exit_price
    mt["closed_at"]    = datetime.now(timezone.utc).isoformat()

    entry   = mt.get("entry")
    risk    = mt.get("risk_points") or 0.0
    pv      = mt.get("point_value") or 0.0
    is_long = mt["direction"] == "Long"

    if mt.get("exit_reason") is not None:
        # SCALP dynamic close: PnL/R is the BLENDED realized R booked across the legs,
        # not a single-exit number (a TP1-then-BE-stop is a partial WIN, not a flat
        # loss). exit_reason is set ONLY by the dynamic finaliser, so the legacy /
        # SWING single-TP path (exit_reason None) is byte-identical below.
        mt["r_multiple"]  = round(mt.get("realized_r") or 0.0, 2)
        mt["pnl_points"]  = round(mt["r_multiple"] * risk, 4)
        mt["pnl_dollars"] = round(mt["pnl_points"] * pv, 2)
    else:
        if entry is not None and exit_price is not None:
            pnl_points = (exit_price - entry) if is_long else (entry - exit_price)
        else:
            pnl_points = 0.0
        mt["pnl_points"]  = round(pnl_points, 4)
        mt["pnl_dollars"] = round(pnl_points * pv, 2)
        mt["r_multiple"]  = round(pnl_points / risk, 2) if risk else 0.0
    mt["mfe_r"]       = round(mt["mfe"] / risk, 2) if risk else 0.0
    mt["mae_r"]       = round(mt["mae"] / risk, 2) if risk else 0.0

    _send_outcome_update(mt)
    _apply_outcome_to_journal(mt)

    # Adaptive-learning: persist AFTER the user-facing outcome card + journal so a
    # slow DB can never delay the notification. Idempotent + FAIL-OPEN (architect
    # note B); mt already carries closed_at/outcome/r_multiple at this point.
    try:
        _record_strategy_trade(mt)
    except Exception as exc:
        logger.warning("strategy-trade persist error: %s", exc)

    # ── SWING (flag-on) multi-day persistence: mark the thesis row closed so a
    # stopped/TP'd SWING trade is NOT resurrected as OPEN on the next boot (the
    # rehydrate query selects WHERE closed = FALSE). Gated on is_swing (set only on
    # SWING flag-on registration) so SCALP / legacy closes are byte-identical; the
    # mt already carries closed=True/closed_at/r_multiple here. FAIL-OPEN. ──
    if mt.get("is_swing"):
        try:
            _persist_swing_thesis(mt)
        except Exception as exc:
            logger.warning("swing thesis close-persist error: %s", exc)

    # ── Option C (S4): a SCALP dynamic PAPER auto trade has NO ACTIVE_TRADE slot —
    # this managed lifecycle is its sole authority — so reproduce the post-outcome
    # auto bookkeeping that the legacy ACTIVE_TRADES/check_trade_events path applies
    # for live / legacy-paper trades: re-arm the setup on a stop-loss (so AUTO can
    # re-enter once it is READY again) and apply the per-asset post-outcome cooldown.
    # Tag-gated (auto_exec_status=="simulated"): only tagged paper auto trades, never
    # SWING / live / manual_only / untracked managed trades. Fail-open. ──
    if mt.get("auto_exec_status") == "simulated":
        try:
            _inst    = mt.get("instrument")
            _outcome = mt.get("outcome")
            if _outcome == "Loss":
                # A losing managed close is a pre-TP1 stop-out (realized_r < 0); re-arm
                # exactly as check_trade_events does on STOP_HIT so the setup can fire
                # again the instant it is READY (SCALP re-entry).
                _key = mt.get("auto_setup_key")
                if _key is not None:
                    with AUTO_TRADE_LOCK:
                        AUTO_FIRED_KEYS.discard(_key)
                _set_outcome_cooldown(_inst, cooldown_after_loss(_inst), "loss")
            elif _outcome == "Win":
                _set_outcome_cooldown(_inst, cooldown_after_win(_inst), "win")
        except Exception as exc:
            logger.warning("paper-dynamic post-outcome bookkeeping error: %s", exc)


def _send_management_update(mt, title, detail):
    """Record + post a single trade-management update to the instrument channel."""
    mt.setdefault("updates", []).append(f"{title} — {detail}")
    url = _discord_url(mt.get("symbol") or mt.get("instrument"))
    if not url:
        return
    content = (f"**{mt.get('instrument')} {mt.get('direction')} — Trade Management**\n"
               f"{title}\n{detail}")
    try:
        requests.post(url, json={"content": content[:1900]}, timeout=5)
    except Exception as exc:
        logger.error("Management update post error: %s", exc)


def _send_outcome_update(mt):
    """Post the terminal-outcome card to the instrument channel and journal."""
    o     = mt.get("outcome", "—")
    emoji = {"Win": "✅", "Loss": "❌", "Breakeven": "➖"}.get(o, "•")
    color = {"Win": 0x2ECC71, "Loss": 0xE74C3C, "Breakeven": 0xF1C40F}.get(o, 0x95A5A6)
    embed = {
        "title": f"{emoji} Trade Closed — {mt.get('result_label', o)}",
        "color": color,
        "fields": [
            {"name": "Instrument", "value": str(mt.get("instrument", "—")), "inline": True},
            {"name": "Direction",  "value": str(mt.get("direction", "—")),  "inline": True},
            {"name": "Result",     "value": str(o),                          "inline": True},
            {"name": "Entry",      "value": str(mt.get("entry", "—")),       "inline": True},
            {"name": "Exit",       "value": str(mt.get("exit_price", "—")),  "inline": True},
            {"name": "R Multiple", "value": f"{mt.get('r_multiple', 0)}R",   "inline": True},
            {"name": "MFE",        "value": f"{mt.get('mfe_r', 0)}R",        "inline": True},
            {"name": "MAE",        "value": f"{mt.get('mae_r', 0)}R",        "inline": True},
            {"name": "PnL (1 contract)", "value": f"${mt.get('pnl_dollars', 0):,.2f}", "inline": True},
        ],
        "footer": {"text": "Trade-management outcome · auto-tracked"},
    }
    if mt.get("exit_reason"):
        embed["fields"].append({"name": "Exit Reason",
                                "value": str(mt.get("exit_reason")), "inline": True})
    updates = mt.get("updates") or []
    if updates:
        embed["fields"].append({"name": "Management Path",
                                "value": "\n".join(f"• {u}" for u in updates)[:1024],
                                "inline": False})
    for url in {_discord_url(mt.get("symbol") or mt.get("instrument")), DISCORD_JOURNAL_WEBHOOK_URL}:
        if not url:
            continue
        try:
            requests.post(url, json={"embeds": [embed]}, timeout=10)
        except Exception as exc:
            logger.error("Outcome update post error: %s", exc)


def _apply_outcome_to_journal(mt):
    """Write the management outcome onto its linked journal entry (additive keys),
    and set the entry's outcome/pnl so analytics + reports can count it. Never
    overwrites an outcome already decided by the manual flow."""
    jid    = mt.get("journal_id")
    target = None
    if jid is not None:
        for e in JOURNAL:
            if e.get("id") == jid:
                target = e
                break
    if target is None:  # fall back to the most-recent dedup match
        for e in JOURNAL:
            if (instrument_of(e.get("symbol", "")) == mt.get("instrument")
                    and e.get("direction") == mt.get("direction")):
                target = e
                break
    if target is None:
        return
    target["mgmt_outcome"]       = mt.get("outcome")
    target["mgmt_result_label"]  = mt.get("result_label")
    target["r_multiple"]         = mt.get("r_multiple")
    target["mfe_r"]              = mt.get("mfe_r")
    target["mae_r"]              = mt.get("mae_r")
    target["management_updates"] = list(mt.get("updates") or [])
    target["mgmt_closed_at"]     = mt.get("closed_at")
    # Only set the canonical outcome if the manual flow hasn't already decided it.
    if _outcome_state(target.get("outcome"), target.get("pnl_dollars")) is None:
        target["outcome"]     = mt.get("outcome")
        target["pnl_dollars"] = mt.get("pnl_dollars")
    logger.info("Journal #%s management outcome → %s (%sR)",
                target.get("id"), mt.get("outcome"), mt.get("r_multiple"))


# ---------------------------------------------------------------------------
# Additive upgrade helpers — AI notes, structure block, screenshot, analytics.
# All grounded in real full_analysis() data; none alter scoring or the webhook
# path. build_setup_notes/build_trade_thesis are isolated so they can later be
# swapped for an LLM without touching callers.
# ---------------------------------------------------------------------------

# Private/loopback host prefixes rejected for screenshot URLs (SSRF-safe; the
# URL is only ever handed to Discord, never fetched server-side).
_PRIVATE_HOST_RE = re.compile(
    r'^(localhost|127\.|0\.0\.0\.0|10\.|192\.168\.|169\.254\.|'
    r'172\.(1[6-9]|2[0-9]|3[0-1])\.)', re.I,
)

PERF_CATEGORIES = ("BOS Demand", "BOS Supply", "CHOCH Bullish", "CHOCH Bearish",
                   "VWAP Reclaim", "VWAP Rejection")


def extract_screenshot_url(record):
    """Return a public http(s) chart/screenshot URL from a webhook payload, or None.

    Accepts several common field names. Rejects non-http(s) schemes and
    private/loopback hosts. Never fetches the URL — only a validated public URL
    is passed through to Discord's embed image.
    """
    if not isinstance(record, dict):
        return None
    raw = (record.get("screenshot") or record.get("screenshot_url")
           or record.get("chart_url") or record.get("chart_image")
           or record.get("chart") or record.get("image"))
    if not raw:
        return None
    url = str(raw).strip()
    # Ignore the legacy placeholder string; cap length (Discord image URL limit).
    if not url or url.startswith("[") or len(url) > 2048:
        return None
    try:
        p = urlparse(url)
    except Exception:
        return None
    if p.scheme not in ("http", "https") or not p.hostname:
        return None
    if _PRIVATE_HOST_RE.match(p.hostname):
        return None
    return url


def _fmt_lvl(v):
    """Format a numeric price level as a 2-dp string, or None if not numeric."""
    try:
        return f"{float(v):.2f}"
    except (TypeError, ValueError):
        return None


def build_structure_fields(a, direction):
    """Return (bos_status, choch_status, vwap_position, supply_demand_zone) strings
    grounded in the full_analysis() result `a`. VWAP side is derived by comparing
    current price to the VWAP value (vwap_status is freshness, not direction)."""
    lpt = a.get("last_price_by_type") or {}
    if direction == "Long":
        bos_lvl   = _fmt_lvl(lpt.get("BOS DEMAND"))
        choch_lvl = _fmt_lvl(lpt.get("CHOCH DEMAND"))
        zone_lvl  = _fmt_lvl(a.get("nearest_demand"))
        bos_status   = f"BOS Demand @ {bos_lvl}" if bos_lvl else "None"
        choch_status = f"Bullish CHOCH @ {choch_lvl}" if choch_lvl else "None"
        zone_word    = "Demand"
    else:
        bos_lvl   = _fmt_lvl(lpt.get("BOS SUPPLY"))
        choch_lvl = _fmt_lvl(lpt.get("CHOCH SUPPLY"))
        zone_lvl  = _fmt_lvl(a.get("nearest_supply"))
        bos_status   = f"BOS Supply @ {bos_lvl}" if bos_lvl else "None"
        choch_status = f"Bearish CHOCH @ {choch_lvl}" if choch_lvl else "None"
        zone_word    = "Supply"

    # _fmt_lvl validates numerics; float() on its output is then always safe.
    vval_f  = _fmt_lvl(a.get("vwap_value"))
    price_f = _fmt_lvl(a.get("current_price"))
    if vval_f and price_f:
        side = "Above" if float(price_f) >= float(vval_f) else "Below"
        vwap_position = f"{side} VWAP ({vval_f})"
    else:
        vwap_position = "—"

    if a.get("zone_broken_active"):
        sd_zone = f"{zone_word} zone broken"
    elif a.get("zone_mitigated_near"):
        sd_zone = f"{zone_word} zone consumed"
    elif zone_lvl:
        sd_zone = f"{zone_word} intact @ {zone_lvl}"
    else:
        # No nearest zone level on this side — do NOT claim "intact". That string
        # both mislabels the Zone display and trips the Edge Score's zone_active
        # check, fabricating a "Demand/Supply Zone Active" credit with no zone.
        sd_zone = "—"

    return bos_status, choch_status, vwap_position, sd_zone


def build_setup_notes(a, entry):
    """Deterministic, fact-grounded "AI Analysis" for a setup. Every line is built
    from the real confluences in `a`/`entry`, so it can never hallucinate. Kept in
    one place so it can be swapped for an LLM later without touching callers."""
    direction = entry.get("direction", "Long")
    conf         = a.get("confluences") or {}
    bos_status   = entry.get("bos_status")   or "None"
    choch_status = entry.get("choch_status") or "None"
    vwap_pos     = str(entry.get("vwap_position") or "").lower()
    t1           = entry.get("target1")
    # Each note line is gated on a REAL confluence so the notes can never invent a
    # signal the setup didn't actually have.
    has_sweep    = bool(conf.get("liquidity_sweep") or conf.get("sweep") or a.get("liquidity_sweep"))
    zone_mitig   = bool(conf.get("zone_mitigated"))
    zone_intact  = not (a.get("zone_broken_active") or a.get("zone_mitigated_near"))
    has_struct   = (choch_status != "None") or (bos_status != "None")
    lines = []
    if direction == "Long":
        if has_sweep:
            lines.append("Price swept liquidity below recent lows.")
        if zone_mitig:
            lines.append("Demand zone was mitigated and respected.")
        else:
            zone_lvl = _fmt_lvl(a.get("nearest_demand"))
            if zone_lvl:
                lines.append(f"Price reacted at demand near {zone_lvl} and is holding bid.")
        if has_struct:
            lines.append("Bullish CHOCH/BOS supports upside structure.")
        if vwap_pos.startswith("above"):
            lines.append("VWAP confluence supports continuation.")
        if zone_intact and not zone_mitig and zone_lvl:
            lines.append("Demand zone remains intact.")
        lines.append(f"Looking for continuation toward {t1}."
                     if t1 not in (None, "") else
                     "Looking for continuation toward next resistance.")
    else:
        if has_sweep:
            lines.append("Price swept liquidity above recent highs.")
        if zone_mitig:
            lines.append("Supply zone was mitigated and respected.")
        else:
            zone_lvl = _fmt_lvl(a.get("nearest_supply"))
            if zone_lvl:
                lines.append(f"Price rejected supply near {zone_lvl}.")
        if has_struct:
            lines.append("Bearish CHOCH/BOS supports downside structure.")
        if vwap_pos.startswith("below"):
            lines.append("VWAP confluence supports continuation.")
        if zone_intact and not zone_mitig and zone_lvl:
            lines.append("Supply zone remains respected.")
        lines.append(f"Looking for continuation toward {t1}."
                     if t1 not in (None, "") else
                     "Looking for continuation toward next support.")
    if not lines:
        lines.append(entry.get("why_qualifies") or "Setup conditions met.")
    return "\n".join(lines)[:1000]


def build_trade_thesis(a, entry):
    """One-line trade thesis grounded in the setup direction and target."""
    direction = entry.get("direction", "Long")
    sym       = entry.get("symbol", "—")
    t1        = entry.get("target1")
    tgt       = f", targeting {t1}" if t1 not in (None, "") else ""
    if direction == "Long":
        return f"Long {sym}: demand reclaim with bullish CHOCH above VWAP{tgt}."[:240]
    return f"Short {sym}: supply rejection with bearish CHOCH below VWAP{tgt}."[:240]


def classify_setup_categories(entry):
    """Tag a setup with performance categories from its structure + VWAP position."""
    cats = []
    direction    = entry.get("direction", "Long")
    bos_status   = str(entry.get("bos_status") or "")
    choch_status = str(entry.get("choch_status") or "")
    vwap_pos     = str(entry.get("vwap_position") or "").lower()
    if direction == "Long":
        if bos_status not in ("", "None"):   cats.append("BOS Demand")
        if choch_status not in ("", "None"): cats.append("CHOCH Bullish")
        if vwap_pos.startswith("above"):     cats.append("VWAP Reclaim")
    else:
        if bos_status not in ("", "None"):   cats.append("BOS Supply")
        if choch_status not in ("", "None"): cats.append("CHOCH Bearish")
        if vwap_pos.startswith("below"):     cats.append("VWAP Rejection")
    return cats


def _grade_for_score(score):
    """Map an Edge Score (0-EDGE_SCORE_MAX) to a Trade Grade band.

    Bands (Edge Score → Grade): >= 85 A+, >= 70 A (Strong), >= 50 B (Possible),
    below WAIT. These line up 1:1 with the display tiers — A+ Setup (>= 85),
    Strong Trade (>= 70), Possible Trade (>= 50) — so a card's grade never
    contradicts its tier. A SCALP READY (floor 70) is always grade A or better;
    a SWING READY (floor 80) is grade A or better too."""
    s = score or 0
    if s >= 85: return "A+"
    if s >= 70: return "A"
    if s >= 50: return "B"
    return "WAIT"


# ── Trade-strength classification (display / journal / analytics) ──────────────
# Display tier sub-classification by Edge Score: 50-69 → Possible Trade, 70-84 →
# Strong Trade, >= 85 → A+ Setup. This never affects the READY gate itself
# (evaluate_strict_setup); it only labels a setup for display. A score below 50 is
# not a qualified tier and returns None. NOTE: "A+ Setup" is a DISPLAY tier only —
# the journal strict_label stays in {Strong Trade, Possible Trade, WAIT}.
def _trade_strength_from_score(score):
    try:
        s = float(score)
    except (TypeError, ValueError):
        return None
    if s >= 85:
        return "A+ Setup"
    if s >= 70:
        return "Strong Trade"
    if s >= 50:
        return "Possible Trade"
    return None


def _score_tier(score):
    """Conviction tier from the Edge Score (display-only) — the user-facing band
    naming. HIGH CONVICTION >= 70, READY 50-69, else None.
    Distinct from the operational alert_level ladder (WATCH/ARMED/WATCH FOR ENTRY/
    READY): a tier names the STRENGTH of an Edge Score, not the dispatch state, and
    never gates a trade. The bands line up with the display tiers — HIGH CONVICTION
    >= 70 (Strong/A+), READY 50-69 (Possible); in SWING (floor 80) a READY always
    lands in HIGH CONVICTION."""
    try:
        s = float(score)
    except (TypeError, ValueError):
        return None
    if s >= 70:
        return "HIGH CONVICTION"
    if s >= 50:
        return "READY"
    return None


def _decision_support(a):
    """Decision-support header for the live trade card + dashboard gauge. EVERY
    field is derived from REAL analysis data — nothing is fabricated. `a` may be a
    full_analysis result OR a card-entry dict (both carry edge_score,
    conviction_tier, verdict, a volatility dict, a preferred-session flag and a
    trade plan), so it reads everything defensively with .get().

      quality        ← conviction tier: HIGH CONVICTION→HIGH, READY→MODERATE,
                       EARLY READY→SPECULATIVE, else LOW
      probability    ← the Edge Score (the SAME number shown as EdgeScore)
      risk           ← volatility regime: Normal→Low, Caution→Moderate,
                       Block→High, unavailable→Unknown
      reward         ← trade-plan T2 R:R: >=3 Excellent / >=2 Good / >=1.5 Fair / else Poor
      trade_window   ← preferred-session flag
      recommendation ← tier + verdict: full READY enter / EARLY READY aggressive-
                       enter-or-wait / else stand aside
    """
    a = a or {}
    edge    = int(a.get("edge_score") or 0)
    tier    = a.get("conviction_tier") or _score_tier(edge)
    verdict = a.get("verdict") or ""
    vol     = a.get("volatility") or {}
    regime  = (vol.get("regime") or "NA").upper()

    quality = {"HIGH CONVICTION": "HIGH", "READY": "MODERATE",
               "EARLY READY": "SPECULATIVE"}.get(tier, "LOW")

    if vol.get("status") != "ok":
        risk = "Unknown"
    elif vol.get("blocked"):
        risk = "High"
    elif vol.get("caution"):
        risk = "Moderate"
    elif regime == "NORMAL":
        risk = "Low"
    else:
        risk = "Moderate"

    rr = a.get("rr_num")
    if rr is None:
        rr = (a.get("trade_plan") or {}).get("rr_num")
    try:
        rr_f = float(rr)
    except (TypeError, ValueError):
        rr_f = None
    # Fixed 1:1 risk model: the reward distance always equals risk by design, so the
    # old R-multiple grade (Excellent/Good/Fair/Poor) no longer carries meaning —
    # report the fixed ratio honestly instead of flagging every setup as "Poor".
    reward = "1:1 (fixed)" if rr_f is not None else "—"

    pref = a.get("session_preferred")
    if pref is None:
        pref = (a.get("session") or {}).get("preferred")
    trade_window = "Preferred window" if pref else "Off-hours"

    if is_full_ready(verdict):
        recommendation = f"ENTER {ready_direction(verdict).upper()} — full conviction setup."
    elif is_early_ready(verdict):
        recommendation = (f"EARLY {ready_direction(verdict).upper()} — enter aggressive at "
                          "reduced size, or wait for the confirmation candle.")
    else:
        recommendation = "STAND ASIDE — no qualified setup."

    return {
        "quality":        quality,
        "probability":    edge,
        "risk":           risk,
        "reward":         reward,
        "trade_window":   trade_window,
        "recommendation": recommendation,
    }


def _strength_display(strength):
    """Bold, color-coded Discord label for a trade strength."""
    return {"A+ Setup":       "🔥 A+ SETUP",
            "Strong Trade":   "🟢 STRONG TRADE",
            "Possible Trade": "🟡 POSSIBLE TRADE"}.get(strength, "🟡 POSSIBLE TRADE")


def _edge_score_for_entry(entry):
    """Authoritative Edge Score for a stored journal entry. Prefers the
    transparent breakdown score, then the stored edge_score, then the strict
    gate score, then the legacy edge score — so manual/legacy entries still
    rank in recap and analytics."""
    eb = entry.get("edge_breakdown") or {}
    for v in (eb.get("score"), entry.get("edge_score"),
              entry.get("strict_score"), entry.get("legacy_edge_score")):
        try:
            if v is not None:
                return float(v)
        except (TypeError, ValueError):
            continue
    return 0.0


def _display_edge_score(entry):
    """Edge Score for DISPLAY ONLY (recaps / weekly reports). Returns the
    transparent score — the breakdown score, or a stored edge_score that is
    known-transparent (new-format entries also carry edge_grade/edge_breakdown).
    Legacy/manual entries that only have a bias-derived edge_score return "—" so
    the legacy number is never surfaced. Use _edge_score_for_entry (not this) for
    internal ranking, where a legacy fallback is acceptable to order old entries."""
    eb = entry.get("edge_breakdown") or {}
    if eb.get("score") is not None:
        return eb["score"]
    if entry.get("edge_grade") is not None and entry.get("edge_score") is not None:
        return entry["edge_score"]
    return "—"


def _entry_trade_strength(entry):
    """Trade strength for a stored entry: the explicit field if present, else
    derived from its Edge Score (only when ≥50, i.e. a qualified display tier)."""
    st = entry.get("trade_strength")
    if st in ("Possible Trade", "Strong Trade", "A+ Setup"):
        return st
    return _trade_strength_from_score(_edge_score_for_entry(entry))


def compute_edge_breakdown(a, entry):
    """Display Edge Score / Grade / Reasons / Risk for a setup.

    Computed from the SAME pure additive helper (compute_trade_edge_components)
    the READY gate uses, reading the confluences full_analysis() already produced,
    so the displayed Edge Score and the gate score can never diverge. Seven additive
    components (max 110): BOS (+20), CHOCH (+20), VWAP (+15), liquidity sweep (+15),
    volume (+15), CVD agreement (+15), preferred session (+10). Risk lines are
    INFORMATIONAL warnings only — they do NOT reduce the score. Hard blockers (zone
    broken / consumed) force the score to 0.

    Returns {"score": int, "grade": str,
             "score_breakdown": [{"label": str, "points": int}],
             "risk_adjustments": [{"label": str, "points": None}],
             "components": [{"key","label","points","present"}],
             "failed_confirmations": [str], "raw_score": int,
             "max_score": int, "cap_applied": bool,
             "reasons": [str], "risks": [str]}.  (reasons/risks kept for
    backward compatibility — they mirror the breakdown/risk labels.)
    """
    direction = entry.get("direction", "Long")
    is_long   = direction != "Short"
    conf      = a.get("confluences") or {}
    sess      = a.get("session") or get_session_state()

    has_sweep = bool(conf.get("liquidity_sweep") or conf.get("sweep") or a.get("liquidity_sweep"))
    # The seven additive components — same keys the READY gate scores in _signals,
    # so the displayed Edge Score equals the gate score. Structure is split into BOS
    # and CHOCH; volume is a first-class component (spike OR RVOL >= threshold,
    # resolved by the gate and stamped on the confluences / `a`).
    signals = {
        "bos_confirmed":     bool(conf.get("bos")),
        "choch_confirmed":   bool(conf.get("choch")),
        "vwap_confirmed":    bool(conf.get("vwap")),
        "liquidity_sweep":   has_sweep,
        "volume_confirmed":  bool(conf.get("volume_confirmed") or a.get("volume_confirmed")),
        # CVD agreement (+15) — the gate already resolved it per direction into the
        # confluences, so the displayed score matches the gate score exactly.
        "cvd_confirmed":     bool(conf.get("cvd_confirmed")),
        "preferred_session": bool(sess.get("preferred")),
    }
    # SOFT Edge modifiers (SCALP only) — the EXACT list the gate stamped for THIS
    # direction (entry.edge_modifiers), so the displayed Edge Score equals the gate
    # score. SWING stamps none → pure additive sum (byte-for-byte unchanged). The
    # modifiers reduce the final score but are NOT folded into raw_breakdown, so the
    # cap accounting below stays the additive-only positive total.
    modifiers = entry.get("edge_modifiers") or []
    score, raw_breakdown = compute_trade_edge_components(signals, modifiers)
    raw_score   = sum(it["points"] for it in raw_breakdown)
    cap_applied = raw_score > EDGE_SCORE_MAX

    # Direction-aware display labels for the generic component names.
    relabel = {
        "BOS Confirmed":     "Bullish BOS"        if is_long else "Bearish BOS",
        "CHOCH Confirmed":   "Bullish CHOCH"      if is_long else "Bearish CHOCH",
        "VWAP Confirmation": "VWAP Reclaim"       if is_long else "VWAP Rejection",
        "CVD Agreement":     "CVD Confirms Long"  if is_long else "CVD Confirms Short",
    }
    breakdown = [{"label": relabel.get(it["label"], it["label"]), "points": it["points"]}
                 for it in raw_breakdown]
    # Surface the SOFT modifier lines (negative) right after the positive components,
    # so the visible Score Breakdown sums to the displayed (gate) score.
    breakdown += [{"label": m["label"], "points": int(m["points"])}
                  for m in modifiers if m]

    # Per-setup diagnostics: EVERY component with its present/points, plus the list
    # of confirmations that did NOT fire. Lets the card / dashboard render the full
    # 7-component checklist uniformly (present and absent alike).
    components = [{"key": key, "label": relabel.get(label, label),
                  "points": pts, "present": bool(signals.get(key))}
                 for key, label, pts in EDGE_COMPONENTS]
    failed_confirmations = [relabel.get(label, label)
                            for key, label, pts in EDGE_COMPONENTS
                            if not signals.get(key)]

    # ── Risk lines — INFORMATIONAL warnings only; they do NOT reduce the Edge
    #    Score (the score is the pure additive sum above). Shown as bullet flags. ─
    risk_adj = []
    def _risk(label):
        risk_adj.append({"label": label, "points": None})

    risk_label = str(a.get("risk_label") or "")
    price = a.get("current_price")
    try:
        near_pct = float(cfg("NEAR_PCT"))
    except Exception:
        near_pct = 0.004
    near_opposite = False
    try:
        if price is not None:
            price = float(price)
            if is_long:
                sup = a.get("nearest_supply")
                near_opposite = sup is not None and 0 <= (float(sup) - price) <= price * near_pct * 1.5
            else:
                dem = a.get("nearest_demand")
                near_opposite = dem is not None and 0 <= (price - float(dem)) <= price * near_pct * 1.5
    except (TypeError, ValueError):
        near_opposite = False

    if is_long and (near_opposite or risk_label in ("Testing Supply", "Approaching Supply")):
        _risk("Nearby Resistance")
    if not is_long and (near_opposite or risk_label in ("Testing Demand", "Approaching Demand")):
        _risk("Nearby Support")
    if a.get("overextended") or risk_label == "Overextended":
        _risk("Overextended from level")
    if risk_label == "Choppy":
        _risk("Choppy conditions")
    # Volatility regime flags the card with an informational risk line. In SCALP a
    # BLOCK regime (Wild/Dead) now reaches here too (it no longer gates) — flag it.
    vol = a.get("volatility") or {}
    if vol.get("status") == "ok":
        _vreg = vol.get("regime")
        if _vreg == "HIGH_CAUTION":
            _risk("Elevated volatility")
        elif _vreg == "QUIET_CAUTION":
            _risk("Thin / quiet volatility")
        elif _vreg == "HIGH_BLOCK":
            _risk("Extreme volatility")
        elif _vreg == "QUIET_BLOCK":
            _risk("Dead / illiquid market")

    # Dedup by label, preserving first occurrence.
    def _dedup(items):
        seen, out = set(), []
        for it in items:
            if it["label"] in seen:
                continue
            seen.add(it["label"])
            out.append(it)
        return out
    breakdown = _dedup(breakdown)
    risk_adj  = _dedup(risk_adj)

    # Hard blockers override everything: a broken structure or a consumed
    # (mitigated-near) zone is not tradeable, so its Edge Score is 0 regardless of
    # any residual confluences still present in `a`. A single decisive risk line
    # explains the zero so the breakdown stays self-consistent.
    if cfg("GATE_REQUIRE_ZONE") and (a.get("zone_broken_active") or a.get("zone_mitigated_near")):
        blocker = ("Structure invalidated — zone broken"
                   if a.get("zone_broken_active") else "Zone consumed — invalid entry")
        breakdown = []
        risk_adj  = [{"label": blocker, "points": None}]
        score     = 0
        raw_score = 0
        cap_applied = False
        for c in components:
            c["present"] = False
        failed_confirmations = [c["label"] for c in components]

    return {
        "score": score,
        "grade": _grade_for_score(score),
        "score_breakdown": breakdown,
        "risk_adjustments": risk_adj,
        # Per-setup diagnostics: full component list + which confirmations failed,
        # and the honest raw-vs-clamped accounting (cap_applied is True only if the
        # additive sum actually exceeded EDGE_SCORE_MAX — with max 110 it never does).
        "components": components,
        "failed_confirmations": failed_confirmations,
        "raw_score": raw_score,
        "max_score": EDGE_SCORE_MAX,
        "cap_applied": cap_applied,
        # Backward-compatible plain-label lists (mirror the structured items).
        "reasons": [it["label"] for it in breakdown],
        "risks":   [it["label"] for it in risk_adj],
    }


def _analysis_edge_breakdown(a):
    """THE single Edge Score computation for a full_analysis() result `a`.

    Used by full_analysis (to attach the unified score) and reused by
    _build_card_entry, so the card, journal, /why, recaps and dashboard can never
    diverge. Direction follows the strict gate (or, for WAIT, the leading
    confluence direction) so the confluence-based signals line up with is_long
    inside compute_edge_breakdown."""
    conf = a.get("confluences") or {}
    tp   = a.get("trade_plan") or {}
    bias = a.get("bias")
    direction = (a.get("strict_direction") or conf.get("direction") or tp.get("direction")
                 or ("Long" if bias == "Bullish" else "Short" if bias == "Bearish" else "Long"))
    bos_s, choch_s, vwap_pos, sd_zone = build_structure_fields(a, direction)
    # Reuse the EXACT soft modifiers the gate stamped for the candidate direction so
    # the unified Edge Score matches the gate score (parity). SWING stamps none.
    _gd = a.get("gate_debug") or {}
    edge_entry = {
        "direction":          direction,
        "bos_status":         bos_s,
        "choch_status":       choch_s,
        "vwap_position":      vwap_pos,
        "supply_demand_zone": sd_zone,
        "strict_label":       a.get("strict_label"),
        "verdict":            a.get("verdict"),
        "edge_modifiers":     _gd.get("edge_modifiers") or [],
    }
    return compute_edge_breakdown(a, edge_entry)


def _render_edge_block_field(eb):
    """Render the transparent Edge Score / Grade / Score Breakdown / Risk
    Adjustments block as one embed field, with per-item point values."""
    score     = eb.get("score", 0)
    grade     = eb.get("grade", "—")
    breakdown = eb.get("score_breakdown")
    risk_adj  = eb.get("risk_adjustments")
    # Fallback for legacy/plain-label breakdowns that carry no points.
    if breakdown is None:
        breakdown = [{"label": r, "points": None} for r in (eb.get("reasons") or [])]
    if risk_adj is None:
        risk_adj = [{"label": r, "points": None} for r in (eb.get("risks") or [])]

    def _line(it):
        pts = it.get("points")
        if pts is None:
            return f"• {it['label']}"
        return f"{'+' if pts >= 0 else ''}{pts} {it['label']}"

    lines  = [f"**Edge Score: {score} / {EDGE_SCORE_MAX}**", f"**Grade: {grade}**", "", "**Score Breakdown:**"]
    lines += [_line(it) for it in breakdown] if breakdown else ["—"]
    lines += ["", "**Risk Adjustments:**"]
    lines += [_line(it) for it in risk_adj] if risk_adj else ["None"]
    return {"name": "⚡ Edge Score", "value": "\n".join(lines)[:1024], "inline": False}


def _outcome_state(outcome, pnl=None):
    """Map a journal outcome string (+optional pnl) to 'win'/'loss'/'breakeven'/None.

    'None' means still open (Pending / T1 Hit). A Win or Loss with ~zero realized
    P&L is reclassified as a breakeven (e.g. stop hit at break-even after T1)."""
    o  = str(outcome or "")
    ol = o.lower()
    if "breakeven" in ol or ol.strip() == "be" or ol.strip().startswith("be "):
        return "breakeven"
    if o.startswith("Win") or "win" in ol:
        st = "win"
    elif o.startswith("Loss") or "loss" in ol:
        st = "loss"
    else:
        return None
    try:
        if pnl is not None and abs(float(pnl)) < 1e-6:
            return "breakeven"
    except (TypeError, ValueError):
        pass
    return st


def _realized_r(entry, state):
    """Conservative realized-R proxy from the outcome (inferred, not exact)."""
    if state == "breakeven":
        return 0.0
    if state == "loss":
        return -1.0
    o = str(entry.get("outcome", "")).lower()
    try:
        rr = float(entry.get("rr"))
    except (TypeError, ValueError):
        rr = 2.0
    if "t1" in o and "t2" not in o:
        return 1.0
    return rr


def compute_performance_stats(entries=None):
    """Derive performance analytics from closed JOURNAL entries (in-memory only)."""
    entries = JOURNAL if entries is None else entries
    wins = losses = breakevens = 0
    gross_win = gross_loss = 0.0
    r_values = []
    cat = {c: {"win": 0, "loss": 0} for c in PERF_CATEGORIES}
    strength_keys = ("Possible Trade", "Strong Trade", "A+ Setup")
    strength = {k: {"win": 0, "loss": 0, "breakeven": 0,
                    "gross_win": 0.0, "gross_loss": 0.0, "r": []}
                for k in strength_keys}

    for e in entries:
        pnl   = e.get("pnl_dollars")
        state = _outcome_state(e.get("outcome"), pnl)
        if state is None:
            continue
        if state == "win":
            wins += 1
            if pnl is not None:
                gross_win += max(0.0, float(pnl))
        elif state == "loss":
            losses += 1
            if pnl is not None:
                gross_loss += abs(min(0.0, float(pnl)))
        else:
            breakevens += 1

        r_values.append(_realized_r(e, state))

        # Split by trade strength (Possible vs Strong).
        st = _entry_trade_strength(e)
        if st in strength:
            b = strength[st]
            if state == "win":
                b["win"] += 1
                if pnl is not None:
                    b["gross_win"] += max(0.0, float(pnl))
            elif state == "loss":
                b["loss"] += 1
                if pnl is not None:
                    b["gross_loss"] += abs(min(0.0, float(pnl)))
            else:
                b["breakeven"] += 1
            b["r"].append(_realized_r(e, state))

        if state in ("win", "loss"):
            for c in (e.get("setup_categories") or classify_setup_categories(e)):
                if c in cat:
                    cat[c][state] += 1

    decided = wins + losses
    win_rate = (wins / decided * 100.0) if decided else None
    profit_factor = (gross_win / gross_loss) if gross_loss > 0 else None
    avg_r = (sum(r_values) / len(r_values)) if r_values else None

    by_strength = {}
    for k, b in strength.items():
        dec = b["win"] + b["loss"]
        by_strength[k] = {
            "wins": b["win"], "losses": b["loss"], "breakevens": b["breakeven"],
            "decided": dec, "closed": dec + b["breakeven"],
            "win_rate": (b["win"] / dec * 100.0) if dec else None,
            "avg_r": (sum(b["r"]) / len(b["r"])) if b["r"] else None,
            "gross_win": round(b["gross_win"], 2), "gross_loss": round(b["gross_loss"], 2),
            "profit_factor": (b["gross_win"] / b["gross_loss"]) if b["gross_loss"] > 0 else None,
        }

    return {
        "wins": wins, "losses": losses, "breakevens": breakevens,
        "decided": decided, "closed": wins + losses + breakevens,
        "win_rate": win_rate,
        "gross_win": round(gross_win, 2), "gross_loss": round(gross_loss, 2),
        "profit_factor": profit_factor, "avg_r": avg_r,
        "categories": cat,
        "by_strength": by_strength,
    }


def post_performance_stats(reason=""):
    """Compute and post the performance-analytics embed to the journal channel."""
    if not DISCORD_JOURNAL_WEBHOOK_URL:
        return
    s = compute_performance_stats()
    if s["closed"] == 0:
        return
    wr   = f"{s['win_rate']:.0f}%" if s["win_rate"] is not None else "—"
    if s["profit_factor"] is not None:
        pf = f"{s['profit_factor']:.2f}"
    else:
        pf = "∞" if s["gross_win"] > 0 else "—"
    avgr = f"{s['avg_r']:+.2f}R" if s["avg_r"] is not None else "—"

    cat_lines = []
    for c in PERF_CATEGORIES:
        w, l = s["categories"][c]["win"], s["categories"][c]["loss"]
        if w + l > 0:
            cat_lines.append(f"{c}: {w}W / {l}L ({w / (w + l) * 100:.0f}%)")
    cat_text = "\n".join(cat_lines) or "No categorized results yet."

    def _fmt_strength(k):
        b = s.get("by_strength", {}).get(k)
        if not b or b.get("closed", 0) == 0:
            return f"{k}: —"
        wr_b = f"{b['win_rate']:.0f}%" if b.get("win_rate") is not None else "—"
        ar_b = f"{b['avg_r']:+.2f}R" if b.get("avg_r") is not None else "—"
        if b.get("profit_factor") is not None:
            pf_b = f"{b['profit_factor']:.2f}"
        else:
            pf_b = "∞" if b.get("gross_win", 0) > 0 else "—"
        return (f"**{k}**: {b['wins']}W / {b['losses']}L / {b['breakevens']}BE\n"
                f"WR {wr_b} · Avg {ar_b} · PF {pf_b}")
    strength_text = "\n".join(_fmt_strength(k) for k in ("Possible Trade", "Strong Trade", "A+ Setup"))

    embed = {
        "color":  0x5865F2,
        "author": {"name": f"{BOT_NAME} · Performance"},
        "title":  "📈 Performance Analytics",
        "description": reason or "Updated after a closed trade.",
        "fields": [
            {"name": "Wins ✅",        "value": str(s["wins"]),       "inline": True},
            {"name": "Losses ❌",      "value": str(s["losses"]),     "inline": True},
            {"name": "Breakeven ⚖️",   "value": str(s["breakevens"]), "inline": True},
            {"name": "Win Rate",       "value": wr,                   "inline": True},
            {"name": "Profit Factor",  "value": pf,                   "inline": True},
            {"name": "Avg R",          "value": avgr,                 "inline": True},
            {"name": "🎯 By Trade Strength", "value": strength_text[:1024], "inline": False},
            {"name": "📊 By Setup Type", "value": cat_text[:1024],    "inline": False},
        ],
        "footer": {"text": "Session stats · in-memory, resets on restart"},
    }
    try:
        requests.post(DISCORD_JOURNAL_WEBHOOK_URL, json={"embeds": [embed]}, timeout=5)
        logger.info("Performance stats posted: %dW/%dL/%dBE",
                    s["wins"], s["losses"], s["breakevens"])
    except Exception as exc:
        logger.warning("Performance stats post failed: %s", exc)


def _build_card_entry(a, ticker=None, record=None):
    """Build the trade-card dict (single source of truth for both the journal
    entry and the live alert card) from a full_analysis() result `a`.

    `record` (incoming webhook) preserves the exact ticker (e.g. "MNQ1!");
    `ticker` is used by the periodic loop where no webhook record exists.
    """
    record     = record or {}
    tp         = a.get("trade_plan") or {}
    direction  = a.get("strict_direction") or tp.get("direction") or "Long"
    inst       = (tp.get("instrument") or a.get("active_ticker")
                  or record.get("instrument")
                  or instrument_of(record.get("ticker") or ticker or record.get("alert_type", "")))
    # Preserve exact ticker (e.g. "MNQ1!") when supplied, else the normalized symbol.
    symbol     = record.get("ticker") or ticker or inst
    entry_zone = tp.get("entry_zone")

    # BOS / CHOCH levels from the most recent same-side structure alerts.
    lpt = a.get("last_price_by_type") or {}
    if direction == "Long":
        bos_level, choch_level = lpt.get("BOS DEMAND"), lpt.get("CHOCH DEMAND")
        bos_type,  choch_type  = "Demand", "Bullish"
    else:
        bos_level, choch_level = lpt.get("BOS SUPPLY"), lpt.get("CHOCH SUPPLY")
        bos_type,  choch_type  = "Supply", "Bearish"

    # Additive structure block + screenshot (grounded in `a` / webhook record).
    with _timed("aiNotesMs"):
        bos_status, choch_status, vwap_position, sd_zone = build_structure_fields(a, direction)
    with _timed("screenshotMs"):
        screenshot_url = extract_screenshot_url(record)

    entry = {
        "datetime":         datetime.now(timezone.utc).isoformat(),
        "symbol":           symbol,
        "instrument":       inst,
        "direction":        direction,
        "setup_stage":      a.get("setup_stage", "Trade Ready"),
        "strict_label":     a.get("strict_label", "WAIT"),
        "strict_score":     a.get("strict_score", 0),
        "verdict":          a.get("verdict", "WAIT"),
        "entry_zone":       entry_zone,
        "stop_loss":        tp.get("stop_loss"),
        "target1":          tp.get("target1"),
        "target2":          tp.get("target2"),
        "rr":               tp.get("rr"),
        # ── Additive trade-management plan (Feature 1) ──
        "target3":          tp.get("target3"),
        "be_level":         tp.get("be_level"),
        "partial_level":    tp.get("partial_level"),
        "runner_target":    tp.get("runner_target"),
        "risk_points":      tp.get("risk_points"),
        "reward_points":    tp.get("reward_points"),
        "rr_num":           tp.get("rr_num"),
        "max_invalidation": tp.get("max_invalidation"),
        "management_plan":  tp.get("management"),
        # ── Additive ATR dynamic-stop metadata (single source = the trade plan) ──
        "atr_pts":                   tp.get("atr_pts"),
        "atr_multiplier":            tp.get("atr_multiplier"),
        "atr_stop":                  tp.get("atr_stop"),
        "structure_stop":            tp.get("structure_stop"),
        "calculated_stop":           tp.get("calculated_stop"),
        "min_stop_ticks":            tp.get("min_stop_ticks"),
        "tick_size":                 tp.get("tick_size"),
        "stop_distance_ticks":       tp.get("stop_distance_ticks"),
        "risk_dollars_per_contract": tp.get("risk_dollars_per_contract"),
        "volatility_regime":         tp.get("volatility_regime"),
        "volatility_label":          tp.get("volatility_label"),
        "min_floor_applied":         tp.get("min_floor_applied"),
        "bos_type":         bos_type,
        "choch_type":       choch_type,
        "bos_level":        bos_level,
        "choch_level":      choch_level,
        "why_qualifies":    a.get("strict_reason") or a.get("why", "—"),
        "bias":             a.get("bias", "—"),
        "confidence":       f"{a.get('confidence', 0)}%",
        "edge_score":       a.get("edge_score", 0),
        "market_structure": a.get("structure_label", "—"),
        "risk_zone":        a.get("risk_label", "—"),
        "reasoning_chain":  a.get("reasoning_chain") or [],
        "why":              a.get("why", "—"),
        # ── Additive fields (do not remove; consumers use .get() defaults) ──
        "bos_status":         bos_status,
        "choch_status":       choch_status,
        "vwap_position":      vwap_position,
        "supply_demand_zone": sd_zone,
        "screenshot_url":     screenshot_url,
        "volatility":         a.get("volatility"),
    }
    entry["setup_categories"] = classify_setup_categories(entry)
    with _timed("aiNotesMs"):
        entry["setup_notes"]  = build_setup_notes(a, entry)
        entry["trade_thesis"] = build_trade_thesis(a, entry)
    # Session focus + next step, carried onto the card, /why and the journal so a
    # READY is always tagged with the window it fired in and what to do next.
    sess = a.get("session") or get_session_state()
    entry["session_preferred"] = bool(sess.get("preferred"))
    entry["session_bonus"]     = int(sess.get("bonus", 0))
    entry["session_window"]    = sess.get("window", "—")
    entry["next_step"]         = a.get("stage_next_step") or entry.get("why_qualifies") or "—"
    # Transparent Edge Score is the authoritative READY-trade score: it drives the
    # Possible/Strong strength label, the card/journal display, recap and analytics.
    # The legacy bias-derived edge score is preserved for backward compatibility.
    # Reuse the unified Edge Score computed once in full_analysis so the card,
    # journal, /why, recap and dashboard can never diverge; only recompute for a
    # bare/legacy `a` that never passed through full_analysis.
    eb = a.get("edge_breakdown") or compute_edge_breakdown(a, entry)
    entry["edge_breakdown"]    = eb
    entry["legacy_edge_score"] = a.get("legacy_edge_score", entry.get("edge_score", 0))
    entry["edge_score"]        = eb.get("score", entry.get("edge_score", 0))
    entry["edge_grade"]        = eb.get("grade")
    entry["score_breakdown"]   = eb.get("score_breakdown", [])
    entry["risk_adjustments"]  = eb.get("risk_adjustments", [])
    entry["trade_strength"]    = _trade_strength_from_score(entry["edge_score"]) or entry.get("strict_label")
    entry["a_plus"]            = (entry["trade_strength"] == "A+ Setup")
    # Conviction tier (score band) for the READY card label — reuse the value
    # full_analysis already computed; recompute only for a bare/legacy `a`.
    entry["conviction_tier"]   = a.get("conviction_tier") or _score_tier(entry["edge_score"])
    # Gate diagnostics + decision-support header — reuse the values full_analysis
    # already computed (recompute the header only for a bare/legacy `a`).
    entry["long_score"]            = a.get("long_score")
    entry["short_score"]           = a.get("short_score")
    entry["conflict_gap"]          = a.get("conflict_gap")
    entry["dominant_direction"]    = a.get("dominant_direction")
    entry["current_atr"]           = a.get("current_atr")
    entry["volatility_multiplier"] = a.get("volatility_multiplier")
    entry["ready_reason"]          = a.get("ready_reason") or a.get("strict_reason")
    entry["rejected_reasons"]      = a.get("rejected_reasons") or a.get("strict_missing")
    entry["alert_diagnostics"]     = a.get("alert_diagnostics")
    entry["decision_support"]      = a.get("decision_support") or _decision_support(entry)
    # Professional Review (display-only pre-READY pro grade) — carry the ACTIVE
    # model block onto the card entry so the live card / journal mirror the
    # dashboard. Defensive .get → absent on a bare/legacy `a` (field simply omitted).
    entry["pro_review"] = a.get("pro_review")
    # Trade Debate Engine (display-only Bull vs Bear vs Judge) — carry the block
    # onto the card entry so the live card / journal mirror the dashboard. Defensive
    # .get → absent on a bare/legacy `a` (field simply omitted).
    entry["trade_debate"] = a.get("trade_debate")
    # Learning Engine v2 (display-only): carry the Confidence Governor + Trade Memory
    # blocks onto the card entry so the live card / journal mirror the dashboard.
    # Defensive .get → absent on a bare/legacy `a` (field simply omitted).
    entry["confidence_governor"] = a.get("confidence_governor")
    entry["trade_memory"] = a.get("trade_memory")
    # SWING (flag-on) only: carry the P4-computed HTF context onto the entry so the
    # managed-trade register can build a per-trade thesis WITHOUT recomputing it
    # ("one read, many consumers"). Absent in SCALP / flag-off → entry byte-identical.
    if _swing_htf_enabled():
        entry["_swing_context"] = a.get("swing_context")
    return entry


def _build_why_explanation(entry):
    """Render a plain-language explanation of WHY a setup qualifies (Feature 6).

    Works off a card-entry dict (the same shape stored in LAST_READY_BY_TICKER
    and built by _build_card_entry), so it has one consistent input shape. Reads
    everything with .get so a partial/legacy entry can never crash the endpoint.
    Surfaces: direction, edge, strength, the 4 passed gate conditions, bonus
    confluences, risks, invalidation, and concrete improvements toward A+."""
    direction = entry.get("direction", "—")
    edge      = entry.get("edge_score", 0)
    strength  = (entry.get("trade_strength")
                 or _trade_strength_from_score(edge)
                 or entry.get("strict_label", "—"))
    grade     = entry.get("edge_grade", "—")
    is_long   = direction == "Long"

    breakdown   = entry.get("score_breakdown") or []
    risks       = entry.get("risk_adjustments") or []
    passed      = [it.get("label") for it in breakdown if it.get("label")]
    risk_labels = [it.get("label") for it in risks if it.get("label")]

    gate_set = {
        "BOS Demand" if is_long else "BOS Supply",
        "Bullish CHOCH" if is_long else "Bearish CHOCH",
        "Confirmation Candle",
        "VWAP Reclaim" if is_long else "VWAP Rejection",
    }
    gate_passed = [p for p in passed if p in gate_set]
    confluences = [p for p in passed if p not in gate_set]

    # Concrete paths toward an A+ (95+) score: missing bonus confluences and any
    # active risk adjustments to resolve. Only shown when not already A+.
    improvements = []
    if edge < 95:
        possible_bonus = [
            "Liquidity Sweep",
            "Confirmed Zone Reaction",
            "Demand Zone Active" if is_long else "Supply Zone Active",
            "Bullish Trend" if is_long else "Bearish Trend",
            "High Confidence",
        ]
        improvements += [f"Add confluence: {b}" for b in possible_bonus if b not in passed]
        improvements += [f"Resolve risk: {r}" for r in risk_labels]

    return {
        "direction":        direction,
        "edge_score":       edge,
        "edge_grade":       grade,
        "trade_strength":   strength,
        "verdict":          entry.get("verdict", entry.get("strict_label", "—")),
        "thesis":           entry.get("trade_thesis", "—"),
        "why_qualifies":    entry.get("why_qualifies", entry.get("why", "—")),
        "setup_notes":      entry.get("setup_notes", "—"),
        "session_preferred": entry.get("session_preferred"),
        "session_bonus":     entry.get("session_bonus"),
        "session_window":    entry.get("session_window"),
        "next_step":         entry.get("next_step", entry.get("stage_next_step", "—")),
        "passed_conditions": gate_passed,
        "confluences":      confluences,
        "risks":            risk_labels,
        "entry_zone":       entry.get("entry_zone"),
        "stop_loss":        entry.get("stop_loss"),
        "targets":          [entry.get("target1"), entry.get("target2"), entry.get("target3")],
        "invalidation":     entry.get("max_invalidation") or entry.get("invalidation") or "—",
        "improvements":     improvements,
    }


# ── Journal persistence (Postgres, fail-open) ────────────────────────────────
# The in-memory JOURNAL is the runtime source of truth; this MIRRORS it to
# Postgres so the day's setups + outcomes survive a restart/deploy. Without it,
# the in-memory journal is wiped on every restart and the manual EOD summary
# comes back blank. Every write is FAIL-OPEN — a DB error is logged and
# swallowed so journaling and the trade path are never affected. Reuses the
# learning-engine connection helper / DATABASE_URL. Display/analytics only:
# nothing here ever feeds the strict gate, sizing, or the money path.
JOURNAL_DB_READY = False


def _journal_dedup_key(entry):
    """Stable dedup key for a journal entry: (instrument, direction, zone_low).
    SINGLE SOURCE OF TRUTH shared by create_journal_entry and the DB reload so
    the two can never drift. Mirrors the original inline logic exactly (note the
    en-dash separator used by entry_zone)."""
    entry_zone = entry.get("entry_zone")
    try:
        zone_key = round(float(str(entry_zone).split("–")[0]), 0) if entry_zone else 0.0
    except (TypeError, ValueError):
        zone_key = 0.0
    return (instrument_of(entry.get("symbol", "")), entry.get("direction"), zone_key)


def _ensure_journal_key(entry):
    """Guarantee a stable unique journal_key (the DB primary key) on an entry.
    entry['id'] is positional and not stable across reload, so a uuid is used for
    persistence. Idempotent."""
    if entry is not None and not entry.get("journal_key"):
        entry["journal_key"] = uuid.uuid4().hex
    return entry


def _check_journal_db_ready():
    """Probe whether the journal_entries table is available and set
    JOURNAL_DB_READY accordingly. NO DDL — the table is created out-of-band
    (database tool in dev, Publish schema-diff in prod), matching the
    learning-engine convention of app-side INSERT/SELECT only. FAIL-OPEN: if the
    table is missing or the DB is unavailable, JOURNAL_DB_READY stays False and
    journaling falls back to in-memory only."""
    global JOURNAL_DB_READY
    if not LEARNING_DB_ENABLED:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM journal_entries LIMIT 1")
            cur.fetchone()
        JOURNAL_DB_READY = True
        logger.info("journal_entries table ready")
    except Exception as exc:
        logger.warning("journal table unavailable (persistence disabled): %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _persist_journal_entry(entry):
    """Upsert one journal entry by journal_key. FAIL-OPEN. The key is assigned
    SYNCHRONOUSLY (so the in-memory entry + DB row match), and a snapshot of the
    entry is captured before the DB write is offloaded to the slow-task worker —
    so a DB stall never delays a trade decision, and a later mutation of the same
    entry can't corrupt this write (the next persist call writes the new state)."""
    if not JOURNAL_DB_READY or not entry:
        return
    _ensure_journal_key(entry)
    key      = entry["journal_key"]
    snapshot = dict(entry)

    def _task():
        conn = _learning_conn()
        if conn is None:
            return
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO journal_entries (journal_key, entry)
                       VALUES (%s, %s)
                       ON CONFLICT (journal_key)
                       DO UPDATE SET entry = EXCLUDED.entry, updated_at = now()""",
                    (key, psycopg2.extras.Json(snapshot)),
                )
        except Exception as exc:
            logger.warning("journal persist failed: %s", exc)
        finally:
            try:
                conn.close()
            except Exception:
                pass

    _enqueue_slow(_task)


def _load_journal_from_db(limit=500):
    """Restore the in-memory JOURNAL from Postgres at boot (newest-first) and
    rebuild JOURNAL_KEYS via the shared dedup helper. FAIL-OPEN: on any error the
    journal stays empty and the app continues. Must run BEFORE the webhook worker
    starts so a reloaded setup still dedupes correctly."""
    global JOURNAL
    if not JOURNAL_DB_READY:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT entry FROM journal_entries
                   ORDER BY created_at DESC
                   LIMIT %s""",
                (int(limit),),
            )
            rows = cur.fetchall()
        loaded = [r[0] for r in rows if isinstance(r[0], dict)]
        JOURNAL = loaded
        JOURNAL_KEYS.clear()
        for e in JOURNAL:
            JOURNAL_KEYS.add(_journal_dedup_key(e))
        logger.info("Journal restored from DB: %d entr%s",
                    len(JOURNAL), "y" if len(JOURNAL) == 1 else "ies")
    except Exception as exc:
        logger.warning("journal load failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


# ── SWING thesis persistence (multi-day, restart-safe) ──────────────────────────
# Same convention as the journal / learning engine: app-side INSERT/SELECT ONLY,
# NO in-app DDL (the swing_theses table is created via the database tool in dev +
# the Publish schema-diff in prod). The persisted snapshot is DISPLAY / local-
# tracking ONLY — it NEVER feeds the strict gate, sizing, dedupe, or the
# /traderspost money path. FAIL-OPEN throughout.
SWING_THESIS_DB_READY = False


def _check_swing_thesis_db_ready():
    """Probe the swing_theses table (no DDL) and set SWING_THESIS_DB_READY. FAIL-OPEN:
    a missing table / unavailable DB disables SWING persistence (in-memory only)."""
    global SWING_THESIS_DB_READY
    if not LEARNING_DB_ENABLED:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM swing_theses LIMIT 1")
            cur.fetchone()
        SWING_THESIS_DB_READY = True
        logger.info("swing_theses table ready")
    except Exception as exc:
        logger.warning("swing_theses table unavailable (SWING persistence disabled): %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _swing_json_safe(obj):
    """Deep JSON-safe copy for a managed-trade snapshot: sets/tuples -> lists,
    non-finite floats -> None. (events_sent is a set; the managed-trade key is a
    tuple — both must be JSON-encodable for the JSONB payload.)"""
    if isinstance(obj, float):
        return obj if math.isfinite(obj) else None
    if isinstance(obj, dict):
        return {k: _swing_json_safe(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple, set)):
        return [_swing_json_safe(v) for v in obj]
    return obj


def _swing_mt_snapshot(mt):
    """Whitelisted, JSON-safe snapshot of a SWING managed trade for persistence.
    Captures levels, progress flags, MFE/MAE, events_sent, closed state and the
    thesis so the watcher + 15-min review fully rehydrate after a restart."""
    keys = (
        "key", "instrument", "direction", "symbol",
        "entry", "entry_lo", "entry_hi", "stop", "tp1", "tp2", "tp3",
        "be_level", "partial", "runner", "tp1_pct", "tp2_pct", "runner_pct",
        "risk_points", "point_value", "registered_at", "updates",
        "mfe", "mae", "be_active", "closed", "initial_stop",
        "remaining_pct", "realized_r", "tp1_hit", "tp2_hit", "runner_hit",
        "be_moved", "exit_reason", "trade_strength", "edge_score", "journal_id",
        "thesis_key", "swing_thesis", "is_swing",
        "swing_reduced", "swing_stop_moved", "swing_exit_advised",
        "auto_setup_key", "auto_exec_status", "auto_opened_at",
    )
    snap = {k: mt.get(k) for k in keys if k in mt}
    snap["events_sent"] = list(mt.get("events_sent") or [])
    return _swing_json_safe(snap)


def _persist_swing_thesis(mt):
    """Upsert a SWING managed trade's snapshot by thesis_key. FAIL-OPEN; the DB
    write is offloaded to the slow-task worker so a stall never delays trade
    management. The snapshot is captured synchronously (so a later mutation of the
    same trade can't corrupt this write)."""
    if not SWING_THESIS_DB_READY or not mt or not mt.get("thesis_key"):
        return
    key        = mt["thesis_key"]
    snapshot   = _swing_mt_snapshot(mt)
    status     = (mt.get("swing_thesis") or {}).get("status")
    closed     = bool(mt.get("closed"))
    instrument = mt.get("instrument")

    def _task():
        conn = _learning_conn()
        if conn is None:
            return
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO swing_theses (thesis_key, payload, status, closed, instrument)
                       VALUES (%s, %s, %s, %s, %s)
                       ON CONFLICT (thesis_key)
                       DO UPDATE SET payload    = EXCLUDED.payload,
                                     status     = EXCLUDED.status,
                                     closed     = EXCLUDED.closed,
                                     instrument = EXCLUDED.instrument,
                                     updated_at = now()""",
                    (key, psycopg2.extras.Json(snapshot), status, closed, instrument),
                )
        except Exception as exc:
            logger.warning("swing thesis persist failed: %s", exc)
        finally:
            try:
                conn.close()
            except Exception:
                pass

    _enqueue_slow(_task)


def _restore_swing_mt_snapshot(payload):
    """Rebuild an in-memory managed-trade dict from a persisted snapshot. events_sent
    back to a set, key back to a tuple. INERT: the caller inserts it straight into
    MANAGED_TRADES_BY_KEY without firing any alert / journal / broker side-effect."""
    if not isinstance(payload, dict):
        return None
    mt = dict(payload)
    mt["events_sent"] = set(mt.get("events_sent") or [])
    k = mt.get("key")
    if isinstance(k, list):
        mt["key"] = tuple(k)
    mt["source"]        = "postgres"
    mt["rehydrated_at"] = now_utc().isoformat()
    return mt


def _load_swing_theses_from_db():
    """Rehydrate OPEN SWING managed trades from Postgres at boot so multi-day holds
    survive a restart. SWING flag-on ONLY; runs BEFORE the webhook worker + watcher.
    FAIL-OPEN. INERT — directly populates MANAGED_TRADES_BY_KEY (never calls
    _register_managed_trade / send_live_ready_card / journal / broker)."""
    if not SWING_THESIS_DB_READY or not _swing_htf_enabled():
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT payload FROM swing_theses WHERE closed = FALSE ORDER BY updated_at DESC"
            )
            rows = cur.fetchall()
        restored = 0
        for (payload,) in rows:
            mt = _restore_swing_mt_snapshot(payload)
            if mt is None or not mt.get("key") or mt.get("closed") or not mt.get("is_swing"):
                continue
            MANAGED_TRADES_BY_KEY[mt["key"]] = mt
            restored += 1
        logger.info("SWING theses restored from DB: %d open", restored)
    except Exception as exc:
        logger.warning("swing thesis load failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


# ── Manual Trade Manager (ADVISORY / DISPLAY-ONLY) ──────────────────────────────
# The user enters a position they took MANUALLY in their own broker; the bot then
# MONITORS it and returns management guidance (live P&L / R, distance to stop &
# targets, thesis health, a HOLD / REDUCE / EXIT / MOVE-STOP recommendation,
# early-exit warnings, what-would-improve / -invalidate and the next review time).
#
# It is STRICTLY ADVISORY: it NEVER sends a broker order, never feeds the strict
# gate / scoring / sizing / dedupe / the /traderspost money path, and never opens or
# closes a tracked ACTIVE_TRADE. "Close" here only stops our local monitoring of the
# row. The existing money gateway can only OPEN a server-derived setup — it cannot
# flatten an arbitrary manual position — so no broker exit path exists by design.
#
# Persistence mirrors the journal / swing-thesis convention: app-side INSERT/SELECT
# (+ a status UPDATE on close) ONLY, NO in-app DDL — the manual_trades table is
# created out-of-band (database tool in dev, Publish schema-diff in prod). FAIL-OPEN
# throughout: when the table / DB is unavailable the manager runs in-memory only and
# a restart simply clears the (display-only) monitor.
MANUAL_TRADE_DB_READY = False
MANUAL_TRADES         = {}                       # id -> trade dict (open working set)
MANUAL_TRADES_LOCK    = threading.RLock()
MANUAL_TRADE_MODES    = ("SCALP", "SWING")


def _check_manual_trade_db_ready():
    """Probe the manual_trades table (no DDL) and set MANUAL_TRADE_DB_READY. FAIL-OPEN:
    a missing table / unavailable DB disables persistence (the monitor runs in-memory
    only)."""
    global MANUAL_TRADE_DB_READY
    if not LEARNING_DB_ENABLED:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM manual_trades LIMIT 1")
            cur.fetchone()
        MANUAL_TRADE_DB_READY = True
        logger.info("manual_trades table ready")
    except Exception as exc:
        logger.warning("manual_trades table unavailable (manual-trade persistence disabled): %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _persist_manual_trade(trade):
    """Upsert a manual trade snapshot by id. FAIL-OPEN; the DB write is offloaded to
    the slow-task worker so a stall never delays the dashboard. The snapshot is
    captured synchronously so a later mutation can't corrupt this write. DISPLAY /
    local-tracking ONLY — never the money path."""
    if not MANUAL_TRADE_DB_READY or not trade or not trade.get("id"):
        return
    tid        = trade["id"]
    snapshot   = {k: v for k, v in trade.items() if k not in ("min_r", "max_r")}
    status     = trade.get("status", "open")
    instrument = trade.get("symbol")

    def _task():
        conn = _learning_conn()
        if conn is None:
            return
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO manual_trades (id, payload, status, instrument)
                       VALUES (%s, %s, %s, %s)
                       ON CONFLICT (id)
                       DO UPDATE SET payload    = EXCLUDED.payload,
                                     status     = EXCLUDED.status,
                                     instrument = EXCLUDED.instrument,
                                     updated_at = now()""",
                    (tid, psycopg2.extras.Json(snapshot), status, instrument),
                )
        except Exception as exc:
            logger.warning("manual trade persist failed: %s", exc)
        finally:
            try:
                conn.close()
            except Exception:
                pass

    _enqueue_slow(_task)


def _load_manual_trades_from_db():
    """Rehydrate OPEN manual trades from Postgres at boot so the advisory monitor
    survives a restart. FAIL-OPEN; INERT — only repopulates the in-memory cache (no
    alert / journal / broker side-effect)."""
    if not MANUAL_TRADE_DB_READY:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT payload FROM manual_trades WHERE status = 'open' ORDER BY updated_at DESC")
            rows = cur.fetchall()
        restored = 0
        with MANUAL_TRADES_LOCK:
            for (payload,) in rows:
                if isinstance(payload, dict) and payload.get("id"):
                    MANUAL_TRADES[payload["id"]] = dict(payload)
                    restored += 1
        logger.info("Manual trades restored from DB: %d open", restored)
    except Exception as exc:
        logger.warning("manual trade load failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _manual_px(x):
    """Format a price / points value for advisory text (2dp); '—' when missing."""
    try:
        return "%.2f" % float(x)
    except (TypeError, ValueError):
        return "—"


def _manual_coerce_float(v):
    try:
        f = float(v)
        if math.isfinite(f):
            return f
    except (TypeError, ValueError):
        pass
    return None


def _parse_manual_entry_time(value):
    """Best-effort parse of a user-supplied entry time to a UTC ISO string. Accepts
    ISO-8601 (tz-aware or naive) or a datetime-local 'YYYY-MM-DDTHH:MM'. A naive value
    is treated as Eastern Time (the dashboard's display zone). Returns (iso|None, raw).
    DISPLAY-ONLY — the entry time never drives the gate or money path."""
    raw = "" if value is None else str(value).strip()
    if not raw:
        return None, ""
    try:
        dt = datetime.fromisoformat(raw)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=ET_TZ)
        return dt.astimezone(timezone.utc).isoformat(), raw
    except (ValueError, TypeError):
        return None, raw


def _build_manual_trade(data):
    """Strictly validate a manual-trade creation payload. Returns (trade, None) on
    success or (None, error_message). ADVISORY-ONLY input — never a money path, so
    these prices are stored for monitoring and are never sent to a broker."""
    symbol = _instrument_from_text(data.get("symbol"))
    if symbol is None:
        return None, "A valid symbol (MGC, MNQ, MES, or MYM) is required."

    draw = str(data.get("direction", "")).strip().lower()
    if draw.startswith("l"):
        direction = "Long"
    elif draw.startswith("s"):
        direction = "Short"
    else:
        return None, "Direction must be LONG or SHORT."

    entry = _manual_coerce_float(data.get("entry"))
    stop  = _manual_coerce_float(data.get("stop"))
    if entry is None or stop is None:
        return None, "Entry and stop must be valid numbers."
    if entry == stop:
        return None, "Entry and stop cannot be equal."

    t1 = _manual_coerce_float(data.get("target1"))
    t2 = _manual_coerce_float(data.get("target2"))
    if t1 is None or t2 is None:
        return None, "Target 1 and Target 2 must be valid numbers."
    t3 = _manual_coerce_float(data.get("target3"))   # optional

    contracts_raw = _manual_coerce_float(data.get("contracts", 1))
    if contracts_raw is None or contracts_raw != int(contracts_raw):
        return None, "Contracts must be a whole number."   # reject 1.5 etc. (int() would silently truncate)
    contracts = int(contracts_raw)
    if contracts < 1 or contracts > 1000:
        return None, "Contracts must be between 1 and 1000."

    mode = str(data.get("mode", "")).strip().upper()
    if mode not in MANUAL_TRADE_MODES:
        return None, "Mode must be SCALP or SWING."

    # Direction must agree with the stop & target placement (catches transposed inputs).
    if direction == "Long":
        if not (stop < entry):
            return None, "For a LONG, the stop must be below the entry."
        if not (t1 > entry and t2 > entry and (t3 is None or t3 > entry)):
            return None, "For a LONG, targets must be above the entry."
    else:
        if not (stop > entry):
            return None, "For a SHORT, the stop must be above the entry."
        if not (t1 < entry and t2 < entry and (t3 is None or t3 < entry)):
            return None, "For a SHORT, targets must be below the entry."

    entry_iso, entry_raw = _parse_manual_entry_time(data.get("entry_time"))
    reason = str(data.get("reason", "") or "").strip()[:500]

    return {
        "id":             "%s-%d-%s" % (symbol, int(time.time() * 1000), uuid.uuid4().hex[:6]),
        "symbol":         symbol,
        "direction":      direction,
        "entry_price":    entry,
        "stop_loss":      stop,
        "target1":        t1,
        "target2":        t2,
        "target3":        t3,
        "contracts":      contracts,
        "mode":           mode,
        "reason":         reason,
        "entry_time":     entry_iso,
        "entry_time_raw": entry_raw,
        "opened_at":      now_utc().isoformat(),
        "status":         "open",
    }, None


def _manual_next_review(mode, now=None):
    """Next advisory review time. SCALP reviews at the next 5-minute boundary; SWING on
    a ~30-minute cadence. DISPLAY-ONLY."""
    now  = now or now_utc()
    step = 5 if mode == "SCALP" else 30
    nxt  = now.replace(second=0, microsecond=0)
    minute = (now.minute // step + 1) * step
    if minute >= 60:
        nxt = (nxt + timedelta(hours=1)).replace(minute=minute - 60)
    else:
        nxt = nxt.replace(minute=minute)
    return nxt


def _stop_at_or_past_be(direction, stop, entry):
    """True when the stop is already at / beyond breakeven (entry)."""
    return (stop >= entry) if direction == "Long" else (stop <= entry)


def compute_manual_trade_management(trade, analysis=None):
    """ADVISORY-ONLY live management read for one manually-entered position.

    Reuses the existing read-only engines (full_analysis, compute_pnl,
    compute_distances) and NEVER mutates trading state, feeds the gate / sizing /
    dedupe, or sends a broker order. Degrades gracefully: a missing / stale price (or
    a zero-risk trade) yields a 'monitor unavailable' status rather than fabricated
    guidance. The only field it writes back on `trade` is the observed min_r / max_r
    (in-memory only) used for the honest 'poor entry but recovering' read."""
    symbol    = trade.get("symbol")
    direction = trade.get("direction", "Long")
    entry     = trade.get("entry_price")
    stop      = trade.get("stop_loss")
    mode      = trade.get("mode", "SCALP")
    is_long   = (direction == "Long")

    out = {
        "id":            trade.get("id"),
        "symbol":        symbol,
        "direction":     direction,
        "mode":          mode,
        "entry_price":   entry,
        "stop_loss":     stop,
        "target1":       trade.get("target1"),
        "target2":       trade.get("target2"),
        "target3":       trade.get("target3"),
        "contracts":     trade.get("contracts"),
        "reason":        trade.get("reason"),
        "entry_time":    trade.get("entry_time"),
        "entry_time_et": (fmt_et(trade.get("entry_time")) if trade.get("entry_time")
                          else (trade.get("entry_time_raw") or "")),
        "opened_at":     trade.get("opened_at"),
        "opened_at_et":  fmt_et(trade.get("opened_at")),
        "next_review_et": fmt_et(_manual_next_review(mode)),
        "warnings":         [],
        "what_improves":    [],
        "what_invalidates": [],
        "entry_assessment": None,
        "advisory_only":    True,
    }

    # Live analysis (read-only). The caller may pass a shared instance so full_analysis
    # is computed once per distinct symbol per poll and fanned out across its trades.
    if analysis is None:
        try:
            analysis = full_analysis(ticker_override=symbol)
        except Exception as exc:
            analysis = None
            logger.warning("manual-trade analysis failed for %s: %s", symbol, exc)
    a = analysis or {}

    # Current price (display source). No live price -> monitor unavailable.
    price = a.get("display_price")
    psrc  = a.get("price_source")
    if price is None:
        price, psrc = display_price_for(symbol)
    out["current_price"] = price
    out["price_source"]  = psrc

    risk = abs(entry - stop) if (entry is not None and stop is not None) else None
    if price is None or not risk:
        out["status"]                = "unavailable"
        out["thesis_status"]         = "UNKNOWN"
        out["recommendation"]        = "MONITOR"
        out["recommendation_reason"] = (
            f"No live price for {symbol} right now — monitoring paused (no guidance fabricated)."
            if price is None else "Entry and stop are equal — cannot compute risk."
        )
        return out

    out["status"] = "ok"

    # ── Live math (reuse the existing read-only helpers) ──
    pnl_trade = {"direction": direction, "entry_price": entry,
                 "contracts": trade.get("contracts", 1), "symbol": symbol}
    dollar_pnl, pts_pnl = compute_pnl(pnl_trade, price)
    fav       = (price - entry) if is_long else (entry - price)
    current_r = fav / risk
    out["unrealized_pnl"]    = round(dollar_pnl, 2)
    out["unrealized_points"] = round(pts_pnl, 2)
    out["current_r"]         = round(current_r, 2)
    out["risk_points"]       = round(risk, 2)

    dist_trade = {"direction": direction, "target1": trade.get("target1"),
                  "target2": trade.get("target2"), "stop_loss": stop}
    to_t1, to_t2, to_stop = compute_distances(dist_trade, price)
    out["dist_to_stop"]    = round(to_stop, 2)
    out["dist_to_target1"] = round(to_t1, 2)
    out["dist_to_target2"] = round(to_t2, 2)
    t3_val = trade.get("target3")
    if t3_val is not None:
        out["dist_to_target3"] = round((t3_val - price) if is_long else (price - t3_val), 2)

    # Track observed extremes (in-memory only) for the 'recovering' read.
    prev_min = trade.get("min_r")
    prev_max = trade.get("max_r")
    trade["min_r"] = current_r if prev_min is None else min(prev_min, current_r)
    trade["max_r"] = current_r if prev_max is None else max(prev_max, current_r)

    # Position vs stop / targets (inclusive — price can sit exactly on a level).
    stop_breached = (price <= stop) if is_long else (price >= stop)
    t1_hit = (price >= trade["target1"]) if is_long else (price <= trade["target1"])
    t2_hit = bool(trade.get("target2") is not None and
                  ((price >= trade["target2"]) if is_long else (price <= trade["target2"])))
    t3_hit = bool(t3_val is not None and
                  ((price >= t3_val) if is_long else (price <= t3_val)))
    out["stop_breached"] = stop_breached
    out["target1_hit"]   = t1_hit
    out["target2_hit"]   = t2_hit
    out["target3_hit"]   = t3_hit

    # ── Live signal reads (all defensive / None-safe) ──
    sc          = str(a.get("structure_class") or "").lower()
    vwap_value  = a.get("vwap_value")
    vwap_status = str(a.get("vwap_status") or "").lower()
    nearest_supply = a.get("nearest_supply")
    nearest_demand = a.get("nearest_demand")
    market_open = a.get("market_open")
    vol = a.get("volatility") or {}

    structure_bullish = ("bullish" in sc)            # Bullish Trend / Bullish Attempt
    structure_bearish = ("bearish" in sc)
    confirmed_trend   = sc in ("bullish trend", "bearish trend")
    # Only an opposite *confirmed* trend (CHOCH-level) is strong enough to invalidate;
    # an Attempt (BOS-only) or a bias flip alone merely weakens the thesis.
    opposite_confirmed = (confirmed_trend and
                          ((is_long and structure_bearish) or ((not is_long) and structure_bullish)))
    opposite_soft = (((is_long and structure_bearish) or ((not is_long) and structure_bullish))
                     and not opposite_confirmed)

    vwap_ok      = (vwap_status == "ok" and vwap_value is not None)
    vwap_against = bool(vwap_ok and ((price < vwap_value) if is_long else (price > vwap_value)))
    near_stop    = (not stop_breached) and (to_stop <= 0.25 * risk)

    # Opposing zone sitting between price and the first target (resistance ahead of a
    # long / support ahead of a short).
    zone_ahead = None
    tgt1 = trade.get("target1")
    if is_long and nearest_supply is not None and tgt1 is not None \
            and price < nearest_supply < tgt1:
        zone_ahead = nearest_supply
    if (not is_long) and nearest_demand is not None and tgt1 is not None \
            and tgt1 < nearest_demand < price:
        zone_ahead = nearest_demand

    # ── Thesis status ──
    if stop_breached or opposite_confirmed:
        thesis = "INVALID"
    elif (current_r < 0) or opposite_soft or vwap_against or near_stop or (zone_ahead is not None):
        thesis = "WEAKENING"
    else:
        thesis = "VALID"

    # ── Warnings ──
    warnings = []
    if stop_breached:
        warnings.append(f"Price has reached or passed your stop at {_manual_px(stop)}.")
    if opposite_confirmed:
        warnings.append(f"Market structure flipped against you ({a.get('structure_class') or 'opposite trend'}).")
    elif opposite_soft:
        warnings.append(f"Early structure pressure against your direction ({a.get('structure_class') or '—'}).")
    if vwap_against and not stop_breached:
        warnings.append(f"Price is on the wrong side of VWAP ({_manual_px(vwap_value)}) for a {'long' if is_long else 'short'}.")
    if near_stop:
        warnings.append(f"Price is within {_manual_px(to_stop)} pts of your stop.")
    if zone_ahead is not None:
        warnings.append(f"An opposing {'supply' if is_long else 'demand'} zone at {_manual_px(zone_ahead)} sits before your first target.")
    if vol.get("status") == "ok" and vol.get("blocked"):
        warnings.append(f"Volatility is elevated ({vol.get('label') or 'high'}) — expect wider swings than normal.")
    out["warnings"] = warnings

    # ── Recommendation ──
    if stop_breached:
        rec, why = "EXIT", f"Your stop at {_manual_px(stop)} has been hit — the trade is invalidated; exit per your plan."
    elif thesis == "INVALID":
        rec = "EXIT"
        why = ("Your thesis is broken but you're in profit — bank it rather than give it back."
               if dollar_pnl > 0 else
               "Your thesis is broken and the trade is offside — cut the loss.")
    elif t3_hit or t2_hit:
        rec, why = "REDUCE", "You've reached a deeper target — scale out and trail your stop to protect the win."
    elif t1_hit:
        rec, why = "MOVE STOP", f"First target reached — take partial profit and move your stop to breakeven ({_manual_px(entry)})."
    elif current_r >= 1.0 and not _stop_at_or_past_be(direction, stop, entry):
        rec, why = "MOVE STOP", f"You're up about {current_r:.1f}R — move your stop to breakeven ({_manual_px(entry)}) to make this risk-free."
    elif thesis == "WEAKENING":
        if near_stop or current_r <= -0.5:
            rec, why = "REDUCE", "Momentum is against you and price is pressing your stop — consider trimming risk."
        else:
            rec, why = "HOLD", "Thesis is weakening but your stop is intact — hold and watch the listed risks closely."
    else:
        rec = "HOLD"
        why = (f"Thesis intact and the trade is working ({current_r:.1f}R) — let it run toward your targets."
               if current_r > 0 else
               "Thesis intact — give the trade room to your stop; no action needed yet.")

    # Market closed: pause and extend the review to the next open — never invalidate
    # a held position just because the session is shut.
    if market_open is False:
        out["next_review_et"] = a.get("next_open") or out["next_review_et"]
        if not stop_breached:
            # A held position is PAUSED while the session is shut — never invalidated by
            # (often stale) closed-market structure. Only a real stop-out keeps INVALID/EXIT.
            rec, why = "HOLD", "Market is closed — monitoring paused; reassess at the next session open."
            thesis = "PAUSED"

    out["thesis_status"]         = thesis
    out["recommendation"]        = rec
    out["recommendation_reason"] = why

    # ── What would improve / invalidate the thesis ──
    improves, invalidates = [], []
    if is_long:
        if vwap_against:
            improves.append(f"Reclaim and hold above VWAP ({_manual_px(vwap_value)}).")
        improves.append("A bullish CHOCH / BOS confirming higher highs in your favor.")
        improves.append(f"Volume expansion driving price toward {_manual_px(tgt1)}.")
        invalidates.append(f"A decisive close below your stop at {_manual_px(stop)}.")
        invalidates.append("A confirmed bearish CHOCH (structure flips down).")
        if nearest_demand is not None:
            invalidates.append(f"Price accepting below the demand zone at {_manual_px(nearest_demand)}.")
    else:
        if vwap_against:
            improves.append(f"Lose and hold below VWAP ({_manual_px(vwap_value)}).")
        improves.append("A bearish CHOCH / BOS confirming lower lows in your favor.")
        improves.append(f"Volume expansion driving price toward {_manual_px(tgt1)}.")
        invalidates.append(f"A decisive close above your stop at {_manual_px(stop)}.")
        invalidates.append("A confirmed bullish CHOCH (structure flips up).")
        if nearest_supply is not None:
            invalidates.append(f"Price accepting above the supply zone at {_manual_px(nearest_supply)}.")
    out["what_improves"]    = improves
    out["what_invalidates"] = invalidates

    # ── Entry-quality read (honest, derived from observed action since monitoring) ──
    min_r = trade.get("min_r", current_r)
    recovering = (min_r <= -0.4 and current_r > min_r + 0.3 and current_r > -0.1)
    if recovering and current_r > 0:
        out["entry_assessment"] = (f"This trade went against you (low {min_r:.1f}R) and has recovered to "
                                   f"+{current_r:.1f}R — the entry was poorly timed; favor scaling out into "
                                   f"strength over expecting a clean runner.")
    elif recovering:
        out["entry_assessment"] = (f"Down to {min_r:.1f}R earlier, now {current_r:.1f}R and recovering — the "
                                   f"entry was early; manage risk tightly back toward breakeven.")
    elif current_r < 0:
        out["entry_assessment"] = (f"Currently offside at {current_r:.1f}R (worst {min_r:.1f}R). Hold only while "
                                   f"your stop and thesis are intact.")
    return out


def _bot_active_trade_monitor_items(analysis_cache):
    """ADVISORY DISPLAY mirror of the bot's own OPEN positions (ACTIVE_TRADES_BY_INST),
    rendered in the SAME shape as the manual monitor rows so a bot-executed order shows
    up in the Trade Monitor box automatically.

    READ-ONLY by construction: each row is built from a THROWAWAY copy of the tracked
    trade (compute_manual_trade_management may write min_r/max_r back onto the dict it is
    handed, so the live ACTIVE_TRADE object is never passed in), reuses the same read-only
    full_analysis cache, and feeds NO gate / journal / learning / broker / dedupe path. A
    row appears while the position is open and disappears on the next poll once the bot
    closes it (clear_active_trade) — no open/close hooks and no duplicate storage. The
    "Stop monitoring" control is hidden for these rows in the UI; even if its id were
    POSTed to /manual-trade/close it only pops from MANUAL_TRADES (a no-op here) and can
    never touch the real position. FAIL-OPEN: any error skips that instrument's mirror
    rather than breaking the monitor list."""
    items = []
    for inst, at in active_trade_snapshot().items():
        if not at:
            continue
        try:
            opened = at.get("opened_at") or ""
            mirror = {
                "id":          "bot-%s-%s" % (inst, opened or uuid.uuid4().hex[:8]),
                "symbol":      at.get("symbol") or inst,
                "direction":   at.get("direction", "Long"),
                "entry_price": at.get("entry_price"),
                "stop_loss":   at.get("stop_loss"),
                "target1":     at.get("target1"),
                "target2":     at.get("target2"),
                "target3":     at.get("target3"),
                "contracts":   at.get("contracts"),
                "mode":        at.get("mode") or TRADING_MODE,
                "reason":      "",
                "entry_time":  opened or None,
                "opened_at":   opened or now_utc().isoformat(),
                "status":      "open",
            }
            sym = mirror["symbol"]
            if sym not in analysis_cache:
                try:
                    analysis_cache[sym] = full_analysis(ticker_override=sym)
                except Exception as exc:
                    logger.warning("bot-monitor analysis failed for %s: %s", sym, exc)
                    analysis_cache[sym] = None
            row = compute_manual_trade_management(mirror, analysis=analysis_cache[sym])
            row["origin"]          = "bot"
            row["advisory_mirror"] = True
            items.append(row)
        except Exception as exc:
            logger.warning("bot-monitor mirror failed for %s: %s", inst, exc)
    return items


@app.route("/manual-trade", methods=["GET", "POST"])
def manual_trade():
    """ADVISORY-ONLY Manual Trade Manager. POST creates a monitored position; GET lists
    every open position with live guidance. Owner-only (auth enforced at the Express
    /api edge; NOT in dashboard-auth OPEN_PATHS). NEVER sends a broker order."""
    if request.method == "POST":
        data = request.get_json(force=True, silent=True) or {}
        trade, err = _build_manual_trade(data)
        if err:
            return jsonify({"status": "error", "reason": err}), 400
        with MANUAL_TRADES_LOCK:
            MANUAL_TRADES[trade["id"]] = trade
        _persist_manual_trade(trade)
        logger.info("Manual trade added (advisory-only): %s %s @ %.2f",
                    trade["symbol"], trade["direction"], trade["entry_price"])
        return jsonify({"status": "added", "id": trade["id"],
                        "trade": compute_manual_trade_management(trade)}), 200

    # GET — list open manual trades with live advisory guidance. full_analysis is
    # computed ONCE per distinct symbol then fanned out across that symbol's trades.
    analysis_cache = {}
    items = []
    with MANUAL_TRADES_LOCK:
        trades = list(MANUAL_TRADES.values())
        for t in trades:
            sym = t.get("symbol")
            if sym not in analysis_cache:
                try:
                    analysis_cache[sym] = full_analysis(ticker_override=sym)
                except Exception as exc:
                    logger.warning("manual-trade list analysis failed for %s: %s", sym, exc)
                    analysis_cache[sym] = None
            _row = compute_manual_trade_management(t, analysis=analysis_cache[sym])
            _row["origin"] = "manual"
            items.append(_row)
    # ADVISORY DISPLAY-ONLY: also surface the bot's own OPEN positions so an
    # auto-executed (or manually-entered) order shows up in this monitor box
    # automatically. Read-only mirror — never a second order, never journaled or
    # learned twice; it clears itself when the bot closes the position. FAIL-OPEN.
    try:
        items.extend(_bot_active_trade_monitor_items(analysis_cache))
    except Exception as exc:
        logger.warning("bot-monitor merge failed: %s", exc)
    items.sort(key=lambda x: x.get("opened_at") or "", reverse=True)
    return jsonify({"status": "ok", "trades": items,
                    "persisted": MANUAL_TRADE_DB_READY, "count": len(items)}), 200


@app.route("/manual-trade/close", methods=["POST"])
def manual_trade_close():
    """Stop monitoring a manual trade. ADVISORY-ONLY — this only removes the row from
    the local monitor (and marks it closed in our table); it NEVER sends a broker
    order or touches a tracked ACTIVE_TRADE."""
    data = request.get_json(force=True, silent=True) or {}
    tid  = str(data.get("id", "")).strip()
    if not tid:
        return jsonify({"status": "error", "reason": "A trade id is required."}), 400
    with MANUAL_TRADES_LOCK:
        trade = MANUAL_TRADES.pop(tid, None)
    if trade is None:
        return jsonify({"status": "error", "reason": "No open manual trade with that id."}), 404
    trade["status"]    = "closed"
    trade["closed_at"] = now_utc().isoformat()
    _persist_manual_trade(trade)
    logger.info("Manual trade monitoring stopped: %s", tid)
    return jsonify({"status": "closed", "id": tid}), 200


def create_journal_entry(record, a, sizing, post_discord=True):
    """Auto-journal every Possible/Strong Trade recommendation, skipping duplicates.

    post_discord=False stores the entry in-memory only and skips the (slow)
    journal-channel Discord embed, so the webhook worker can send the trade alert
    first and offload that embed to the slow-task worker."""
    global JOURNAL, JOURNAL_KEYS

    strict_label = a.get("strict_label", "WAIT")
    if strict_label not in ("Strong Trade", "Possible Trade"):
        return None

    entry      = _build_card_entry(a, record=record)
    ticker     = entry["symbol"]
    direction  = entry["direction"]
    entry_zone = entry["entry_zone"]

    # Dedup key: instrument + direction + entry-zone low rounded to nearest integer.
    dedup_key = _journal_dedup_key(entry)

    if dedup_key in JOURNAL_KEYS:
        logger.info("Journal dedup skip: %s %s @ %.0f", ticker, direction, dedup_key[2])
        return None

    with _timed("journalWriteMs"):
        JOURNAL_KEYS.add(dedup_key)

        entry["id"]      = len(JOURNAL) + 1
        entry["outcome"] = "Pending"
        # Chart screenshot: use a validated public URL when the alert carried one,
        # else keep the legacy placeholder string and continue (no failure).
        if entry.get("screenshot_url"):
            entry["screenshot"] = entry["screenshot_url"]
        else:
            entry["screenshot"] = "[ Screenshot placeholder — add URL or image link ]"
            logger.info("Screenshot unavailable for journal #%d — continuing", entry["id"])

        _ensure_journal_key(entry)
        JOURNAL.insert(0, entry)
        if len(JOURNAL) > 500:
            JOURNAL.pop()

    _persist_journal_entry(entry)  # fail-open Postgres mirror (off the decision worker)
    if post_discord:
        send_journal_discord_embed(entry)
    logger.info("Journal entry #%d created: %s %s %s @ %s",
                entry["id"], ticker, strict_label, direction, entry_zone)
    return entry


def active_trade_field(trade, current_price):
    """Return a single Discord embed field dict showing live trade status (v11)."""
    dollar_pnl, pts_pnl   = compute_pnl(trade, current_price)
    to_t1, to_t2, to_stop = compute_distances(trade, current_price)

    pnl_emoji = "🟢" if dollar_pnl >= 0 else "🔴"
    pnl_str   = f"+${dollar_pnl:,.0f}" if dollar_pnl >= 0 else f"-${abs(dollar_pnl):,.0f}"

    status = trade.get("status", "active")
    state_str = {
        "active":    "🟢  Stage 5 — Entered",
        "breakeven": "🟡  Stage 6 — T1 Hit (Breakeven Active)",
    }.get(status, "🟢  Stage 5 — Entered")

    if status == "active":
        next_action = f"Wait for T1 at `{trade['target1']:.1f}`"
    elif status == "breakeven":
        next_action = (f"Wait for T2 at `{trade['target2']:.1f}`  ·  "
                       f"Stop at breakeven `{trade['entry_price']:.1f}`")
    else:
        next_action = "—"

    value = (
        f"**State:** {state_str}\n"
        f"**Entry:** `{trade['entry_price']:.1f}`  ·  "
        f"**Current Price:** `{current_price:.1f}`\n"
        f"**PnL:** {pnl_emoji} {pnl_str} ({pts_pnl:+.1f} pts)\n"
        f"\n"
        f"**Distance to T1:** `{to_t1:.1f} pts`\n"
        f"**Distance to T2:** `{to_t2:.1f} pts`\n"
        f"**Distance to Stop:** `{to_stop:.1f} pts`\n"
        f"\n"
        f"**Next Action:** {next_action}"
    )

    return {"name": "📊  ACTIVE TRADE MANAGEMENT", "value": value, "inline": False}


# ENTER / CLOSE command alerts for every enabled instrument (registry-driven), so
# MES/MYM command alerts route to the command handler instead of falling through
# to scoring. Built from the same instrument list as the rest of the engine.
_COMMAND_TYPES = {f"{inst} {act}"
                  for inst in enabled_instruments()
                  for act in ("ENTER", "CLOSE")}
# Registry-driven so every enabled instrument's data-only VWAP push takes the fast
# inline ack path (the VWAP store is written synchronously above; no heavy scoring).
# MGC/MNQ membership is unchanged — this is the same set plus MES/MYM.
_DATA_ONLY_TYPES = _per_inst_alert_set("VWAP")


def _handle_command_alert(normalized, data, parsed_price, resolved_inst):
    """Execute ENTER / CLOSE trade commands sent via TradingView webhook.

    Returns a Flask Response to short-circuit the webhook handler, or None
    to fall through to normal alert scoring.
    """
    profile   = str(data.get("profile", DEFAULT_PROFILE))
    is_enter  = normalized.endswith("ENTER")

    # ── ENTER ─────────────────────────────────────────────────────────────
    if is_enter:
        # R:R multiple for the LOCAL tracked TP (Discord-only path). Defaults to 1:1;
        # the plan-sourced fill below lifts it from the authoritative plan so a truly-
        # ready Opening Range Breakout is tracked/announced at its sanctioned 1:4.
        _rr_mult  = 1.0
        _rr_label = "1:1"
        try:
            entry = float(data["entry"]) if data.get("entry") else None
            stop  = float(data["stop"])  if data.get("stop")  else None
            t1    = float(data["t1"])    if data.get("t1")    else None
            t2    = float(data["t2"])    if data.get("t2")    else None
        except (ValueError, TypeError) as exc:
            return jsonify({"status": "error", "reason": str(exc)}), 400

        # Fall back to current trade plan for any missing values
        if None in (entry, stop, t1, t2):
            a  = full_analysis(current_price_override=parsed_price, ticker_override=resolved_inst)
            tp = a["trade_plan"]
            if not tp.get("trade_plan") or not tp.get("entry_zone"):
                return jsonify({"status": "error",
                                "reason": "No ready setup to enter — fill in Entry / Stop / T1 / T2, or wait for a valid Long Ready / Short Ready setup."}), 400
            try:
                if entry is None:
                    zone = str(tp["entry_zone"])
                    if "–" in zone:
                        lo_s, hi_s = zone.split("–")
                        entry = (float(lo_s) + float(hi_s)) / 2
                    else:
                        entry = float(zone)
                if stop is None:
                    stop = float(tp["stop_loss"])
                if t1   is None:
                    t1   = float(tp["target1"])
                if t2   is None:
                    t2   = float(tp["target2"])
            except (ValueError, TypeError, KeyError) as exc:
                return jsonify({"status": "error", "reason": f"Missing trade plan params: {exc}"}), 400
            # Authoritative plan drives the tracked R:R (1:4 only for a truly-ready ORB).
            _rr_mult  = float(tp.get("rr_num", 1.0) or 1.0)
            _rr_label = str(tp.get("rr", "1:1") or "1:1")

        contracts = int(data.get("contracts", 1))
        symbol    = resolved_inst

        # The stop side is the ground truth for a bracket trade (stop below entry =
        # Long, above = Short). Resolve direction from the explicit field when given,
        # else infer it from the stop side; reject a payload whose stated direction
        # contradicts the stop placement. Without this an omitted direction defaults
        # Long, so a Short ENTER would put the 1:1 take-profit on the stop side while
        # announcing "(1:1)" and mis-tag ACTIVE_TRADE for the win/loss watcher.
        if entry == stop:
            return jsonify({"status": "error",
                            "reason": "Entry and stop are equal — cannot place a 1:1 trade."}), 400
        inferred = "Long" if stop < entry else "Short"
        _dir_raw = data.get("direction")
        if _dir_raw and str(_dir_raw)[0].lower() in ("l", "s") \
                and str(_dir_raw)[0].lower() != inferred[0].lower():
            return jsonify({"status": "error",
                            "reason": (f"Direction '{_dir_raw}' contradicts the stop placement "
                                       f"(stop {'below' if stop < entry else 'above'} entry = {inferred}).")}), 400
        direction = inferred

        # Re-derive the tracked take-profit FROM entry/stop at the plan's R:R multiple
        # (_rr_mult is 1.0 everywhere except a truly-ready Opening Range Breakout, which
        # the authoritative plan marks 1:4), rather than trusting client-supplied t1/t2
        # (deeper targets are retired). Keeps the tracked exit consistent with the plan.
        _risk = abs(entry - stop)
        t1 = (entry + _rr_mult * _risk) if direction == "Long" else (entry - _rr_mult * _risk)
        t2 = t1

        # Record the trade for local tracking (one slot per instrument).
        # set_active_trade() serialises the write on ACTIVE_TRADES_LOCK so two
        # concurrent ENTERs can't race on this instrument's record.
        _trade = {
            "direction":   direction,
            "entry_price": entry,
            "stop_loss":   stop,
            "target1":     t1,
            "target2":     t2,
            "contracts":   contracts,
            "profile":     profile,
            "symbol":      symbol,
            "opened_at":   now_utc().isoformat(),
            "t1_hit":      False,
            "t2_hit":      False,
            "status":      "active",
        }
        set_active_trade(symbol, _trade)
        content = (
            f"✅ **TRADE ENTERED — {direction.upper()}**\n"
            f"Entry `{entry:.2f}`  ·  Stop `{stop:.2f}`  ·  "
            f"TP `{t1:.2f}` ({_rr_label})  ·  Contracts `{contracts}`"
        )
        _url = _discord_url(normalized)
        if _url:
            try:
                requests.post(_url, json={"content": content}, timeout=5)
            except Exception:
                pass
        logger.info("ENTER command: %s %s @ %.1f", direction, profile, entry)
        return jsonify({"status": "entered", "trade": _trade}), 200

    # ── CLOSE (per-instrument) ────────────────────────────────────────────
    _at = active_trade_for(resolved_inst)
    if not _at:
        return jsonify({"status": "error", "reason": "No active trade to close."}), 400

    exit_price = parsed_price
    closed     = dict(_at)

    if exit_price is not None:
        dollar_pnl, _ = compute_pnl(_at, exit_price)
        pnl_str    = f"+${dollar_pnl:,.0f}" if dollar_pnl >= 0 else f"-${abs(dollar_pnl):,.0f}"
        content    = (
            f"🏁 **TRADE CLOSED**\n"
            f"{_at['direction']} @ `{_at['entry_price']:.1f}`  ·  "
            f"Exit `{exit_price:.1f}`  ·  PnL **{pnl_str}**"
        )
        outcome_str = (
            f"Win — Closed {pnl_str} ✅" if dollar_pnl >= 0
            else f"Loss — Closed {pnl_str} ❌"
        )
    else:
        dollar_pnl  = None
        content     = (
            f"🏁 **TRADE CLOSED**\n"
            f"{_at['direction']} @ `{_at['entry_price']:.1f}`"
        )
        outcome_str = "Closed Manually"

    clear_active_trade(resolved_inst, opened_at=_at.get("opened_at"))
    _update_journal_outcome(outcome_str, pnl_dollars=dollar_pnl, symbol=resolved_inst)

    _url = _discord_url(normalized)
    if _url:
        try:
            requests.post(_url, json={"content": content}, timeout=5)
        except Exception:
            pass
    logger.info("CLOSE command: %s", outcome_str)
    return jsonify({"status": "closed", "trade": closed}), 200


# ---------------------------------------------------------------------------
# Routes
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# Per-webhook gate diagnostics
# ---------------------------------------------------------------------------
# Every scored webhook produces a full PASS/FAIL breakdown of each READY gate so
# the operator can see EXACTLY why a setup is WAIT. Entries are kept in a ring
# buffer (viewable, owner-only, at /diagnostics) and mirrored best-effort to an
# on-disk log. Recording is fail-open — diagnostics must never crash the worker.
GATE_DIAGNOSTICS = deque(maxlen=400)
_DIAG_LOCK       = threading.Lock()
DIAG_LOG_PATH    = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                "gate_diagnostics.log")
# Cap the on-disk mirror so a write-on-every-webhook file can never grow without
# bound on a long-running VM. When the live file exceeds the cap it is rotated to
# a single ".1" backup, bounding total disk use to ~2× the cap. The /diagnostics
# ring buffer above is the owner-facing surface; the file is a best-effort mirror.
DIAG_LOG_MAX_BYTES = 2 * 1024 * 1024   # 2 MB per file (≈ a few thousand entries)


def _record_diagnostic(text):
    try:
        GATE_DIAGNOSTICS.append(text)
    except Exception:
        pass
    try:
        with _DIAG_LOCK:
            try:
                if os.path.getsize(DIAG_LOG_PATH) >= DIAG_LOG_MAX_BYTES:
                    os.replace(DIAG_LOG_PATH, DIAG_LOG_PATH + ".1")
            except FileNotFoundError:
                pass
            with open(DIAG_LOG_PATH, "a", encoding="utf-8") as fh:
                fh.write(text.rstrip("\n") + "\n\n")
    except Exception:
        pass


def _pf(flag):
    return "PASS" if flag else "FAIL"


def _vol_diag_summary(gd, vol):
    """One-line volatility status for the diagnostic header."""
    vol = vol or {}
    if gd.get("volatility_block"):
        return "BLOCK (holds setup at WAIT)"
    if vol.get("status") == "ok":
        return vol.get("decision") or "ok"
    return "unavailable (fail-open, no score effect)"


def _vol_diag_detail(vol):
    """Indented volatility fields for the diagnostic: currentATR, baselineATR,
    volatilityMultiplier, volatilityThreshold, volatilityDecision."""
    vol = vol or {}
    if vol.get("status") != "ok":
        return ["    (volatility reading unavailable - fail-open, no effect)"]

    def _n(x):
        try:
            return "%.2f" % float(x)
        except (TypeError, ValueError):
            return "—"
    adj = vol.get("score_adj", 0) or 0
    adj_str = ("+%d" % adj) if adj > 0 else ("%d" % adj)
    return [
        "    currentATR ........... %s pts" % _n(vol.get("atr_pts")),
        "    baselineATR .......... %s pts" % _n(vol.get("baseline_pts")),
        "    volatilityMultiplier . %sx" % _n(vol.get("ratio")),
        "    volatilityThreshold .. elevated >= %sx | extreme >= %sx" % (
            _n(vol.get("threshold_elevated")), _n(vol.get("threshold_extreme"))),
        "    volatilityDecision ... %s (Edge %s)" % (vol.get("label", "—"), adj_str),
    ]


def _stop_diag_lines(tp):
    """Human-readable ATR dynamic-stop breakdown for the owner-only /diagnostics
    text view. `tp` is a build_strict_trade_plan result dict; lines are emitted
    only when ATR stop metadata is present (additive / display-only — never used
    by the trade decision)."""
    tp = tp or {}

    def _n(x):
        if x is None:
            return "—"
        try:
            return "%g" % float(x)
        except (TypeError, ValueError):
            return str(x)
    return [
        "    currentATR ........... %s pts" % _n(tp.get("atr_pts")),
        "    atrMultiplier ........ %sx" % _n(tp.get("atr_multiplier")),
        "    nearestDemand ........ %s" % _n(tp.get("nearest_demand")),
        "    nearestSupply ........ %s" % _n(tp.get("nearest_supply")),
        "    structureStop ........ %s" % _n(tp.get("structure_stop")),
        "    atrStop .............. %s" % _n(tp.get("atr_stop")),
        "    minStopTicks ......... %s%s" % (
            _n(tp.get("min_stop_ticks")),
            " (FLOOR APPLIED)" if tp.get("min_floor_applied") else ""),
        "    finalStop ............ %s" % _n(tp.get("stop_loss")),
        "    stopDistanceTicks .... %s" % _n(tp.get("stop_distance_ticks")),
        "    riskPerContract ...... $%s" % _n(tp.get("risk_dollars_per_contract")),
        "    riskReward ........... %s" % _n(tp.get("rr")),
    ]


def format_gate_diagnostic(symbol, trigger, candidate, gd, verdict,
                           extra_blockers=None, vol=None):
    """Human-readable per-gate PASS/FAIL block for one scored webhook. `gd` is the
    candidate direction's gate_debug from evaluate_strict_setup (expanded above).
    Structure passes on ANY ONE of BOS/CHOCH/swing; the individual rows are shown
    for visibility while "Structure (any one)" + "Blocked by" reflect the real
    gate, so the breakdown never misreports the cause of a WAIT."""
    gd    = gd or {}
    side  = "Supply" if candidate == "Short" else "Demand"
    ready = is_actionable(verdict)
    cmp_  = "<" if candidate == "Short" else ">"
    fails = list(gd.get("failed_conditions") or [])
    for b in (extra_blockers or []):
        if b and b not in fails:
            fails.append(b)
    lines = [
        "──────── GATE DIAGNOSTIC ────────",
        "%s | %s | Trigger: %s" % (
            symbol, fmt_et(now_utc(), "%Y-%m-%d %H:%M:%S ET"), trigger),
        "Candidate direction: %s" % (candidate.upper() if candidate else "NONE"),
        "",
        "  BOS (%s) .............. %s" % (side, _pf(gd.get("bos"))),
        "  CHOCH (%s) ............ %s" % (side, _pf(gd.get("choch"))),
        "  Swing (HH/HL or LH/LL)  %s" % _pf(gd.get("swing")),
        "  Structure (any one) ... %s" % _pf(gd.get("structure_confirmed")),
        "  VWAP (price %s VWAP) ... %s" % (cmp_, _pf(gd.get("vwap_confirmed"))),
        "  %s zone present ...... %s" % (side, _pf(gd.get("zone_present"))),
        "  Zone Mitigated ........ %s" % _pf(gd.get("zone_mitigated")),
        "  Reaction (candle/sweep) %s" % _pf(gd.get("reaction")),
        "  Zone valid (mit+react)  %s" % _pf(gd.get("zone_valid")),
        "  Zone state ............ %s" % (gd.get("zoneState") or "—"),
        "  Zone valid (gate) ..... %s" % _pf(gd.get("zoneValid")),
        "  Trading Session (bonus) %s" % _pf(gd.get("session_pref")),
        "  Conflict .............. %s" % ("YES" if gd.get("conflicting_structure") else "no"),
        "  Volatility ............ %s" % _vol_diag_summary(gd, vol),
    ]
    lines.extend(_vol_diag_detail(vol))
    lines.extend([
        "  Edge Score ............ %d / %d" % (gd.get("edge_score", 0), gd.get("ready_threshold", EDGE_READY_THRESHOLD)),
        "",
        "  FINAL READY DECISION: %s" % ("PASS" if ready else "FAIL"),
    ])
    if ready:
        lines.append("  Result: %s" % verdict)
    else:
        lines.append("  Result: WAIT")
        lines.append("  Blocked by: %s" % (", ".join(fails) if fails else "confluence"))
    lines.append("──────── END DIAGNOSTIC ─────────")
    return "\n".join(lines)


def _record_eval_metrics(a, webhook_received_at, eval_started_at, eval_finished_at,
                         eval_duration_ms, alert_sent_at, instrument, tiered_sent=False,
                         trigger="webhook", signal_type=None, is_duplicate=False,
                         signal_cooldown_remaining_ms=None):
    """Append one per-evaluation timing + volatility record to EVAL_METRICS (the
    live Diagnostics page / /eval-metrics read this). Best-effort — it must never
    raise into the worker. Phase timings come from the thread-local accumulator
    populated by the _timed() blocks during this evaluation; a phase that did not
    run for this alert (e.g. no journal write on a WAIT) is left None.

    Also records the gate breakdown (edge / zone / confirmations / blockers), the
    tiered alert_level, and the alert-dispatch + cooldown context so the live
    Diagnostics page can show exactly why a setup did or did not alert."""
    t   = _eval_timing_get() or {}
    vol = (a or {}).get("volatility") or {}
    gd  = (a or {}).get("gate_debug") or {}
    total_delay = None
    if webhook_received_at is not None and alert_sent_at is not None:
        total_delay = round((alert_sent_at - webhook_received_at).total_seconds() * 1000.0, 3)

    # ── Alert dispatch + cooldown context (best-effort, for diagnostics) ─────────
    alert_level = (a or {}).get("alert_level")
    verdict     = (a or {}).get("verdict") or ""
    inst_key    = instrument_of(instrument) if instrument else None
    alert_sent  = bool(alert_sent_at) or bool(tiered_sent)
    # Which throttle governs this level: READY re-posts on TRADE_READY_INTERVAL vs
    # LAST_LIVE_CARD_AT; the early tiers (WATCH / ARMED / WATCH FOR ENTRY) on
    # WATCH_ARMED_COOLDOWN_SEC vs LAST_TIER_AT.
    last_alert_at, cooldown_ms = None, None
    if alert_level == "READY":
        last_alert_at = LAST_LIVE_CARD_AT.get(inst_key) if inst_key else None
        cooldown_ms   = trade_ready_interval() * 1000
    elif alert_level in ("WATCH", "ARMED", "WATCH FOR ENTRY"):
        last_alert_at = LAST_TIER_AT.get(inst_key) if inst_key else None
        cooldown_ms   = int(cfg("WATCH_ARMED_COOLDOWN_SEC")) * 1000
    cooldown_remaining_ms = None
    if last_alert_at is not None and cooldown_ms is not None:
        elapsed_ms = (datetime.now(timezone.utc) - last_alert_at).total_seconds() * 1000.0
        cooldown_remaining_ms = round(max(0.0, cooldown_ms - elapsed_ms), 1)
    suppressed = bool(alert_level and not alert_sent
                      and cooldown_remaining_ms is not None and cooldown_remaining_ms > 0)
    blockers = ", ".join(gd.get("failed_conditions") or [])
    if not blockers:
        blockers = "READY" if is_actionable(verdict) else "-"

    # ── EARLY pre-READY timing (additive diagnostics; never affects the gate) ────
    et_slot         = dict(EARLY_EVENT_TIMES.get(inst_key) or {}) if inst_key else {}
    early_at_iso    = et_slot.get("earlyAlertTime")
    event_start_iso = et_slot.get("eventStartTime")
    event_start_dt  = None
    if event_start_iso:
        try:
            event_start_dt = datetime.fromisoformat(event_start_iso)
        except (ValueError, TypeError):
            event_start_dt = None
    # LAST_READY_SENT_AT is per-instrument and persists across setups. Attribute a
    # READY send to THIS event row ONLY when the current verdict is READY, or the
    # recorded READY happened at/after this event's start — otherwise it's a stale
    # READY from an earlier setup and must not pair with a fresh event.
    ready_dt         = LAST_READY_SENT_AT.get(inst_key) if inst_key else None
    ready_is_current = bool(ready_dt) and (
        is_actionable(verdict)
        or (event_start_dt is not None and ready_dt >= event_start_dt))
    ready_at_iso    = ready_dt.isoformat() if ready_is_current else None
    first_alert_iso = early_at_iso or ready_at_iso   # EARLY if it fired, else READY
    alert_delay_seconds = None
    try:
        if event_start_iso and first_alert_iso:
            delay = (datetime.fromisoformat(first_alert_iso)
                     - datetime.fromisoformat(event_start_iso)).total_seconds()
            if delay >= 0:                       # guard against stale/negative pairs
                alert_delay_seconds = round(delay, 1)
    except (ValueError, TypeError):
        alert_delay_seconds = None
    # False when EARLY caught it first; True when the current verdict is the
    # candle-close READY with no EARLY preceding it; None otherwise (incl. later
    # WAIT re-evaluations after a prior READY, so a stale READY can't read as True).
    if early_at_iso:
        waited_for_candle_close = False
    elif is_actionable(verdict):
        waited_for_candle_close = True
    else:
        waited_for_candle_close = None

    # ── Direction / setup-type / decision + processing-latency aliases (additive,
    # for the per-row latency view). direction prefers the verdict side, then the
    # gate candidate; setupType is the inbound alert_type when known, else the
    # structural stage; totalLatencyMs is webhook->finished (full processing
    # latency) and falls back to the in-eval duration for heartbeat rows. ──
    _candidate = gd.get("candidate") or (a or {}).get("gate_candidate")
    if verdict.startswith("LONG"):
        direction = "Long"
    elif verdict.startswith("SHORT"):
        direction = "Short"
    elif _candidate in ("Long", "Short"):
        direction = _candidate
    else:
        direction = None
    setup_type = signal_type or (a or {}).get("setup_stage") or (a or {}).get("structure_class")
    _eval_tp = (a or {}).get("trade_plan") or {}
    if not isinstance(_eval_tp, dict):
        _eval_tp = {}
    if webhook_received_at is not None and eval_finished_at is not None:
        total_latency_ms = round((eval_finished_at - webhook_received_at).total_seconds() * 1000.0, 3)
    else:
        total_latency_ms = eval_duration_ms

    record = {
        "webhookReceivedAt":    webhook_received_at.isoformat() if webhook_received_at else None,
        "evaluationStartedAt":  eval_started_at.isoformat() if eval_started_at else None,
        "evaluationFinishedAt": eval_finished_at.isoformat() if eval_finished_at else None,
        "evaluationDurationMs": eval_duration_ms,
        "indicatorCalcMs":      t.get("indicatorCalcMs"),
        "volatilityCalcMs":     t.get("volatilityCalcMs"),
        "scoringMs":            t.get("scoringMs"),
        "aiNotesMs":            t.get("aiNotesMs"),
        "screenshotMs":         t.get("screenshotMs"),
        "journalWriteMs":       t.get("journalWriteMs"),
        "alertSentAt":          alert_sent_at.isoformat() if alert_sent_at else None,
        "totalAlertDelayMs":    total_delay,
        # ── Volatility reading used by this evaluation ──
        "currentATR":           vol.get("atr_pts"),
        "baselineATR":          vol.get("baseline_pts"),
        "volatilityMultiplier": vol.get("ratio"),
        "volatilityThreshold":  vol.get("threshold_extreme"),
        "volatilityDecision":   vol.get("decision"),
        # ── ATR dynamic-stop breakdown (single source = this eval's trade plan) ──
        "atrMultiplier":          _eval_tp.get("atr_multiplier"),
        "nearestDemand":          _eval_tp.get("nearest_demand"),
        "nearestSupply":          _eval_tp.get("nearest_supply"),
        "structureStop":          _eval_tp.get("structure_stop"),
        "atrStop":                _eval_tp.get("atr_stop"),
        "minStopTicks":           _eval_tp.get("min_stop_ticks"),
        "stopDistanceTicks":      _eval_tp.get("stop_distance_ticks"),
        "finalStop":              _eval_tp.get("stop_loss"),
        "riskDollarsPerContract": _eval_tp.get("risk_dollars_per_contract"),
        "riskReward":             _eval_tp.get("rr"),
        "minFloorApplied":        _eval_tp.get("min_floor_applied"),
        # ── Context ──
        "instrument":           instrument,
        "verdict":              (a or {}).get("verdict"),
        # ── Per-signal latency view (additive aliases) ──
        "direction":            direction,
        "setupType":            setup_type,
        "decision":             (a or {}).get("verdict"),
        "alertReceivedTime":    webhook_received_at.isoformat() if webhook_received_at else None,
        "processingStartTime":  eval_started_at.isoformat() if eval_started_at else None,
        "processingEndTime":    eval_finished_at.isoformat() if eval_finished_at else None,
        "totalLatencyMs":       total_latency_ms,
        "isDuplicate":          bool(is_duplicate),
        "signalCooldownRemainingMs": signal_cooldown_remaining_ms,
        # ── Gate / decision breakdown ──
        "alertLevel":           alert_level,
        "edgeScore":            gd.get("edge_score"),
        "edgeOk":               gd.get("edge_ok"),
        "zoneValid":            gd.get("zone_valid"),
        "confirmationsPassed":  gd.get("confirmations_passed"),
        "confirmationsNeeded":  gd.get("confirmations_needed"),
        "readyThreshold":       gd.get("ready_threshold"),
        "gateBlockers":         blockers,
        # ── Expanded WAIT diagnostics (additive; surfaced on the Diagnostics page) ──
        "trigger":              trigger,
        "vwapConfirmed":        gd.get("vwap_confirmed"),
        "structureConfirmed":   gd.get("structure_confirmed"),
        "candleConfirmed":      gd.get("candle_confirmed"),
        "liquidityConfirmed":   gd.get("liquidity_sweep"),
        "volatilityConfirmed":  (None if gd.get("volatility_block") is None
                                 else (not gd.get("volatility_block"))),
        "confidenceScore":      (a or {}).get("confidence"),
        "waitReason":           (a or {}).get("strict_reason") or (a or {}).get("reason"),
        # ── Alert dispatch + cooldown ──
        "alertSent":            alert_sent,
        "webhookSent":          bool(alert_sent_at),
        "tieredSent":           bool(tiered_sent),
        "lastAlertAt":          last_alert_at.isoformat() if last_alert_at else None,
        "cooldownMs":           cooldown_ms,
        "cooldownRemainingMs":  cooldown_remaining_ms,
        "suppressedByCooldown": suppressed,
        # ── EARLY pre-READY timing (additive) ──
        "eventStartTime":       event_start_iso,
        "sweepTime":            et_slot.get("sweepTime"),
        "chochTime":            et_slot.get("chochTime"),
        "displacementTime":     et_slot.get("displacementTime"),
        "earlyAlertTime":       early_at_iso,
        "readyAlertTime":       ready_at_iso,
        "alertDelaySeconds":    alert_delay_seconds,
        "waitedForCandleClose": waited_for_candle_close,
    }
    with EVAL_METRICS_LOCK:
        EVAL_METRICS.append(record)

    # ── Cumulative counters (separate lock; NEVER nested in EVAL_METRICS_LOCK) ──
    # Best-effort, like the rest of this function — counter math must never raise
    # into the worker / heartbeat loop.
    try:
        verdict_str = (a or {}).get("verdict") or ""
        is_ready    = is_actionable(verdict_str)
        if (a or {}).get("market_open") is False:
            # Market closed — evaluations are paused. Never tally a quiet tape as
            # an evaluation or a failed/rejected signal (the row is still recorded
            # above for diagnostics; only the counters are skipped).
            return
        with COUNTERS_LOCK:
            COUNTERS["evaluations_run"] += 1
            if alert_sent:
                COUNTERS["alerts_sent"] += 1
            # Webhook (non-duplicate) signal funnel: how many inbound signals
            # passed every filter (READY) vs were rejected (WAIT). Heartbeat
            # re-evals and duplicate repeats are excluded so this tracks real
            # inbound TradingView signals only.
            if trigger == "webhook" and not is_duplicate:
                if is_ready:
                    COUNTERS["signals_passed_filters"] += 1
                else:
                    COUNTERS["signals_rejected"] += 1
            # Count a fresh setup once per non-READY -> READY transition per
            # instrument (NOT on every heartbeat re-eval of a still-READY setup).
            prev_ready = _READY_STATE_BY_INST.get(inst_key, False)
            if is_ready and not prev_ready:
                COUNTERS["ready_setups_detected"] += 1
            if inst_key is not None:
                _READY_STATE_BY_INST[inst_key] = is_ready
            # Tally each failed gate on a WAIT verdict so the operator can see the
            # dominant reasons setups don't fire.
            if not is_ready:
                for _fc in (gd.get("failed_conditions") or []):
                    COUNTERS["wait_reasons_breakdown"][_fc] = \
                        COUNTERS["wait_reasons_breakdown"].get(_fc, 0) + 1
                # Canonical, broken-out rejection reasons (req 6). Scoped to genuine
                # inbound signals (webhook, non-duplicate) so this cleanly decomposes
                # the signals_rejected funnel bucket; duplicates are tallied as
                # cooldown_duplicate in the webhook() dedup path instead. Counted at
                # the CONDITION level (not just the active hard gate) so SCALP
                # confirmation gaps (vwap/structure/candle) are visible even when the
                # raw wait_reasons_breakdown lumps them into "confirmations(N<M)".
                # session_filter is deliberately NEVER bumped: the trading session is
                # a +10 bonus, never a gate, so it can never reject a setup.
                if trigger == "webhook" and not is_duplicate:
                    _rr = COUNTERS["rejection_reasons"]
                    def _bump_rr(_k):
                        _rr[_k] = _rr.get(_k, 0) + 1
                    if not gd.get("zone_valid"):
                        _bump_rr("zone_valid")
                    if gd.get("vwap_confirmed") is False:
                        _bump_rr("vwap_confirmed")
                    if gd.get("structure_confirmed") is False:
                        _bump_rr("structure_confirmed")
                    if gd.get("location_ok") is False:
                        _bump_rr("location")
                    # Volume FAIL-OPEN: only count when data is present but unconfirmed
                    # (volume_ok already encodes "confirmed OR no data" — a missing feed
                    # never rejects a setup, so it must never inflate this counter).
                    if not gd.get("volume_ok"):
                        _bump_rr("volume_unconfirmed")
                    if gd.get("cvd_conflict"):
                        _bump_rr("cvd_conflict")
                    if gd.get("volatility_block"):
                        _bump_rr("volatility_block")
                    if not gd.get("edge_ok"):
                        _bump_rr("edge_score_low")
                    if gd.get("conflicting_structure"):
                        _bump_rr("conflicting_structure")
    except Exception as exc:
        logger.error("Counter update failed (eval still recorded): %s", exc)


def _update_setup_state(inst, a, dispatched_ready=False, is_duplicate=False):
    """Derive a per-instrument setup lifecycle state AFTER an evaluation. Pure
    display/diagnostics — it is NEVER read by full_analysis or the gate, so it can
    never alter a READY/WAIT verdict. States: FORMING -> READY -> ACTIVE, plus
    INVALIDATED / EXPIRED. A READY->ACTIVE move requires a live READY card actually
    dispatched on THIS eval (dispatched_ready), not merely a READY verdict (so a
    heartbeat re-eval never promotes to ACTIVE). Live states are STICKY: a transient
    heartbeat/duplicate re-eval never downgrades them, so the 1-min TradingView
    repeats can't flap READY<->FORMING. A live state leaves only via an upgrade,
    INVALIDATED (zone broken/mitigated or an opposite-direction READY), or EXPIRED
    (held longer than SETUP_STATE_TTL_SEC)."""
    inst_key = instrument_of(inst) if inst else None
    if not inst_key:
        return
    a         = a or {}
    verdict   = a.get("verdict") or ""
    ready     = is_actionable(verdict)
    # Zone broken/mitigated INVALIDATES a live setup ONLY when the zone is a hard
    # gate (SWING). In SCALP the zone is demoted to a non-blocking signal, so a
    # consumed/broken zone never invalidates the (display-only) setup state — the
    # setup stays live exactly as the demoted gate scored it.
    invalid   = bool(cfg("GATE_REQUIRE_ZONE")
                     and (a.get("zone_broken_active") or a.get("zone_mitigated_near")))
    candidate = a.get("gate_candidate")
    if verdict.startswith("LONG"):
        cur_dir = "Long"
    elif verdict.startswith("SHORT"):
        cur_dir = "Short"
    elif candidate in ("Long", "Short"):
        cur_dir = candidate
    else:
        cur_dir = None
    now = now_utc()

    with STATE_LOCK:
        prev       = SETUP_STATE.get(inst_key) or {}
        prev_state = prev.get("state")
        prev_dir   = prev.get("direction")
        prev_since = prev.get("since_dt") or now
        live_prev  = prev_state in ("FORMING", "READY", "ACTIVE")
        opposite_ready = bool(ready and cur_dir and prev_dir and cur_dir != prev_dir)

        # A duplicate repeat of the SAME signal must never downgrade a live state —
        # it only refreshes liveness (it can still invalidate/expire below).
        if is_duplicate and live_prev and not invalid and not opposite_ready:
            base, base_dir = prev_state, prev_dir
        elif invalid or opposite_ready:
            base, base_dir = "INVALIDATED", (cur_dir if opposite_ready else prev_dir)
        elif ready:
            base     = "ACTIVE" if (dispatched_ready or prev_state == "ACTIVE") else "READY"
            base_dir = cur_dir or prev_dir
        elif cur_dir in ("Long", "Short"):
            base, base_dir = "FORMING", cur_dir
        else:
            base, base_dir = None, None

        # Stickiness: a live state is never downgraded by a transient re-eval. Only
        # an upgrade (higher rank), INVALIDATED, or EXPIRED can move it; a lower or
        # empty base is ignored while the prior live state still stands.
        _RANK = {"FORMING": 1, "READY": 2, "ACTIVE": 3}
        if live_prev and base != "INVALIDATED":
            if base in _RANK and prev_state in _RANK and _RANK[base] < _RANK[prev_state]:
                base, base_dir = prev_state, prev_dir
            elif base is None:
                base, base_dir = prev_state, prev_dir

        # since: reset when the state label changes; otherwise carry it forward.
        since_dt = now if base != prev_state else prev_since
        # Expiry: a live state held longer than the TTL ages out to EXPIRED.
        if (base in ("FORMING", "READY", "ACTIVE")
                and (now - since_dt).total_seconds() > SETUP_STATE_TTL_SEC):
            base, since_dt = "EXPIRED", now

        SETUP_STATE[inst_key] = {
            "state":          base,
            "direction":      base_dir,
            "since_dt":       since_dt,
            "since":          since_dt.isoformat(),
            "last_update_dt": now,
            "last_update":    now.isoformat(),
        }


def _process_webhook_alert(record, parsed_price, resolved_inst, normalized,
                           account_size, risk_pct, profile_name,
                           webhook_received_at=None, is_duplicate=False,
                           cooldown_remaining_ms=None):
    """Heavy webhook tail (analysis + journaling + Discord) run OFF the request
    thread so TradingView gets a fast ack and never times out. All state this job
    reads (ALERT_HISTORY, zone flags, CURRENT_PRICE/VWAP) is committed
    synchronously before the job is queued; the per-alert price is passed in
    explicitly so late processing still scores against the correct price.

    Ordering is latency-critical: the READY/WARN/WAIT decision (full_analysis) is
    scored and TIMED first, the trade alert is sent BEFORE any journaling, and the
    journal-channel embed is offloaded to the slow-task worker — so nothing slow
    ever delays the decision or the alert. Per-evaluation timings + the volatility
    reading are recorded to EVAL_METRICS for the Diagnostics page."""
    _eval_timing_begin()
    eval_started_at = now_utc()
    _eval_t0 = time.perf_counter()
    a = full_analysis(current_price_override=parsed_price, ticker_override=resolved_inst,
                      cooldown_active=is_duplicate)
    eval_finished_at = now_utc()
    eval_duration_ms = round((time.perf_counter() - _eval_t0) * 1000.0, 3)
    alert_sent_at = None
    tiered_sent   = False

    # ── Unconfirmed zone mitigation → consumed-zone notice, skip the trade
    # engine. A CONFIRMED bullish mitigation reaction sets zone_mitigated_near
    # False (handled as a LONG above) and falls through to the READY-card path.
    # ZONE-HARD-GATE ONLY (SWING): in SCALP the zone is a non-blocking signal
    # (GATE_REQUIRE_ZONE False), so a consumed zone must NOT short-circuit the
    # live dispatch — fall through to the normal scoring / READY-card path. ──
    if cfg("GATE_REQUIRE_ZONE") and a.get("zone_mitigated_near"):
        _mz_price = a.get("mitigated_zone_price")
        send_zone_mitigated_message(record, _mz_price)
        logger.info("Zone mitigated (unconfirmed) — %s — scoring skipped", normalized)
        _record_diagnostic(
            "%s | %s | Trigger: %s\nResult: WAIT\nBlocked by: zone_consumed "
            "(zone already reacted — scoring skipped)" % (
                resolved_inst, fmt_et(now_utc(), "%Y-%m-%d %H:%M:%S ET"), normalized))
        _record_eval_metrics(a, webhook_received_at, eval_started_at,
                             eval_finished_at, eval_duration_ms, alert_sent_at,
                             resolved_inst, tiered_sent=tiered_sent,
                             signal_type=normalized, is_duplicate=is_duplicate,
                             signal_cooldown_remaining_ms=cooldown_remaining_ms)
        try:
            _update_setup_state(resolved_inst, a, dispatched_ready=False,
                                is_duplicate=is_duplicate)
        except Exception as exc:
            logger.error("Setup-state update failed (zone-mitigated path): %s", exc)
        return

    # ── EARLY intrabar pre-READY alert (additive, fail-open). Fired HERE — before
    # the journal/READY-card path below — so an early, unconfirmed sweep+structure
    # heads-up precedes the confirmed READY in time. It never alters the verdict,
    # the journal, or managed trades. ──
    try:
        _maybe_dispatch_early_alert(a, record)
    except Exception as exc:
        logger.error("EARLY alert dispatch error: %s", exc)

    # ── SETUP BUILDING heads-up (additive, NON-actionable, SCALP only). Fired HERE
    # alongside the EARLY alert — purely informational, never alters the verdict,
    # the journal, or managed trades. Throttled per instrument. ──
    try:
        _maybe_send_setup_building_alert(a, record)
    except Exception as exc:
        logger.error("Setup-building alert dispatch error: %s", exc)

    # Reduced-conviction setups (BOS-only "Attempt" / EARLY tier) trade at smaller
    # size — applied to the contract COUNT (mode-aware; SWING stays full size).
    _size_mult = _setup_risk_mult(a.get("verdict", ""), a.get("structure_class"))
    sizing = calculate_position_sizing(a["trade_plan"], account_size, risk_pct, profile_name, size_mult=_size_mult)

    # ── Active trade: a WIN is booked the moment T1 is hit; stop = loss. ──
    # check_trade_events returns STOP_HIT exclusively, or one/both of T1/T2 — so
    # stop and targets never co-occur in one call. Stop takes precedence.
    _at = active_trade_for(resolved_inst)
    if _at and parsed_price is not None:
        events = check_trade_events(_at, parsed_price)
        if "STOP_HIT" in events:
            send_trade_event_message("STOP_HIT", _at, parsed_price)
            d_pnl, _ = compute_pnl(_at, parsed_price)
            _update_journal_outcome("Loss — Stop Hit ❌", pnl_dollars=d_pnl, symbol=resolved_inst)
            # SCALP re-entry: a stop-out re-arms this setup so AUTO can enter it
            # again the instant it is READY again (operator request). The WIN path
            # below intentionally does NOT re-arm (no immediate re-entry after a win
            # while READY lingers). SWING never populates AUTO_FIRED_KEYS, so this is
            # a no-op there — its money path is unchanged.
            if TRADING_MODE == "SCALP":
                _stopped_key = _at.get("auto_setup_key")
                if _stopped_key is not None:
                    with AUTO_TRADE_LOCK:
                        AUTO_FIRED_KEYS.discard(_stopped_key)
            # Per-asset post-LOSS cooldown (0s default => no-op for MGC/MNQ). Set
            # OUTSIDE AUTO_TRADE_LOCK (SAFETY_LOCK must never nest under it).
            _set_outcome_cooldown(resolved_inst, cooldown_after_loss(resolved_inst), "loss")
            clear_active_trade(resolved_inst, opened_at=_at.get("opened_at"))
        elif "T1_HIT" in events or "T2_HIT" in events:
            send_trade_event_message("T1_HIT", _at, parsed_price)
            d_pnl, _ = compute_pnl(_at, parsed_price)
            _update_journal_outcome("Win — T1 Hit ✅", pnl_dollars=d_pnl, symbol=resolved_inst)
            # Per-asset post-WIN cooldown (0s default => no-op for MGC/MNQ).
            _set_outcome_cooldown(resolved_inst, cooldown_after_win(resolved_inst), "win")
            clear_active_trade(resolved_inst, opened_at=_at.get("opened_at"))

    # ── Trading Journal + live alert ───────────────────────────────────────────
    # The main alert channel now receives the same clean trade-card as the
    # journal, but ONLY when a brand-new setup is READY. create_journal_entry()
    # returns the entry just once per setup (deduped), so this fires the instant
    # alert exactly once on the triggering webhook; _trade_ready_loop() then
    # re-posts the card every 5 min while the setup stays READY.
    # Fail-open: journaling/enrichment + the live card must never crash the worker.
    # Dedup + build the card + store the journal IN-MEMORY only (fast). A failure
    # here must not crash the worker or block the alert below.
    try:
        journal_entry = create_journal_entry(record, a, sizing, post_discord=False)
    except Exception as exc:
        journal_entry = None
        logger.error("Journal build/store error (alert still attempted): %s", exc)

    # Trade alert FIRST — the instant a brand-new setup is READY, BEFORE any
    # Discord journal post, so the alert is never queued behind slower work. Its
    # error handling is isolated so a live-card failure can't suppress the journal
    # embed offloaded below.
    if (journal_entry and not active_trade_for(resolved_inst)
            and is_actionable(a.get("verdict"))):
        try:
            _dispatched = send_live_ready_card(journal_entry,
                                 record.get("ticker") or record.get("instrument")
                                 or journal_entry.get("instrument"),
                                 notify=True)
            # Stamp the alert time ONLY when a Discord card was actually sent, so a
            # muted instrument never inflates alert_sent_at / the alerts_sent counter
            # / the READY->ACTIVE setup-state transition (it is still evaluated and
            # journaled above — just silent on Discord).
            if _dispatched:
                alert_sent_at = now_utc()
        except Exception as exc:
            logger.error("Live-card send error (alert path): %s", exc)

    # -- Auto-trade (hands-free execution; additive + fail-open) --------------
    # AUTO enters on the FIRST ACTIONABLE READY — EARLY tier (Edge 50-59) included
    # and intentionally half-sized (RISK_MULT_EARLY, floored at 1 contract) — routed
    # through the SAME audited gateway as the manual button. Never raises into the
    # webhook worker.
    #
    # SCALP timing fix: the auto trigger must NOT be gated on the journal dedup.
    # A SCALP setup routinely fires EARLY READY first — which claims the journal
    # dedup slot — then strengthens to FULL READY a bar or two later. The old
    # `journal_entry and ...` guard skipped auto on that journal-deduped event,
    # delaying the entry by minutes (or missing it until the setup re-formed).
    # Triggering on the LIVE actionable verdict, independent of the journal, fires
    # auto the instant the setup becomes actionable. EARLY tier now auto-fires too
    # (half-size); AUTO_FIRED_KEYS keys on (instrument, direction, zone_low) — which
    # is identical for the EARLY and the later FULL READY of the same zone — so the
    # setup still enters exactly once (at the EARLY point) and never double-enters.
    # AUTO_FIRED_KEYS keeps a per-setup "one entry per READY event" throttle so a
    # continuously-READY setup can't machine-gun the daily cap in minutes; the key
    # is recorded only on a CONFIRMED entry (a transient gateway failure retries on
    # the next webhook). Operator change: a live position no longer blocks a new auto
    # entry (the `not ACTIVE_TRADE` precondition is gone and _maybe_auto_execute is
    # called with allow_stack=True), so distinct setups (new zones) and post-stop-out
    # re-entries can open concurrently — bounded only by the per-day cap. A STOP-OUT
    # re-arms the stopped setup (see the STOP_HIT handler) so it re-enters the instant
    # it is READY again; a WIN intentionally does NOT re-arm.
    # SWING is unchanged: it never emits EARLY and keeps the original journal-gated,
    # one-position condition (allow_stack defaults False), so its money path stays
    # byte-for-byte identical.
    if TRADING_MODE == "SCALP":
        # When the dual-TF engine is ON it OWNS SCALP auto-execution (fired from the
        # dual_tf_entry worker job via the 1m-bias + 5s-convergence rule), so the legacy
        # Edge-verdict SCALP auto trigger is disabled here to avoid a double entry.
        # Flag OFF => this condition is byte-identical to before.
        if (not DUAL_TF_ENGINE
                and is_actionable(a.get("verdict"))
                and auto_trade_enabled(resolved_inst)):
            _setup_key = _auto_setup_key(a, resolved_inst)
            with AUTO_TRADE_LOCK:
                _already_fired = _setup_key in AUTO_FIRED_KEYS
            if not _already_fired:
                try:
                    if _maybe_auto_execute(resolved_inst, allow_stack=True,
                                           setup_key=_setup_key):
                        with AUTO_TRADE_LOCK:
                            AUTO_FIRED_KEYS.add(_setup_key)
                except Exception as exc:
                    logger.error("Auto-trade dispatch error (non-fatal): %s", exc)
    else:
        if (journal_entry and not active_trade_for(resolved_inst)
                and is_actionable(a.get("verdict"))
                and auto_trade_enabled(resolved_inst)):
            try:
                _maybe_auto_execute(resolved_inst)
            except Exception as exc:
                logger.error("Auto-trade dispatch error (non-fatal): %s", exc)

    # -- Fast Entry early-entry money path (SCALP-only; additive + fail-open) ---
    # Self-guards to a no-op unless FAST_ENTRY_MONEY + FAST_ENTRY_TRIGGER + SCALP +
    # NOT DUAL_TF (via _fast_entry_money_enabled), so with the flags OFF this whole
    # block never runs and the money path is byte-identical. It fires ONLY when the
    # legacy Edge auto did NOT (strict verdict is WAIT) but the seconds layer permits
    # an early entry on an aligned, nearly-valid HTF setup. The fire-once key is built
    # to MATCH the key the later FULL-READY legacy auto would mint
    # (instrument, direction, zone_low) so a fast early entry CLAIMS the setup and the
    # HTF-READY block never double-enters the same zone. Routed through the SAME
    # audited gateway (source="fast_entry"); ALL money safety (risk cap, daily cap,
    # market/session, dedupe, confirmed-send-only) is shared there. DUAL_TF is
    # mutually exclusive (its own engine owns auto), so the two seconds engines can
    # never double-fire.
    if (_fast_entry_money_enabled()
            and not is_actionable(a.get("verdict"))
            and auto_trade_enabled(resolved_inst)):
        _fe = a.get("fast_entry") or {}
        _fe_dir = _fe.get("direction")
        if _fe.get("early_entry_allowed") and _fe_dir in ("Long", "Short"):
            try:
                _fz = str((a.get("trade_plan") or {}).get("entry_zone", ""))
                _fz_low = round(float(_fz.split("–")[0]), 0) if _fz else 0.0
            except (TypeError, ValueError):
                _fz_low = 0.0
            _fe_key = (instrument_of(resolved_inst), _fe_dir, _fz_low)
            with AUTO_TRADE_LOCK:
                _fe_already = _fe_key in AUTO_FIRED_KEYS
            if not _fe_already:
                try:
                    if _maybe_auto_execute(resolved_inst, allow_stack=True,
                                           setup_key=_fe_key, source="fast_entry"):
                        with AUTO_TRADE_LOCK:
                            AUTO_FIRED_KEYS.add(_fe_key)
                except Exception as exc:
                    logger.error("Fast-entry auto-execute error (non-fatal): %s", exc)

    # Tiered WATCH/ARMED early alert (SCALP only). Mutually exclusive with the READY
    # card above (alert_level is READY vs WATCH/ARMED) and throttled per instrument.
    # The throttle state is recorded synchronously but the Discord POST is offloaded
    # to the slow-task worker, so it can never delay the READY card, the journal
    # enqueue below, or the next webhook evaluation. Fail-open.
    try:
        tiered_sent = _maybe_send_tiered_alert(a, record)
    except Exception as exc:
        logger.error("Tiered alert dispatch error: %s", exc)

    # Offload the journal-channel embed (the only slow piece left here), regardless
    # of the live-card outcome, so the decision worker is free immediately.
    if journal_entry:
        _enqueue_slow(lambda e=journal_entry: send_journal_discord_embed(e))

    _gd = a.get("gate_debug") or {}
    if is_actionable(a["verdict"]):
        _gate_str = "READY"
    elif _gd.get("conflicting_structure"):
        _gate_str = "conflict"
    else:
        _gate_str = "zone=%s vwap=%s struct=%s edge=%d%s" % (
            # SWING (require_zone) logs zone as the strict Y/N gate value; SCALP logs
            # the zone STATE (Fresh/Tested/Consumed/None) since zone no longer gates.
            (("Y" if _gd.get("zone_valid") else "N") if _gd.get("require_zone")
                else (_gd.get("zoneState") or "—")),
            "Y" if _gd.get("vwap_confirmed") else "N",
            "Y" if _gd.get("structure_confirmed") else "N",
            _gd.get("edge_score", 0),
            "" if _gd.get("edge_ok") else ("<%d" % _gd.get("ready_threshold", EDGE_READY_THRESHOLD)),
        )
        _vol = a.get("volatility") or {}
        if _gd.get("volatility_block"):
            _gate_str += " vol=BLOCK"
        elif _vol.get("status") == "ok" and _vol.get("score_adj"):
            _gate_str += " volAdj=%+d" % _vol.get("score_adj")
    logger.info(
        "Alert: %s | %s (%d/10) | %d%% | Edge %d | %s → %s | Struct: %s | Risk: %s | Gate: %s",
        normalized, a["bias"], a["strength"], a["confidence"], a["edge_score"],
        a["recommendation"], a["verdict"], a["structure_class"], a["risk_label"], _gate_str,
    )

    # ── Full per-gate diagnostic — logged AND persisted to the owner-viewable
    # /diagnostics buffer so it's clear EXACTLY which gate holds a setup at WAIT.
    # Hard blockers applied after the gate (zone broken) are surfaced explicitly
    # since gate_debug itself is not recomputed by those overrides. ──
    _extra = []
    if a.get("zone_broken_active"):
        _extra.append("zone_broken")
    _candidate = a.get("gate_candidate") or ready_direction(a.get("verdict"))
    try:
        _diag = format_gate_diagnostic(resolved_inst, normalized, _candidate, _gd,
                                       a["verdict"], extra_blockers=_extra,
                                       vol=a.get("volatility"))
        _tp_diag = a.get("trade_plan")
        if isinstance(_tp_diag, dict) and _tp_diag.get("atr_pts") is not None:
            _diag += "\n  ATR dynamic stop —\n" + "\n".join(_stop_diag_lines(_tp_diag))
        logger.info("Gate diagnostic —\n%s", _diag)
        _record_diagnostic(_diag)
    except Exception as exc:
        logger.error("Gate diagnostic formatting failed (alert still recorded): %s", exc)

    _record_eval_metrics(a, webhook_received_at, eval_started_at,
                         eval_finished_at, eval_duration_ms, alert_sent_at,
                         resolved_inst, tiered_sent=tiered_sent,
                         signal_type=normalized, is_duplicate=is_duplicate,
                         signal_cooldown_remaining_ms=cooldown_remaining_ms)

    # ── Structured per-webhook latency line (additive diagnostics) ──────────────
    try:
        logger.info(
            "Webhook latency | sym=%s dir=%s setup=%s decision=%s dup=%s "
            "alertReceivedTime=%s processingStartTime=%s processingEndTime=%s "
            "evalMs=%s totalMs=%s",
            resolved_inst, (a.get("gate_candidate") or "-"), normalized,
            a.get("verdict"), is_duplicate,
            (webhook_received_at.isoformat() if webhook_received_at else "-"),
            (eval_started_at.isoformat() if eval_started_at else "-"),
            (eval_finished_at.isoformat() if eval_finished_at else "-"),
            eval_duration_ms,
            (round((eval_finished_at - webhook_received_at).total_seconds() * 1000.0, 1)
             if webhook_received_at else eval_duration_ms))
    except Exception as exc:
        logger.error("Latency log formatting failed: %s", exc)

    # ── Persistent setup-state lifecycle (additive, DISPLAY-ONLY) ───────────────
    # Derived AFTER the verdict + dispatch so it never feeds back into the gate. A
    # READY->ACTIVE transition requires that a live READY card was actually sent on
    # THIS evaluation (alert_sent_at), not merely a READY verdict.
    try:
        _update_setup_state(resolved_inst, a,
                            dispatched_ready=bool(alert_sent_at),
                            is_duplicate=is_duplicate)
    except Exception as exc:
        logger.error("Setup-state update failed: %s", exc)


# ── Asynchronous webhook processing ──────────────────────────────────────────
# TradingView aborts a webhook if the server does not respond quickly ("request
# took too long and timed out"). The analysis itself is in-memory/fast, but the
# Discord POSTs in the tail (journal + live card, each up to 5-10 s) can stack
# and blow past that timeout. So the request thread does only the fast, in-memory
# state commit (record + zone flags + price/VWAP) and then hands the heavy tail
# to a single background worker, returning an immediate ack. The worker is
# serialized (one job at a time, FIFO) so concurrent alerts (e.g. MGC + MNQ on
# the same bar) never race on shared state.
_WEBHOOK_JOBS          = queue.Queue()
_WEBHOOK_WORKER_LOCK   = threading.Lock()
_WEBHOOK_WORKER_THREAD = None


def _webhook_worker():
    while True:
        job = _WEBHOOK_JOBS.get()
        try:
            if job.get("job_type") == "dual_tf_entry":
                _process_dual_tf_entry_job(
                    **{k: v for k, v in job.items() if k != "job_type"})
            else:
                _process_webhook_alert(**job)
        except Exception as exc:
            logger.error("Webhook background processing failed: %s", exc)
        finally:
            _WEBHOOK_JOBS.task_done()


def _ensure_webhook_worker():
    """Start the background worker on first use (idempotent, thread-safe). Lazy
    start keeps module import side-effect-free and works regardless of how Flask
    is launched (python app.py or a WSGI server)."""
    global _WEBHOOK_WORKER_THREAD
    if _WEBHOOK_WORKER_THREAD is not None and _WEBHOOK_WORKER_THREAD.is_alive():
        return
    with _WEBHOOK_WORKER_LOCK:
        if _WEBHOOK_WORKER_THREAD is not None and _WEBHOOK_WORKER_THREAD.is_alive():
            return
        _WEBHOOK_WORKER_THREAD = threading.Thread(
            target=_webhook_worker, name="webhook-worker", daemon=True)
        _WEBHOOK_WORKER_THREAD.start()
        logger.info("Webhook background worker started")


# ── Slow-task worker ─────────────────────────────────────────────────────────
# Everything that is NOT the trade decision or the trade alert (the journal-
# channel Discord embed, etc.) runs here, OFF the decision worker, so a slow or
# timing-out Discord POST can never delay the next alert's READY/WARN/WAIT
# decision or the trade alert itself. Single FIFO thread, so it preserves the
# same no-race guarantee on shared JOURNAL state that the webhook worker relies
# on (the in-memory store still happens on the decision worker; only the embed
# is offloaded).
_SLOW_TASKS         = queue.Queue()
_SLOW_WORKER_LOCK   = threading.Lock()
_SLOW_WORKER_THREAD = None


def _slow_task_worker():
    while True:
        fn = _SLOW_TASKS.get()
        try:
            fn()
        except Exception as exc:
            logger.error("Slow task failed: %s", exc)
        finally:
            _SLOW_TASKS.task_done()


def _ensure_slow_worker():
    """Start the slow-task worker on first use (idempotent, thread-safe)."""
    global _SLOW_WORKER_THREAD
    if _SLOW_WORKER_THREAD is not None and _SLOW_WORKER_THREAD.is_alive():
        return
    with _SLOW_WORKER_LOCK:
        if _SLOW_WORKER_THREAD is not None and _SLOW_WORKER_THREAD.is_alive():
            return
        _SLOW_WORKER_THREAD = threading.Thread(
            target=_slow_task_worker, name="slow-task-worker", daemon=True)
        _SLOW_WORKER_THREAD.start()
        logger.info("Slow-task background worker started")


def _enqueue_slow(fn):
    _ensure_slow_worker()
    _SLOW_TASKS.put(fn)


# ── Heartbeat market re-evaluation loop (additive, DIAGNOSTIC-ONLY) ───────────
# Periodically re-scores every instrument so the Diagnostics page shows a live,
# continuously-updated read (counters, gate signals, WAIT reasons) instead of only
# the infrequent TradingView webhooks. It calls full_analysis + _record_eval_metrics
# ONLY — never a Discord / journal / EARLY / tiered / live-card path — so it can
# never alter a READY/WAIT verdict or post a duplicate alert. Fail-open per
# instrument, and strictly less frequent than the existing /status polling that
# already calls full_analysis, so it adds no new concurrency risk.
_HEARTBEAT_INSTRUMENTS = tuple(enabled_instruments())


def _run_heartbeat_evaluations():
    # Market closed → pause the diagnostic re-eval entirely: no full_analysis, no
    # eval metrics, no setup-state churn. A quiet (closed) tape must never be
    # re-scored into a stream of "failed" WAITs the counters then tally.
    if not market_session_status()["open"]:
        return
    for inst in _HEARTBEAT_INSTRUMENTS:
        try:
            _eval_timing_begin()          # per-instrument so phase timings don't bleed
            _t0     = time.perf_counter()
            started = now_utc()
            a       = full_analysis(ticker_override=inst)
            finished = now_utc()
            dur_ms  = round((time.perf_counter() - _t0) * 1000.0, 3)
            _record_eval_metrics(a, None, started, finished, dur_ms, None, inst,
                                 tiered_sent=False, trigger="heartbeat")
            try:                       # display-only lifecycle refresh (never dispatches)
                _update_setup_state(inst, a, dispatched_ready=False, is_duplicate=False)
            except Exception as exc:
                logger.error("Heartbeat setup-state update failed for %s: %s", inst, exc)
        except Exception as exc:
            logger.error("Heartbeat evaluation failed for %s: %s", inst, exc)


def _heartbeat_eval_loop():
    """Run a heartbeat evaluation pass now, then reschedule every
    EVAL_HEARTBEAT_INTERVAL seconds. Diagnostic-only; safe on dev and prod."""
    try:
        if EVAL_HEARTBEAT_ENABLED:
            _run_heartbeat_evaluations()
    except Exception as exc:
        logger.error("Heartbeat eval loop error: %s", exc)
    finally:
        threading.Timer(EVAL_HEARTBEAT_INTERVAL, _heartbeat_eval_loop).start()


# ════════════════════════════════════════════════════════════════════════════
# BACKTESTING ENGINE — READ-ONLY research surface. Completely decoupled from the
# live money path: it only INSERT/SELECTs into the backtest_* tables, never reads
# or mutates a live global, never posts Discord, never writes strategy_trades,
# never touches the gate / sizing / dedupe / /traderspost. All endpoints are
# owner-gated by the Express dashboard auth (they are NOT in OPEN_PATHS). Every
# helper is FAIL-OPEN: a DB/parse hiccup degrades to a clean JSON error, never a
# 500 into the analysis path.
# ════════════════════════════════════════════════════════════════════════════
import json as _bt_json_mod
import csv as _bt_csv_mod
import io as _bt_io_mod

try:
    import backtest_engine as bt
    BACKTEST_AVAILABLE = True
except Exception as _bt_import_exc:   # pragma: no cover - defensive
    bt = None
    BACKTEST_AVAILABLE = False
    logger.warning("backtest engine import failed (backtest disabled): %s", _bt_import_exc)


def _bt_conn(statement_timeout_ms=30000):
    """Short-lived autocommit connection for the backtest tables. None on error."""
    if not LEARNING_DB_ENABLED:
        return None
    try:
        conn = psycopg2.connect(LEARNING_DB_URL, connect_timeout=5)
        conn.autocommit = True
        try:
            with conn.cursor() as cur:
                cur.execute("SET statement_timeout = %s", (int(statement_timeout_ms),))
        except Exception:
            pass
        return conn
    except Exception as exc:
        logger.warning("backtest DB connect failed: %s", exc)
        return None


def _bt_json_safe(obj):
    """Recursively replace non-finite floats with None so the result is valid
    JSONB (Postgres rejects Infinity/NaN tokens)."""
    if isinstance(obj, float):
        return obj if math.isfinite(obj) else None
    if isinstance(obj, dict):
        return {k: _bt_json_safe(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [_bt_json_safe(v) for v in obj]
    return obj


def _bt_store_dataset(symbol, timeframe, source_tz, source_label, filename, parsed):
    """Persist a parsed dataset + its candles. Dedupe by file sha256 (re-uploading
    the identical file reuses the existing dataset)."""
    conn = _bt_conn()
    if conn is None:
        return {"ok": False, "error": "Database unavailable — backtest storage offline."}
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT id, row_count FROM backtest_datasets WHERE sha256=%s",
                        (parsed["sha256"],))
            existing = cur.fetchone()
            if existing:
                return {"ok": True, "reused": True, "dataset_id": existing[0],
                        "row_count": existing[1]}
            cur.execute(
                """INSERT INTO backtest_datasets
                       (symbol, timeframe, source_label, source_tz, original_filename,
                        sha256, row_count, gap_count, first_ts, last_ts)
                   VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                   RETURNING id""",
                (symbol, timeframe, source_label, source_tz, filename,
                 parsed["sha256"], parsed["row_count"], parsed["gap_count"],
                 parsed["first_ts"], parsed["last_ts"]))
            ds_id = cur.fetchone()[0]
            rows = [(ds_id, symbol, timeframe, c["ts"], c["open"], c["high"],
                     c["low"], c["close"], c["volume"]) for c in parsed["candles"]]
            psycopg2.extras.execute_values(
                cur,
                """INSERT INTO backtest_candles
                       (dataset_id, symbol, timeframe, ts, open, high, low, close, volume)
                   VALUES %s ON CONFLICT (dataset_id, ts) DO NOTHING""",
                rows, page_size=1000)
        return {"ok": True, "reused": False, "dataset_id": ds_id,
                "row_count": parsed["row_count"]}
    except Exception as exc:
        # A concurrent identical upload can trip the sha256 unique index — re-read.
        try:
            with conn.cursor() as cur:
                cur.execute("SELECT id, row_count FROM backtest_datasets WHERE sha256=%s",
                            (parsed["sha256"],))
                existing = cur.fetchone()
            if existing:
                return {"ok": True, "reused": True, "dataset_id": existing[0],
                        "row_count": existing[1]}
        except Exception:
            pass
        logger.warning("backtest store dataset failed: %s", exc)
        return {"ok": False, "error": f"Storage error: {exc}"}
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _bt_list_datasets():
    conn = _bt_conn()
    if conn is None:
        return []
    try:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT id, symbol, timeframe, source_label, source_tz, row_count,
                          gap_count, first_ts, last_ts, uploaded_at, original_filename
                   FROM backtest_datasets ORDER BY uploaded_at DESC LIMIT 200""")
            out = []
            for r in cur.fetchall():
                out.append({
                    "id": r[0], "symbol": r[1], "timeframe": r[2], "source_label": r[3],
                    "source_tz": r[4], "row_count": r[5], "gap_count": r[6],
                    "first_ts": r[7].isoformat() if r[7] else None,
                    "last_ts": r[8].isoformat() if r[8] else None,
                    "uploaded_at": r[9].isoformat() if r[9] else None,
                    "filename": r[10]})
            return out
    except Exception as exc:
        logger.warning("backtest list datasets failed: %s", exc)
        return []
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _bt_get_dataset(dataset_id):
    conn = _bt_conn()
    if conn is None:
        return None
    try:
        with conn.cursor() as cur:
            cur.execute("""SELECT id, symbol, timeframe, source_tz, row_count
                           FROM backtest_datasets WHERE id=%s""", (dataset_id,))
            r = cur.fetchone()
            if not r:
                return None
            return {"id": r[0], "symbol": r[1], "timeframe": r[2],
                    "source_tz": r[3], "row_count": r[4]}
    except Exception as exc:
        logger.warning("backtest get dataset failed: %s", exc)
        return None
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _bt_delete_dataset(dataset_id):
    conn = _bt_conn()
    if conn is None:
        return False
    try:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM backtest_datasets WHERE id=%s", (dataset_id,))
        return True
    except Exception as exc:
        logger.warning("backtest delete dataset failed: %s", exc)
        return False
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _bt_load_candles(dataset_id, start_ts=None, end_ts=None):
    """Return ascending UTC candle dicts for a dataset (optionally range-clamped)."""
    conn = _bt_conn()
    if conn is None:
        return []
    try:
        q = ["SELECT ts, open, high, low, close, volume FROM backtest_candles WHERE dataset_id=%s"]
        params = [dataset_id]
        if start_ts is not None:
            q.append("AND ts >= %s"); params.append(start_ts)
        if end_ts is not None:
            q.append("AND ts <= %s"); params.append(end_ts)
        q.append("ORDER BY ts ASC")
        with conn.cursor() as cur:
            cur.execute(" ".join(q), tuple(params))
            out = []
            for r in cur.fetchall():
                ts = r[0]
                if ts.tzinfo is None:
                    ts = ts.replace(tzinfo=timezone.utc)
                out.append({"ts": ts.astimezone(timezone.utc), "open": float(r[1]),
                            "high": float(r[2]), "low": float(r[3]), "close": float(r[4]),
                            "volume": float(r[5]) if r[5] is not None else 0.0})
            return out
    except Exception as exc:
        logger.warning("backtest load candles failed: %s", exc)
        return []
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _bt_create_run(params):
    conn = _bt_conn()
    if conn is None:
        return None
    try:
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO backtest_runs (params, status, progress) VALUES (%s,'queued',0) RETURNING id",
                (psycopg2.extras.Json(_bt_json_safe(params)),))
            return cur.fetchone()[0]
    except Exception as exc:
        logger.warning("backtest create run failed: %s", exc)
        return None
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _bt_update_run(run_id, status=None, progress=None, result=None, error=None):
    conn = _bt_conn()
    if conn is None:
        return
    try:
        sets, vals = ["updated_at = now()"], []
        if status is not None:
            sets.append("status = %s"); vals.append(status)
        if progress is not None:
            sets.append("progress = %s"); vals.append(float(progress))
        if result is not None:
            sets.append("result_json = %s"); vals.append(psycopg2.extras.Json(_bt_json_safe(result)))
        if error is not None:
            sets.append("error = %s"); vals.append(str(error)[:2000])
        vals.append(run_id)
        with conn.cursor() as cur:
            cur.execute(f"UPDATE backtest_runs SET {', '.join(sets)} WHERE id=%s", tuple(vals))
    except Exception as exc:
        logger.warning("backtest update run failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _bt_get_run(run_id):
    conn = _bt_conn()
    if conn is None:
        return None
    try:
        with conn.cursor() as cur:
            cur.execute("""SELECT id, params, status, progress, result_json, error,
                                  created_at, updated_at
                           FROM backtest_runs WHERE id=%s""", (run_id,))
            r = cur.fetchone()
            if not r:
                return None
            return {"id": r[0], "params": r[1], "status": r[2], "progress": r[3],
                    "result": r[4], "error": r[5],
                    "created_at": r[6].isoformat() if r[6] else None,
                    "updated_at": r[7].isoformat() if r[7] else None}
    except Exception as exc:
        logger.warning("backtest get run failed: %s", exc)
        return None
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _bt_run_worker(run_id, dataset_id, params):
    """Background backtest executor. FAIL-OPEN: any error lands as status=error."""
    try:
        _bt_update_run(run_id, status="running", progress=0.1)
        candles = _bt_load_candles(dataset_id, params.get("start_ts"), params.get("end_ts"))
        if not candles:
            _bt_update_run(run_id, status="error",
                           error="No candles found for this dataset / date range.")
            return
        _bt_update_run(run_id, progress=0.4)
        result = bt.run_backtest(candles, params)
        if not result.get("ok"):
            _bt_update_run(run_id, status="error",
                           error=result.get("error") or "Backtest failed.")
            return
        # Echo the human-facing params so the UI/export has full context.
        result["params_echo"] = {
            "dataset_id": dataset_id, "mode": params.get("mode"),
            "session": params.get("session") or "All",
            "strategies": params.get("strategies"),
            "start": params.get("start_label"), "end": params.get("end_label"),
        }
        _bt_update_run(run_id, status="done", progress=1.0, result=result)
    except Exception as exc:
        logger.warning("backtest worker crashed: %s", exc)
        try:
            _bt_update_run(run_id, status="error", error=f"Worker error: {exc}")
        except Exception:
            pass


def _bt_opt_worker(run_id, dataset_id, params):
    """Background optimization-study executor. FAIL-OPEN like _bt_run_worker."""
    try:
        _bt_update_run(run_id, status="running", progress=0.1)
        candles = _bt_load_candles(dataset_id, params.get("start_ts"), params.get("end_ts"))
        if not candles:
            _bt_update_run(run_id, status="error",
                           error="No candles found for this dataset / date range.")
            return
        _bt_update_run(run_id, progress=0.4)
        result = bt.run_optimization(candles, params)
        if not result.get("ok"):
            _bt_update_run(run_id, status="error",
                           error=result.get("error") or "Optimization failed.")
            return
        result["params_echo"] = {
            "dataset_id": dataset_id, "mode": params.get("mode"),
            "strategies": params.get("strategies"),
            "start": params.get("start_label"), "end": params.get("end_label"),
            "min_trades": params.get("min_trades"),
        }
        _bt_update_run(run_id, status="done", progress=1.0, result=result)
    except Exception as exc:
        logger.warning("optimization worker crashed: %s", exc)
        try:
            _bt_update_run(run_id, status="error", error=f"Worker error: {exc}")
        except Exception:
            pass


def _bt_et_bounds(date_str, end_of_day=False):
    """Interpret a YYYY-MM-DD (or full ISO) string as an ET instant → UTC datetime."""
    if not date_str:
        return None
    s = str(date_str).strip()
    try:
        if "T" in s or " " in s:
            dt = datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=ET_TZ)
            return dt.astimezone(timezone.utc)
        d = datetime.strptime(s, "%Y-%m-%d").date()
        t = datetime.max.time().replace(microsecond=0) if end_of_day else datetime.min.time()
        return datetime.combine(d, t).replace(tzinfo=ET_TZ).astimezone(timezone.utc)
    except Exception:
        return None


def _bt_guard():
    """None when backtest is usable, else a (json, status) error tuple."""
    if not BACKTEST_AVAILABLE:
        return jsonify({"ok": False, "error": "Backtest engine unavailable."}), 503
    if not LEARNING_DB_ENABLED:
        return jsonify({"ok": False, "error": "Database not configured — backtest disabled."}), 503
    return None


@app.route("/backtest/upload", methods=["POST"])
def bt_upload():
    """Owner-only. Body = raw CSV text; query: symbol, timeframe, tz, label, filename."""
    guard = _bt_guard()
    if guard:
        return guard
    # symbol/timeframe accept a concrete value OR "auto"/blank to request detection.
    symbol_raw = (request.args.get("symbol") or "auto").strip()
    timeframe_raw = (request.args.get("timeframe") or "auto").strip()
    source_tz = request.args.get("tz") or "America/New_York"
    label = request.args.get("label") or None
    filename = request.args.get("filename") or None
    auto_symbol = symbol_raw.lower() in ("", "auto")
    auto_tf = timeframe_raw.lower() in ("", "auto")
    symbol = "auto" if auto_symbol else symbol_raw.upper()
    timeframe = "auto" if auto_tf else timeframe_raw.lower()
    if not auto_symbol and symbol not in bt.VALID_SYMBOLS:
        return jsonify({"ok": False, "error": "symbol must be MGC or MNQ"}), 400
    if not auto_tf and timeframe not in bt.VALID_TIMEFRAMES:
        return jsonify({"ok": False, "error": "timeframe must be 1m/3m/5m/15m"}), 400
    try:
        ZoneInfo(source_tz)
    except Exception:
        return jsonify({"ok": False, "error": f"unknown timezone '{source_tz}'"}), 400
    raw = request.get_data(cache=False, as_text=True)
    if not raw or not raw.strip():
        return jsonify({"ok": False, "error": "empty upload body"}), 400
    parsed = bt.parse_candles_csv(raw, symbol, timeframe, source_tz=source_tz,
                                  filename=filename)
    if not parsed["ok"]:
        return jsonify({"ok": False, "error": parsed["error"]}), 400
    # Persist using the engine-resolved (possibly auto-detected) symbol/timeframe.
    eff_symbol = parsed["symbol"]
    eff_timeframe = parsed["timeframe"]
    stored = _bt_store_dataset(eff_symbol, eff_timeframe, source_tz, label, filename, parsed)
    if not stored.get("ok"):
        return jsonify(stored), 500
    return jsonify({
        "ok": True, "dataset_id": stored["dataset_id"], "reused": stored.get("reused", False),
        "symbol": eff_symbol, "timeframe": eff_timeframe,
        "detected_symbol": parsed["detected_symbol"],
        "detected_timeframe": parsed["detected_timeframe"],
        "row_count": parsed["row_count"], "skipped": parsed["skipped"],
        "dup_removed": parsed["dup_removed"], "gap_count": parsed["gap_count"],
        "inferred_timeframe": parsed["inferred_timeframe"],
        "first_ts": parsed["first_ts"].isoformat() if parsed["first_ts"] else None,
        "last_ts": parsed["last_ts"].isoformat() if parsed["last_ts"] else None,
        "warnings": parsed["warnings"],
    })


