if __name__ == "__main__":
    port = int(os.environ.get("PORT", 8000))
    if LEARNING_DB_ENABLED:
        _check_journal_db_ready()                  # probe journal_entries (no DDL; table created via DB tool/publish diff)
        _load_journal_from_db()                    # restore today's journal so EOD survives restarts (BEFORE the worker)
        _check_tradezella_db_ready()               # probe tradezella_trades (no DDL; owner-only review import, FAIL-OPEN)
        if _swing_htf_enabled():                   # SWING flag-on only — SCALP boot stays untouched
            _check_swing_thesis_db_ready()         # probe swing_theses (no DDL; table created via DB tool/publish diff)
            _load_swing_theses_from_db()           # rehydrate open multi-day SWING holds (INERT) BEFORE the worker/watcher
        _check_manual_trade_db_ready()             # probe manual_trades (no DDL; created via DB tool/publish diff)
        _load_manual_trades_from_db()              # rehydrate open ADVISORY-ONLY manual positions (display monitor)
    _ensure_webhook_worker()                       # background webhook processor (fast ack to TradingView)
    threading.Timer(0, _vwap_autofetch_loop).start()  # auto-fetch VWAP now, then every VWAP_FETCH_INTERVAL (no Discord posting)
    threading.Timer(0, _price_autofetch_loop).start()  # DISPLAY-ONLY price now, then every PRICE_FETCH_INTERVAL (never feeds the gate)
    threading.Timer(0, _managed_watch_loop).start()  # open-trade exit (stop/TP) watcher on its own fast timer (MANAGED_WATCH_INTERVAL); no-op while flat, never feeds the gate
    threading.Timer(0, _cross_market_loop).start()  # cross-market index alignment — DISPLAY on dev+prod; Discord SEND gated to live inside the loop
    if EVAL_HEARTBEAT_ENABLED:
        threading.Timer(0, _heartbeat_eval_loop).start()  # periodic market re-eval (diagnostics-only; no Discord) — runs on dev + prod
    if LEARNING_DB_ENABLED:
        threading.Thread(target=_recompute_learning, daemon=True).start()  # warm the learning cache from Postgres at boot (display-only)
        threading.Thread(target=_load_last_report, daemon=True).start()    # warm the last performance report from Postgres at boot (display-only)
    # Unconditional, time-based Discord senders run on the LIVE (prod) instance only.
    # In dev they would double-post to the shared live channel — see DISCORD_LIVE_ENABLED.
    if DISCORD_LIVE_ENABLED:
        threading.Timer(0, _heartbeat_loop).start()   # fire immediately, then every HEARTBEAT_INTERVAL
        threading.Timer(trade_ready_interval(), _trade_ready_loop).start()  # re-post READY card (mode-aware cadence)
        threading.Timer(ANALYST_REPORT_INTERVAL, _analyst_report_loop).start()  # open-position unified-thesis updates → journal channel (DISPLAY/NOTIFY only)
        _schedule_eod()                               # schedule daily EOD summary
        _schedule_weekly_report()                     # schedule weekly report (Fri after close)
    else:
        logger.info(
            "DISCORD_LIVE_ENABLED=False (dev instance) — heartbeat / trade-ready / EOD / "
            "weekly Discord schedulers disabled so this instance can't double-post to the "
            "live channel. Set DISCORD_LIVE=1 to enable."
        )
    app.run(host="0.0.0.0", port=port, debug=False)
